INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36921, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "元気とは、体や心が健康で、活気にあふれていること。", "primary_collocate": null, "pronunciation": "げんき", "ipa": "ɡeŋki", "syllable_count": 3, "sentences": [{"text": "長い紐を引くと、馬は元気に走ります。", "target_word": "元気", "complexity_tier": "T3", "furigana": "長[なが]い紐[ひも]を引[ひ]くと、馬[うま]は元気[げんき]に走[はし]ります。", "sentence_source": "mined"}, {"text": "祖母は八十歳になっても元気で、毎朝散歩をしている。", "target_word": "元気", "complexity_tier": "T3", "furigana": "祖母[そぼ]は八十歳[はちじゅっさい]になっても元気[げんき]で、毎朝[まいあさ]散歩[さんぽ]をしている。", "sentence_source": "generated"}, {"text": "風邪が治って、今日は朝から元気です。", "target_word": "元気", "complexity_tier": "T2", "furigana": "風邪[かぜ]が治[なお]って、今日[きょう]は朝[あさ]から元気[げんき]です。", "sentence_source": "generated"}, {"text": "試合に負けた後も、彼は元気に笑っていた。", "target_word": "元気", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けた後[あと]も、彼[かれ]は元気[げんき]に笑[わら]っていた。", "sentence_source": "generated"}, {"text": "友達の顔を見たら、急に元気が出てきた。", "target_word": "元気", "complexity_tier": "T3", "furigana": "友達[ともだち]の顔[かお]を見[み]たら、急[きゅう]に元気[げんき]が出[で]てきた。", "sentence_source": "generated"}, {"text": "母が作ったスープを飲んで、少し元気になった。", "target_word": "元気", "complexity_tier": "T3", "furigana": "母[はは]が作[つく]ったスープを飲[の]んで、少[すこ]し元気[げんき]になった。", "sentence_source": "generated"}, {"text": "元気な声であいさつすると、気持ちがいい。", "target_word": "元気", "complexity_tier": "T3", "furigana": "元気[げんき]な声[こえ]であいさつすると、気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "先生は、疲れている私に「元気を出して」と声をかけた。", "target_word": "元気", "complexity_tier": "T3", "furigana": "先生[せんせい]は、疲[つか]れている私[わたし]に「元気[げんき]を出[だ]して」と声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "久しぶりに会った友人は元気で、昔と変わらず冗談ばかり言っていた。", "target_word": "元気", "complexity_tier": "T4", "furigana": "久[ひさ]しぶりに会[あ]った友人[ゆうじん]は元気[げんき]で、昔[むかし]と変[か]わらず冗談[じょうだん]ばかり言[い]っていた。", "sentence_source": "generated"}, {"text": "子どもたちは朝から元気で、公園で夕方まで遊んだ。", "target_word": "元気", "complexity_tier": "T3", "furigana": "子[こ]どもたちは朝[あさ]から元気[げんき]で、公園[こうえん]で夕方[ゆうがた]まで遊[あそ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "元気", "label": "語幹"}, {"form": "元気な", "label": "連体形"}, {"form": "元気に", "label": "連用形"}, {"form": "元気で", "label": "て形"}, {"form": "元気だ", "label": "終止形"}, {"form": "元気だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "体も心も健康で、活気や勢いがある様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36921, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元気", "is_correct": true, "explanation": "形状詞の語幹。「元気に走る」と続き、馬の様子を表すので空所に入る。"}, {"text": "元気な", "is_correct": false, "explanation": "連体形。名詞の前に置く形で、「馬は元気な走ります」とは続かない。"}, {"text": "元気だった", "is_correct": false, "explanation": "過去形。「元気だった走ります」と続かず、文の形に合わない。"}, {"text": "元気だ", "is_correct": false, "explanation": "終止形。「元気だに走ります」となり、ここでは続かない。"}], "explanations": {"元気": "形状詞の語幹。「元気に走る」と続き、馬の様子を表すので空所に入る。", "元気な": "連体形。名詞の前に置く形で、「馬は元気な走ります」とは続かない。", "元気だった": "過去形。「元気だった走ります」と続かず、文の形に合わない。", "元気だ": "終止形。「元気だに走ります」となり、ここでは続かない。"}, "sentence_index": 0, "correct_answer": "元気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社で元気診断を受けて、異常はなかった。", "explanation": "「健康診断」は言えるが、「元気診断」という検査名はない。元気は人の様子を表す語で、検査の名前には使わない。"}, {"text": "この靴は元気で、山道を歩いても壊れない。", "explanation": "元気は人や動物の状態に使い、靴の頑丈さには使わない。頑丈さは「丈夫」で表す。"}, {"text": "その子は元気が高いので、熱を下げる薬を飲ませた。", "explanation": "熱の高さは「熱が高い」で表す。「元気が高い」とは言わず、元気は人の体や気力の様子を表すので体温には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36921, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元気", "is_correct": true, "explanation": "形状詞の語幹。「元気な声」の形で、名詞「声」を修飾する。"}, {"text": "元気に", "is_correct": false, "explanation": "連用形。「元気に声」と名詞を直接修飾できず、空所に入らない。"}, {"text": "元気で", "is_correct": false, "explanation": "て形。「元気で声」と名詞を修飾できず、空所に入らない。"}, {"text": "元気なら", "is_correct": false, "explanation": "仮定形。「元気なら声」と名詞に続かず、文の形に合わない。"}], "explanations": {"元気": "形状詞の語幹。「元気な声」の形で、名詞「声」を修飾する。", "元気に": "連用形。「元気に声」と名詞を直接修飾できず、空所に入らない。", "元気で": "て形。「元気で声」と名詞を修飾できず、空所に入らない。", "元気なら": "仮定形。「元気なら声」と名詞に続かず、文の形に合わない。"}, "sentence_index": 6, "correct_answer": "元気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母の元気が完全に治って、ほっとした。", "explanation": "「元気」は治る対象ではない。病気の回復は「病気が治る」で表し、「元気が治る」とは言わない。"}, {"text": "明日の元気は晴れだから、洗濯をしよう。", "explanation": "空模様は「天気」で表す。「元気」は人の体や気力を表すので、空模様には使わない。"}, {"text": "このお酒は元気で、少し飲んだだけで酔ってしまった。", "explanation": "酒の強さは「強い」で表す。「元気」は人の気力や体の様子を表すので、酒には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36921, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は元気の、毎朝一時間も庭仕事をしている。", "corrected_sentence": "祖父は元気で、毎朝一時間も庭仕事をしている。", "error_description": "形状詞「元気」は文を続けるとき「で」をつけて「元気で」とする。「元気の」は誤りで、正しくは「元気で」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "元気", "is_correct": true, "explanation": "語幹。活用語尾のつかない基本の形で、ここで問われる形と一致する。"}, {"text": "元気な", "is_correct": false, "explanation": "連体形。名詞の前に置く形で、「元気な〜」の形でここには使えない。"}, {"text": "元気だった", "is_correct": false, "explanation": "過去形。「八十歳になっても元気だった」の後に「で」が続かず、文法的に誤り。"}, {"text": "元気に", "is_correct": false, "explanation": "連用形。「ても元気で」の形に合わず、文の構造に合わない。"}], "correct_form": "元気", "base_form": "元気", "form_label": "語幹", "sentence_index": 1, "explanations": {"元気": "語幹。活用語尾のつかない基本の形で、ここで問われる形と一致する。", "元気な": "連体形。名詞の前に置く形で、「元気な〜」の形でここには使えない。", "元気だった": "過去形。「八十歳になっても元気だった」の後に「で」が続かず、文法的に誤り。", "元気に": "連用形。「ても元気で」の形に合わず、文の構造に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36921, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "帰宅したとき、弟は元気なだった。", "corrected_sentence": "帰宅したとき、弟は元気だった。", "error_description": "形状詞「元気」の過去形は「元気だった」。「元気なだった」は連体形の「な」を余分につけた誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "元気", "is_correct": true, "explanation": "語幹。「元気を出す」の名詞的な用法で、活用語尾のつかない形。"}, {"text": "元気で", "is_correct": false, "explanation": "て形。「元気を出す」の名詞的な形には合わない。"}, {"text": "元気だ", "is_correct": false, "explanation": "終止形。「元気だを出して」とは続かない。"}, {"text": "元気なら", "is_correct": false, "explanation": "仮定形。「元気ならを出して」とは続かず、文の形に合わない。"}], "correct_form": "元気", "base_form": "元気", "form_label": "語幹", "sentence_index": 7, "explanations": {"元気": "語幹。「元気を出す」の名詞的な用法で、活用語尾のつかない形。", "元気で": "て形。「元気を出す」の名詞的な形には合わない。", "元気だ": "終止形。「元気だを出して」とは続かない。", "元気なら": "仮定形。「元気ならを出して」とは続かず、文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「子供でも」の「で」で、「子供」に直接付き後ろの「も」に続く。"}, {"text": "を", "is_correct": false, "explanation": "「分かる」は目的語を取らないので、「子供を分かる」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、対象の範囲を示すここの文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は、ここで対象の範囲を示せない。"}], "correct_answer": "で", "explanations": {"で": "正解。「子供でも」の「で」で、「子供」に直接付き後ろの「も」に続く。", "を": "「分かる」は目的語を取らないので、「子供を分かる」は不自然。", "へ": "方向を表す「へ」は、対象の範囲を示すここの文脈に合わない。", "から": "起点を表す「から」は、ここで対象の範囲を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「子供が」で、「飛び出して」の動作主を示す主語の格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「飛び出す」は目的語を取らないので、「子供を」では不自然。"}, {"text": "に", "is_correct": false, "explanation": "相手や到達点を示す「に」で、ここでは動作の主体にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、動作の主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「子供が」で、「飛び出して」の動作主を示す主語の格助詞。", "を": "「飛び出す」は目的語を取らないので、「子供を」では不自然。", "に": "相手や到達点を示す「に」で、ここでは動作の主体にならない。", "から": "起点を表す「から」で、動作の主体を示せない。"}, "error_tags": {"を": "目的語", "に": "相手・位置", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おとなではない、小さい人。", "primary_collocate": null, "pronunciation": "こども", "ipa": "kodomo", "syllable_count": 3, "sentences": [{"text": "公園で子供が楽しそうに遊んでいます。", "target_word": "子供", "complexity_tier": "T3", "furigana": "公園[こうえん]で子供[こども]が楽[たの]しそうに遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "この映画は子供でも分かるように作られています。", "target_word": "子供", "complexity_tier": "T3", "furigana": "この映画[えいが]は子供[こども]でも分[わ]かるように作[つく]られています。", "sentence_source": "generated"}, {"text": "子供は夜九時までに寝る決まりです。", "target_word": "子供", "complexity_tier": "T3", "furigana": "子供[こども]は夜[よる]九時[くじ]までに寝[ね]る決[き]まりです。", "sentence_source": "generated"}, {"text": "電車で子供に席をゆずりました。", "target_word": "子供", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で子供[こども]に席[せき]をゆずりました。", "sentence_source": "generated"}, {"text": "子供のとき、毎年夏に海へ行きました。", "target_word": "子供", "complexity_tier": "T3", "furigana": "子供[こども]のとき、毎年[まいとし]夏[なつ]に海[うみ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "雨の日は、子供が外で遊べなくて退屈そうだ。", "target_word": "子供", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、子供[こども]が外[そと]で遊[あそ]べなくて退屈[たいくつ]そうだ。", "sentence_source": "generated"}, {"text": "大人は無料ですが、子供は半額です。", "target_word": "子供", "complexity_tier": "T3", "furigana": "大人[おとな]は無料[むりょう]ですが、子供[こども]は半額[はんがく]です。", "sentence_source": "generated"}, {"text": "小さな子供が道に飛び出して、車が急に止まった。", "target_word": "子供", "complexity_tier": "T3", "furigana": "小[ちい]さな子供[こども]が道[みち]に飛[と]び出[だ]して、車[くるま]が急[きゅう]に止[と]まった。", "sentence_source": "generated"}, {"text": "子供はよく食べて、よく寝て、大きくなる。", "target_word": "子供", "complexity_tier": "T3", "furigana": "子供[こども]はよく食[た]べて、よく寝[ね]て、大[おお]きくなる。", "sentence_source": "generated"}, {"text": "公園で子供が泣いていたので、近くにいた大人が声をかけた。", "target_word": "子供", "complexity_tier": "T3", "furigana": "公園[こうえん]で子供[こども]が泣[な]いていたので、近[ちか]くにいた大人[おとな]が声[こえ]をかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "子供", "label": "基本形"}, {"form": "こども", "label": "ひらがな表記"}], "register": "中立", "sense_fingerprint": "大人になっていない小さい人（幼い人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "子供", "is_correct": true, "explanation": "正解。楽しそうに遊ぶ主体となる人を表し、文に合う。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗う道具で、遊ぶ主体にはならない。"}, {"text": "台風", "is_correct": false, "explanation": "気象現象で、楽しそうに遊ぶ主体にはならない。"}, {"text": "電柱", "is_correct": false, "explanation": "物で、遊ぶ主体にはならない。"}], "explanations": {"子供": "正解。楽しそうに遊ぶ主体となる人を表し、文に合う。", "石鹸": "洗う道具で、遊ぶ主体にはならない。", "台風": "気象現象で、楽しそうに遊ぶ主体にはならない。", "電柱": "物で、遊ぶ主体にはならない。"}, "sentence_index": 0, "correct_answer": "子供"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成人式で、子供たちが新成人として祝われた。", "explanation": "新成人は大人なので、ここは〈子供〉を使えない。〈大人〉の意味で使っているが、〈子供〉の定義（おとなではない小さい人）とは逆。"}, {"text": "大学の子供は、教授の講義を真剣に聞いている。", "explanation": "大学生には〈学生〉を使う。〈子供〉は小さい人を指すので、大学生には合わない。"}, {"text": "駅の売店で、子供の店員が新聞を売っている。", "explanation": "店員は働く大人を指すので、〈子供〉は合わない。〈子供〉は〈大人〉の意味で使われており、定義（おとなではない小さい人）と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "子供", "is_correct": true, "explanation": "正解。半額になる対象として文に合う人を表す。"}, {"text": "富士山", "is_correct": false, "explanation": "山の名前で、料金の割引対象にはならない。"}, {"text": "雨", "is_correct": false, "explanation": "天気を表す語で、料金の割引対象にはならない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "景色を表す語で、料金の割引対象にはならない。"}], "explanations": {"子供": "正解。半額になる対象として文に合う人を表す。", "富士山": "山の名前で、料金の割引対象にはならない。", "雨": "天気を表す語で、料金の割引対象にはならない。", "夕焼け": "景色を表す語で、料金の割引対象にはならない。"}, "sentence_index": 6, "correct_answer": "子供"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の選挙で、子供の候補者が市長に立候補する。", "explanation": "候補者は大人を指すので、〈子供〉の定義（おとなではない小さい人）とは合わない。〈大人〉の意味で使っている。"}, {"text": "今年の入社式で、子供の新入社員が代表の挨拶をした。", "explanation": "新入社員は大人なので、ここは〈子供〉を使えない。〈若者〉の意味で使っているが、〈子供〉の定義とは合わない。"}, {"text": "マンションの管理人は子供で、毎朝ごみを集めている。", "explanation": "管理人は大人の仕事なので、〈子供〉の定義（おとなではない小さい人）とは合わない。〈大人〉の意味で使っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子供を公園で遊んでいる。", "corrected_sentence": "子供が公園で遊んでいる。", "error_description": "「遊ぶ」の主語を示す「が」が正しい。「を」は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36922, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子供を靴が、玄関にそろえて置いてある。", "corrected_sentence": "子供の靴が、玄関にそろえて置いてある。", "error_description": "名詞「靴」を修飾する「の」が正しい。「を」は目的語の格助詞で、ここでは使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「片付けを手伝いました」の「を」。作業の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「片付けが手伝いました」では片付けが主語になり、手伝う対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「片付けの手伝いました」は動詞として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「片付けへ手伝う」は方向の意味になり、作業の対象として合わない。"}], "correct_answer": "を", "explanations": {"を": "「片付けを手伝いました」の「を」。作業の対象を示す。", "が": "「片付けが手伝いました」では片付けが主語になり、手伝う対象にならない。", "の": "「片付けの手伝いました」は動詞として成り立たない。", "へ": "「片付けへ手伝う」は方向の意味になり、作業の対象として合わない。"}, "error_tags": {"が": "主語", "の": "連体・所属", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人がだれかを助けて、いっしょに何かをすることを言います。", "primary_collocate": null, "pronunciation": "てつだう", "ipa": "tesɯdaɯ", "syllable_count": 4, "sentences": [{"text": "日曜日は、母が夕飯を作るのを手伝います。", "target_word": "手伝います", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は、母[はは]が夕飯[ゆうはん]を作[つく]るのを手伝[てつだ]います。", "sentence_source": "generated"}, {"text": "荷物が重そうなおばあさんが階段を上るのを手伝いました。", "target_word": "手伝いました", "complexity_tier": "T3", "furigana": "荷物[にもつ]が重[おも]そうなおばあさんが階段[かいだん]を上[のぼ]るのを手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "宿題が多くて困っていたら、兄が手伝ってくれました。", "target_word": "手伝って", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が多[おお]くて困[こま]っていたら、兄[あに]が手伝[てつだ]ってくれました。", "sentence_source": "generated"}, {"text": "明日は引っ越しなので、友だちに手伝ってもらう予定です。", "target_word": "手伝って", "complexity_tier": "T3", "furigana": "明日[あした]は引[ひ]っ越[こ]しなので、友[とも]だちに手伝[てつだ]ってもらう予定[よてい]です。", "sentence_source": "generated"}, {"text": "一人では終わらないから、少し手伝ってくれませんか。", "target_word": "手伝って", "complexity_tier": "T3", "furigana": "一人[ひとり]では終[お]わらないから、少[すこ]し手伝[てつだ]ってくれませんか。", "sentence_source": "generated"}, {"text": "弟は部屋の掃除を手伝わないで、ゲームばかりしている。", "target_word": "手伝わない", "complexity_tier": "T3", "furigana": "弟[おとうと]は部屋[へや]の掃除[そうじ]を手伝[てつだ]わないで、ゲームばかりしている。", "sentence_source": "generated"}, {"text": "先生の仕事を手伝うために、放課後も学校に残りました。", "target_word": "手伝う", "complexity_tier": "T3", "furigana": "先生[せんせい]の仕事[しごと]を手伝[てつだ]うために、放課後[ほうかご]も学校[がっこう]に残[のこ]りました。", "sentence_source": "generated"}, {"text": "忙しそうだったので、私は店の片付けを手伝いました。", "target_word": "手伝いました", "complexity_tier": "T3", "furigana": "忙[いそが]しそうだったので、私[わたし]は店[みせ]の片付[かたづ]けを手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "運動会の準備を手伝う人は、朝八時に集まってください。", "target_word": "手伝う", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の準備[じゅんび]を手伝[てつだ]う人[ひと]は、朝[あさ]八時[はちじ]に集[あつ]まってください。", "sentence_source": "generated"}, {"text": "父が庭の草をぬくのを、私も手伝った。", "target_word": "手伝った", "complexity_tier": "T3", "furigana": "父[ちち]が庭[にわ]の草[くさ]をぬくのを、私[わたし]も手伝[てつだ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手伝う", "label": "終止形"}, {"form": "手伝います", "label": "丁寧形"}, {"form": "手伝って", "label": "て形"}, {"form": "手伝った", "label": "過去形"}, {"form": "手伝わない", "label": "否定形"}, {"form": "手伝える", "label": "可能形"}], "register": "中立", "sense_fingerprint": "だれかを助けて、いっしょに仕事や用事をすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手伝います", "is_correct": true, "explanation": "「作るのを手伝います」で、母の作業を一緒にするという意味が通る。"}, {"text": "食べます", "is_correct": false, "explanation": "「作るのを食べます」は意味が通らず、作業を手伝う文の骨組みが崩れる。"}, {"text": "洗います", "is_correct": false, "explanation": "「作るのを洗います」は対象が合わず不自然。"}, {"text": "寝ます", "is_correct": false, "explanation": "「作るのを寝ます」は成立しない。"}], "explanations": {"手伝います": "「作るのを手伝います」で、母の作業を一緒にするという意味が通る。", "食べます": "「作るのを食べます」は意味が通らず、作業を手伝う文の骨組みが崩れる。", "洗います": "「作るのを洗います」は対象が合わず不自然。", "寝ます": "「作るのを寝ます」は成立しない。"}, "sentence_index": 0, "correct_answer": "手伝います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海でおぼれた子どもを手伝った。", "explanation": "ここは〈助ける〉（危険から救う）の意味。手伝うは相手の作業に加わることなので、救助の場面には合わない。"}, {"text": "被災地の人々に食料を毎週手伝っている。", "explanation": "ここは〈支援〉の意味。物資を届けて支えることは「支援」で表し、手伝うは作業に加わる意味になる。"}, {"text": "母は寝ている子どもを手伝っていた。", "explanation": "ここは〈見守る〉の意味。寝ている子をそっと見守ることは「見守る」で表し、「手伝う」は作業に加わる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手伝う", "is_correct": true, "explanation": "「先生の仕事を手伝うために」で、仕事に加わって助けるという意味が通る。"}, {"text": "飲む", "is_correct": false, "explanation": "「仕事を飲むために」は意味をなさない。"}, {"text": "眠る", "is_correct": false, "explanation": "「仕事を眠るために」は成立しない。"}, {"text": "浴びる", "is_correct": false, "explanation": "「仕事を浴びるために」は文脈に合わず、不自然。"}], "explanations": {"手伝う": "「先生の仕事を手伝うために」で、仕事に加わって助けるという意味が通る。", "飲む": "「仕事を飲むために」は意味をなさない。", "眠る": "「仕事を眠るために」は成立しない。", "浴びる": "「仕事を浴びるために」は文脈に合わず、不自然。"}, "sentence_index": 6, "correct_answer": "手伝う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は壊れた自転車を手伝った。", "explanation": "ここは〈修理〉の意味。壊れた物を直すことは「修理する」で、手伝うでは表せない。"}, {"text": "係の人が会議の内容を断った。", "explanation": "ここは〈拒否〉の意味。申し出を退けることは「断る」で表し、作業に加わる「手伝う」とは違う。"}, {"text": "彼女はピアノを手伝った。", "explanation": "ここは〈演奏〉の意味。楽器を弾くことは「演奏する」で、手伝うでは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹はテーブルの準備を手伝くれた。", "corrected_sentence": "妹はテーブルの準備を手伝ってくれた。", "error_description": "「手伝ってくれた」の「って」が抜けている。「手伝う」のて形は「手伝って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "手伝いました", "is_correct": true, "explanation": "丁寧形の過去で、「階段を上るのを手伝った」という過去の出来事を表す。"}, {"text": "手伝って", "is_correct": false, "explanation": "て形は文を言い切れず、文末に置くと文が成り立たない。"}, {"text": "手伝ったら", "is_correct": false, "explanation": "条件節で、文末に置くと文が終わらず成り立たない。"}, {"text": "手伝えば", "is_correct": false, "explanation": "条件節で、文末に置くと文が終わらず成り立たない。"}], "correct_form": "手伝いました", "base_form": "手伝う", "form_label": "丁寧形（過去）", "sentence_index": 1, "explanations": {"手伝いました": "丁寧形の過去で、「階段を上るのを手伝った」という過去の出来事を表す。", "手伝って": "て形は文を言い切れず、文末に置くと文が成り立たない。", "手伝ったら": "条件節で、文末に置くと文が終わらず成り立たない。", "手伝えば": "条件節で、文末に置くと文が終わらず成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36924, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は庭の草取りに手伝ってくれた。", "corrected_sentence": "祖父は庭の草取りを手伝ってくれた。", "error_description": "「手伝う」は作業を表す語に「を」をとる。「草取りに」の「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "手伝いました", "is_correct": true, "explanation": "丁寧形の過去で、「片付けを手伝った」という過去の行動を表す。"}, {"text": "手伝い", "is_correct": false, "explanation": "連用形の語幹だけでは文を言い切れず、文末に置くと成り立たない。"}, {"text": "手伝わず", "is_correct": false, "explanation": "連用中止形は文を続ける形で、文末に置くと文が終わらず成り立たない。"}, {"text": "手伝わせ", "is_correct": false, "explanation": "使役の語幹は文末で言い切れず、「手伝わせ。」は成り立たない。"}], "correct_form": "手伝いました", "base_form": "手伝う", "form_label": "丁寧形（過去）", "sentence_index": 7, "explanations": {"手伝いました": "丁寧形の過去で、「片付けを手伝った」という過去の行動を表す。", "手伝い": "連用形の語幹だけでは文を言い切れず、文末に置くと成り立たない。", "手伝わず": "連用中止形は文を続ける形で、文末に置くと文が終わらず成り立たない。", "手伝わせ": "使役の語幹は文末で言い切れず、「手伝わせ。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
