INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36925, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人の作業を助けるために、その人のそばで一緒に作業をする。", "primary_collocate": null, "pronunciation": "てつだう", "ipa": "tesɯdaɯ", "syllable_count": 4, "sentences": [{"text": "台所で母のそばに立って、野菜を切るのを手伝った。", "target_word": "手伝った", "complexity_tier": "T3", "furigana": "台所[だいどころ]で母[はは]のそばに立[た]って、野菜[やさい]を切[き]るのを手伝[てつだ]った。", "sentence_source": "generated"}, {"text": "父が車を洗っているとき、私もとなりでスポンジを持って手伝った。", "target_word": "手伝った", "complexity_tier": "T3", "furigana": "父[ちち]が車[くるま]を洗[あら]っているとき、私[わたし]もとなりでスポンジを持[も]って手伝[てつだ]った。", "sentence_source": "generated"}, {"text": "先生が教室の机を並べていたので、そばに行って手伝いました。", "target_word": "手伝いました", "complexity_tier": "T3", "furigana": "先生[せんせい]が教室[きょうしつ]の机[つくえ]を並[なら]べていたので、そばに行[い]って手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "祖父の畑で、毎週土曜日に草取りを手伝っています。", "target_word": "手伝っています", "complexity_tier": "T3", "furigana": "祖父[そふ]の畑[はたけ]で、毎週[まいしゅう]土曜日[どようび]に草取[くさと]りを手伝[てつだ]っています。", "sentence_source": "generated"}, {"text": "姉は妹のそばにすわって、絵の具を使う作業を手伝いました。", "target_word": "手伝いました", "complexity_tier": "T3", "furigana": "姉[あね]は妹[いもうと]のそばにすわって、絵[え]の具[ぐ]を使[つか]う作業[さぎょう]を手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "店が忙しい日は、近所の人も来て荷物を運ぶのを手伝ってくれる。", "target_word": "手伝って", "complexity_tier": "T3", "furigana": "店[みせ]が忙[いそが]しい日[ひ]は、近所[きんじょ]の人[ひと]も来[き]て荷物[にもつ]を運[はこ]ぶのを手伝[てつだ]ってくれる。", "sentence_source": "generated"}, {"text": "彼の隣で資料をコピーして、発表の準備を手伝いました。", "target_word": "手伝いました", "complexity_tier": "T3", "furigana": "彼[かれ]の隣[となり]で資料[しりょう]をコピーして、発表[はっぴょう]の準備[じゅんび]を手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "大工さんの横で、板をおさえて作業を手伝わせてもらった。", "target_word": "手伝わせて", "complexity_tier": "T3", "furigana": "大工[だいく]さんの横[よこ]で、板[いた]をおさえて作業[さぎょう]を手伝[てつだ]わせてもらった。", "sentence_source": "generated"}, {"text": "人が足りないと言われたので、受付で先輩の横に立って手伝いました。", "target_word": "手伝いました", "complexity_tier": "T3", "furigana": "人[ひと]が足[た]りないと言[い]われたので、受付[うけつけ]で先輩[せんぱい]の横[よこ]に立[た]って手伝[てつだ]いました。", "sentence_source": "generated"}, {"text": "先輩といっしょに机を運んで、教室の模様替えを手伝います。", "target_word": "手伝います", "complexity_tier": "T3", "furigana": "先輩[せんぱい]といっしょに机[つくえ]を運[はこ]んで、教室[きょうしつ]の模様替[もようが]えを手伝[てつだ]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手伝う", "label": "終止形"}, {"form": "手伝います", "label": "丁寧形"}, {"form": "手伝って", "label": "て形"}, {"form": "手伝った", "label": "過去形"}, {"form": "手伝わない", "label": "否定形"}, {"form": "手伝わせる", "label": "使役形"}], "register": "中立", "sense_fingerprint": "相手のそばで、同じ作業を一緒にして助けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36925, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手伝った", "is_correct": true, "explanation": "「野菜を切るのを手伝った」で、母の作業に加わって助けたという意味が通る。"}, {"text": "食べた", "is_correct": false, "explanation": "「切るのを食べた」は意味をなさない。"}, {"text": "洗った", "is_correct": false, "explanation": "「切るのを洗った」は動作の対象が合わず不自然。"}, {"text": "寝た", "is_correct": false, "explanation": "「切るのを寝た」は成立しない。"}], "explanations": {"手伝った": "「野菜を切るのを手伝った」で、母の作業に加わって助けたという意味が通る。", "食べた": "「切るのを食べた」は意味をなさない。", "洗った": "「切るのを洗った」は動作の対象が合わず不自然。", "寝た": "「切るのを寝た」は成立しない。"}, "sentence_index": 0, "correct_answer": "手伝った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嵐で流された犬を手伝った。", "explanation": "ここは〈救う〉の意味。危険から命を助けることは「救う」で、手伝うは作業に加わる意味になる。"}, {"text": "壊れた屋根を手伝った。", "explanation": "ここは〈修理〉の意味。壊れた物を直すことは「修理する」で、手伝うでは表せない。"}, {"text": "被災地へ寄付金を手伝った。", "explanation": "ここは〈寄付〉の意味。お金を贈ることは「寄付する」で、手伝うでは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36925, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手伝いました", "is_correct": true, "explanation": "「発表の準備を手伝いました」で、準備の作業に加わって助けたという意味が通る。"}, {"text": "眠りました", "is_correct": false, "explanation": "「準備を眠りました」は成立しない。"}, {"text": "飲みました", "is_correct": false, "explanation": "「準備を飲みました」は意味をなさない。"}, {"text": "噛みました", "is_correct": false, "explanation": "「準備を噛みました」は文脈に合わず不自然。"}], "explanations": {"手伝いました": "「発表の準備を手伝いました」で、準備の作業に加わって助けたという意味が通る。", "眠りました": "「準備を眠りました」は成立しない。", "飲みました": "「準備を飲みました」は意味をなさない。", "噛みました": "「準備を噛みました」は文脈に合わず不自然。"}, "sentence_index": 6, "correct_answer": "手伝いました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は運動会の様子を手伝った。", "explanation": "ここは〈撮影〉の意味。映像や写真を撮ることは「撮影する」で、手伝うでは表せない。"}, {"text": "看護師は患者の体温を手伝った。", "explanation": "ここは〈測定〉の意味。数値を計ることは「測定する」で、手伝うは使わない。"}, {"text": "研究者は鳥の動きを手伝った。", "explanation": "ここは〈観察〉の意味。注意深く見ることは「観察する」で、手伝うでは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36925, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は玄関の靴を並べるのを手伝わった。", "corrected_sentence": "兄は玄関の靴を並べるのを手伝った。", "error_description": "「手伝う」の過去形は「手伝った」。「手伝わった」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "手伝った", "is_correct": true, "explanation": "普通形の過去で、スポンジを持って作業を手伝ったという出来事を表す。"}, {"text": "手伝って", "is_correct": false, "explanation": "て形は文末に置けず、文が成り立たない。"}, {"text": "手伝ったら", "is_correct": false, "explanation": "条件節で、文末に置くと文が終わらず成り立たない。"}, {"text": "手伝えば", "is_correct": false, "explanation": "条件節で、文末に置くと文が終わらず成り立たない。"}], "correct_form": "手伝った", "base_form": "手伝う", "form_label": "普通形（過去）", "sentence_index": 1, "explanations": {"手伝った": "普通形の過去で、スポンジを持って作業を手伝ったという出来事を表す。", "手伝って": "て形は文末に置けず、文が成り立たない。", "手伝ったら": "条件節で、文末に置くと文が終わらず成り立たない。", "手伝えば": "条件節で、文末に置くと文が終わらず成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36925, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は教材の準備に手伝ってくれた。", "corrected_sentence": "先生は教材の準備を手伝ってくれた。", "error_description": "「手伝う」は作業を表す語に「を」をとる。「準備に」の「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "手伝わせて", "is_correct": true, "explanation": "使役て形で「～せてもらう」となり、許可を得て作業に加わったという意味になる。"}, {"text": "手伝えて", "is_correct": false, "explanation": "可能のて形で「手伝えてもらった」となり、許可を得た使役の意味にならない。"}, {"text": "手伝わなくて", "is_correct": false, "explanation": "否定のて形で「～せてもらった」の形が成り立たない。"}, {"text": "手伝わせない", "is_correct": false, "explanation": "否定の使役形で、許可を得て手伝った文脈と矛盾する。"}], "correct_form": "手伝わせて", "base_form": "手伝う", "form_label": "使役て形", "sentence_index": 7, "explanations": {"手伝わせて": "使役て形で「～せてもらう」となり、許可を得て作業に加わったという意味になる。", "手伝えて": "可能のて形で「手伝えてもらった」となり、許可を得た使役の意味にならない。", "手伝わなくて": "否定のて形で「～せてもらった」の形が成り立たない。", "手伝わせない": "否定の使役形で、許可を得て手伝った文脈と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「家族で」は一緒に行く人の範囲を示す。"}, {"text": "に", "is_correct": false, "explanation": "「家族に」は相手や到達点を示すので、一緒に行く人を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「家族を」は目的語。「行った」は目的語をとらないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「家族から」は起点を示す。家族が出発点になる文となり、意味が合わない。"}], "correct_answer": "で", "explanations": {"で": "正解。「家族で」は一緒に行く人の範囲を示す。", "に": "「家族に」は相手や到達点を示すので、一緒に行く人を表せない。", "を": "「家族を」は目的語。「行った」は目的語をとらないので合わない。", "から": "「家族から」は起点を示す。家族が出発点になる文となり、意味が合わない。"}, "error_tags": {"に": "相手・到達点の誤り", "を": "目的語の誤り", "から": "起点の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「家族で」は一緒に行く人の範囲を示す。"}, {"text": "を", "is_correct": false, "explanation": "「家族を」は目的語。「行く」は目的語をとらないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「家族から」は起点を示す。家族が出発点になる文となり、意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「家族へ」は向かう相手を示すので、一緒に行く人を表せず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "正解。「家族で」は一緒に行く人の範囲を示す。", "を": "「家族を」は目的語。「行く」は目的語をとらないので合わない。", "から": "「家族から」は起点を示す。家族が出発点になる文となり、意味が合わない。", "へ": "「家族へ」は向かう相手を示すので、一緒に行く人を表せず、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "から": "起点の誤り", "へ": "方向・相手の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お父さんやお母さん、子どもなど、いっしょに住んでいる人のグループのことです。", "primary_collocate": null, "pronunciation": "かぞく", "ipa": "kazokɯ", "syllable_count": 3, "sentences": [{"text": "私の家族は五人で、犬も一匹いる。", "target_word": "家族", "complexity_tier": "T3", "furigana": "わたしのかぞくはごにんで、いぬもいっぴきいる。", "sentence_source": "generated"}, {"text": "夏休みに、家族で海へ行った。", "target_word": "家族", "complexity_tier": "T3", "furigana": "なつやすみに、かぞくでうみへいった。", "sentence_source": "generated"}, {"text": "家族みんなで晩ごはんを食べるのが好きだ。", "target_word": "家族", "complexity_tier": "T3", "furigana": "かぞくみんなでばんごはんをたべるのがすきだ。", "sentence_source": "generated"}, {"text": "姉は家族の中でいちばん料理が上手だ。", "target_word": "家族", "complexity_tier": "T3", "furigana": "あねはかぞくのなかでいちばんりょうりがじょうずだ。", "sentence_source": "generated"}, {"text": "家族の誕生日には、みんなでケーキを作る。", "target_word": "家族", "complexity_tier": "T3", "furigana": "かぞくのたんじょうびには、みんなでケーキをつくる。", "sentence_source": "generated"}, {"text": "引っ越したので、家族の写真を新しい部屋に飾った。", "target_word": "家族", "complexity_tier": "T3", "furigana": "ひっこしたので、かぞくのしゃしんをあたらしいへやにかざった。", "sentence_source": "generated"}, {"text": "家族がそろうまで、夕食を待っていた。", "target_word": "家族", "complexity_tier": "T3", "furigana": "かぞくがそろうまで、ゆうしょくをまっていた。", "sentence_source": "generated"}, {"text": "家族で動物園に行くと、弟はいつも大はしゃぎだ。", "target_word": "家族", "complexity_tier": "T3", "furigana": "かぞくでどうぶつえんにいくと、おとうとはいつもおおはしゃぎだ。", "sentence_source": "generated"}, {"text": "友だちの家族はとても親切で、私にお菓子をくれた。", "target_word": "家族", "complexity_tier": "T3", "furigana": "ともだちのかぞくはとてもしんせつで、わたしにおかしをくれた。", "sentence_source": "generated"}, {"text": "毎年お正月には、家族が祖母の家に集まる。", "target_word": "家族", "complexity_tier": "T3", "furigana": "まいとしおしょうがつには、かぞくがそぼのいえにあつまる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家族", "label": "基本形"}, {"form": "家族たち", "label": "複数形"}, {"form": "ご家族", "label": "敬称形"}], "register": "中立（常体）", "sense_fingerprint": "親や子どもなど同じ家に住む人たちのグループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正解。「私の家族は五人で、犬も一匹いる」は、同じ家で暮らす人数を述べる文として自然。"}, {"text": "同僚", "is_correct": false, "explanation": "同僚は職場の仲間で、同じ家で暮らす人々ではないため、人数と犬の文脈に合わない。"}, {"text": "部員", "is_correct": false, "explanation": "部員は部活動の構成員で、家で暮らす人数の説明には合わない。"}, {"text": "委員会", "is_correct": false, "explanation": "委員会は組織で、犬を飼う家の人数を述べる文の主語にはならない。"}], "explanations": {"家族": "正解。「私の家族は五人で、犬も一匹いる」は、同じ家で暮らす人数を述べる文として自然。", "同僚": "同僚は職場の仲間で、同じ家で暮らす人々ではないため、人数と犬の文脈に合わない。", "部員": "部員は部活動の構成員で、家で暮らす人数の説明には合わない。", "委員会": "委員会は組織で、犬を飼う家の人数を述べる文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "フランス語とスペイン語は同じ家族に属する。", "explanation": "ここは言語学の〈語族〉の意味。家族は人が暮らす集まりを指し、言語の系統分類には使わない。"}, {"text": "大雨で家族の床が傾いたので、業者に修理を頼んだ。", "explanation": "ここは〈家屋〉（建物）の意味。家族は人の集まりなので、建物の床が傾く文には合わない。"}, {"text": "遠縁を含めると、家族は百人を超えた。", "explanation": "ここは〈親族〉（遠縁まで含む血縁の全体）の意味。親族と取り違えやすいが、家族は一緒に住む人々を指すので、同居しない遠縁まで数える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正解。「家族がそろうまで、夕食を待っていた」は、同じ家で暮らす人々が集まるのを待つ意味になり自然。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は物で、夕食のために食卓にそろう集まりではないため、この文の主語として成り立たない。"}, {"text": "植木", "is_correct": false, "explanation": "植木は夕食のために「そろう」ものではなく、この文では成り立たない。"}, {"text": "定規", "is_correct": false, "explanation": "定規は文房具で、夕食を待つ人々のように食卓にそろう主体にはならないため、文が成り立たない。"}], "explanations": {"家族": "正解。「家族がそろうまで、夕食を待っていた」は、同じ家で暮らす人々が集まるのを待つ意味になり自然。", "辞書": "辞書は物で、夕食のために食卓にそろう集まりではないため、この文の主語として成り立たない。", "植木": "植木は夕食のために「そろう」ものではなく、この文では成り立たない。", "定規": "定規は文房具で、夕食を待つ人々のように食卓にそろう主体にはならないため、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜遅く、ようやく家族に帰り着いた。", "explanation": "ここは〈家庭〉（暮らしの場としての家）の意味。家庭と取り違えやすいが、家族は人の集まりなので、帰り着く場所としては使わない。"}, {"text": "ライオンは、ネコと同じ家族に分類される。", "explanation": "ここは生物分類の〈科〉の意味。家族は人が一緒に暮らす集まりを指すので、動物の分類単位には使わない。"}, {"text": "あの名家は代々、家族の繁栄のため婚姻を重ねてきた。", "explanation": "ここは〈一族〉（代々続く血縁の集団）の意味。家族は今同居する人々を指すので、代々続く一族の繁栄の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の家族を、毎週日曜に近くの公園へ散歩に行く。", "corrected_sentence": "私の家族は、毎週日曜に近くの公園へ散歩に行く。", "error_description": "誤りは「家族を」の「を」。正しくは「家族は」の「は」で、家族が散歩に行く主語になる。「を」だと家族が目的語になり、主語のない文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36926, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔母は家族に一緒に、週末に映画を観に行く。", "corrected_sentence": "叔母は家族と一緒に、週末に映画を観に行く。", "error_description": "誤りは「家族に一緒に」の「に」。正しくは「家族と一緒に」の「と」で、「一緒に」は共にする相手を「と」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「家族は」で家族を話題（主題）として示し、その内訳を説明する。"}, {"text": "を", "is_correct": false, "explanation": "「家族を」は目的語を示す。ここは家族の内訳を説明する文なので、目的語にする必要がなく合わない。"}, {"text": "に", "is_correct": false, "explanation": "「家族に」は相手や位置を示す。「家族に両親と姉と私の四人だ」とは続かず、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「家族へ」は向かう相手を示すので、構成員の内訳を述べる文には続かず成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「家族は」で家族を話題（主題）として示し、その内訳を説明する。", "を": "「家族を」は目的語を示す。ここは家族の内訳を説明する文なので、目的語にする必要がなく合わない。", "に": "「家族に」は相手や位置を示す。「家族に両親と姉と私の四人だ」とは続かず、成り立たない。", "へ": "「家族へ」は向かう相手を示すので、構成員の内訳を述べる文には続かず成り立たない。"}, "error_tags": {"を": "目的語の誤り", "に": "相手・位置の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「家族になれる」の「に」は、変化の結果として到達する状態を示す。"}, {"text": "を", "is_correct": false, "explanation": "「家族を」は目的語。「なる」は目的語をとらないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「家族で」は手段や場所を示す。ここは状態の変化先を示す位置なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「家族が」は主語。ここは「なれる」の変化先を示す位置で、主語を置くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「家族になれる」の「に」は、変化の結果として到達する状態を示す。", "を": "「家族を」は目的語。「なる」は目的語をとらないので合わない。", "で": "「家族で」は手段や場所を示す。ここは状態の変化先を示す位置なので合わない。", "が": "「家族が」は主語。ここは「なれる」の変化先を示す位置で、主語を置くと文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "で": "手段・場所の誤り", "が": "主語の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "血縁や婚姻などで結ばれた、一緒に生活する人々の集まり。または、その関係。", "primary_collocate": null, "pronunciation": "かぞく", "ipa": "kazokɯ", "syllable_count": 3, "sentences": [{"text": "最終的に、その雰囲気を取り入れた、木漏れ日が差し込む開放的な小屋が完成し、家族の新たな憩いの場となった。", "target_word": "家族", "complexity_tier": "T4", "furigana": "さいしゅうてきに、そのふんいきをとりいれた、こもれびがさしこむかいほうてきなこやがかんせいし、かぞくのあらたないこいのばとなった。", "sentence_source": "mined"}, {"text": "私の家族は両親と姉と私の四人だ。", "target_word": "家族", "complexity_tier": "T3", "furigana": "わたしのかぞくはりょうしんとあねとわたしのよにんだ。", "sentence_source": "generated"}, {"text": "結婚してから、妻の家族とも親しくなった。", "target_word": "家族", "complexity_tier": "T3", "furigana": "けっこんしてから、つまのかぞくともしたしくなった。", "sentence_source": "generated"}, {"text": "遠くに住んでいても、家族の絆は変わらない。", "target_word": "家族", "complexity_tier": "T3", "furigana": "とおくにすんでいても、かぞくのきずなはかわらない。", "sentence_source": "generated"}, {"text": "彼は家族を養うために、毎日遅くまで働いている。", "target_word": "家族", "complexity_tier": "T3", "furigana": "かれはかぞくをやしなうために、まいにちおそくまではたらいている。", "sentence_source": "generated"}, {"text": "日曜日は家族そろって祖父母の家を訪ねる。", "target_word": "家族", "complexity_tier": "T3", "furigana": "にちようびはかぞくそろってそふぼのいえをたずねる。", "sentence_source": "generated"}, {"text": "家族が増えたので、もっと広い家に引っ越すことにした。", "target_word": "家族", "complexity_tier": "T3", "furigana": "かぞくがふえたので、もっとひろいいえにひっこすことにした。", "sentence_source": "generated"}, {"text": "血のつながりがなくても、長く暮らせば本当の家族になれる。", "target_word": "家族", "complexity_tier": "T3", "furigana": "ちのつながりがなくても、ながくくらせばほんとうのかぞくになれる。", "sentence_source": "generated"}, {"text": "病気の母を家族みんなで支えた。", "target_word": "家族", "complexity_tier": "T3", "furigana": "びょうきのははをかぞくみんなでささえた。", "sentence_source": "generated"}, {"text": "転勤が決まり、家族と相談したうえで返事をすることにした。", "target_word": "家族", "complexity_tier": "T3", "furigana": "てんきんがきまり、かぞくとそうだんしたうえでへんじをすることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家族", "label": "基本形"}, {"form": "家族たち", "label": "複数形"}, {"form": "ご家族", "label": "敬称形"}], "register": "中立（常体）", "sense_fingerprint": "血縁や婚姻で結ばれ共に暮らす人々の集まりやその関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 木漏れ日 (Zipf 2.6), 差し込む (Zipf 3.05), 憩い (Zipf 3.01)','sentence 5 above tier T1: 3 words above tier T1 (max 2): そろっ (Zipf 3.78), 祖父母 (Zipf 3.47), 訪ねる (Zipf 3.3)']::text[], 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正解。「家族の新たな憩いの場」は、血縁や婚姻で結ばれ一緒に暮らす人々の集まりとして自然に続く。"}, {"text": "税金", "is_correct": false, "explanation": "税金は納める金銭で、小屋を憩いの場として使う人々の集まりではないため文が通らない。"}, {"text": "書類", "is_correct": false, "explanation": "書類は文書で、小屋を憩いの場として使う主体にはならないため文が成り立たない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は出版物で、小屋が憩いの場になるという文の主語にはならないため不自然。"}], "explanations": {"家族": "正解。「家族の新たな憩いの場」は、血縁や婚姻で結ばれ一緒に暮らす人々の集まりとして自然に続く。", "税金": "税金は納める金銭で、小屋を憩いの場として使う人々の集まりではないため文が通らない。", "書類": "書類は文書で、小屋を憩いの場として使う主体にはならないため文が成り立たない。", "雑誌": "雑誌は出版物で、小屋が憩いの場になるという文の主語にはならないため不自然。"}, "sentence_index": 0, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カエルは両生類の家族に分類される。", "explanation": "ここは生物分類の〈科〉の意味。家族は人が一緒に暮らす集まりを指すので、動物の分類単位には使わない。"}, {"text": "仕事を終えて、やっと家族に帰った。", "explanation": "ここは〈家庭〉（暮らしの場としての家）の意味。家族は人の集まりなので、帰る先の場所としては使わない。"}, {"text": "この二つの料理は、同じ家族に分類される。", "explanation": "ここは〈類〉（同系統にまとめた分類）の意味。家族は人が一緒に暮らす集まりを指すので、料理の分類には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家族", "is_correct": true, "explanation": "正解。「家族が増えた」は一緒に暮らす人が増えたことを示し、広い家に引っ越す理由になる。"}, {"text": "社員", "is_correct": false, "explanation": "社員は会社に勤める人を指し、一緒に住む人の増加を表さないため、引っ越しの理由にならない。"}, {"text": "部員", "is_correct": false, "explanation": "部員は部活動の構成員で、住まいを広げる理由にはならないので合わない。"}, {"text": "生徒", "is_correct": false, "explanation": "生徒は学校に通う人で、一緒に住む人数の増加を表さないため、引っ越しの理由に合わない。"}], "explanations": {"家族": "正解。「家族が増えた」は一緒に暮らす人が増えたことを示し、広い家に引っ越す理由になる。", "社員": "社員は会社に勤める人を指し、一緒に住む人の増加を表さないため、引っ越しの理由にならない。", "部員": "部員は部活動の構成員で、住まいを広げる理由にはならないので合わない。", "生徒": "生徒は学校に通う人で、一緒に住む人数の増加を表さないため、引っ越しの理由に合わない。"}, "sentence_index": 6, "correct_answer": "家族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家族が古くなり、来月建て替えることになった。", "explanation": "ここは〈家屋〉（建物）の意味。家屋と取り違えやすいが、家族は人の集まりなので、建物の老朽化には使えない。"}, {"text": "英語とドイツ語は同じ家族に分類される。", "explanation": "ここは言語学の〈語族〉の意味。家族は人が暮らす集まりを指し、言語の系統の分類には使わない。"}, {"text": "その図書館は、家族の本を五千冊所蔵している。", "explanation": "ここは〈書籍の集まり〉の意味。家族は人の集まりなので、本の集まりを指す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は家族に一緒に、毎年夏に温泉へ行く。", "corrected_sentence": "祖父は家族と一緒に、毎年夏に温泉へ行く。", "error_description": "誤りは「家族に」の「に」。正しくは「家族と一緒に」の「と」で、「一緒に」は共にする相手を「と」で示す。「家族に一緒に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36927, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "久しぶりに家族を会えて、とてもうれしかった。", "corrected_sentence": "久しぶりに家族と会えて、とてもうれしかった。", "error_description": "誤りは「家族を会えて」の「を」。「会う」は「と」で相手を示すので、正しくは「家族と会えて」。「を」は目的語を示すが、「会う」の相手には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
