INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36928, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いいと思うことを、してほしいと人に言うこと。", "primary_collocate": null, "pronunciation": "すすめる", "ipa": "sɯsɯme̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "医者は父に、毎日少し歩くことを勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "医者[いしゃ]は父[ちち]に、毎日[まいにち]少[すこ]し歩[ある]くことを勧[すす]めた。", "sentence_source": "generated"}, {"text": "友達が勧めてくれた店は、とても安くておいしかった。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "友達[ともだち]が勧[すす]めてくれた店[みせ]は、とても安[やす]くておいしかった。", "sentence_source": "generated"}, {"text": "先生に留学を勧められて、本気で考え始めた。", "target_word": "勧められて", "complexity_tier": "T3", "furigana": "先生[せんせい]に留学[りゅうがく]を勧[すす]められて、本気[ほんき]で考[かんが]え始[はじ]めた。", "sentence_source": "generated"}, {"text": "私はこの本を、ぜひ高校生に勧めたい。", "target_word": "勧めたい", "complexity_tier": "T3", "furigana": "私[わたし]はこの本[ほん]を、ぜひ高校生[こうこうせい]に勧[すす]めたい。", "sentence_source": "generated"}, {"text": "母は風邪をひいた私に、早く休むよう勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "母[はは]は風邪[かぜ]をひいた私[わたし]に、早[はや]く休[やす]むよう勧[すす]めた。", "sentence_source": "generated"}, {"text": "店員が新しい商品を勧めてきたが、私は買わなかった。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "店員[てんいん]が新[あたら]しい商品[しょうひん]を勧[すす]めてきたが、私[わたし]は買[か]わなかった。", "sentence_source": "generated"}, {"text": "駅員は、混んでいるので別の道を使うよう勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "駅員[えきいん]は、混[こ]んでいるので別[べつ]の道[みち]を使[つか]うよう勧[すす]めた。", "sentence_source": "generated"}, {"text": "山田さんに勧められた映画を、週末に見に行った。", "target_word": "勧められた", "complexity_tier": "T3", "furigana": "山田[やまだ]さんに勧[すす]められた映画[えいが]を、週末[しゅうまつ]に見[み]に行[い]った。", "sentence_source": "generated"}, {"text": "先生は生徒に、毎日日記を書くことを勧めている。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、毎日[まいにち]日記[にっき]を書[か]くことを勧[すす]めている。", "sentence_source": "generated"}, {"text": "友人が転職を勧めるので、一度会社の人と話してみた。", "target_word": "勧める", "complexity_tier": "T3", "furigana": "友人[ゆうじん]が転職[てんしょく]を勧[すす]めるので、一度[いちど]会社[かいしゃ]の人[ひと]と話[はな]してみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勧める", "label": "基本形"}, {"form": "勧めない", "label": "否定形"}, {"form": "勧めます", "label": "丁寧形"}, {"form": "勧めて", "label": "て形"}, {"form": "勧めた", "label": "た形"}, {"form": "勧められる", "label": "受身形"}, {"form": "勧めれば", "label": "仮定形"}, {"form": "勧めよう", "label": "意向形"}], "register": "中立", "sense_fingerprint": "よいと思うことを相手に言って、してみるよう提案する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36928, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勧めた", "is_correct": true, "explanation": "正解。過去の出来事として「歩くことを勧めた」の形で文を完成させる。"}, {"text": "食べた", "is_correct": false, "explanation": "「歩くことを食べた」は意味をなさず、空欄に入らない。"}, {"text": "並べた", "is_correct": false, "explanation": "「歩くことを並べた」は文として成り立たず、空欄に入らない。"}, {"text": "磨いた", "is_correct": false, "explanation": "「歩くことを磨いた」は意味をなさず、空欄に入らない。"}], "explanations": {"勧めた": "正解。過去の出来事として「歩くことを勧めた」の形で文を完成させる。", "食べた": "「歩くことを食べた」は意味をなさず、空欄に入らない。", "並べた": "「歩くことを並べた」は文として成り立たず、空欄に入らない。", "磨いた": "「歩くことを磨いた」は意味をなさず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "勧めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議を勧めた。", "explanation": "ここは〈進める〉の意味（物事を先へ動かす）。〈勧める〉は人に何かをしてほしいと言う意味で、会議には使わない。"}, {"text": "父は大手銀行に勧めて、毎朝通っている。", "explanation": "〈勤める〉（会社で働く）と取り違えている。〈勧める〉は人に言う意味で、働く場所には使わない。"}, {"text": "先生は窓を勧めて、教室の空気を入れ替えた。", "explanation": "ここは〈開ける〉の意味。〈勧める〉は人に何かをするよう言う意味で、窓のような物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36928, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勧めた", "is_correct": true, "explanation": "正解。駅員が別の道を使うよう提案した過去の出来事として文が成り立つ。"}, {"text": "脱いだ", "is_correct": false, "explanation": "「別の道を使うよう脱いだ」は意味をなさず、空欄に入らない。"}, {"text": "数えた", "is_correct": false, "explanation": "「別の道を使うよう数えた」は文として成り立たず、空欄に入らない。"}, {"text": "焼いた", "is_correct": false, "explanation": "「別の道を使うよう焼いた」は意味をなさず、空欄に入らない。"}], "explanations": {"勧めた": "正解。駅員が別の道を使うよう提案した過去の出来事として文が成り立つ。", "脱いだ": "「別の道を使うよう脱いだ」は意味をなさず、空欄に入らない。", "数えた": "「別の道を使うよう数えた」は文として成り立たず、空欄に入らない。", "焼いた": "「別の道を使うよう焼いた」は意味をなさず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "勧めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で、議題を勧めて、予定通り終わらせた。", "explanation": "ここは〈進める〉の意味（話を先へ動かす）。〈勧める〉は人にしてほしいと言う意味で、議題には使わない。"}, {"text": "来客に、この部屋の鍵を勧めた。", "explanation": "ここは〈渡す〉の意味。〈勧める〉は人に言う意味で、鍵のような物を渡すには〈渡す〉を使う。"}, {"text": "私は書類を勧めた。", "explanation": "物を手渡すときは〈差し出す〉を使う。〈勧める〉は人に言う行為で、書類には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36928, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒を読書を勧めた。", "corrected_sentence": "先生は生徒に読書を勧めた。", "error_description": "「勧める」は勧める相手を「に」で示す。「を」は誤りで、「生徒に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "勧めて", "is_correct": true, "explanation": "正解。て形で、「くれた」に続けて「勧めてくれた店」の形を作る。"}, {"text": "勧める", "is_correct": false, "explanation": "基本形は「くれた」に続けられず、「勧めるくれた」となり不自然。"}, {"text": "勧めた", "is_correct": false, "explanation": "た形では「勧めたくれた」となり、文法的に続かない。"}, {"text": "勧めない", "is_correct": false, "explanation": "否定形で、意味が逆になり文脈に合わない。"}], "correct_form": "勧めて", "base_form": "勧める", "form_label": "て形", "sentence_index": 1, "explanations": {"勧めて": "正解。て形で、「くれた」に続けて「勧めてくれた店」の形を作る。", "勧める": "基本形は「くれた」に続けられず、「勧めるくれた」となり不自然。", "勧めた": "た形では「勧めたくれた」となり、文法的に続かない。", "勧めない": "否定形で、意味が逆になり文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36928, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は弟を暑い日は水を飲むよう勧めた。", "corrected_sentence": "母は弟に暑い日は水を飲むよう勧めた。", "error_description": "「勧める」は勧める相手を「に」で示す。「を」は誤りで、「弟に」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "勧められた", "is_correct": true, "explanation": "正解。受身の連体形で、名詞「映画」を修飾して「勧められた映画」になる。"}, {"text": "勧めよう", "is_correct": false, "explanation": "意向形で「勧めることにしよう」の意味になり、名詞「映画」を修飾できない。"}, {"text": "勧めれば", "is_correct": false, "explanation": "仮定形で、名詞「映画」を修飾できず文が成り立たない。"}, {"text": "勧めます", "is_correct": false, "explanation": "丁寧形で、名詞「映画」を直接修飾できない。"}], "correct_form": "勧められた", "base_form": "勧める", "form_label": "受身の過去形", "sentence_index": 7, "explanations": {"勧められた": "正解。受身の連体形で、名詞「映画」を修飾して「勧められた映画」になる。", "勧めよう": "意向形で「勧めることにしよう」の意味になり、名詞「映画」を修飾できない。", "勧めれば": "仮定形で、名詞「映画」を修飾できず文が成り立たない。", "勧めます": "丁寧形で、名詞「映画」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「勧める」の対象（ごみの分別）を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「分別が勧める」では分別が動作主になり、文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「分別へ勧める」では勧める対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾するが、「分別の勧めている」では文として続かない。"}], "correct_answer": "を", "explanations": {"を": "「勧める」の対象（ごみの分別）を示す格助詞。", "が": "「分別が勧める」では分別が動作主になり、文に合わない。", "へ": "方向を表すが、「分別へ勧める」では勧める対象を示せない。", "の": "名詞を修飾するが、「分別の勧めている」では文として続かない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「勧める」の対象（挑戦）を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「挑戦に勧めた」は勧める対象を示せず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「挑戦から勧めた」は勧める対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、「挑戦で勧めた」は文として続かない。"}], "correct_answer": "を", "explanations": {"を": "「勧める」の対象（挑戦）を示す格助詞。", "に": "「挑戦に勧めた」は勧める対象を示せず、不自然。", "から": "起点を表すが、「挑戦から勧めた」は勧める対象にならない。", "で": "手段を表すが、「挑戦で勧めた」は文として続かない。"}, "error_tags": {"に": "位置・相手", "から": "起点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある行為や物事を、相手にとって良いこととして進めて、実行するように促す。", "primary_collocate": null, "pronunciation": "すすめる", "ipa": "sɯsɯme̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "医者は患者に、禁煙を勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]に、禁煙[きんえん]を勧[すす]めた。", "sentence_source": "generated"}, {"text": "市は住民にごみの分別を勧めている。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "市[し]は住民[じゅうみん]にごみの分別[ぶんべつ]を勧[すす]めている。", "sentence_source": "generated"}, {"text": "上司に昇進試験を受けるよう勧められた。", "target_word": "勧められた", "complexity_tier": "T3", "furigana": "上司[じょうし]に昇進[しょうしん]試験[しけん]を受[う]けるよう勧[すす]められた。", "sentence_source": "generated"}, {"text": "友人は私に、早めに病院へ行くことを勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "友[ゆう]人[じん]は私[わたし]に、早[はや]めに病[びょう]院[いん]へ行[い]くことを勧[すす]めた。", "sentence_source": "generated"}, {"text": "祖母は孫に、毎日少し歩くことを勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "祖[そ]母[ぼ]は孫[まご]に、毎[まい]日[にち]少[すこ]し歩[ある]くことを勧[すす]めた。", "sentence_source": "generated"}, {"text": "学校は生徒に、朝ごはんを食べることを勧めている。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "学校[がっこう]は生徒[せいと]に、朝[あさ]ごはんを食[た]べることを勧[すす]めている。", "sentence_source": "generated"}, {"text": "兄は私に運動を勧めたが、忙しくて続かなかった。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]に運動[うんどう]を勧[すす]めたが、忙[いそが]しくて続[つづ]かなかった。", "sentence_source": "generated"}, {"text": "彼女は友人に、新しい仕事への挑戦を勧めた。", "target_word": "勧めた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は友人[ゆうじん]に、新[あたら]しい仕事[しごと]への挑戦[ちょうせん]を勧[すす]めた。", "sentence_source": "generated"}, {"text": "店の人が試食を勧めてくれたので、一つ食べてみた。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]が試食[ししょく]を勧[すす]めてくれたので、一[ひと]つ食[た]べてみた。", "sentence_source": "generated"}, {"text": "先生は私に、大学院に進むことを勧めてくれた。", "target_word": "勧めて", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]に、大学院[だいがくいん]に進[すす]むことを勧[すす]めてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勧める", "label": "基本形"}, {"form": "勧めない", "label": "否定形"}, {"form": "勧めます", "label": "丁寧形"}, {"form": "勧めて", "label": "て形"}, {"form": "勧めた", "label": "た形"}, {"form": "勧められる", "label": "受身形"}, {"form": "勧めれば", "label": "仮定形"}, {"form": "勧めよう", "label": "意向形"}], "register": "中立", "sense_fingerprint": "相手のためによいこととして、行動や物を実行・利用するよう促す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勧めた", "is_correct": true, "explanation": "「勧める」の過去形。医者が患者に健康のため禁煙を促す文に合う。"}, {"text": "吸った", "is_correct": false, "explanation": "「吸う」は喫煙の動作で、「禁煙を吸った」は組み合わせが成り立たず空所に入らない。"}, {"text": "配った", "is_correct": false, "explanation": "「配る」は物を分ける動作で、「禁煙を配った」は意味をなさない。"}, {"text": "読んだ", "is_correct": false, "explanation": "「読む」は文字を追う動作で、「禁煙を読んだ」は文として成り立たない。"}], "explanations": {"勧めた": "「勧める」の過去形。医者が患者に健康のため禁煙を促す文に合う。", "吸った": "「吸う」は喫煙の動作で、「禁煙を吸った」は組み合わせが成り立たず空所に入らない。", "配った": "「配る」は物を分ける動作で、「禁煙を配った」は意味をなさない。", "読んだ": "「読む」は文字を追う動作で、「禁煙を読んだ」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "勧めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "運転手はトラックを、ゆっくり前へ勧めた。", "explanation": "ここは「進める（前へ動かす）」の意味。勧めるは人に行動を促す語で、乗り物を動かすことには使わないので合わない。"}, {"text": "母は弟の失敗を、きつく勧めた。", "explanation": "ここは「責める（過ちを咎める）」の意味。勧めるは相手のためになることとして促す語で、人の失敗を責める場面には合わない。"}, {"text": "泥棒は店の金を勧めた。", "explanation": "ここは「盗む」の意味。勧めるは相手のためになることを促す語で、人の物を奪う行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勧めた", "is_correct": true, "explanation": "「勧める」の過去形。兄が私に運動を促した意味で文に合う。"}, {"text": "洗った", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「運動を洗った」は意味をなさない。"}, {"text": "買った", "is_correct": false, "explanation": "「買う」は品物を手に入れる動作で、「運動を買った」は組み合わせが成り立たない。"}, {"text": "運んだ", "is_correct": false, "explanation": "「運ぶ」は物を移す動作で、「運動を運んだ」は文として成り立たない。"}], "explanations": {"勧めた": "「勧める」の過去形。兄が私に運動を促した意味で文に合う。", "洗った": "「洗う」は汚れを落とす動作で、「運動を洗った」は意味をなさない。", "買った": "「買う」は品物を手に入れる動作で、「運動を買った」は組み合わせが成り立たない。", "運んだ": "「運ぶ」は物を移す動作で、「運動を運んだ」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "勧めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察官は、無実の男の秘密を勧めた。", "explanation": "ここは「暴露する（秘密を明かす）」の意味。勧めるは良いこととして促す語で、秘密を明かす行為には合わない。"}, {"text": "彼は被害者に、自分の過ちを勧めた。", "explanation": "ここは「謝る（詫びる）」の意味。勧めるは行動を促す語で、過ちを詫びる場面には合わない。"}, {"text": "父は会議の議題を、次の回へ勧めた。", "explanation": "ここは「先送りする（次へ回す）」の意味。勧めるは人に行動を促す語で、議題を次に回す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒に、毎日予習することに勧めた。", "corrected_sentence": "先生は生徒に、毎日予習することを勧めた。", "error_description": "「勧める」の目的語は「ことを」で示す。「ことに」は誤りで、正しくは「ことを」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "勧めて", "is_correct": true, "explanation": "「勧めている」の「て」形。「〜ている」の進行の形で、文の述べ方に合う。"}, {"text": "勧めない", "is_correct": false, "explanation": "否定形。「勧めていない」となり、市が分別を勧めているという内容と合わない。"}, {"text": "勧められ", "is_correct": false, "explanation": "受身形の連用形。市が勧められる側になり、文の主語と意味が合わない。"}, {"text": "勧めれば", "is_correct": false, "explanation": "仮定形。条件を表し、「勧めている」の進行の文とは続かない。"}], "correct_form": "勧めて", "base_form": "勧める", "form_label": "て形", "sentence_index": 1, "explanations": {"勧めて": "「勧めている」の「て」形。「〜ている」の進行の形で、文の述べ方に合う。", "勧めない": "否定形。「勧めていない」となり、市が分別を勧めているという内容と合わない。", "勧められ": "受身形の連用形。市が勧められる側になり、文の主語と意味が合わない。", "勧めれば": "仮定形。条件を表し、「勧めている」の進行の文とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36929, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩は後輩に、早めに資格を取ることを勧めるた。", "corrected_sentence": "先輩は後輩に、早めに資格を取ることを勧めた。", "error_description": "「勧める」に直接「た」をつけることはできない。語幹「勧め」に「た」をつけて、正しくは「勧めた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "勧めた", "is_correct": true, "explanation": "「勧める」の「た」形。過去に友人へ挑戦を促した文に合う。"}, {"text": "勧めよう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、過去の出来事を述べる文と合わない。"}, {"text": "勧めて", "is_correct": false, "explanation": "て形。文末に置けず、「挑戦を勧めて。」では文が成り立たない。"}, {"text": "勧めます", "is_correct": false, "explanation": "丁寧形。普通体の文に混ざり、文体が合わない。"}], "correct_form": "勧めた", "base_form": "勧める", "form_label": "た形", "sentence_index": 7, "explanations": {"勧めた": "「勧める」の「た」形。過去に友人へ挑戦を促した文に合う。", "勧めよう": "意向形。「〜しよう」の意味になり、過去の出来事を述べる文と合わない。", "勧めて": "て形。文末に置けず、「挑戦を勧めて。」では文が成り立たない。", "勧めます": "丁寧形。普通体の文に混ざり、文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理論", "is_correct": true, "explanation": "対義語。頭の中で組み立てる考えと、実際に行うことという対になる関係にある。"}, {"text": "感覚", "is_correct": false, "explanation": "感覚は感じ取る働きを指し、理論との対義関係にはならない。"}, {"text": "伝統", "is_correct": false, "explanation": "伝統は受け継がれてきたものを指し、理論と実践の対義関係には当たらない。"}, {"text": "財産", "is_correct": false, "explanation": "財産は所有するものを指し、実践との対義関係にはならない。"}], "correct_answer": "理論", "explanations": {"理論": "対義語。頭の中で組み立てる考えと、実際に行うことという対になる関係にある。", "感覚": "感覚は感じ取る働きを指し、理論との対義関係にはならない。", "伝統": "伝統は受け継がれてきたものを指し、理論と実践の対義関係には当たらない。", "財産": "財産は所有するものを指し、実践との対義関係にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理論", "is_correct": true, "explanation": "対義語。頭の中で組み立てる考えと、実際に行うことという対になる関係にある。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心に生じる気持ちを指し、理論と実践の対義関係には当たらない。"}, {"text": "空想", "is_correct": false, "explanation": "空想は頭の中で思い描くことを指し、実践と対になる語としては一般的ではない。"}, {"text": "慣習", "is_correct": false, "explanation": "慣習は社会で繰り返されてきたならわしを指し、理論との対義関係にはならない。"}], "correct_answer": "理論", "explanations": {"理論": "対義語。頭の中で組み立てる考えと、実際に行うことという対になる関係にある。", "感情": "感情は心に生じる気持ちを指し、理論と実践の対義関係には当たらない。", "空想": "空想は頭の中で思い描くことを指し、実践と対になる語としては一般的ではない。", "慣習": "慣習は社会で繰り返されてきたならわしを指し、理論との対義関係にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "考えや理論を、実際の行動や活動に移すこと。", "primary_collocate": null, "pronunciation": "じっせん", "ipa": "dʑisseɴ", "syllable_count": 4, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "実践", "complexity_tier": "T5", "furigana": "かかる感覚的[かんかくてき]知見[ちけん]の蓄積[ちくせき]は、単一[たんいつ]品種[ひんしゅ]を基準[きじゅん]とした旧来[きゅうらい]の分類[ぶんるい]体系[たいけい]を相対化[そうたいか]し、微細[びさい]な区画[くかく]ごとの個性[こせい]を階層的[かいそうてき]に位置[いち]づけるアペラシオンの概念[がいねん]を、より厳密[げんみつ]かつ動的[どうてき]なヒエラルキーへと昇華[しょうか]させ、ワインの価値[かち]評価[ひょうか]基準[きじゅん]そのものを哲学的[てつがくてき]かつ実践的[じっせんてき]に再定義[さいていぎ]しているのである。", "sentence_source": "mined"}, {"text": "理論を学ぶだけでなく、実践することが大切だ。", "target_word": "実践", "complexity_tier": "T3", "furigana": "理論[りろん]を学[まな]ぶだけでなく、実践[じっせん]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "授業で習った方法を、日々の仕事で実践している。", "target_word": "実践", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で習[なら]った方法[ほうほう]を、日々[ひび]の仕事[しごと]で実践[じっせん]している。", "sentence_source": "generated"}, {"text": "彼は環境保護の考えを自分の生活で実践した。", "target_word": "実践", "complexity_tier": "T3", "furigana": "彼[かれ]は環境[かんきょう]保護[ほご]の考[かんが]えを自分[じぶん]の生活[せいかつ]で実践[じっせん]した。", "sentence_source": "generated"}, {"text": "教育理論は、現場での実践を通して見直されていく。", "target_word": "実践", "complexity_tier": "T4", "furigana": "教育[きょういく]理論[りろん]は、現場[げんば]での実践[じっせん]を通[とお]して見直[みなお]されていく。", "sentence_source": "generated"}, {"text": "計画は立派だが、実践が伴わなければ意味がない。", "target_word": "実践", "complexity_tier": "T4", "furigana": "計画[けいかく]は立派[りっぱ]だが、実践[じっせん]が伴[ともな]わなければ意味[いみ]がない。", "sentence_source": "generated"}, {"text": "医学部では、講義のあとに臨床での実践が待っている。", "target_word": "実践", "complexity_tier": "T4", "furigana": "医学部[いがくぶ]では、講義[こうぎ]のあとに臨床[りんしょう]での実践[じっせん]が待[ま]っている。", "sentence_source": "generated"}, {"text": "先生の教えを実践してみたら、成績が少しずつ上がった。", "target_word": "実践", "complexity_tier": "T3", "furigana": "先生[せんせい]の教[おし]えを実践[じっせん]してみたら、成績[せいせき]が少[すこ]しずつ上[あ]がった。", "sentence_source": "generated"}, {"text": "研究者の提案を、地域の学校が実践に移した。", "target_word": "実践", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]の提案[ていあん]を、地域[ちいき]の学校[がっこう]が実践[じっせん]に移[うつ]した。", "sentence_source": "generated"}, {"text": "言うのは簡単だが、実践するとなると多くの壁がある。", "target_word": "実践", "complexity_tier": "T3", "furigana": "言[い]うのは簡単[かんたん]だが、実践[じっせん]するとなると多[おお]くの壁[かべ]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実践する", "label": "dictionary form (suru verb)"}, {"form": "実践した", "label": "past"}, {"form": "実践的", "label": "adjectival (-teki)"}], "register": "formal", "sense_fingerprint": "理論や考えを実際の行動に移すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: アペラシオン (Zipf 1.01)']::text[], '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実践", "is_correct": true, "explanation": "「実践的」の形で入り、理論を行動に移す観点から哲学と合わせて再定義するという文意に合う。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄的に」は捨てるという意味になり、哲学的かつ再定義するという文の流れと合わない。"}, {"text": "解消", "is_correct": false, "explanation": "「解消的に」は取り除く意味になり、哲学的に再定義するという文の流れに合わない。"}, {"text": "欠如", "is_correct": false, "explanation": "「欠如的に」は足りない状態を表す形になり、再定義の仕方として文意が通らない。"}], "explanations": {"実践": "「実践的」の形で入り、理論を行動に移す観点から哲学と合わせて再定義するという文意に合う。", "放棄": "「放棄的に」は捨てるという意味になり、哲学的かつ再定義するという文の流れと合わない。", "解消": "「解消的に」は取り除く意味になり、哲学的に再定義するという文の流れに合わない。", "欠如": "「欠如的に」は足りない状態を表す形になり、再定義の仕方として文意が通らない。"}, "sentence_index": 0, "correct_answer": "実践"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は昨日、社員の意見を集めるアンケートを実践した。", "explanation": "ここは〈実施〉の意味。調査や行事を行うことは実施と言い、実践は考えや理論を行動に移すことを指すので合わない。"}, {"text": "新しい機能をアプリに実践した。", "explanation": "ここは〈実装〉の意味。ソフトの機能を組み込むことは実装と言い、実践は考えを行動に移すことを指すので合わない。"}, {"text": "新しいエンジンを実践して、異音がないか確かめた。", "explanation": "ここは〈試運転〉の意味。機械を動かして確かめることは試運転と言い、考えを行動に移す実践とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実践", "is_correct": true, "explanation": "医学部の講義の後に臨床で待っているものとして、実際に行うことを表す語が合う。"}, {"text": "睡眠", "is_correct": false, "explanation": "「臨床での睡眠が待っている」は成り立たず、講義の後の臨床の場面に合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「臨床での雑談が待っている」は臨床の課題の流れに合わず、文意が通らない。"}, {"text": "辞退", "is_correct": false, "explanation": "「臨床での辞退が待っている」は辞退する行為が待つという意味になり、文の流れに合わない。"}], "explanations": {"実践": "医学部の講義の後に臨床で待っているものとして、実際に行うことを表す語が合う。", "睡眠": "「臨床での睡眠が待っている」は成り立たず、講義の後の臨床の場面に合わない。", "雑談": "「臨床での雑談が待っている」は臨床の課題の流れに合わず、文意が通らない。", "辞退": "「臨床での辞退が待っている」は辞退する行為が待つという意味になり、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "実践"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアノを実践した。", "explanation": "ここは〈演奏〉の意味。楽器を弾いて音を出すことは演奏と言い、実践は考えを行動に移すことなので合わない。"}, {"text": "星の動きを実践した。", "explanation": "ここは〈観察〉の意味。注意深く見て調べることは観察と言い、実践は考えを行動に移すことを指すので合わない。"}, {"text": "新作映画の内容を実践した。", "explanation": "ここは〈評論〉の意味。作品を論じて評価することは評論と言い、実践は批評の意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考えを実践で移すには、まず小さく始めることが大切だ。", "corrected_sentence": "考えを実践に移すには、まず小さく始めることが大切だ。", "error_description": "「移す」は到達点を表す「に」を取るので、手段の「で」は誤り。正しくは「実践に移す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36931, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その理論を実践おかげで、現場の問題が減った。", "corrected_sentence": "その理論を実践したおかげで、現場の問題が減った。", "error_description": "「おかげで」は直前に動詞の過去形（「実践したおかげで」）か、名詞＋「の」（「実践のおかげで」）が必要。「実践おかげで」は「した」も「の」もなく、続かない誤り。正しくは「実践したおかげで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36932, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「近年は」と主題を示し、文の始めに自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「近年を」は目的語になり、後の文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「近年で」は場所や手段の意味になり、ここでは不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「近年へ」は方向を表すが、時を表す語には合わない。"}], "correct_answer": "は", "explanations": {"は": "正解。「近年は」と主題を示し、文の始めに自然につながる。", "を": "「近年を」は目的語になり、後の文が成り立たない。", "で": "「近年で」は場所や手段の意味になり、ここでは不自然。", "へ": "「近年へ」は方向を表すが、時を表す語には合わない。"}, "error_tags": {"を": "object", "で": "means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
