INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36932, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ここ数年、今に至るまでの数年間のこと。", "primary_collocate": null, "pronunciation": "きんねん", "ipa": "kiɴneɴ", "syllable_count": 4, "sentences": [{"text": "近年、この町に住む外国人が増えています。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]、この町[まち]に住[す]む外国人[がいこくじん]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "近年は夏の暑さが厳しくなりました。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]は夏[なつ]の暑[あつ]さが厳[きび]しくなりました。", "sentence_source": "generated"}, {"text": "近年の技術の進歩は、とても速いです。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]の技術[ぎじゅつ]の進歩[しんぽ]は、とても速[はや]いです。", "sentence_source": "generated"}, {"text": "近年、紙の本を読む人が少なくなっています。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]、紙[かみ]の本[ほん]を読[よ]む人[ひと]が少[すく]なくなっています。", "sentence_source": "generated"}, {"text": "近年は、自転車で通勤する人が多くなりました。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]は、自転車[じてんしゃ]で通勤[つうきん]する人[ひと]が多[おお]くなりました。", "sentence_source": "generated"}, {"text": "この川では、近年めったに魚が釣れません。", "target_word": "近年", "complexity_tier": "T3", "furigana": "この川[かわ]では、近年[きんねん]めったに魚[さかな]が釣[つ]れません。", "sentence_source": "generated"}, {"text": "近年になって、やっと駅前に新しい店ができました。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]になって、やっと駅前[えきまえ]に新[あたら]しい店[みせ]ができました。", "sentence_source": "generated"}, {"text": "昔は人が多かったですが、近年は静かな村になりました。", "target_word": "近年", "complexity_tier": "T3", "furigana": "昔[むかし]は人[ひと]が多[おお]かったですが、近年[きんねん]は静[しず]かな村[むら]になりました。", "sentence_source": "generated"}, {"text": "近年の子どもたちは、小さいころからスマホを使っています。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]の子[こ]どもたちは、小[ちい]さいころからスマホを使[つか]っています。", "sentence_source": "generated"}, {"text": "近年、日本の冬は雪が少ない年が続いています。", "target_word": "近年", "complexity_tier": "T3", "furigana": "近年[きんねん]、日本[にほん]の冬[ふゆ]は雪[ゆき]が少[すく]ない年[とし]が続[つづ]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近年", "label": "基本形"}], "register": "written", "sense_fingerprint": "recent years: the last several years up to the present, used to describe a trend", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36932, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正解。「近年、外国人が増えている」は最近数年の傾向を表し、自然。"}, {"text": "大昔", "is_correct": false, "explanation": "大昔は遠い過去なので、今増えているという話には合わない。"}, {"text": "郊外", "is_correct": false, "explanation": "郊外は場所を表すので、ここでは「増えています」の主語として成り立たない。"}, {"text": "海外", "is_correct": false, "explanation": "海外は場所を表すので、この町に住む人の話には合わない。"}], "explanations": {"近年": "正解。「近年、外国人が増えている」は最近数年の傾向を表し、自然。", "大昔": "大昔は遠い過去なので、今増えているという話には合わない。", "郊外": "郊外は場所を表すので、ここでは「増えています」の主語として成り立たない。", "海外": "海外は場所を表すので、この町に住む人の話には合わない。"}, "sentence_index": 0, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近年、先日町で財布を落としました。", "explanation": "ここは〈先日〉（ある時点の出来事）の意味。近年は数年にわたる傾向に使うので、一度きりの出来事とは合わない。"}, {"text": "近年、この日の空はよく晴れていました。", "explanation": "ここは〈その日〉（ある特定の一日）の意味。近年は数年単位なので、一日の天気とは合わない。"}, {"text": "近年、午前中に新しい店がオープンしました。", "explanation": "ここは〈今日の午前〉（ある一日の時間帯）の意味。近年は数年の期間を指すので、一日の時間帯とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36932, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近年", "is_correct": true, "explanation": "正解。「近年になって、やっと新しい店ができた」は時期を示し、自然。"}, {"text": "屋上", "is_correct": false, "explanation": "屋上は場所を表すので、「になって」と時期を示す文には合わない。"}, {"text": "地下", "is_correct": false, "explanation": "地下は場所を表すので、ここでは時期を示す文が成り立たない。"}, {"text": "遠方", "is_correct": false, "explanation": "遠方は場所を表すので、時期を表す文には合わない。"}], "explanations": {"近年": "正解。「近年になって、やっと新しい店ができた」は時期を示し、自然。", "屋上": "屋上は場所を表すので、「になって」と時期を示す文には合わない。", "地下": "地下は場所を表すので、ここでは時期を示す文が成り立たない。", "遠方": "遠方は場所を表すので、時期を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "近年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近年、午後に雨が降りました。", "explanation": "ここは〈今日の午後〉（その日の時間帯）の意味。近年は数年単位なので、一日の時間帯の雨とは合わない。"}, {"text": "近年、先週、庭に花が咲きました。", "explanation": "ここは〈先週〉（一週間前の週）の意味。近年は数年単位なので、先週の一度の出来事とは合わない。"}, {"text": "当時まだ子どもだった私は、近年、海で泳ぎました。", "explanation": "ここは〈当時〉（その時期）の意味。過去の一時期を指す文に近年を使うと、時期がずれて不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36932, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近年を、冬が暖かくなりました。", "corrected_sentence": "近年は、冬が暖かくなりました。", "error_description": "「近年」は主題を示す「は」で続ける。「を」は目的語の印なので、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36932, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年を医療は、とても進歩しました。", "corrected_sentence": "近年の医療は、とても進歩しました。", "error_description": "「近年の医療」の「の」が正しい。「近年を医療」と書くと、近年が目的語になり意味が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「観点が違う」で、観点を主語として示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「観点を違う」は動詞「違う」と組み合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「観点へ違う」は「違う」と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、「観点で違う」は主語にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「観点が違う」で、観点を主語として示す格助詞。", "を": "「観点を違う」は動詞「違う」と組み合わず不自然。", "へ": "方向を表すが、「観点へ違う」は「違う」と結びつかない。", "で": "手段を表すが、「観点で違う」は主語にならず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「費用の観点」の「の」で、観点の内容（費用）を示す連体修飾。"}, {"text": "に", "is_correct": false, "explanation": "「費用に観点」は名詞をつなぐ形として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「費用が観点だけで」では主語として文が壊れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「費用へ観点で決める」は文として続かない。"}], "correct_answer": "の", "explanations": {"の": "「費用の観点」の「の」で、観点の内容（費用）を示す連体修飾。", "に": "「費用に観点」は名詞をつなぐ形として不自然。", "が": "「費用が観点だけで」では主語として文が壊れる。", "へ": "方向を表すが、「費用へ観点で決める」は文として続かない。"}, "error_tags": {"に": "位置", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを見たり考えたりするときの、決まった見方や立場のこと。", "primary_collocate": null, "pronunciation": "かんてん", "ipa": "kaɴteɴ", "syllable_count": 4, "sentences": [{"text": "この問題を、別の観点から考えてみましょう。", "target_word": "観点", "complexity_tier": "T3", "furigana": "この問題[もんだい]を、別[べつ]の観点[かんてん]から考[かんが]えてみましょう。", "sentence_source": "generated"}, {"text": "観点が違うので、二人の意見は合わなかった。", "target_word": "観点", "complexity_tier": "T3", "furigana": "観点[かんてん]が違[ちが]うので、二人[ふたり]の意見[いけん]は合[あ]わなかった。", "sentence_source": "generated"}, {"text": "安全という観点では、この道具は使わないほうがいい。", "target_word": "観点", "complexity_tier": "T3", "furigana": "安全[あんぜん]という観点[かんてん]では、この道具[どうぐ]は使[つか]わないほうがいい。", "sentence_source": "generated"}, {"text": "先生は、環境の観点から新しい工場に反対した。", "target_word": "観点", "complexity_tier": "T3", "furigana": "先生[せんせい]は、環境[かんきょう]の観点[かんてん]から新[あたら]しい工場[こうじょう]に反対[はんたい]した。", "sentence_source": "generated"}, {"text": "彼の意見は、お客さんの観点に立っていて分かりやすい。", "target_word": "観点", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は、お客[きゃく]さんの観点[かんてん]に立[た]っていて分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "同じ事件でも、観点によって見え方が変わる。", "target_word": "観点", "complexity_tier": "T3", "furigana": "同[おな]じ事件[じけん]でも、観点[かんてん]によって見[み]え方[かた]が変[か]わる。", "sentence_source": "generated"}, {"text": "大切な観点を忘れずに、レポートを書いてください。", "target_word": "観点", "complexity_tier": "T3", "furigana": "大切[たいせつ]な観点[かんてん]を忘[わす]れずに、レポートを書[か]いてください。", "sentence_source": "generated"}, {"text": "費用の観点だけで決めると、あとで困ることもある。", "target_word": "観点", "complexity_tier": "T3", "furigana": "費用[ひよう]の観点[かんてん]だけで決[き]めると、あとで困[こま]ることもある。", "sentence_source": "generated"}, {"text": "彼女は子どもの観点で町づくりを考えた。", "target_word": "観点", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は子[こ]どもの観点[かんてん]で町[まち]づくりを考[かんが]えた。", "sentence_source": "generated"}, {"text": "話し合いでは、まずそれぞれの観点を出し合った。", "target_word": "観点", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いでは、まずそれぞれの観点[かんてん]を出[だ]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "観点", "label": "基本形"}, {"form": "観点から", "label": "「から」を伴う形"}], "register": "やや硬い（書き言葉・説明的）", "sense_fingerprint": "物事を考えるときの見方・立場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "観点", "is_correct": true, "explanation": "考えるときの見方を表す語で、「別の観点から」として文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態を指すため、問題の考え方の見方としては入らない。"}, {"text": "音楽", "is_correct": false, "explanation": "芸術の分野を指し、問題を考える見方にはならない。"}, {"text": "花束", "is_correct": false, "explanation": "花をまとめた物を指し、「別の花束から考える」は意味をなさない。"}], "explanations": {"観点": "考えるときの見方を表す語で、「別の観点から」として文に合う。", "天気": "空の状態を指すため、問題の考え方の見方としては入らない。", "音楽": "芸術の分野を指し、問題を考える見方にはならない。", "花束": "花をまとめた物を指し、「別の花束から考える」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "観点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は山頂で、大きな観点を地面に置いた。", "explanation": "ここは「荷物（物）」の意味。観点は抽象的な見方で、地面に置く物ではないので合わない。"}, {"text": "彼は会社の観点を、金庫に入れて守った。", "explanation": "ここは「貴重品（物）」の意味。観点は抽象的な見方で、金庫に入れて守る物ではないので合わない。"}, {"text": "姉は大きな観点を、丁寧に洗った。", "explanation": "ここは「食器（物）」の意味。観点は抽象的な見方で、洗う物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "観点", "is_correct": true, "explanation": "「大切な観点」として、忘れてはいけない見方を表し、文に合う。"}, {"text": "夕日", "is_correct": false, "explanation": "空に見える太陽を指し、レポートの見方とは無関係。"}, {"text": "食器", "is_correct": false, "explanation": "食事に使う道具を指し、レポートの考え方には合わない。"}, {"text": "足音", "is_correct": false, "explanation": "歩くときの音を指し、レポートの内容とは結びつかない。"}], "explanations": {"観点": "「大切な観点」として、忘れてはいけない見方を表し、文に合う。", "夕日": "空に見える太陽を指し、レポートの見方とは無関係。", "食器": "食事に使う道具を指し、レポートの考え方には合わない。", "足音": "歩くときの音を指し、レポートの内容とは結びつかない。"}, "sentence_index": 6, "correct_answer": "観点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は窓辺で、観点を乾かした。", "explanation": "ここは「洗濯物（布）」の意味。観点は抽象的な見方で、乾かす対象にはならないので合わない。"}, {"text": "彼女は小さな観点を、針で縫い合わせた。", "explanation": "ここは「布（生地）」の意味。観点は抽象的な見方で、縫い合わせる素材ではないので合わない。"}, {"text": "社長は会議の観点を、冷蔵庫に入れた。", "explanation": "ここは「食品（物）」の意味。観点は抽象的な見方で、冷蔵庫に入れる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "安全の観点に、この計画は見直すべきだ。", "corrected_sentence": "安全の観点から、この計画は見直すべきだ。", "error_description": "「〜の観点から」で「その方面から」を表す。「観点に」は誤りで、正しくは「観点から」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36934, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "費用の観点を、まず予算案を見直そう。", "corrected_sentence": "費用の観点から、まず予算案を見直そう。", "error_description": "「観点」の直後の助詞が「を」になっている。「見直す」の方法・立場を表すには「から」が必要で、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「集める」の対象（切手）を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「切手が集める」では切手が動作主になり、文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「切手へ集める」では集める対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「切手より集める」は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「集める」の対象（切手）を示す格助詞。", "が": "「切手が集める」では切手が動作主になり、文に合わない。", "へ": "方向を表すが、「切手へ集める」では集める対象を示せない。", "より": "比較を表すが、「切手より集める」は目的語にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「集める」の対象（珍しい石）を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「石に集める」は集める対象を示せず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾するが、「石の集めている」では文として続かない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表すが、「石と集めている」は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「集める」の対象（珍しい石）を示す格助詞。", "に": "「石に集める」は集める対象を示せず、不自然。", "の": "名詞を修飾するが、「石の集めている」では文として続かない。", "と": "並列を表すが、「石と集めている」は目的語にならない。"}, "error_tags": {"に": "位置", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たくさんのものを、一つのところに、かためる。", "primary_collocate": null, "pronunciation": "あつめる", "ipa": "asɯme̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "秋になると、公園で落ち葉を集めて遊びます。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "秋[あき]になると、公園[こうえん]で落[お]ち葉[ば]を集[あつ]めて遊[あそ]びます。", "sentence_source": "generated"}, {"text": "弟は古い切手を集めるのが好きだ。", "target_word": "集める", "complexity_tier": "T3", "furigana": "弟[おとうと]は古[ふる]い切手[きって]を集[あつ]めるのが好[す]きだ。", "sentence_source": "generated"}, {"text": "子供たちが浜辺で貝を集めている。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "子供[こども]たちが浜辺[はまべ]で貝[かい]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "床に落ちた小さなごみを、ほうきで集めた。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "床[ゆか]に落[お]ちた小[ちい]さなごみを、ほうきで集[あつ]めた。", "sentence_source": "generated"}, {"text": "母は空き缶を集めて、リサイクルに出している。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "母[はは]は空[あ]き缶[かん]を集[あつ]めて、リサイクルに出[だ]している。", "sentence_source": "generated"}, {"text": "雨水を集めて、庭の花にかけた。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "雨水[あまみず]を集[あつ]めて、庭[にわ]の花[はな]にかけた。", "sentence_source": "generated"}, {"text": "机の上の本を一つの箱に集めてください。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の本[ほん]を一[ひと]つの箱[はこ]に集[あつ]めてください。", "sentence_source": "generated"}, {"text": "祖父は昔から珍しい石を集めている。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔[むかし]から珍[めずら]しい石[いし]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "風でちらばった紙を、急いで集めた。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "風[かぜ]でちらばった紙[かみ]を、急[いそ]いで集[あつ]めた。", "sentence_source": "generated"}, {"text": "彼女は集めたどんぐりを、かごに入れて持ち帰った。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は集[あつ]めたどんぐりを、かごに入[い]れて持[も]ち帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集める", "label": "基本形"}, {"form": "集めない", "label": "否定形"}, {"form": "集めます", "label": "丁寧形"}, {"form": "集めて", "label": "て形"}, {"form": "集めた", "label": "た形"}, {"form": "集められる", "label": "可能形・受身形"}, {"form": "集めれば", "label": "仮定形"}, {"form": "集めよう", "label": "意向形"}], "register": "中立", "sense_fingerprint": "多くの物を一か所にまとめる・収集する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: ちらばっ (Zipf 1.51)']::text[], '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集めて", "is_correct": true, "explanation": "「集める」のて形。落ち葉を一か所にまとめてから遊ぶ流れに合う。"}, {"text": "洗って", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、落ち葉を洗って遊ぶ文には合わない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨く」は表面をこする動作で、公園の落ち葉には合わない。"}, {"text": "買って", "is_correct": false, "explanation": "「買う」は店で手に入れる動作で、公園の落ち葉には合わない。"}], "explanations": {"集めて": "「集める」のて形。落ち葉を一か所にまとめてから遊ぶ流れに合う。", "洗って": "「洗う」は汚れを落とす動作で、落ち葉を洗って遊ぶ文には合わない。", "磨いて": "「磨く」は表面をこする動作で、公園の落ち葉には合わない。", "買って": "「買う」は店で手に入れる動作で、公園の落ち葉には合わない。"}, "sentence_index": 0, "correct_answer": "集めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、母は床を念入りに集めた。", "explanation": "ここは「掃除する」の意味。集めるは物を一か所に寄せる動作で、床そのものを清める意味にはならないので合わない。"}, {"text": "道で落ちた硬貨を、一枚だけ集めた。", "explanation": "ここは「拾う」の意味。集めるは多くのものを一か所にまとめる動作なので、一枚だけの場合には合わない。"}, {"text": "彼は大きな荷物を、一口で集めた。", "explanation": "ここは「食べる（口に入れる）」の意味。集めるは物を寄せる動作で、口に入れる行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集めて", "is_correct": true, "explanation": "「集める」のて形。机の上の本を箱にまとめてほしいという指示に合う。"}, {"text": "破いて", "is_correct": false, "explanation": "「破く」は紙を裂く動作で、本を箱に入れる指示の流れに合わない。"}, {"text": "読んで", "is_correct": false, "explanation": "「読む」は内容を追う動作で、箱に入れる指示とは合わない。"}, {"text": "切って", "is_correct": false, "explanation": "「切る」は物を切断する動作で、箱にまとめる流れに合わない。"}], "explanations": {"集めて": "「集める」のて形。机の上の本を箱にまとめてほしいという指示に合う。", "破いて": "「破く」は紙を裂く動作で、本を箱に入れる指示の流れに合わない。", "読んで": "「読む」は内容を追う動作で、箱に入れる指示とは合わない。", "切って": "「切る」は物を切断する動作で、箱にまとめる流れに合わない。"}, "sentence_index": 6, "correct_answer": "集めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、友人と公園を集めた。", "explanation": "ここは「散歩する」の意味。集めるは物や人を一つの場所に寄せる動作で、場所を歩き回る場面には合わない。"}, {"text": "自転車を一台、歩道の端に集めた。", "explanation": "ここは「寄せる（近くへ動かす）」の意味。集めるは多くのものをまとめる動作なので、一台だけの場合には合わない。"}, {"text": "彼女は大切な約束を集めてしまった。", "explanation": "ここは「忘れる」の意味。集めるは物や人を寄せる動作で、記憶から消える場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉はどんぐりに集めるのが趣味だ。", "corrected_sentence": "姉はどんぐりを集めるのが趣味だ。", "error_description": "「集める」の目的語は「を」で示す。「どんぐりに集める」は誤りで、正しくは「どんぐりを集める」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "集める", "is_correct": true, "explanation": "基本形。「〜のが好きだ」の前に置く形で、文の構造に合う。"}, {"text": "集めて", "is_correct": false, "explanation": "て形。「〜のが」に続けられず、文が成り立たない。"}, {"text": "集めます", "is_correct": false, "explanation": "丁寧形。普通体の文に混ざり、「〜のが」に続かない。"}, {"text": "集めれば", "is_correct": false, "explanation": "仮定形。条件を表し、「〜のが好きだ」とは続かない。"}], "correct_form": "集める", "base_form": "集める", "form_label": "基本形", "sentence_index": 1, "explanations": {"集める": "基本形。「〜のが好きだ」の前に置く形で、文の構造に合う。", "集めて": "て形。「〜のが」に続けられず、文が成り立たない。", "集めます": "丁寧形。普通体の文に混ざり、「〜のが」に続かない。", "集めれば": "仮定形。条件を表し、「〜のが好きだ」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36936, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹はおはじきを集めるて、箱にしまった。", "corrected_sentence": "妹はおはじきを集めて、箱にしまった。", "error_description": "「集める」に直接「て」をつけることはできない。語幹「集め」に「て」をつけて、正しくは「集めて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "集めて", "is_correct": true, "explanation": "「集める」のて形。「〜ている」の進行の形として、石を集めている状態に合う。"}, {"text": "集めない", "is_correct": false, "explanation": "否定形。「集めないでいる」となり、石を集めているという内容と合わない。"}, {"text": "集めた", "is_correct": false, "explanation": "た形。過去の動作になり、「〜ている」の継続の文と合わない。"}, {"text": "集めよう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、継続している状態を表さない。"}], "correct_form": "集めて", "base_form": "集める", "form_label": "て形", "sentence_index": 7, "explanations": {"集めて": "「集める」のて形。「〜ている」の進行の形として、石を集めている状態に合う。", "集めない": "否定形。「集めないでいる」となり、石を集めているという内容と合わない。", "集めた": "た形。過去の動作になり、「〜ている」の継続の文と合わない。", "集めよう": "意向形。「〜しよう」の意味になり、継続している状態を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「集める」の対象（店の全員）を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「全員に集めて」は対象を示せず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「全員が集めて」は他動詞「集める」の対象にならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「全員より集めて」は対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「集める」の対象（店の全員）を示す格助詞。", "に": "「全員に集めて」は対象を示せず、不自然。", "が": "「全員が集めて」は他動詞「集める」の対象にならず不自然。", "より": "比較を表すが、「全員より集めて」は対象を示せない。"}, "error_tags": {"に": "位置・相手", "が": "主語", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「集める」の対象（資料）を示す格助詞。"}, {"text": "の", "is_correct": false, "explanation": "「資料の集めて」は名詞修飾になり、目的語を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「資料へ集めて」は集める対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列を表すが、「資料と集めて」は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「集める」の対象（資料）を示す格助詞。", "の": "「資料の集めて」は名詞修飾になり、目的語を示せず不自然。", "へ": "方向を表すが、「資料へ集めて」は集める対象を示せない。", "と": "並列を表すが、「資料と集めて」は目的語にならない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物が一つの場所に寄り合う。また、寄せて一つにまとめる。", "primary_collocate": null, "pronunciation": "あつめる", "ipa": "asɯme̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "先生は生徒を教室に集めて、大事な話をした。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]を教室[きょうしつ]に集[あつ]めて、大事[だいじ]な話[はなし]をした。", "sentence_source": "generated"}, {"text": "店長は朝、店の全員を集めて、今日の予定を話した。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "店長[てんちょう]は朝[あさ]、店[みせ]の全員[ぜんいん]を集[あつ]めて、今日[きょう]の予定[よてい]を話[はな]した。", "sentence_source": "generated"}, {"text": "町の人々からお金を集めて、新しい図書館を建てた。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]からお金[かね]を集[あつ]めて、新[あたら]しい図書館[としょかん]を建[た]てた。", "sentence_source": "generated"}, {"text": "委員長は、会議のために全員を会議室に集めた。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "委員長[いいんちょう]は、会議[かいぎ]のために全員[ぜんいん]を会議室[かいぎしつ]に集[あつ]めた。", "sentence_source": "generated"}, {"text": "彼は友達を家に集めて、誕生日のお祝いをした。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "彼[かれ]は友達[ともだち]を家[いえ]に集[あつ]めて、誕生日[たんじょうび]のお祝[いわ]いをした。", "sentence_source": "generated"}, {"text": "地域の人からたくさんの署名を集めた。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "地域[ちいき]の人[ひと]からたくさんの署名[しょめい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "祭りの太鼓の音が、町中の人を集めた。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "祭[まつ]りの太鼓[たいこ]の音[おと]が、町中[まちじゅう]の人[ひと]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "必要な資料を集めて、一つのファイルにまとめた。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "必要[ひつよう]な資料[しりょう]を集[あつ]めて、一[ひと]つのファイルにまとめた。", "sentence_source": "generated"}, {"text": "消防士たちは、出動の前に広場へ全員を集めた。", "target_word": "集めた", "complexity_tier": "T3", "furigana": "消防士[しょうぼうし]たちは、出動[しゅつどう]の前[まえ]に広場[ひろば]へ全員[ぜんいん]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "クラスの全員から宿題を集めて、先生に出した。", "target_word": "集めて", "complexity_tier": "T3", "furigana": "クラスの全員[ぜんいん]から宿題[しゅくだい]を集[あつ]めて、先生[せんせい]に出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集める", "label": "基本形"}, {"form": "集めない", "label": "否定形"}, {"form": "集めます", "label": "丁寧形"}, {"form": "集めて", "label": "て形"}, {"form": "集めた", "label": "た形"}, {"form": "集められる", "label": "可能形・受身形"}, {"form": "集めれば", "label": "仮定形"}, {"form": "集めよう", "label": "意向形"}], "register": "中立", "sense_fingerprint": "人・お金・資料などを一つの場所や一つのまとまりに寄せる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce42f7e-bdb3-4b75-b684-6dd8db65015b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集めて", "is_correct": true, "explanation": "「集める」のて形。生徒を教室に呼び寄せてから話をする流れに合う。"}, {"text": "解いて", "is_correct": false, "explanation": "「解く」は問題の答えを出す動作で、生徒を教室に寄せる文脈には合わない。"}, {"text": "閉じて", "is_correct": false, "explanation": "「閉じる」は戸などを閉める動作で、人を場所に寄せる意味にならない。"}, {"text": "眺めて", "is_correct": false, "explanation": "「眺める」は見渡す動作で、生徒を教室に寄せる意味にならない。"}], "explanations": {"集めて": "「集める」のて形。生徒を教室に呼び寄せてから話をする流れに合う。", "解いて": "「解く」は問題の答えを出す動作で、生徒を教室に寄せる文脈には合わない。", "閉じて": "「閉じる」は戸などを閉める動作で、人を場所に寄せる意味にならない。", "眺めて": "「眺める」は見渡す動作で、生徒を教室に寄せる意味にならない。"}, "sentence_index": 0, "correct_answer": "集めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "委員長は、会議の時間を正確に集めた。", "explanation": "ここは「測る（時間を計る）」の意味。集めるは物や人を一か所に寄せる動作で、時間を計る場面には合わない。"}, {"text": "彼は相手の顔を集めた。", "explanation": "ここは「殴る（強く打つ）」の意味。集めるは寄せる動作で、人を打つ行為には合わない。"}, {"text": "作業員は、クレーンで一艘の船を、高い空へ集めた。", "explanation": "ここは「飛ばす（空へ上げる）」の意味。集めるは寄せる動作で、空へ飛ばす場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集めた", "is_correct": true, "explanation": "「集める」の過去形。太鼓の音が町中の人を寄せた意味に合う。"}, {"text": "壊した", "is_correct": false, "explanation": "「壊す」は物を壊す動作で、人には使えず文に合わない。"}, {"text": "掘った", "is_correct": false, "explanation": "「掘る」は地面を掘る動作で、人を対象にできない。"}, {"text": "乾かした", "is_correct": false, "explanation": "「乾かす」は水分を取る動作で、人には使えない。"}], "explanations": {"集めた": "「集める」の過去形。太鼓の音が町中の人を寄せた意味に合う。", "壊した": "「壊す」は物を壊す動作で、人には使えず文に合わない。", "掘った": "「掘る」は地面を掘る動作で、人を対象にできない。", "乾かした": "「乾かす」は水分を取る動作で、人には使えない。"}, "sentence_index": 6, "correct_answer": "集めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は夜、夕食を集めた。", "explanation": "ここは「作る（料理を仕上げる）」の意味。集めるは物を一か所に寄せる動作で、料理を作る場面には合わない。"}, {"text": "弟は部屋をぴかぴかに集めたまま出かけた。", "explanation": "ここは「磨く（光らせる）」の意味。集めるは物を寄せる動作で、磨く場面には合わない。"}, {"text": "彼は一口でケーキを集めた。", "explanation": "ここは「食べる」の意味。集めるは物を寄せる動作で、口に入れて食べる行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "PTAは保護者から寄付に集めて、遊具を買った。", "corrected_sentence": "PTAは保護者から寄付を集めて、遊具を買った。", "error_description": "「集める」の目的語は「を」で示す。「寄付に集めて」は誤りで、正しくは「寄付を集めて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "集めて", "is_correct": true, "explanation": "「集める」のて形。全員を集めてから話したという順序に合う。"}, {"text": "集めない", "is_correct": false, "explanation": "否定形。全員を集めなかったことになり、話したという内容と合わない。"}, {"text": "集めよう", "is_correct": false, "explanation": "意向形。「〜しよう」の意味になり、過去の話として合わない。"}, {"text": "集めます", "is_correct": false, "explanation": "丁寧形。普通体の文に混ざり、「、」でつなげず文が成り立たない。"}], "correct_form": "集めて", "base_form": "集める", "form_label": "て形", "sentence_index": 1, "explanations": {"集めて": "「集める」のて形。全員を集めてから話したという順序に合う。", "集めない": "否定形。全員を集めなかったことになり、話したという内容と合わない。", "集めよう": "意向形。「〜しよう」の意味になり、過去の話として合わない。", "集めます": "丁寧形。普通体の文に混ざり、「、」でつなげず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36937, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は朝、生徒全員をホールに集めるた。", "corrected_sentence": "先生は朝、生徒全員をホールに集めた。", "error_description": "「集める」に直接「た」をつけることはできない。語幹「集め」に「た」をつけて、正しくは「集めた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "集めて", "is_correct": true, "explanation": "「集める」のて形。資料を集めてから一つにまとめたという順序に合う。"}, {"text": "集める", "is_correct": false, "explanation": "基本形。文の途中で止まり、「まとめた」と続かない。"}, {"text": "集めます", "is_correct": false, "explanation": "丁寧形。普通体の文に混ざり、「まとめた」と続かない。"}, {"text": "集められ", "is_correct": false, "explanation": "受身の連用形。「資料を」を主語にできず、文が成り立たない。"}], "correct_form": "集めて", "base_form": "集める", "form_label": "て形", "sentence_index": 7, "explanations": {"集めて": "「集める」のて形。資料を集めてから一つにまとめたという順序に合う。", "集める": "基本形。文の途中で止まり、「まとめた」と続かない。", "集めます": "丁寧形。普通体の文に混ざり、「まとめた」と続かない。", "集められ": "受身の連用形。「資料を」を主語にできず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da41ef81-ad0c-4031-9989-be988fed0a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「運用を誤る」の目的語を示す。「誤る」は目的語に「を」を取る。"}, {"text": "の", "is_correct": false, "explanation": "「運用の誤る」は成り立たず、「の」は名詞どうしをつなぐ助詞で、動詞の項にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「運用に誤る」は成り立たず、「に」は誤る対象を示さない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「運用へ誤る」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「運用を誤る」の目的語を示す。「誤る」は目的語に「を」を取る。", "の": "「運用の誤る」は成り立たず、「の」は名詞どうしをつなぐ助詞で、動詞の項にはならない。", "に": "「運用に誤る」は成り立たず、「に」は誤る対象を示さない。", "へ": "「へ」は方向を示すが、「運用へ誤る」は成り立たない。"}, "error_tags": {"を": "目的語の格", "の": "名詞どうしの連結", "に": "対象の格", "へ": "方向の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを使うために、どのように動かすかを考えること。", "primary_collocate": null, "pronunciation": "うんよう", "ipa": "ɯɴjoː", "syllable_count": 4, "sentences": [{"text": "道具を買うだけでなく、どう運用するかを先に決めておこう。", "target_word": "運用", "complexity_tier": "T3", "furigana": "道具[どうぐ]を買[か]うだけでなく、どう運用[うんよう]するかを先[さき]に決[き]めておこう。", "sentence_source": "generated"}, {"text": "運用の計画が甘かったので、新しいアプリは使われなくなった。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]の計画[けいかく]が甘[あま]かったので、新[あたら]しいアプリは使[つか]われなくなった。", "sentence_source": "generated"}, {"text": "限られた予算の運用を考えるのが、私の仕事です。", "target_word": "運用", "complexity_tier": "T3", "furigana": "限[かぎ]られた予算[よさん]の運用[うんよう]を考[かんが]えるのが、私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "運用の仕方を工夫すれば、古いパソコンでも十分使える。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]の仕方[しかた]を工夫[くふう]すれば、古[ふる]いパソコンでも十分[じゅうぶん]使[つか]える。", "sentence_source": "generated"}, {"text": "運用ルールを決めないと、共有の車はすぐ混乱する。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]ルールを決[き]めないと、共有[きょうゆう]の車[くるま]はすぐ混乱[こんらん]する。", "sentence_source": "generated"}, {"text": "この倉庫は運用次第で、もっと便利になる。", "target_word": "運用", "complexity_tier": "T3", "furigana": "この倉庫[そうこ]は運用[うんよう]次第[しだい]で、もっと便利[べんり]になる。", "sentence_source": "generated"}, {"text": "運用の方法を話し合ってから、新しい設備を入れた。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]の方法[ほうほう]を話[はな]し合[あ]ってから、新[あたら]しい設備[せつび]を入[い]れた。", "sentence_source": "generated"}, {"text": "運用を誤ると、せっかくの制度も役に立たない。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]を誤[あやま]ると、せっかくの制度[せいど]も役[やく]に立[た]たない。", "sentence_source": "generated"}, {"text": "先生は教室の電子黒板の運用について、皆に意見を聞いた。", "target_word": "運用", "complexity_tier": "T3", "furigana": "先生[せんせい]は教室[きょうしつ]の電子[でんし]黒板[こくばん]の運用[うんよう]について、皆[みな]に意見[いけん]を聞[き]いた。", "sentence_source": "generated"}, {"text": "道具の運用を考える時間も、仕事のうちだ。", "target_word": "運用", "complexity_tier": "T3", "furigana": "道具[どうぐ]の運用[うんよう]を考[かんが]える時間[じかん]も、仕事[しごと]のうちだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運用する", "label": "終止形"}, {"form": "運用した", "label": "過去形"}, {"form": "運用して", "label": "て形"}, {"form": "運用しない", "label": "否定形"}, {"form": "運用される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "道具や制度を使うために、どう動かすかを考えて決めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運用", "is_correct": true, "explanation": "道具をどう動かし使うかを決める意味で、「どう〜する」に入る。"}, {"text": "工具", "is_correct": false, "explanation": "工具は道具の一種の名詞で、「どう工具する」とは動詞化しないので入らない。"}, {"text": "部品", "is_correct": false, "explanation": "部品は物の名前で、「どう部品するか」は成り立たない。"}, {"text": "看板", "is_correct": false, "explanation": "看板は掲示物の名前で、「どう看板するか」とは言えない。"}], "explanations": {"運用": "道具をどう動かし使うかを決める意味で、「どう〜する」に入る。", "工具": "工具は道具の一種の名詞で、「どう工具する」とは動詞化しないので入らない。", "部品": "部品は物の名前で、「どう部品するか」は成り立たない。", "看板": "看板は掲示物の名前で、「どう看板するか」とは言えない。"}, "sentence_index": 0, "correct_answer": "運用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書館の本を運用して、レポートを書いた。", "explanation": "本を使う意味は〈利用〉。〈運用〉は機械や制度を動かすことなので、本には使わない。"}, {"text": "この祭りは町内会が毎年運用している。", "explanation": "催しや団体を経営する意味は〈運営〉。〈運用〉は機械や制度を動かすことで合わない。"}, {"text": "弟は宿題の答えを運用して、先生をだました。", "explanation": "答えを写す意味は〈写す〉。〈運用〉は機械や制度を動かすことで、答えには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運用", "is_correct": true, "explanation": "設備の動かし方を表し、「〜の方法」として自然に入る。"}, {"text": "湖", "is_correct": false, "explanation": "湖は場所の名前で、動かし方の話し合いの対象にならない。"}, {"text": "梯子", "is_correct": false, "explanation": "梯子は道具の名前で、動かし方の方法としては話し合う内容にならない。"}, {"text": "網", "is_correct": false, "explanation": "網は道具の名前で、設備の方法としては成り立たない。"}], "explanations": {"運用": "設備の動かし方を表し、「〜の方法」として自然に入る。", "湖": "湖は場所の名前で、動かし方の話し合いの対象にならない。", "梯子": "梯子は道具の名前で、動かし方の方法としては話し合う内容にならない。", "網": "網は道具の名前で、設備の方法としては成り立たない。"}, "sentence_index": 6, "correct_answer": "運用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "話し相手の気持ちを運用して、会話を続けた。", "explanation": "相手の気持ちに寄り添う意味は〈配慮〉。〈運用〉は機械や制度を動かすことで、人の気持ちには使わない。"}, {"text": "車の運用を練習して、免許を取った。", "explanation": "車を操る意味は〈運転〉。〈運用〉は車には使わない。"}, {"text": "眠っていた才能を運用して、新しい仕事を始めた。", "explanation": "才能を役立てる意味は〈活用〉。才能は機械や制度ではないので〈運用〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "道具の運用を、来週までに決まる。", "corrected_sentence": "道具の運用が、来週までに決まる。", "error_description": "「決まる」は主語に「が」を取る自動詞。「運用を」は誤りで、正しくは「運用が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36938, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使い方を変えるなら、運用して必要がある。", "corrected_sentence": "使い方を変えるなら、運用する必要がある。", "error_description": "「必要」は連体形（辞書形）に続けるため「運用する必要」が正しい。「運用して必要」は活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「運用が始まる」の主語を示す。「始まる」は自動詞なので主語に「が」を取る。"}, {"text": "を", "is_correct": false, "explanation": "「始まる」は自動詞で目的語の「を」を取らない。「運用を始まる」は誤り。"}, {"text": "に", "is_correct": false, "explanation": "「運用に始まる」は成り立たない。「に」は時点や方向を示し、主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「運用で始まる」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「運用が始まる」の主語を示す。「始まる」は自動詞なので主語に「が」を取る。", "を": "「始まる」は自動詞で目的語の「を」を取らない。「運用を始まる」は誤り。", "に": "「運用に始まる」は成り立たない。「に」は時点や方向を示し、主語にはならない。", "で": "「で」は手段や場所を示すが、「運用で始まる」は成り立たない。"}, "error_tags": {"を": "自動詞に目的語", "に": "時点・方向の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "機械やシステムなどを、目的に合わせて動かしたり、使ったりすること。", "primary_collocate": null, "pronunciation": "うんよう", "ipa": "ɯɴjoː", "syllable_count": 4, "sentences": [{"text": "この機械を、どう運用するかを決めた。", "target_word": "運用", "complexity_tier": "T3", "furigana": "この機械[きかい]を、どう運用[うんよう]するかを決[き]めた。", "sentence_source": "generated"}, {"text": "この規則は来月から運用が始まります。", "target_word": "運用", "complexity_tier": "T3", "furigana": "この規則[きそく]は来月[らいげつ]から運用[うんよう]が始[はじ]まります。", "sentence_source": "generated"}, {"text": "新しいシステムの運用には、専門の担当者が必要だ。", "target_word": "運用", "complexity_tier": "T3", "furigana": "新[あたら]しいシステムの運用[うんよう]には、専門[せんもん]の担当者[たんとうしゃ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "会社は古い機械を定期点検しながら運用して、長く使っている。", "target_word": "運用", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は古[ふる]い機械[きかい]を定期[ていき]点検[てんけん]しながら運用[うんよう]して、長[なが]く使[つか]っている。", "sentence_source": "generated"}, {"text": "運用を始めたばかりなので、まだ小さな問題が多い。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]を始[はじ]めたばかりなので、まだ小[ちい]さな問題[もんだい]が多[おお]い。", "sentence_source": "generated"}, {"text": "サーバーを二十四時間運用するため、交代で見守っている。", "target_word": "運用", "complexity_tier": "T3", "furigana": "サーバーを二十四時間[にじゅうよじかん]運用[うんよう]するため、交代[こうたい]で見守[みまも]っている。", "sentence_source": "generated"}, {"text": "市は、この施設を安全に運用するためのルールを作った。", "target_word": "運用", "complexity_tier": "T3", "furigana": "市[し]は、この施設[しせつ]を安全[あんぜん]に運用[うんよう]するためのルールを作[つく]った。", "sentence_source": "generated"}, {"text": "運用のコストが高すぎて、導入をやめることにした。", "target_word": "運用", "complexity_tier": "T3", "furigana": "運用[うんよう]のコストが高[たか]すぎて、導入[どうにゅう]をやめることにした。", "sentence_source": "generated"}, {"text": "試験的に運用してみて、問題がなければ全校に広げる。", "target_word": "運用", "complexity_tier": "T3", "furigana": "試験的[しけんてき]に運用[うんよう]してみて、問題[もんだい]がなければ全校[ぜんこう]に広[ひろ]げる。", "sentence_source": "generated"}, {"text": "彼は大きな機械の運用に慣れていて、故障にもすぐ気づく。", "target_word": "運用", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな機械[きかい]の運用[うんよう]に慣[な]れていて、故障[こしょう]にもすぐ気[き]づく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "運用する", "label": "終止形"}, {"form": "運用した", "label": "過去形"}, {"form": "運用して", "label": "て形"}, {"form": "運用しない", "label": "否定形"}, {"form": "運用される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "機械やシステム、制度を目的に合わせて実際に動かし使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bd5b2a-24c0-4711-bcdb-72baf5213c95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "運用", "is_correct": true, "explanation": "「機械を動かして使う」の意味で、「どう〜するか」に入る。"}, {"text": "基板", "is_correct": false, "explanation": "「基板」は部品の名前で、「どう基板するか」と動詞化しないため入らない。"}, {"text": "回路", "is_correct": false, "explanation": "「回路」も物の名前なので、「どう回路するか」は成り立たない。"}, {"text": "部品", "is_correct": false, "explanation": "「部品」は物の名前で、「どう部品するか」とは言えない。"}], "explanations": {"運用": "「機械を動かして使う」の意味で、「どう〜するか」に入る。", "基板": "「基板」は部品の名前で、「どう基板するか」と動詞化しないため入らない。", "回路": "「回路」も物の名前なので、「どう回路するか」は成り立たない。", "部品": "「部品」は物の名前で、「どう部品するか」とは言えない。"}, "sentence_index": 0, "correct_answer": "運用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人の先生たちは、生徒の気持ちを運用して、やる気を引き出した。", "explanation": "人の気持ちを導いて動かす意味は〈導く〉。〈運用〉は機械やシステムを動かすことなので、人の気持ちには使わない。"}, {"text": "この店は、地域の住民が二十年以上運用している。", "explanation": "店や団体の経営は〈運営〉を使う。〈運用〉は機械や制度を目的に合わせて動かすことなので合わない。"}, {"text": "友人と予定を運用して、週末の旅行を決めた。", "explanation": "予定を立てる意味は〈組む〉。〈運用〉は機械やシステムを動かすことで、予定には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "運用", "is_correct": true, "explanation": "施設や機械の動かし方を表し、「安全に〜する」に入る。"}, {"text": "景観", "is_correct": false, "explanation": "景観は風景の名前で、「安全に景観する」とは言わない。"}, {"text": "正門", "is_correct": false, "explanation": "正門は建物の出入口の名前で、「安全に正門する」は成り立たない。"}, {"text": "案内板", "is_correct": false, "explanation": "案内板は掲示物の名前で、「安全に案内板する」とは動詞化しない。"}], "explanations": {"運用": "施設や機械の動かし方を表し、「安全に〜する」に入る。", "景観": "景観は風景の名前で、「安全に景観する」とは言わない。", "正門": "正門は建物の出入口の名前で、「安全に正門する」は成り立たない。", "案内板": "案内板は掲示物の名前で、「安全に案内板する」とは動詞化しない。"}, "sentence_index": 6, "correct_answer": "運用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の花を運用して、毎朝水をやった。", "explanation": "花を育てる意味は〈育てる〉。〈運用〉は機械や制度を動かすことで、植物には使わない。"}, {"text": "うちの犬を運用して、散歩に出かけた。", "explanation": "犬を連れて歩く意味は〈連れる〉。〈運用〉は機械や制度を動かすことで、動物には使わない。"}, {"text": "古い知識を運用して、新しい企画を考えた。", "explanation": "知識を役立てる意味は〈活用〉。知識は機械や制度ではないので〈運用〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい制度の運用を、来月から始まる。", "corrected_sentence": "新しい制度の運用が、来月から始まる。", "error_description": "「始まる」は主語に「が」を取る自動詞。「運用を」は誤りで、正しくは「運用が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36939, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このシステムは来年度から運用して予定だ。", "corrected_sentence": "このシステムは来年度から運用する予定だ。", "error_description": "「予定」は連体形（辞書形）に続けるため「運用する予定」が正しい。「運用して予定」は活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8ba898d-26ba-45b0-8878-cd9248f53336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
