INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36940, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見つめ直す」の対象は「を」で示すので、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「原点に見つめ直す」は対象を示せず、不自然で文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「原点が見つめ直す」は原点を主語にしてしまい、「見つめ直す」の目的語にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「原点へ見つめ直す」は文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「見つめ直す」の対象は「を」で示すので、文に合う。", "に": "「原点に見つめ直す」は対象を示せず、不自然で文が成り立たない。", "が": "「原点が見つめ直す」は原点を主語にしてしまい、「見つめ直す」の目的語にならず文が成り立たない。", "へ": "「へ」は方向を示すので、「原点へ見つめ直す」は文に合わない。"}, "error_tags": {"に": "帰着点", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36940, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が始まったところ", "primary_collocate": null, "pronunciation": "げんてん", "ipa": "ɡeɴteɴ", "syllable_count": 4, "sentences": [{"text": "この小さな工場が、わが社の原点だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "この小[ちい]さな工場[こうじょう]が、わが社[しゃ]の原点[げんてん]だ。", "sentence_source": "generated"}, {"text": "研究の原点は、子どものころの疑問だった。", "target_word": "原点", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の原点[げんてん]は、子[こ]どものころの疑問[ぎもん]だった。", "sentence_source": "generated"}, {"text": "彼は成功しても、いつも原点を忘れない人だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "彼[かれ]は成功[せいこう]しても、いつも原点[げんてん]を忘[わす]れない人[ひと]だ。", "sentence_source": "generated"}, {"text": "この町は日本の鉄道の原点と言われている。", "target_word": "原点", "complexity_tier": "T3", "furigana": "この町[まち]は日本[にほん]の鉄道[てつどう]の原点[げんてん]と言[い]われている。", "sentence_source": "generated"}, {"text": "話が分からなくなったので、原点に戻って考えた。", "target_word": "原点", "complexity_tier": "T3", "furigana": "話[はなし]が分[わ]からなくなったので、原点[げんてん]に戻[もど]って考[かんが]えた。", "sentence_source": "generated"}, {"text": "私の音楽の原点は、祖父のギターだ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "私[わたし]の音楽[おんがく]の原点[げんてん]は、祖父[そふ]のギターだ。", "sentence_source": "generated"}, {"text": "運動を始めた原点は、健康診断の結果だった。", "target_word": "原点", "complexity_tier": "T3", "furigana": "運動[うんどう]を始[はじ]めた原点[げんてん]は、健康診断[けんこうしんだん]の結果[けっか]だった。", "sentence_source": "generated"}, {"text": "失敗したときは、原点を見つめ直すことが大切だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "失敗[しっぱい]したときは、原点[げんてん]を見[み]つめ直[なお]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "この祭りの原点は、千年前の祈りにある。", "target_word": "原点", "complexity_tier": "T3", "furigana": "この祭[まつ]りの原点[げんてん]は、千年前[せんねんまえ]の祈[いの]りにある。", "sentence_source": "generated"}, {"text": "彼女の優しさの原点は、母の言葉にあると思う。", "target_word": "原点", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の優[やさ]しさの原点[げんてん]は、母[はは]の言葉[ことば]にあると思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原点", "label": "基本形"}, {"form": "原点に", "label": "に格"}, {"form": "原点を", "label": "を格"}], "register": "中立", "sense_fingerprint": "物事が始まった出発点・起源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36940, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原点", "is_correct": true, "explanation": "「わが社の原点」は会社の出発点を指し、文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "会社を「天気」とは言えず、「わが社の天気だ」は意味が通らない。"}, {"text": "宿題", "is_correct": false, "explanation": "会社の位置づけを「宿題」とは言わず、文に合わない。"}, {"text": "句読点", "is_correct": false, "explanation": "会社を指す語として「句読点」は合わず、文が成り立たない。"}], "explanations": {"原点": "「わが社の原点」は会社の出発点を指し、文の意味に合う。", "天気": "会社を「天気」とは言えず、「わが社の天気だ」は意味が通らない。", "宿題": "会社の位置づけを「宿題」とは言わず、文に合わない。", "句読点": "会社を指す語として「句読点」は合わず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "原点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この資料の原点は、三ページ目にまとめてある。", "explanation": "ここは〈要点〉（大事な部分）の意味。原点は物事の始まりを指すので、重要な部分という意味では合わない。"}, {"text": "この商品は原点が高いので、値段も高い。", "explanation": "ここは〈原価〉の意味。原点は物事の始まりを指すので、費用の意味では合わない。"}, {"text": "この料金は、相場を原点に決めた。", "explanation": "ここは〈基準〉の意味。原点は始まりの点を指すので、判断の物差しとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36940, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原点", "is_correct": true, "explanation": "「運動を始めた原点」は運動の出発点を指し、文に合う。"}, {"text": "鍵盤", "is_correct": false, "explanation": "運動を始めた経緯を「鍵盤」とは言わず、意味が通らない。"}, {"text": "段ボール", "is_correct": false, "explanation": "運動の始まりを「段ボール」とは言わず、文に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "運動の出発点として「座布団」は合わず、文が成り立たない。"}], "explanations": {"原点": "「運動を始めた原点」は運動の出発点を指し、文に合う。", "鍵盤": "運動を始めた経緯を「鍵盤」とは言わず、意味が通らない。", "段ボール": "運動の始まりを「段ボール」とは言わず、文に合わない。", "座布団": "運動の出発点として「座布団」は合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "原点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この借金の原点は、百万円だ。", "explanation": "ここは〈元金〉（元になる金額）の意味。原点は物事の始まりを指すので、金額の意味では合わない。"}, {"text": "この小説の原点は、もう出版社に届いた。", "explanation": "ここは〈原稿〉の意味。原点は始まりの点を指し、書類や文章を表さないので合わない。"}, {"text": "この山の原点は、雪に覆われている。", "explanation": "ここは〈頂上〉（一番高い所）の意味。原点は物事の始まりを指すので、山の頂きの意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36940, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は失敗しても、いつも原点で忘れない人だ。", "corrected_sentence": "彼女は失敗しても、いつも原点を忘れない人だ。", "error_description": "「原点を忘れる」の対象を示す「を」が「で」になっている。正しくは「原点を忘れない」。「原点で忘れる」は不自然なので直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36940, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "難しいときこそ、原点に見つめ直すことが大切だ。", "corrected_sentence": "難しいときこそ、原点を見つめ直すことが大切だ。", "error_description": "「見つめ直す」の対象は「を」で示す。「原点に見つめ直す」の「に」が誤りで、「原点を見つめ直す」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
