INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36941, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見失う」の対象は「を」で示すので、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「原点が見失う」は「原点」を主語にしてしまい、「見失う」の目的語にならず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「原点より見失う」は比べる意味にならず、文が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するので、「原点の見失うと」は目的語を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「見失う」の対象は「を」で示すので、文に合う。", "が": "「原点が見失う」は「原点」を主語にしてしまい、「見失う」の目的語にならず文が成り立たない。", "より": "「より」は比較を示すので、「原点より見失う」は比べる意味にならず、文が通らない。", "の": "「の」は名詞を修飾するので、「原点の見失うと」は目的語を示せず、文が成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36941, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の始まりや、基礎となる点。", "primary_collocate": null, "pronunciation": "げんてん", "ipa": "ɡeɴteɴ", "syllable_count": 4, "sentences": [{"text": "基礎の練習こそ、すべての上達の原点だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "基礎[きそ]の練習[れんしゅう]こそ、すべての上達[じょうたつ]の原点[げんてん]だ。", "sentence_source": "generated"}, {"text": "新しい計画を立てる前に、原点を確認しよう。", "target_word": "原点", "complexity_tier": "T3", "furigana": "新[あたら]しい計画[けいかく]を立[た]てる前[まえ]に、原点[げんてん]を確認[かくにん]しよう。", "sentence_source": "generated"}, {"text": "迷ったときは、仕事の原点に立ち返るようにしている。", "target_word": "原点", "complexity_tier": "T3", "furigana": "迷[まよ]ったときは、仕事[しごと]の原点[げんてん]に立[た]ち返[かえ]るようにしている。", "sentence_source": "generated"}, {"text": "家族との会話が、私の考え方の原点になった。", "target_word": "原点", "complexity_tier": "T3", "furigana": "家族[かぞく]との会話[かいわ]が、私[わたし]の考[かんが]え方[かた]の原点[げんてん]になった。", "sentence_source": "generated"}, {"text": "この絵本は、物語を書く者の原点とも言える作品だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "この絵本[えほん]は、物語[ものがたり]を書[か]く者[もの]の原点[げんてん]とも言[い]える作品[さくひん]だ。", "sentence_source": "generated"}, {"text": "会社の理念は、すべての判断の原点だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の理念[りねん]は、すべての判断[はんだん]の原点[げんてん]だ。", "sentence_source": "generated"}, {"text": "彼は初心を忘れず、いつも原点から考える。", "target_word": "原点", "complexity_tier": "T3", "furigana": "彼[かれ]は初心[しょしん]を忘[わす]れず、いつも原点[げんてん]から考[かんが]える。", "sentence_source": "generated"}, {"text": "原点を見失うと、何のために働くのか分からなくなる。", "target_word": "原点", "complexity_tier": "T3", "furigana": "原点[げんてん]を見失[みうしな]うと、何[なん]のために働[はたら]くのか分[わ]からなくなる。", "sentence_source": "generated"}, {"text": "この事件が、環境運動の原点になった。", "target_word": "原点", "complexity_tier": "T3", "furigana": "この事件[じけん]が、環境運動[かんきょううんどう]の原点[げんてん]になった。", "sentence_source": "generated"}, {"text": "チームの原点は、仲間を大切にする心だ。", "target_word": "原点", "complexity_tier": "T3", "furigana": "チームの原点[げんてん]は、仲間[なかま]を大切[たいせつ]にする心[こころ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原点", "label": "基本形"}, {"form": "原点に", "label": "に格"}, {"form": "原点から", "label": "から格"}], "register": "中立", "sense_fingerprint": "判断や考えの土台となる基本の点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36941, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原点", "is_correct": true, "explanation": "「上達の原点」は上達の出発点を指し、文に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "上達の要素として「湿度」は意味が通らない。"}, {"text": "段ボール", "is_correct": false, "explanation": "上達を支える要素として「段ボール」は合わず、文が成り立たない。"}, {"text": "句読点", "is_correct": false, "explanation": "上達を表す語として「句読点」は意味が通らない。"}], "explanations": {"原点": "「上達の原点」は上達の出発点を指し、文に合う。", "湿度": "上達の要素として「湿度」は意味が通らない。", "段ボール": "上達を支える要素として「段ボール」は合わず、文が成り立たない。", "句読点": "上達を表す語として「句読点」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "原点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は原点が高く、利益が少ない。", "explanation": "ここは〈原価〉の意味。原点は物事の始まりを指すので、費用の意味では合わない。"}, {"text": "来月の売上の原点は、百万円だ。", "explanation": "ここは〈目安〉（おおよその基準の数字）の意味。原点は始まりの点を指すので、数値の目安とは言えない。"}, {"text": "彼は後半に原点を三点加えた。", "explanation": "ここは〈得点〉の意味。原点は物事の始まりを指すので、点数の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36941, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原点", "is_correct": true, "explanation": "「原点から考える」は出発点から考えることで、文に合う。"}, {"text": "鍵盤", "is_correct": false, "explanation": "「鍵盤から考える」は意味が通らない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団から考える」は文脈に合わず、意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気から考える」は意味が通らず、文が成り立たない。"}], "explanations": {"原点": "「原点から考える」は出発点から考えることで、文に合う。", "鍵盤": "「鍵盤から考える」は意味が通らない。", "座布団": "「座布団から考える」は文脈に合わず、意味が通らない。", "天気": "「天気から考える」は意味が通らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "原点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社を訴えたのは、原点の元社員だ。", "explanation": "ここは〈原告〉（訴えた側の人）の意味。原点は物事の始まりを指し、人を表さないので合わない。"}, {"text": "この工場では、原点を精製して燃料を作る。", "explanation": "ここは〈原油〉の意味。原点は始まりの点を指し、精製する材料を表さないので合わない。"}, {"text": "このチームの原点は、勝ち点が最も多い順位だ。", "explanation": "ここは〈首位〉（一番上の順位）の意味。原点は物事の始まりを指すので、順位の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36941, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では、いつも原点を立ち返って議論する。", "corrected_sentence": "会議では、いつも原点に立ち返って議論する。", "error_description": "「立ち返る」の帰着点は「に」で示す。「原点を立ち返る」の「を」が誤りで、「原点に立ち返る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36941, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "迷うときは、原点を立ち返ることが大切だ。", "corrected_sentence": "迷うときは、原点に立ち返ることが大切だ。", "error_description": "「立ち返る」の帰着点は「に」で示す。「原点を立ち返る」の「を」が誤りで、「原点に立ち返る」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「評価が分かれる」の主語。意見や評価が割れていることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「分かれる」は自動詞なので目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「評価で分かれている」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す。「評価と分かれている」は文意に合わない。"}], "correct_answer": "が", "explanations": {"が": "「評価が分かれる」の主語。意見や評価が割れていることを表す。", "を": "「分かれる」は自動詞なので目的語の「を」は取れない。", "で": "手段や場所を表すが、「評価で分かれている」では意味が通らない。", "と": "相手や並列を表す。「評価と分かれている」は文意に合わない。"}, "error_tags": {"を": "目的語の誤用", "で": "手段の誤用", "と": "相手の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるものや人の価値を、よく考えて判断すること。", "primary_collocate": null, "pronunciation": "ひょうか", "ipa": "çoːka", "syllable_count": 3, "sentences": [{"text": "先生は私の作文を高く評価してくれた。", "target_word": "評価", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の作文[さくぶん]を高[たか]く評価[ひょうか]してくれた。", "sentence_source": "generated"}, {"text": "この映画は専門家の評価が分かれている。", "target_word": "評価", "complexity_tier": "T3", "furigana": "この映画[えいが]は専門家[せんもんか]の評価[ひょうか]が分[わ]かれている。", "sentence_source": "generated"}, {"text": "長い間努力を続けた結果、会社での評価が上がった。", "target_word": "評価", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]努力[どりょく]を続[つづ]けた結果[けっか]、会社[かいしゃ]での評価[ひょうか]が上[あ]がった。", "sentence_source": "generated"}, {"text": "試験の点数だけで人の価値を評価するのは正しくない。", "target_word": "評価", "complexity_tier": "T3", "furigana": "試験[しけん]の点数[てんすう]だけで人[ひと]の価値[かち]を評価[ひょうか]するのは正[ただ]しくない。", "sentence_source": "generated"}, {"text": "彼の作品は、亡くなった後にようやく正当な評価を受けた。", "target_word": "評価", "complexity_tier": "T3", "furigana": "彼[かれ]の作品[さくひん]は、亡[な]くなった後[あと]にようやく正当[せいとう]な評価[ひょうか]を受[う]けた。", "sentence_source": "generated"}, {"text": "客の評価が低かったので、店はメニューを変えた。", "target_word": "評価", "complexity_tier": "T3", "furigana": "客[きゃく]の評価[ひょうか]が低[ひく]かったので、店[みせ]はメニューを変[か]えた。", "sentence_source": "generated"}, {"text": "新しい資料を見て、私は彼に対する評価を改めた。", "target_word": "評価", "complexity_tier": "T3", "furigana": "新[あたら]しい資料[しりょう]を見[み]て、私[わたし]は彼[かれ]に対[たい]する評価[ひょうか]を改[あらた]めた。", "sentence_source": "generated"}, {"text": "仕事の成果を公平に評価する制度が必要だ。", "target_word": "評価", "complexity_tier": "T3", "furigana": "仕事[しごと]の成果[せいか]を公平[こうへい]に評価[ひょうか]する制度[せいど]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "実際に使ってみないと、この道具の評価はできない。", "target_word": "評価", "complexity_tier": "T3", "furigana": "実際[じっさい]に使[つか]ってみないと、この道具[どうぐ]の評価[ひょうか]はできない。", "sentence_source": "generated"}, {"text": "去年の失敗があったため、部長からの評価は厳しかった。", "target_word": "評価", "complexity_tier": "T3", "furigana": "去年[きょねん]の失敗[しっぱい]があったため、部長[ぶちょう]からの評価[ひょうか]は厳[きび]しかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "評価する", "label": "辞書形"}, {"form": "評価して", "label": "て形"}, {"form": "評価した", "label": "た形"}, {"form": "評価される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "物事や人の価値を考えて判断すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "評価", "is_correct": true, "explanation": "作文の出来を判断して高く評価する意味で、「高く」と文脈に合う。"}, {"text": "批判", "is_correct": false, "explanation": "欠点を指摘する意味。「作文を高く批判」は文脈に合わない。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを振り返ること。作文を対象にした「高く反省」は成り立たない。"}, {"text": "想像", "is_correct": false, "explanation": "頭の中で思い描くこと。「作文を高く想像」は文として不自然。"}], "explanations": {"評価": "作文の出来を判断して高く評価する意味で、「高く」と文脈に合う。", "批判": "欠点を指摘する意味。「作文を高く批判」は文脈に合わない。", "反省": "自分の行いを振り返ること。作文を対象にした「高く反省」は成り立たない。", "想像": "頭の中で思い描くこと。「作文を高く想像」は文として不自然。"}, "sentence_index": 0, "correct_answer": "評価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事故の犯人を評価して、警察がついに逮捕した。", "explanation": "ここは〈特定〉の意味。評価は物事の価値を判断することで、犯人を見つける意味では使わない。"}, {"text": "寒い夜、ストーブに火を評価した。", "explanation": "ここは〈点火〉の意味。ストーブに火を付けるのは点火で、評価しても火はつかない。"}, {"text": "このバッグは評価が三万円もした。", "explanation": "ここは〈価格〉の意味。金額は価格で、評価は物事の価値の判断を表すので、値段の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "評価", "is_correct": true, "explanation": "人の働きや見方を判断し直す意味で、「彼に対する〜を改めた」に合う。"}, {"text": "点検", "is_correct": false, "explanation": "調べて状態を確かめる意味。見方を改める文脈には合わない。"}, {"text": "採取", "is_correct": false, "explanation": "取り集める意味。「彼に対する採取を改めた」は成り立たない。"}, {"text": "計量", "is_correct": false, "explanation": "分量をはかる意味。人に対する見方には使えない。"}], "explanations": {"評価": "人の働きや見方を判断し直す意味で、「彼に対する〜を改めた」に合う。", "点検": "調べて状態を確かめる意味。見方を改める文脈には合わない。", "採取": "取り集める意味。「彼に対する採取を改めた」は成り立たない。", "計量": "分量をはかる意味。人に対する見方には使えない。"}, "sentence_index": 6, "correct_answer": "評価"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "くじの当選者を評価して、景品を渡した。", "explanation": "ここは〈抽選〉の意味。くじで決まることに評価は使わない。"}, {"text": "荷物を家まで評価した。", "explanation": "ここは〈配達〉の意味。荷物を家まで届けるのは配達で、評価では物を運べない。"}, {"text": "明日の雨量を評価して、傘を買った。", "explanation": "ここは〈予測〉の意味。雨量は予測するもので、評価の対象にはしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このゲームは若い世代の評価を分かれている。", "corrected_sentence": "このゲームは若い世代の評価が分かれている。", "error_description": "「評価が分かれる」の主語は「評価が」。「分かれる」は自動詞なので「評価を」は誤り。正しくは「評価が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36942, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の料理は客から高く評価して、人気が出た。", "corrected_sentence": "この店の料理は客から高く評価されて、人気が出た。", "error_description": "「客から評価される」の受身が必要。「評価して」は能動の形で、評価される側の文脈に合わない。正しくは「評価されて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「住宅を買う」の目的語を示す。買うは他動詞なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "「住宅が買う」では主語になり、買う主体が兄である文の意味と合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置を表す「に」では、買う対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、買う対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「住宅を買う」の目的語を示す。買うは他動詞なので「を」。", "が": "「住宅が買う」では主語になり、買う主体が兄である文の意味と合わない。", "に": "位置を表す「に」では、買う対象を示せない。", "へ": "方向を表す「へ」では、買う対象を示せない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「住宅では」で、話題になる場所（住宅という場）を示す。"}, {"text": "と", "is_correct": false, "explanation": "「住宅と悩む」では並列や相手を示すが、悩む人との関係として文が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞を伴わないと文が切れてしまい、ここでは成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐだけなので、「住宅の、」で文が切れて成立しない。"}], "correct_answer": "で", "explanations": {"で": "「住宅では」で、話題になる場所（住宅という場）を示す。", "と": "「住宅と悩む」では並列や相手を示すが、悩む人との関係として文が成立しない。", "を": "「を」は動詞を伴わないと文が切れてしまい、ここでは成立しない。", "の": "「の」は名詞をつなぐだけなので、「住宅の、」で文が切れて成立しない。"}, "error_tags": {"と": "並列", "を": "目的語（動詞なし）", "の": "所有・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が住んでいるための建物や場所です。", "primary_collocate": null, "pronunciation": "じゅうたく", "ipa": "dʑɯːtakɯ", "syllable_count": 4, "sentences": [{"text": "この町は駅から近いので、新しい住宅がどんどん建っています。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "この町[まち]は駅[えき]から近[ちか]いので、新[あたら]しい住宅[じゅうたく]がどんどん建[た]っています。", "sentence_source": "generated"}, {"text": "兄は来月、郊外にある小さな住宅を買う予定です。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "兄[あに]は来月[らいげつ]、郊外[こうがい]にある小[ちい]さな住宅[じゅうたく]を買[か]う予定[よてい]です。", "sentence_source": "generated"}, {"text": "住宅が増えたため、田んぼだった場所は今ではほとんど残っていません。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "住宅[じゅうたく]が増[ふ]えたため、田[た]んぼだった場所[ばしょ]は今[いま]ではほとんど残[のこ]っていません。", "sentence_source": "generated"}, {"text": "地震に強い住宅を作るには、土台をしっかり固める必要があります。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "地震[じしん]に強[つよ]い住宅[じゅうたく]を作[つく]るには、土台[どだい]をしっかり固[かた]める必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "古い住宅は冬になると寒いので、窓を二重にしました。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "古[ふる]い住宅[じゅうたく]は冬[ふゆ]になると寒[さむ]いので、窓[まど]を二重[にじゅう]にしました。", "sentence_source": "generated"}, {"text": "山の斜面に並ぶ住宅の屋根が、夕日を受けて赤く光っていました。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]に並[なら]ぶ住宅[じゅうたく]の屋根[やね]が、夕日[ゆうひ]を受[う]けて赤[あか]く光[ひか]っていました。", "sentence_source": "generated"}, {"text": "会社は社員のために、駅の近くに安い住宅を用意してくれました。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]のために、駅[えき]の近[ちか]くに安[やす]い住宅[じゅうたく]を用意[ようい]してくれました。", "sentence_source": "generated"}, {"text": "工場の隣の住宅では、毎日の騒音に悩む人が多いそうです。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "工場[こうじょう]の隣[となり]の住宅[じゅうたく]では、毎日[まいにち]の騒音[そうおん]に悩[なや]む人[ひと]が多[おお]いそうです。", "sentence_source": "generated"}, {"text": "住宅の広さよりも、日当たりのよさを選ぶ人もいます。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "住宅[じゅうたく]の広[ひろ]さよりも、日当[ひあ]たりのよさを選[えら]ぶ人[ひと]もいます。", "sentence_source": "generated"}, {"text": "市は災害で家を失った人のために、仮の住宅を急いで準備しました。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "市[し]は災害[さいがい]で家[いえ]を失[うしな]った人[ひと]のために、仮[かり]の住宅[じゅうたく]を急[いそ]いで準備[じゅんび]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住宅", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人が暮らすための建物。家や集合した居住用の建物を指す一般的な語。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住宅", "is_correct": true, "explanation": "「新しい住宅がどんどん建っています」の主語として、建つものに当たる。"}, {"text": "工事", "is_correct": false, "explanation": "工事は建つものではないので、「新しい工事がどんどん建っています」は成立しない。"}, {"text": "費用", "is_correct": false, "explanation": "費用は建つものではないので、文が成立しない。"}, {"text": "交通", "is_correct": false, "explanation": "交通は建つものではないので、文が成立しない。"}], "explanations": {"住宅": "「新しい住宅がどんどん建っています」の主語として、建つものに当たる。", "工事": "工事は建つものではないので、「新しい工事がどんどん建っています」は成立しない。", "費用": "費用は建つものではないので、文が成立しない。", "交通": "交通は建つものではないので、文が成立しない。"}, "sentence_index": 0, "correct_answer": "住宅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この畑は、毎年春に野菜を植える大切な住宅だ。", "explanation": "ここは〈畑〉の意味。畑は作物を育てる場所で、人が住むための住宅とは言わない。"}, {"text": "この工場は、毎日二十四時間機械が動く住宅だ。", "explanation": "ここは〈工場〉の意味。工場は生産のための施設で、住宅とは言わない。"}, {"text": "この店は、夜遅くまで客でにぎわう住宅だ。", "explanation": "ここは〈店〉の意味。店は商売の場で、暮らすための住宅とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住宅", "is_correct": true, "explanation": "「安い住宅を用意」の目的語として、家を指す。"}, {"text": "社員", "is_correct": false, "explanation": "「安い社員を用意」は意味をなさず、文が成立しない。"}, {"text": "天気", "is_correct": false, "explanation": "「安い天気を用意」は成立しない。"}, {"text": "駅", "is_correct": false, "explanation": "「安い駅を用意」は成立せず、「駅の近く」の文脈と合わない。"}], "explanations": {"住宅": "「安い住宅を用意」の目的語として、家を指す。", "社員": "「安い社員を用意」は意味をなさず、文が成立しない。", "天気": "「安い天気を用意」は成立しない。", "駅": "「安い駅を用意」は成立せず、「駅の近く」の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "住宅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この学校は、毎朝生徒が勉強する大切な住宅だ。", "explanation": "ここは〈学校〉の意味。学校は教育の施設で、人が暮らすための住宅とは違う。"}, {"text": "駅前の事務所は、社員が夜まで働く住宅だ。", "explanation": "ここは〈事務所〉の意味。事務所は仕事の場で、暮らすための住宅とは合わない。"}, {"text": "市場は、朝早くから人が買い物をする住宅だ。", "explanation": "ここは〈市場〉の意味。市場は商いの場で、住宅とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は来月、郊外の住宅が買う予定です。", "corrected_sentence": "兄は来月、郊外の住宅を買う予定です。", "error_description": "「買う」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36944, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい住宅が建てないので、中古を買った。", "corrected_sentence": "新しい住宅を建てないので、中古を買った。", "error_description": "「建てる」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「住宅が次々と建っています」の主語を示す。建つ（自動詞）の主語は「が」。"}, {"text": "を", "is_correct": false, "explanation": "「建つ」は他動詞ではないので、目的語の「を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」では、建っている対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、ここで文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「住宅が次々と建っています」の主語を示す。建つ（自動詞）の主語は「が」。", "を": "「建つ」は他動詞ではないので、目的語の「を」は取らない。", "で": "場所や手段を表す「で」では、建っている対象を示せない。", "より": "比較の「より」では、ここで文の意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「住宅が並んでいる」の主語を示す。並ぶ（自動詞）の主語は「が」。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」では、並んでいる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、並んでいる状態の主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では、文の述語「並んでいる」が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「住宅が並んでいる」の主語を示す。並ぶ（自動詞）の主語は「が」。", "から": "起点を表す「から」では、並んでいる対象を示せない。", "へ": "方向を表す「へ」では、並んでいる状態の主語にならない。", "の": "連体修飾の「の」では、文の述語「並んでいる」が成り立たない。"}, "error_tags": {"から": "起点", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が生活するための建物や、その建物が集まっている地域のこと。", "primary_collocate": null, "pronunciation": "じゅうたく", "ipa": "dʑɯːtakɯ", "syllable_count": 4, "sentences": [{"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "住宅", "complexity_tier": "T4", "furigana": "せんごのとしけいかくにおいて、ブルータリズムはきのうせいをじゅうししたあらたなじゅうたくようしきとしてふきゅうしました。", "sentence_source": "mined"}, {"text": "駅の近くに新しい住宅が次々と建っています。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "えきのちかくにあたらしいじゅうたくがつぎつぎとたっています。", "sentence_source": "generated"}, {"text": "この町は、静かな住宅が多くて暮らしやすいです。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "このまちは、しずかなじゅうたくがおおくてくらしやすいです。", "sentence_source": "generated"}, {"text": "市は、お年寄りのために安い住宅を用意しました。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "しは、おとしよりのためにやすいじゅうたくをよういしました。", "sentence_source": "generated"}, {"text": "木で造った住宅は、夏でもすずしく過ごせます。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "きでつくったじゅうたくは、なつでもすずしくすごせます。", "sentence_source": "generated"}, {"text": "地震に強い住宅を選ぶ人が増えています。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "じしんにつよいじゅうたくをえらぶひとがふえています。", "sentence_source": "generated"}, {"text": "古い住宅を直して、カフェとして使っています。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "ふるいじゅうたくをなおして、カフェとしてつかっています。", "sentence_source": "generated"}, {"text": "山の斜面に、小さな住宅が並んでいる。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "やまのしゃめんに、ちいさなじゅうたくがならんでいる。", "sentence_source": "generated"}, {"text": "住宅の窓から、海がよく見えます。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "じゅうたくのまどから、うみがよくみえます。", "sentence_source": "generated"}, {"text": "工場の跡地に、大きな住宅ができる予定です。", "target_word": "住宅", "complexity_tier": "T3", "furigana": "こうじょうのあとちに、おおきなじゅうたくができるよていです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住宅", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が暮らすための建物、またはそれが集まった地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: すずしく (Zipf 1.49)']::text[], '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住宅", "is_correct": true, "explanation": "「新たな住宅様式」として、建物の型を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「新たな天気様式」は成立せず、文が意味をなさない。"}, {"text": "駅", "is_correct": false, "explanation": "「新たな駅様式」は建物の型を表さず、不自然。"}, {"text": "財布", "is_correct": false, "explanation": "「新たな財布様式」は成立せず、建築の話題に合わない。"}], "explanations": {"住宅": "「新たな住宅様式」として、建物の型を表す。", "天気": "「新たな天気様式」は成立せず、文が意味をなさない。", "駅": "「新たな駅様式」は建物の型を表さず、不自然。", "財布": "「新たな財布様式」は成立せず、建築の話題に合わない。"}, "sentence_index": 0, "correct_answer": "住宅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市民会館は地域の大きな住宅で、毎月多くの催し物が開かれる。", "explanation": "ここは〈建物〉の意味。会館は催し物のための建物で、人が暮らす住宅とは言わない。"}, {"text": "図書館は、子どもが本を読む大切な住宅だ。", "explanation": "ここは〈施設〉の意味。図書館は公共施設で、人が生活する建物ではないので住宅は使えない。"}, {"text": "駅前の店舗は、夕方になると多くの客でにぎわう住宅だ。", "explanation": "ここは〈店〉の意味。店舗は商売の場で、暮らすための住宅とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住宅", "is_correct": true, "explanation": "「古い住宅」として、建物を指す。直して使う対象になる。"}, {"text": "試合", "is_correct": false, "explanation": "「古い試合を直す」は不自然で、建物の意味に合わない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は直して住む・使うものではなく、カフェにする文脈に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「古い季節を直す」は言えず、文が成立しない。"}], "explanations": {"住宅": "「古い住宅」として、建物を指す。直して使う対象になる。", "試合": "「古い試合を直す」は不自然で、建物の意味に合わない。", "雑誌": "雑誌は直して住む・使うものではなく、カフェにする文脈に合わない。", "季節": "「古い季節を直す」は言えず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "住宅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の近くの神社は、毎年多くの参拝者が集まる住宅だ。", "explanation": "ここは〈神社〉の意味。神社は参拝の施設で、人が生活する住宅とは違う。"}, {"text": "この病院は、毎日たくさんの患者を診る住宅だ。", "explanation": "ここは〈病院〉の意味。病院は治療の施設で、人が暮らすための建物ではない。"}, {"text": "小さな事務所は、三人の社員が働く住宅だ。", "explanation": "ここは〈事務所〉の意味。事務所は仕事の場で、暮らすための住宅とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父母はこの住宅を三十年住んでいる。", "corrected_sentence": "祖父母はこの住宅に三十年住んでいる。", "error_description": "「住む」は場所を「に」で示す。「住宅を」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36945, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い住宅の直して、カフェにした。", "corrected_sentence": "古い住宅を直して、カフェにした。", "error_description": "「直す」の目的語は「住宅を」で示す。「住宅の」は誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
