INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36946, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いろいろなものを使って、うまく役に立たせること。", "primary_collocate": null, "pronunciation": "かつよう", "ipa": "kat͡sɯjoː", "syllable_count": 4, "sentences": [{"text": "余った布を活用して、かわいい袋を作った。", "target_word": "活用", "complexity_tier": "T3", "furigana": "余[あま]った布[ぬの]を活用[かつよう]して、かわいい袋[ふくろ]を作[つく]った。", "sentence_source": "generated"}, {"text": "経験を活用できる仕事を探している。", "target_word": "活用", "complexity_tier": "T3", "furigana": "経験[けいけん]を活用[かつよう]できる仕事[しごと]を探[さが]している。", "sentence_source": "generated"}, {"text": "古い新聞紙を活用すると、窓がきれいに拭ける。", "target_word": "活用", "complexity_tier": "T3", "furigana": "古[ふる]い新聞紙[しんぶんし]を活用[かつよう]すると、窓[まど]がきれいに拭[ふ]ける。", "sentence_source": "generated"}, {"text": "学んだ知識は、実際の生活で活用してこそ意味がある。", "target_word": "活用", "complexity_tier": "T3", "furigana": "学[まな]んだ知識[ちしき]は、実際[じっさい]の生活[せいかつ]で活用[かつよう]してこそ意味[いみ]がある。", "sentence_source": "generated"}, {"text": "母は残り物を活用して、おいしいスープを作ってくれた。", "target_word": "活用", "complexity_tier": "T3", "furigana": "母[はは]は残[のこ]り物[もの]を活用[かつよう]して、おいしいスープを作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "辞書を活用しながら、英語の本を読み進めた。", "target_word": "活用", "complexity_tier": "T3", "furigana": "辞書[じしょ]を活用[かつよう]しながら、英語[えいご]の本[ほん]を読[よ]み進[すす]めた。", "sentence_source": "generated"}, {"text": "彼はあらゆる人脈を活用し、短い期間で店を開いた。", "target_word": "活用", "complexity_tier": "T3", "furigana": "彼[かれ]はあらゆる人脈[じんみゃく]を活用[かつよう]し、短[みじか]い期間[きかん]で店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "空いた時間を活用して、毎日少しずつ日記を書いている。", "target_word": "活用", "complexity_tier": "T3", "furigana": "空[あ]いた時間[じかん]を活用[かつよう]して、毎日[まいにち]少[すこ]しずつ日記[にっき]を書[か]いている。", "sentence_source": "generated"}, {"text": "使わなくなった傘を活用した植木鉢が、庭に並んでいる。", "target_word": "活用", "complexity_tier": "T3", "furigana": "使[つか]わなくなった傘[かさ]を活用[かつよう]した植木鉢[うえきばち]が、庭[にわ]に並[なら]んでいる。", "sentence_source": "generated"}, {"text": "町の人たちは地元の素材を活用して、新しいお菓子を考えた。", "target_word": "活用", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちは地元[じもと]の素材[そざい]を活用[かつよう]して、新[あたら]しいお菓子[かし]を考[かんが]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活用する", "label": "辞書形"}, {"form": "活用した", "label": "過去形"}, {"form": "活用しない", "label": "否定形"}, {"form": "活用できる", "label": "可能形"}, {"form": "活用される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "余り物・経験・知識などをうまく使って役に立たせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 拭ける (Zipf 1.63)']::text[], 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36946, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活用", "is_correct": true, "explanation": "「余った布を活用して」で、余り物をうまく役立てる意味が入る。"}, {"text": "通勤", "is_correct": false, "explanation": "通勤は職場へ行き来すること。「布を通勤して」では意味が成り立たない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれること。布を目的語にすると文が通らない。"}, {"text": "遅刻", "is_correct": false, "explanation": "遅刻は時刻に遅れること。布を目的語にする文では意味が通らない。"}], "explanations": {"活用": "「余った布を活用して」で、余り物をうまく役立てる意味が入る。", "通勤": "通勤は職場へ行き来すること。「布を通勤して」では意味が成り立たない。", "誕生": "誕生は生まれること。布を目的語にすると文が通らない。", "遅刻": "遅刻は時刻に遅れること。布を目的語にする文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "活用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は、毎日の活用を静かに楽しんでいる。", "explanation": "ここは〈生活〉の意味。日々の暮らしを指す語で、道具や方法を役立てる活用とは別。"}, {"text": "「書く」は五段に活用する動詞だ。", "explanation": "ここは〈文法の語形変化〉の意味。動詞の形が変わることを指し、役立てる意味の活用とは別。"}, {"text": "祖父の活用のカメラは、今も大切に飾ってある。", "explanation": "ここは〈愛用〉の意味。大切に使い続けている品を表す語で、役立てる意味の活用は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36946, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活用", "is_correct": true, "explanation": "「人脈を活用し」で、人のつながりをうまく役立てる意味が入る。"}, {"text": "失業", "is_correct": false, "explanation": "失業は仕事を失うこと。人脈を目的語にすると文が成り立たない。"}, {"text": "出勤", "is_correct": false, "explanation": "出勤は職場へ行くこと。人脈を目的語にする文では意味が通らない。"}, {"text": "欠勤", "is_correct": false, "explanation": "欠勤は仕事を休むこと。人脈を目的語にすると文が通らない。"}], "explanations": {"活用": "「人脈を活用し」で、人のつながりをうまく役立てる意味が入る。", "失業": "失業は仕事を失うこと。人脈を目的語にすると文が成り立たない。", "出勤": "出勤は職場へ行くこと。人脈を目的語にする文では意味が通らない。", "欠勤": "欠勤は仕事を休むこと。人脈を目的語にすると文が通らない。"}, "sentence_index": 6, "correct_answer": "活用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "「食べる」は一段に活用する動詞だ。", "explanation": "ここは〈文法の語形変化〉の意味。動詞の形が変わることを指し、役立てる意味の活用とは別。"}, {"text": "会社は、大きな活用を得た。", "explanation": "ここは〈利益〉の意味。もうけのことを指し、役立てる行為を表す活用とは合わない。"}, {"text": "今年の新人は、試合で大活用した。", "explanation": "ここは〈活躍〉の意味。目立って働くことを表す語で、道具や方法を役立てる活用とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36946, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "余った食材を活用ないと、もったいない。", "corrected_sentence": "余った食材を活用しないと、もったいない。", "error_description": "「活用」は「する」の付く動詞。否定は「活用しない」が正しく、「活用ない」は動詞の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36946, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の余った食材を活用で、新しい料理を作った。", "corrected_sentence": "店の余った食材を活用して、新しい料理を作った。", "error_description": "「活用」の後は「して」で文をつなぐ。「で」は誤りで、「活用して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
