INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36947, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "道具や方法、場所などを、目的に合わせて効果的に使うこと。", "primary_collocate": null, "pronunciation": "かつよう", "ipa": "kat͡sɯjoː", "syllable_count": 4, "sentences": [{"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "活用", "complexity_tier": "T3", "furigana": "近年[きんねん]、センサーやデータ解析技術[かいせきぎじゅつ]を活用[かつよう]した「精密農業[せいみつのうぎょう]」が注目[ちゅうもく]されています。", "sentence_source": "mined"}, {"text": "空き教室を活用して、放課後の学習スペースを作った。", "target_word": "活用", "complexity_tier": "T3", "furigana": "空[あ]き教室[きょうしつ]を活用[かつよう]して、放課後[ほうかご]の学習[がくしゅう]スペースを作[つく]った。", "sentence_source": "generated"}, {"text": "この町は古い駅舎を活用した、小さな美術館で有名だ。", "target_word": "活用", "complexity_tier": "T3", "furigana": "この町[まち]は古[ふる]い駅舎[えきしゃ]を活用[かつよう]した、小[ちい]さな美術館[びじゅつかん]で有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "地図アプリを活用すれば、初めての街でも迷わない。", "target_word": "活用", "complexity_tier": "T3", "furigana": "地図[ちず]アプリを活用[かつよう]すれば、初[はじ]めての街[まち]でも迷[まよ]わない。", "sentence_source": "generated"}, {"text": "雨水を活用する取り組みが、各地の学校で始まっている。", "target_word": "活用", "complexity_tier": "T3", "furigana": "雨水[あまみず]を活用[かつよう]する取[と]り組[く]みが、各地[かくち]の学校[がっこう]で始[はじ]まっている。", "sentence_source": "generated"}, {"text": "限られた予算を上手に活用して、目標の本数を作り終えた。", "target_word": "活用", "complexity_tier": "T3", "furigana": "限[かぎ]られた予算[よさん]を上手[じょうず]に活用[かつよう]して、目標[もくひょう]の本数[ほんすう]を作[つく]り終[お]えた。", "sentence_source": "generated"}, {"text": "休日は図書館を活用して、資格試験の勉強をしている。", "target_word": "活用", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]は図書館[としょかん]を活用[かつよう]して、資格[しかく]試験[しけん]の勉強[べんきょう]をしている。", "sentence_source": "generated"}, {"text": "先生は写真や動画を活用し、わかりやすい授業を心がけている。", "target_word": "活用", "complexity_tier": "T3", "furigana": "先生[せんせい]は写真[しゃしん]や動画[どうが]を活用[かつよう]し、わかりやすい授業[じゅぎょう]を心[こころ]がけている。", "sentence_source": "generated"}, {"text": "山の斜面を活用した段々畑は、景色も美しい。", "target_word": "活用", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]を活用[かつよう]した段々畑[だんだんばたけ]は、景色[けしき]も美[うつく]しい。", "sentence_source": "generated"}, {"text": "新しい機械を活用することで、作業時間が半分になった。", "target_word": "活用", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]を活用[かつよう]することで、作業[さぎょう]時間[じかん]が半分[はんぶん]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活用する", "label": "辞書形"}, {"form": "活用した", "label": "過去形"}, {"form": "活用しない", "label": "否定形"}, {"form": "活用できる", "label": "可能形"}, {"form": "活用される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "道具・方法・場所などを目的に合わせて効果的に使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 段々畑 (Zipf 1.93)']::text[], 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36947, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活用", "is_correct": true, "explanation": "「技術を活用した精密農業」で、道具や方法を目的に合わせて役立てる意味が入る。"}, {"text": "遅刻", "is_correct": false, "explanation": "遅刻は時刻に遅れること。「技術を遅刻した」は他動詞の形にならず成り立たない。"}, {"text": "病気", "is_correct": false, "explanation": "病気は体の不調のこと。「技術を病気した」では文が成り立たない。"}, {"text": "出勤", "is_correct": false, "explanation": "出勤は職場へ行くこと。「技術を出勤した」では目的語を取れず不自然。"}], "explanations": {"活用": "「技術を活用した精密農業」で、道具や方法を目的に合わせて役立てる意味が入る。", "遅刻": "遅刻は時刻に遅れること。「技術を遅刻した」は他動詞の形にならず成り立たない。", "病気": "病気は体の不調のこと。「技術を病気した」では文が成り立たない。", "出勤": "出勤は職場へ行くこと。「技術を出勤した」では目的語を取れず不自然。"}, "sentence_index": 0, "correct_answer": "活用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝の活用を欠かさず続けている。", "explanation": "ここは〈運動〉の意味。体を動かすことを指す語で、道具や方法を役立てる活用とは違う。"}, {"text": "「見る」は一段に活用する動詞だ。", "explanation": "ここは〈文法の語形変化〉の意味。動詞の形が変わることを指し、道具や方法を役立てる意味ではない。"}, {"text": "祭りの夜、町に活用が戻ってきた。", "explanation": "ここは〈活気〉の意味。にぎやかな勢いを表す語で、道具や方法を役立てる活用とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36947, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活用", "is_correct": true, "explanation": "「図書館を活用して」で、施設を勉強に役立てる意味が入る。"}, {"text": "宿泊", "is_correct": false, "explanation": "宿泊は泊まること。「図書館を宿泊して」では意味が通らない。"}, {"text": "通勤", "is_correct": false, "explanation": "通勤は職場へ行き来すること。図書館を目的語にすると文が成り立たない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれること。図書館を目的語にする文では意味が通らない。"}], "explanations": {"活用": "「図書館を活用して」で、施設を勉強に役立てる意味が入る。", "宿泊": "宿泊は泊まること。「図書館を宿泊して」では意味が通らない。", "通勤": "通勤は職場へ行き来すること。図書館を目的語にすると文が成り立たない。", "誕生": "誕生は生まれること。図書館を目的語にする文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "活用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "選手はチームの優勝に向けて、大活用した。", "explanation": "ここは〈活躍〉の意味。目立って働くことを表し、道具や方法を役立てる活用とは別の語。"}, {"text": "「来る」はカ変に活用する動詞だ。", "explanation": "ここは〈文法の語形変化〉の意味。動詞の形が変わることを指し、目的に合わせて役立てる意味ではない。"}, {"text": "この火山は百年ぶりに活用を始めた。", "explanation": "ここは〈活動〉の意味。火山が働き出す場面は活動で、道具や方法を役立てる活用とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36947, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "余った材料を活用れば、夕食がすぐに作れる。", "corrected_sentence": "余った材料を活用すれば、夕食がすぐに作れる。", "error_description": "「活用」は「する」の付く動詞。条件の「すれば」が正しく、「活用れば」は動詞の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36947, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人々は、空き地に活用して小さな花壇を作った。", "corrected_sentence": "町の人々は、空き地を活用して小さな花壇を作った。", "error_description": "「活用」は使うもの（目的語）に「を」を付ける。「に」は誤りで、「空き地を活用して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示し、「通うコストを考えると」と続く。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、「コストに考えると」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「考えると」の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "所属を示すが、「通うコストの考えると」は文として続かない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示し、「通うコストを考えると」と続く。", "に": "相手や場所を示すが、「コストに考えると」は意味が通らない。", "へ": "方向を示すが、「考えると」の目的語にはならない。", "の": "所属を示すが、「通うコストの考えると」は文として続かない。"}, "error_tags": {"に": "相手・場所", "へ": "方向", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示し、「コストが少ないとは限らない」と続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「少ない」は形容詞で目的語をとらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、「コストに少ない」は形容詞に続かず成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「コストから少ない」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語を示し、「コストが少ないとは限らない」と続く。", "を": "目的語を示すが、「少ない」は形容詞で目的語をとらないので合わない。", "に": "相手や場所を示すが、「コストに少ない」は形容詞に続かず成り立たない。", "から": "起点を示すが、「コストから少ない」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするために必要な、お金や時間や力のこと。", "primary_collocate": null, "pronunciation": "こすと", "ipa": "kosɯto", "syllable_count": 3, "sentences": [{"text": "この旅行は、時間のコストが大きすぎる。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "この旅行[りょこう]は、時間[じかん]のコストが大[おお]きすぎる。", "sentence_source": "generated"}, {"text": "安い店でも、通うコストを考えると高くつく。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "安[やす]い店[みせ]でも、通[かよ]うコストを考[かんが]えると高[たか]くつく。", "sentence_source": "generated"}, {"text": "手作りは材料のコストは低いが、時間がかかる。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "手作[てづく]りは材料[ざいりょう]のコストは低[ひく]いが、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "弟は、ゲームを買う前にコストをよく考えた。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "弟[おとうと]は、ゲームを買[か]う前[まえ]にコストをよく考[かんが]えた。", "sentence_source": "generated"}, {"text": "毎日遠くまで歩くのは、体力のコストが高い。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "毎日[まいにち]遠[とお]くまで歩[ある]くのは、体力[たいりょく]のコストが高[たか]い。", "sentence_source": "generated"}, {"text": "コストを下げるために、母は自分で野菜を育て始めた。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "コストを下[さ]げるために、母[はは]は自分[じぶん]で野菜[やさい]を育[そだ]て始[はじ]めた。", "sentence_source": "generated"}, {"text": "新しい服を買うより直すほうが、コストがかからない。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "新[あたら]しい服[ふく]を買[か]うより直[なお]すほうが、コストがかからない。", "sentence_source": "generated"}, {"text": "安いからといって、コストが少ないとは限らない。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "安[やす]いからといって、コストが少[すく]ないとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "部活を続けるコストは、お金だけではなく時間もだ。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "部活[ぶかつ]を続[つづ]けるコストは、お金[かね]だけではなく時間[じかん]もだ。", "sentence_source": "generated"}, {"text": "引っ越しのコストを調べたら、思ったより高かった。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのコストを調[しら]べたら、思[おも]ったより高[たか]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コスト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かをするために必要なお金・時間・力（日常的な負担）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コスト", "is_correct": true, "explanation": "時間の負担量を表し、「時間のコストが大きすぎる」と自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の性質で、「時間の色が大きすぎる」は意味が通らない。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉は表現手段で、「時間の言葉が大きすぎる」は成り立たない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは感覚の性質で、「時間の匂いが大きすぎる」は意味が通らない。"}], "explanations": {"コスト": "時間の負担量を表し、「時間のコストが大きすぎる」と自然に続く。", "色": "色は見た目の性質で、「時間の色が大きすぎる」は意味が通らない。", "言葉": "言葉は表現手段で、「時間の言葉が大きすぎる」は成り立たない。", "匂い": "匂いは感覚の性質で、「時間の匂いが大きすぎる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "コスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この方法の一番のコストは、時間が短くてすむことだ。", "explanation": "ここは〈メリット〉（利点）の意味。「時間が短くてすむ」は利点で、必要な負担を表すコストとは合わない。"}, {"text": "弟は、ゲームを買う前に、コストの好みをはっきり言った。", "explanation": "ここは〈好み〉の意味。「好みをはっきり言う」の好みは自分の趣味のことで、必要な金銭や時間の量であるコストは好みにならない。"}, {"text": "弟は、母にコストの気持ちを伝えた。", "explanation": "ここは〈感謝〉の意味。「〜の気持ち」と伝えるのは感謝で、金銭や労力の量であるコストは気持ちにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コスト", "is_correct": true, "explanation": "お金や労力の必要量で、「コストがかからない」と自然に続く。"}, {"text": "写真", "is_correct": false, "explanation": "写真は画像で、「写真がかからない」は成り立たない。"}, {"text": "野菜", "is_correct": false, "explanation": "野菜は食べ物で、「野菜がかからない」は意味が通らない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は周りにあるもので、「空気がかからない」は成り立たない。"}], "explanations": {"コスト": "お金や労力の必要量で、「コストがかからない」と自然に続く。", "写真": "写真は画像で、「写真がかからない」は成り立たない。", "野菜": "野菜は食べ物で、「野菜がかからない」は意味が通らない。", "空気": "空気は周りにあるもので、「空気がかからない」は成り立たない。"}, "sentence_index": 6, "correct_answer": "コスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は絵のコストに恵まれ、すぐに上達した。", "explanation": "ここは〈才能〉の意味。生まれ持った能力に「恵まれる」のは才能で、必要な量を表すコストとは合わない。"}, {"text": "明日のコストは晴れるでしょう。", "explanation": "ここは〈天気〉の意味。晴れるかどうかを言うのは天気で、コストは空の状態を表さない。"}, {"text": "コストが強くて、授業中ずっとあくびをしていた。", "explanation": "ここは〈眠気〉の意味。強くて抑えにくいのは眠気で、コストはそのような感覚の性質を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "業者ごとのコストが比べて、一番安いところに決めた。", "corrected_sentence": "業者ごとのコストを比べて、一番安いところに決めた。", "error_description": "「比べる」の目的語を示すのは「を」。「が」にすると主語になり、「比べて」と続かず文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36948, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい設備を入れると、コストがかける。", "corrected_sentence": "新しい設備を入れると、コストがかかる。", "error_description": "「コストが」に対応するのは自動詞の「かかる」。「かける」は「コストをかける」の形で、「コストが」とは続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示し、「コストを削減する」と続く。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、「コストに削減する」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "所属を示すが、「コストの削減する」は動詞が続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「削減する」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示し、「コストを削減する」と続く。", "に": "相手や場所を示すが、「コストに削減する」は意味が通らない。", "の": "所属を示すが、「コストの削減する」は動詞が続かず文が成り立たない。", "へ": "方向を示すが、「削減する」の目的語にはならない。"}, "error_tags": {"に": "相手・場所", "の": "所属", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を実現するために必要となる、金銭、労力、時間などの消費量。", "primary_collocate": null, "pronunciation": "こすと", "ipa": "kosɯto", "syllable_count": 3, "sentences": [{"text": "新製品の開発には、多額のコストがかかる。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の開発[かいはつ]には、多額[たがく]のコストがかかる。", "sentence_source": "generated"}, {"text": "会社は、コストを削減するため工場を統合する方針を発表した。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、コストを削減[さくげん]するため工場[こうじょう]を統合[とうごう]する方針[ほうしん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "輸送コストが上がり、商品の価格に影響が出ている。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "輸送[ゆそう]コストが上[あ]がり、商品[しょうひん]の価格[かかく]に影響[えいきょう]が出[で]ている。", "sentence_source": "generated"}, {"text": "この計画は、コストと効果のバランスを見て決める。", "target_word": "コスト", "complexity_tier": "T3", "furigana": "この計画[けいかく]は、コストと効果[こうか]のバランスを見[み]て決[き]める。", "sentence_source": "generated"}, {"text": "工場は、設備の更新コストを三年で回収する予定だ。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "工場[こうじょう]は、設備[せつび]の更新[こうしん]コストを三年[さんねん]で回収[かいしゅう]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "長期的に見ると、省エネ機器は運用コストを抑えられる。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "長期的[ちょうきてき]に見[み]ると、省[しょう]エネ機器[きき]は運用[うんよう]コストを抑[おさ]えられる。", "sentence_source": "generated"}, {"text": "プロジェクトのコストが予算を超えたため、中止となった。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "プロジェクトのコストが予算[よさん]を超[こ]えたため、中止[ちゅうし]となった。", "sentence_source": "generated"}, {"text": "部品を共通化し、製造コストを大幅に下げた。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "部品[ぶひん]を共通化[きょうつうか]し、製造[せいぞう]コストを大幅[おおはば]に下[さ]げた。", "sentence_source": "generated"}, {"text": "見積書には、材料費のほかに作業にかかるコストも含まれている。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "見積書[みつもりしょ]には、材料費[ざいりょうひ]のほかに作業[さぎょう]にかかるコストも含[ふく]まれている。", "sentence_source": "generated"}, {"text": "導入コストが高くても、効率が上がれば元が取れる。", "target_word": "コスト", "complexity_tier": "T4", "furigana": "導入[どうにゅう]コストが高[たか]くても、効率[こうりつ]が上[あ]がれば元[もと]が取[と]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コスト", "label": "基本形"}], "register": "formal", "sense_fingerprint": "事業や計画の実現に必要な金銭・労力・時間の消費量（経営・経済の用語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コスト", "is_correct": true, "explanation": "事業に必要な金銭の消費量で、「多額のコストがかかる」と自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の性質で、「多額の色がかかる」は意味が通らない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生物や製品の期間で、「多額の寿命がかかる」は成り立たない。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は気体で、「多額の酸素がかかる」は意味が通らない。"}], "explanations": {"コスト": "事業に必要な金銭の消費量で、「多額のコストがかかる」と自然に続く。", "色": "色は見た目の性質で、「多額の色がかかる」は意味が通らない。", "寿命": "寿命は生物や製品の期間で、「多額の寿命がかかる」は成り立たない。", "酸素": "酸素は気体で、「多額の酸素がかかる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "コスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬のコストは、飲んでから三十分ほどで現れる。", "explanation": "ここは〈効果〉の意味。飲んで三十分ほどで現れるのは効果で、支払う金銭や労力の量であるコストは現れない。"}, {"text": "この布はコストが深く、落ち着いた印象だ。", "explanation": "ここは〈色合い〉の意味。色の深さや落ち着きを表すのは色合いで、コストはそれを表さない。"}, {"text": "このタオルはコストがやわらかく、肌になじむ。", "explanation": "ここは〈感触〉の意味。やわらかさや肌へのなじみは感触で、コストは手触りを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コスト", "is_correct": true, "explanation": "プロジェクトの費用として予算を超えうるもので、「プロジェクトのコストが予算を超えた」と続く。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、「プロジェクトの天気が予算を超えた」は意味が通らない。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の性質で、「プロジェクトの味が予算を超えた」は成り立たない。"}, {"text": "音", "is_correct": false, "explanation": "音は聞こえるものの性質で、「プロジェクトの音が予算を超えた」は意味が通らない。"}], "explanations": {"コスト": "プロジェクトの費用として予算を超えうるもので、「プロジェクトのコストが予算を超えた」と続く。", "天気": "天気は空の状態で、「プロジェクトの天気が予算を超えた」は意味が通らない。", "味": "味は食べ物の性質で、「プロジェクトの味が予算を超えた」は成り立たない。", "音": "音は聞こえるものの性質で、「プロジェクトの音が予算を超えた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "コスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コストが高いと、洗濯物がなかなか乾かない。", "explanation": "ここは〈湿度〉の意味。空気の水分の多さである湿度が高いと乾きにくい、という文脈にコストは当てはまらない。"}, {"text": "このコストは、景色がよくて初心者でも楽しめる。", "explanation": "ここは〈コース〉の意味。景色がよく初心者でも楽しめるのはコース（道のり）で、必要な量を表すコストは楽しめるものではない。"}, {"text": "熱が出て、コストが三十八度まで上がった。", "explanation": "ここは〈体温〉の意味。三十八度まで上がるのは体温で、金銭や労力の量であるコストは温度を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店舗の運営コストが見直し、赤字を減らした。", "corrected_sentence": "店舗の運営コストを見直し、赤字を減らした。", "error_description": "「見直す」の目的語を示すのは「を」。「が」にすると主語になり、「見直し」と続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36949, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "製造コストが下げり、利益が増えた。", "corrected_sentence": "製造コストが下がり、利益が増えた。", "error_description": "「下がる」は自動詞で「コストが下がり」と続く。「下げり」という活用形は存在せず、動詞の活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「余っている」の主語。残っている様子を表す。"}, {"text": "を", "is_correct": false, "explanation": "「余る」は自動詞なので目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "「余る」に方向の「に」は合わず、文意が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「活力で余っている」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「余っている」の主語。残っている様子を表す。", "を": "「余る」は自動詞なので目的語の「を」は取れない。", "に": "「余る」に方向の「に」は合わず、文意が通らない。", "で": "手段や場所を表すが、「活力で余っている」では意味が通らない。"}, "error_tags": {"を": "目的語の誤用", "に": "方向の誤用", "で": "手段の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生きているものが元気に活動する力のことです。", "primary_collocate": null, "pronunciation": "かつりょく", "ipa": "katsɯɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "朝の散歩を始めてから、毎日活力がわいてくる。", "target_word": "活力", "complexity_tier": "T3", "furigana": "朝[あさ]の散歩[さんぽ]を始[はじ]めてから、毎日[まいにち]活力[かつりょく]がわいてくる。", "sentence_source": "generated"}, {"text": "子どもたちの活力あふれる声が、校庭に響いていた。", "target_word": "活力", "complexity_tier": "T3", "furigana": "子[こ]どもたちの活力[かつりょく]あふれる声[こえ]が、校庭[こうてい]に響[ひび]いていた。", "sentence_source": "generated"}, {"text": "祖父は八十歳を過ぎても活力があり、毎日畑に出ている。", "target_word": "活力", "complexity_tier": "T3", "furigana": "祖父[そふ]は八十歳[はちじゅっさい]を過[す]ぎても活力[かつりょく]があり、毎日[まいにち]畑[はたけ]に出[で]ている。", "sentence_source": "generated"}, {"text": "睡眠が足りないと、昼間に活力が出ない。", "target_word": "活力", "complexity_tier": "T3", "furigana": "睡眠[すいみん]が足[た]りないと、昼間[ひるま]に活力[かつりょく]が出[で]ない。", "sentence_source": "generated"}, {"text": "彼女の笑顔を見ると、私も活力をもらえる。", "target_word": "活力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑顔[えがお]を見[み]ると、私[わたし]も活力[かつりょく]をもらえる。", "sentence_source": "generated"}, {"text": "病気のあとで活力を失い、しばらく何もする気になれなかった。", "target_word": "活力", "complexity_tier": "T3", "furigana": "病気[びょうき]のあとで活力[かつりょく]を失[うしな]い、しばらく何[なに]もする気[き]になれなかった。", "sentence_source": "generated"}, {"text": "若い選手たちは活力に満ちていて、練習でも声がよく出る。", "target_word": "活力", "complexity_tier": "T3", "furigana": "若[わか]い選手[せんしゅ]たちは活力[かつりょく]に満[み]ちていて、練習[れんしゅう]でも声[こえ]がよく出[で]る。", "sentence_source": "generated"}, {"text": "犬は散歩から帰ってきても、まだ活力が余っている様子だった。", "target_word": "活力", "complexity_tier": "T3", "furigana": "犬[いぬ]は散歩[さんぽ]から帰[かえ]ってきても、まだ活力[かつりょく]が余[あま]っている様子[ようす]だった。", "sentence_source": "generated"}, {"text": "好きな音楽を聞くと、疲れていても活力が戻ってくる。", "target_word": "活力", "complexity_tier": "T3", "furigana": "好[す]きな音楽[おんがく]を聞[き]くと、疲[つか]れていても活力[かつりょく]が戻[もど]ってくる。", "sentence_source": "generated"}, {"text": "活力のない顔をしていたので、友達が心配して声をかけた。", "target_word": "活力", "complexity_tier": "T3", "furigana": "活力[かつりょく]のない顔[かお]をしていたので、友達[ともだち]が心配[しんぱい]して声[こえ]をかけた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "標準", "sense_fingerprint": "人や動物が元気に動くための生命力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活力", "is_correct": true, "explanation": "生き物が元気に動く力で、「わいてくる」と合う。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度のことで、「わいてくる」とは言わない。"}, {"text": "年齢", "is_correct": false, "explanation": "生きてきた年数のことで、わいてくる対象ではない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合で、「わいてくる」とは言わない。"}], "explanations": {"活力": "生き物が元気に動く力で、「わいてくる」と合う。", "体温": "体の温度のことで、「わいてくる」とは言わない。", "年齢": "生きてきた年数のことで、わいてくる対象ではない。", "湿度": "空気中の水分の割合で、「わいてくる」とは言わない。"}, "sentence_index": 0, "correct_answer": "活力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉄の橋は活力が高いので、大きな地震でも壊れない。", "explanation": "ここは〈強度〉の意味。活力は生き物や組織の元気の力で、橋の硬さには使わない。"}, {"text": "このモバイルバッテリーは活力が大きく、スマホを何度も充電できる。", "explanation": "ここは〈容量〉の意味。電池の蓄えられる量は容量で、活力とは言わない。"}, {"text": "明日の天気を、活力で予想した。", "explanation": "ここは〈予想〉の意味。予想の方法として活力は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活力", "is_correct": true, "explanation": "元気に動く力で、「満ちている」と合う。"}, {"text": "借金", "is_correct": false, "explanation": "お金を借りて負う債務のことで、「満ちている」とは言わない。"}, {"text": "空腹", "is_correct": false, "explanation": "おなかがすいた状態で、「満ちている」とは言わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "眠りが足りない状態で、「満ちている」の文脈に合わない。"}], "explanations": {"活力": "元気に動く力で、「満ちている」と合う。", "借金": "お金を借りて負う債務のことで、「満ちている」とは言わない。", "空腹": "おなかがすいた状態で、「満ちている」とは言わない。", "寝不足": "眠りが足りない状態で、「満ちている」の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "活力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋の活力が高くて、洗濯物が乾かない。", "explanation": "ここは〈湿度〉の意味。空気中の水分の量は湿度で、活力は生き物や組織の元気の力なので、部屋の状態には使わない。"}, {"text": "新しい店を開くため、活力の数を三人分確保した。", "explanation": "ここは〈人員〉の意味。人の数は人員で、活力は数えられるものではない。"}, {"text": "この会社は資金の活力が足りず、事業を縮小した。", "explanation": "ここは〈財源〉の意味。お金の量は財源で、活力とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その一言で、私は活力を消えた。", "corrected_sentence": "その一言で、私は活力を失った。", "error_description": "「消える」は自動詞で、目的語の「活力を」と合わない。他動詞の「失う」を使い、正しくは「活力を失った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36950, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの店の店員は活力を満ちていて、お客さんに人気がある。", "corrected_sentence": "あの店の店員は活力に満ちていて、お客さんに人気がある。", "error_description": "「満ちる」は「〜に満ちる」で、「を」は使えない。目的を表す「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36951, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「活力が弱くなる」の主語。活力が衰えることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「弱くなる」は自動詞なので目的語の「を」は取れない。"}, {"text": "に", "is_correct": false, "explanation": "「活力に弱くなる」は不自然で、文意が通らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す。「活力と弱くなる」は文意に合わない。"}], "correct_answer": "が", "explanations": {"が": "「活力が弱くなる」の主語。活力が衰えることを表す。", "を": "「弱くなる」は自動詞なので目的語の「を」は取れない。", "に": "「活力に弱くなる」は不自然で、文意が通らない。", "と": "相手や並列を表す。「活力と弱くなる」は文意に合わない。"}, "error_tags": {"を": "目的語の誤用", "に": "方向の誤用", "と": "相手の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
