INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36951, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物や組織が活動するために必要なエネルギーや元気のこと。特に、土や体などの自然の力を指すことが多い。", "primary_collocate": null, "pronunciation": "かつりょく", "ipa": "katsɯɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "雨が続いたおかげで、畑の土に活力が戻ってきた。", "target_word": "活力", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いたおかげで、畑[はたけ]の土[つち]に活力[かつりょく]が戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "肥料を入れすぎると、かえって土の活力が弱くなる。", "target_word": "活力", "complexity_tier": "T3", "furigana": "肥料[ひりょう]を入[い]れすぎると、かえって土[つち]の活力[かつりょく]が弱[よわ]くなる。", "sentence_source": "generated"}, {"text": "この森は古い木が倒れ、新しい芽が育つ活力に満ちている。", "target_word": "活力", "complexity_tier": "T3", "furigana": "この森[もり]は古[ふる]い木[き]が倒[たお]れ、新[あたら]しい芽[め]が育[そだ]つ活力[かつりょく]に満[み]ちている。", "sentence_source": "generated"}, {"text": "植物は冬の間に活力を蓄え、春になると一斉に芽を出す。", "target_word": "活力", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は冬[ふゆ]の間[あいだ]に活力[かつりょく]を蓄[たくわ]え、春[はる]になると一斉[いっせい]に芽[め]を出[だ]す。", "sentence_source": "generated"}, {"text": "新しい若手が入って、会社全体に活力が生まれた。", "target_word": "活力", "complexity_tier": "T3", "furigana": "新[あたら]しい若手[わかて]が入[はい]って、会社[かいしゃ]全体[ぜんたい]に活力[かつりょく]が生[う]まれた。", "sentence_source": "generated"}, {"text": "人が減った商店街は、町の活力を失っている。", "target_word": "活力", "complexity_tier": "T3", "furigana": "人[ひと]が減[へ]った商店街[しょうてんがい]は、町[まち]の活力[かつりょく]を失[うしな]っている。", "sentence_source": "generated"}, {"text": "温泉に入ると、体の活力が高まるといわれる。", "target_word": "活力", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]ると、体[からだ]の活力[かつりょく]が高[たか]まるといわれる。", "sentence_source": "generated"}, {"text": "川の水がきれいになり、魚も増えて川に活力が戻った。", "target_word": "活力", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がきれいになり、魚[さかな]も増[ふ]えて川[かわ]に活力[かつりょく]が戻[もど]った。", "sentence_source": "generated"}, {"text": "豊かな落ち葉が土に活力を与え、野菜がよく育つ。", "target_word": "活力", "complexity_tier": "T3", "furigana": "豊[ゆた]かな落[お]ち葉[ば]が土[つち]に活力[かつりょく]を与[あた]え、野菜[やさい]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "地域の祭りは、町に活力をもたらす大切な行事だ。", "target_word": "活力", "complexity_tier": "T3", "furigana": "地域[ちいき]の祭[まつ]りは、町[まち]に活力[かつりょく]をもたらす大切[たいせつ]な行事[ぎょうじ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活力", "label": "基本形"}, {"form": "活力が", "label": "が格"}, {"form": "活力を", "label": "を格"}, {"form": "活力の", "label": "の格"}], "register": "標準", "sense_fingerprint": "土・自然・組織などが持つ活動のエネルギー", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36951, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活力", "is_correct": true, "explanation": "土地や自然が持つ生命力で、「土に戻ってきた」と合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さのことで、土に戻るとは言わない。"}, {"text": "寿命", "is_correct": false, "explanation": "生きていられる期間のことで、土に戻るとは言わない。"}, {"text": "年輪", "is_correct": false, "explanation": "木の断面にある輪の模様で、土に戻るとは言わない。"}], "explanations": {"活力": "土地や自然が持つ生命力で、「土に戻ってきた」と合う。", "体重": "体の重さのことで、土に戻るとは言わない。", "寿命": "生きていられる期間のことで、土に戻るとは言わない。", "年輪": "木の断面にある輪の模様で、土に戻るとは言わない。"}, "sentence_index": 0, "correct_answer": "活力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鉄板は活力が高いので、ステーキを焼くのに向いている。", "explanation": "ここは〈耐熱性〉の意味。活力は生き物や土地の元気の力で、道具の性能には使わない。"}, {"text": "店の活力を集計して、来月の予算を立てた。", "explanation": "ここは〈集計〉の意味。数字をまとめるのは集計で、活力は数えられるものではない。"}, {"text": "山で、野草の活力を採取して持ち帰った。", "explanation": "ここは〈採取〉の意味。草を取ることは採取だが、活力は取り出せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36951, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活力", "is_correct": true, "explanation": "体や土地の元気の力で、「高まる」と合う。"}, {"text": "年齢", "is_correct": false, "explanation": "生きてきた年数のことで、高まるとは言わない。"}, {"text": "重量", "is_correct": false, "explanation": "重さの量のことで、高まる対象ではない。"}, {"text": "境界", "is_correct": false, "explanation": "区切りの線のことで、高まるとは言わない。"}], "explanations": {"活力": "体や土地の元気の力で、「高まる」と合う。", "年齢": "生きてきた年数のことで、高まるとは言わない。", "重量": "重さの量のことで、高まる対象ではない。", "境界": "区切りの線のことで、高まるとは言わない。"}, "sentence_index": 6, "correct_answer": "活力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この漬物は活力が長持ちするので、夏でも安心して食べられる。", "explanation": "ここは〈保存性〉の意味。食品が傷みにくい性質は保存性で、活力とは言わない。"}, {"text": "鉄道の運賃を活力で算定した。", "explanation": "ここは〈算定〉の意味。金額を計算する方法として活力は使えない。"}, {"text": "図書館の本を、活力によって分類した。", "explanation": "ここは〈分類〉の意味。本を種類ごとに分けるのは分類で、活力はその基準にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36951, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が続いたおかげで、畑の土の活力が戻した。", "corrected_sentence": "雨が続いたおかげで、畑の土の活力が戻った。", "error_description": "「活力が戻る」の「戻る」は自動詞。「戻した」は他動詞で主語の活力と合わない。正しくは「戻った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36951, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "堆肥を入れて、土が活力を満ちている。", "corrected_sentence": "堆肥を入れて、土が活力に満ちている。", "error_description": "「満ちる」は「〜に満ちる」で、「を」は使えない。正しくは「活力に満ちている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "よくない状態へ進むこと。回復の対義語で、この意味に当たる。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増えること。状態の良し悪しの反対語ではない。"}, {"text": "発生", "is_correct": false, "explanation": "事柄が起こること。回復の反対語ではない。"}, {"text": "延長", "is_correct": false, "explanation": "期間を延ばすこと。状態の反対語ではない。"}], "correct_answer": "悪化", "explanations": {"悪化": "よくない状態へ進むこと。回復の対義語で、この意味に当たる。", "増加": "数や量が増えること。状態の良し悪しの反対語ではない。", "発生": "事柄が起こること。回復の反対語ではない。", "延長": "期間を延ばすこと。状態の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "よくない状態へ進むこと。回復の対義語で、この意味に当たる。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめること。回復と反対の関係にはない。"}, {"text": "持続", "is_correct": false, "explanation": "同じ状態が続くこと。回復の反対語ではない。"}, {"text": "解散", "is_correct": false, "explanation": "団体を解くこと。回復の反対語ではない。"}], "correct_answer": "悪化", "explanations": {"悪化": "よくない状態へ進むこと。回復の対義語で、この意味に当たる。", "中断": "途中でやめること。回復と反対の関係にはない。", "持続": "同じ状態が続くこと。回復の反対語ではない。", "解散": "団体を解くこと。回復の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "悪かったものが、元のよい状態にもどること。", "primary_collocate": null, "pronunciation": "かいふく", "ipa": "kaiɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "手術のあと、祖母の体力は少しずつ回復している。", "target_word": "回復", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]のあと、祖母[そぼ]の体力[たいりょく]は少[すこ]しずつ回復[かいふく]している。", "sentence_source": "generated"}, {"text": "台風で止まっていた電車の運転は、昼すぎに回復した。", "target_word": "回復", "complexity_tier": "T3", "furigana": "台風[たいふう]で止[と]まっていた電車[でんしゃ]の運転[うんてん]は、昼[ひる]すぎに回復[かいふく]した。", "sentence_source": "generated"}, {"text": "景気の回復には、まだ時間がかかりそうだ。", "target_word": "回復", "complexity_tier": "T3", "furigana": "景気[けいき]の回復[かいふく]には、まだ時間[じかん]がかかりそうだ。", "sentence_source": "generated"}, {"text": "十分に休めば、疲れは回復する。", "target_word": "回復", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]に休[やす]めば、疲[つか]れは回復[かいふく]する。", "sentence_source": "generated"}, {"text": "失った信用を回復するのは簡単ではない。", "target_word": "回復", "complexity_tier": "T3", "furigana": "失[うしな]った信用[しんよう]を回復[かいふく]するのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "薬を飲んだら熱が下がり、気分も回復した。", "target_word": "回復", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら熱[ねつ]が下[さ]がり、気分[きぶん]も回復[かいふく]した。", "sentence_source": "generated"}, {"text": "停電が回復するまで、私たちはろうそくで過ごした。", "target_word": "回復", "complexity_tier": "T3", "furigana": "停電[ていでん]が回復[かいふく]するまで、私[わたし]たちはろうそくで過[す]ごした。", "sentence_source": "generated"}, {"text": "事故にあった彼は、順調に回復して来月退院する。", "target_word": "回復", "complexity_tier": "T3", "furigana": "事故[じこ]にあった彼[かれ]は、順調[じゅんちょう]に回復[かいふく]して来月[らいげつ]退院[たいいん]する。", "sentence_source": "generated"}, {"text": "水不足だった池の水位が、雨のおかげで回復した。", "target_word": "回復", "complexity_tier": "T3", "furigana": "水不足[みずぶそく]だった池[いけ]の水位[すいい]が、雨[あめ]のおかげで回復[かいふく]した。", "sentence_source": "generated"}, {"text": "彼は回復が早く、三日で仕事に戻れた。", "target_word": "回復", "complexity_tier": "T3", "furigana": "彼[かれ]は回復[かいふく]が早[はや]く、三日[みっか]で仕事[しごと]に戻[もど]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回復する", "label": "辞書形"}, {"form": "回復して", "label": "て形"}, {"form": "回復した", "label": "た形"}, {"form": "回復させる", "label": "使役形"}], "register": "標準", "sense_fingerprint": "悪くなった状態が元のよい状態に戻ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回復", "is_correct": true, "explanation": "悪い状態から元に戻る意味で、少しずつ戻っている文脈に合う。"}, {"text": "延長", "is_correct": false, "explanation": "期間を延ばす意味。体力の状態には使わない。"}, {"text": "発生", "is_correct": false, "explanation": "事が起こる意味で、体力の状態には合わない。"}, {"text": "報告", "is_correct": false, "explanation": "知らせる意味で、体力の状態には当てはまらない。"}], "explanations": {"回復": "悪い状態から元に戻る意味で、少しずつ戻っている文脈に合う。", "延長": "期間を延ばす意味。体力の状態には使わない。", "発生": "事が起こる意味で、体力の状態には合わない。", "報告": "知らせる意味で、体力の状態には当てはまらない。"}, "sentence_index": 0, "correct_answer": "回復"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の間の誤解を回復して、仲は元どおりになった。", "explanation": "ここは〈解消〉の意味。誤解は解消するもので、回復とは言わない。"}, {"text": "壊れた壁を回復して、部屋をきれいにした。", "explanation": "ここは〈修復〉の意味。壊れた物を直すのは修復で、回復は人や状態に使う。"}, {"text": "盗まれた財布を回復して、警察に届けた。", "explanation": "ここは〈取り戻す〉の意味。なくなった物を手に入れ直すのは取り戻すで、回復とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回復", "is_correct": true, "explanation": "停電が元に戻る意味で、「まで過ごした」の前に合う。"}, {"text": "報告", "is_correct": false, "explanation": "知らせることで、停電が続く期間を表す文脈に合わない。"}, {"text": "点検", "is_correct": false, "explanation": "調べることで、停電が続く期間には合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く意味で、停電には使えない。"}], "explanations": {"回復": "停電が元に戻る意味で、「まで過ごした」の前に合う。", "報告": "知らせることで、停電が続く期間を表す文脈に合わない。", "点検": "調べることで、停電が続く期間には合わない。", "撤去": "取り除く意味で、停電には使えない。"}, "sentence_index": 6, "correct_answer": "回復"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の古い機械を回復して、点検を終えた。", "explanation": "ここは〈点検〉の意味。機械を調べて確かめるのは点検で、回復とは言わない。"}, {"text": "貸したお金を回復して、帳簿に記録した。", "explanation": "ここは〈回収〉の意味。貸した金を取り戻すのは回収で、回復とは言わない。"}, {"text": "申込書に名前を回復した。", "explanation": "ここは〈記入〉の意味。紙に書き込むのは記入で、回復は元の状態に戻ることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ひどい熱が下がったあと、患者の体調が回復させた。", "corrected_sentence": "ひどい熱が下がったあと、患者の体調が回復した。", "error_description": "「回復する」は自動詞で、体調が自分で元に戻る意味。「回復させた」の使役形は誤り。正しくは「回復した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36952, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病状が回復を向かっている。", "corrected_sentence": "病状が回復に向かっている。", "error_description": "「向かう」は「〜に向かう」で、目標を表す「に」が必要。「を」は誤り。正しくは「回復に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「目標を達成」の「を」。達成の目的語を示すので正しい。"}, {"text": "に", "is_correct": false, "explanation": "「目標に」は到達点や対象を示すため、達成の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「目標で」は手段や場所を示すので、達成の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「目標へ」は方向を示すため、達成の目的語には使えない。"}], "correct_answer": "を", "explanations": {"を": "「目標を達成」の「を」。達成の目的語を示すので正しい。", "に": "「目標に」は到達点や対象を示すため、達成の目的語にはならない。", "で": "「目標で」は手段や場所を示すので、達成の目的語を示せない。", "へ": "「目標へ」は方向を示すため、達成の目的語には使えない。"}, "error_tags": {"に": "到達点・対象の「に」（目的語不可）", "で": "手段・場所の「で」", "へ": "方向の「へ」"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「達成すると」の「と」は、達成したら、という条件を示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「達成が」は主語を示すが、条件を表す形にはならないので入らない。"}, {"text": "から", "is_correct": false, "explanation": "「達成から」は起点を示し、条件の形として成り立たないので入らない。"}, {"text": "の", "is_correct": false, "explanation": "「達成の」は名詞を修飾する形で、「すると」と続かないので入らない。"}], "correct_answer": "と", "explanations": {"と": "「達成すると」の「と」は、達成したら、という条件を示すので正しい。", "が": "「達成が」は主語を示すが、条件を表す形にはならないので入らない。", "から": "「達成から」は起点を示し、条件の形として成り立たないので入らない。", "の": "「達成の」は名詞を修飾する形で、「すると」と続かないので入らない。"}, "error_tags": {"が": "主語の「が」", "から": "起点の「から」", "の": "連体修飾の「の」"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "やりたいことがうまくいくこと。", "primary_collocate": null, "pronunciation": "たっせい", "ipa": "tasseː", "syllable_count": 4, "sentences": [{"text": "十キロ走るという目標を達成して、夜はぐっすり眠れた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "十[じゅっ]キロ走[はし]るという目標[もくひょう]を達成[たっせい]して、夜[よる]はぐっすり眠[ねむ]れた。", "sentence_source": "generated"}, {"text": "妹は逆上がりができるようになり、自分の目標を達成した。", "target_word": "達成", "complexity_tier": "T3", "furigana": "妹[いもうと]は逆上[さかあ]がりができるようになり、自分[じぶん]の目標[もくひょう]を達成[たっせい]した。", "sentence_source": "generated"}, {"text": "初めて一人で料理を作る目標を達成できて、とてもうれしい。", "target_word": "達成", "complexity_tier": "T3", "furigana": "初[はじ]めて一人[ひとり]で料理[りょうり]を作[つく]る目標[もくひょう]を達成[たっせい]できて、とてもうれしい。", "sentence_source": "generated"}, {"text": "読書は月に三冊という目標を、今月も達成した。", "target_word": "達成", "complexity_tier": "T3", "furigana": "読書[どくしょ]は月[つき]に三冊[さんさつ]という目標[もくひょう]を、今月[こんげつ]も達成[たっせい]した。", "sentence_source": "generated"}, {"text": "兄は貯金の目標を達成したので、新しい自転車を買うそうだ。", "target_word": "達成", "complexity_tier": "T3", "furigana": "兄[あに]は貯金[ちょきん]の目標[もくひょう]を達成[たっせい]したので、新[あたら]しい自転車[じてんしゃ]を買[か]うそうだ。", "sentence_source": "generated"}, {"text": "目標が達成できなかった日は、次にどうするかをノートに書く。", "target_word": "達成", "complexity_tier": "T3", "furigana": "目標[もくひょう]が達成[たっせい]できなかった日[ひ]は、次[つぎ]にどうするかをノートに書[か]く。", "sentence_source": "generated"}, {"text": "ゲームの全面クリアを達成した友達が、画面を見せてくれた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "ゲームの全面[ぜんめん]クリアを達成[たっせい]した友達[ともだち]が、画面[がめん]を見[み]せてくれた。", "sentence_source": "generated"}, {"text": "目標を達成すると、自分へのごほうびにケーキを食べることにしている。", "target_word": "達成", "complexity_tier": "T3", "furigana": "目標[もくひょう]を達成[たっせい]すると、自分[じぶん]へのごほうびにケーキを食[た]べることにしている。", "sentence_source": "generated"}, {"text": "毎朝の早起きが続き、一か月の目標を達成できた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]の早起[はやお]きが続[つづ]き、一[いっ]か月[かげつ]の目標[もくひょう]を達成[たっせい]できた。", "sentence_source": "generated"}, {"text": "課題が達成されたかどうか、先生が確認してくれた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "課題[かだい]が達成[たっせい]されたかどうか、先生[せんせい]が確認[かくにん]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "達成", "label": "名詞形"}, {"form": "達成する", "label": "辞書形"}, {"form": "達成した", "label": "過去形"}, {"form": "達成できる", "label": "可能形"}, {"form": "達成される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "やろうと決めたことが成功すること。日常の小さな目標にも使う（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "達成", "is_correct": true, "explanation": "「目標を成し遂げた」という意味で、「目標を達成して」と自然につながるので正解。"}, {"text": "後悔", "is_correct": false, "explanation": "後悔は気持ちを表す語で、「目標を後悔して」とは言えないので入らない。"}, {"text": "紛失", "is_correct": false, "explanation": "紛失は物をなくすことで、目標を対象にすると不自然なので入らない。"}, {"text": "到着", "is_correct": false, "explanation": "到着は場所に着くことで、「目標を到着して」とは言わないので入らない。"}], "explanations": {"達成": "「目標を成し遂げた」という意味で、「目標を達成して」と自然につながるので正解。", "後悔": "後悔は気持ちを表す語で、「目標を後悔して」とは言えないので入らない。", "紛失": "紛失は物をなくすことで、目標を対象にすると不自然なので入らない。", "到着": "到着は場所に着くことで、「目標を到着して」とは言わないので入らない。"}, "sentence_index": 0, "correct_answer": "達成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は難しい問題を達成した。", "explanation": "ここは〈解く〉の意味。問題は解いたり答えたりするもので、達成は目標や課題を成し遂げたときに使う。"}, {"text": "登山隊は頂上を達成した。", "explanation": "ここは〈到達〉の意味。頂上や場所に着くことは到達で表し、達成は目標を成し遂げたときに使う。"}, {"text": "田中さんは発表で拍手を達成した。", "explanation": "ここは〈獲得〉の意味。拍手は受けたり得たりするもので、達成は目標や課題を成し遂げたときに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "達成", "is_correct": true, "explanation": "「全面クリアを」に続けて、目標を成し遂げる意味で使えるので正解。"}, {"text": "挑戦", "is_correct": false, "explanation": "挑戦は「～に挑戦する」の形を取るので、「全面クリアを挑戦」とは言えず入らない。"}, {"text": "所属", "is_correct": false, "explanation": "所属は組織に属することで、「全面クリアを所属」は成り立たないので入らない。"}, {"text": "漂流", "is_correct": false, "explanation": "漂流は水に流されることで、「全面クリアを漂流」とは言えないので入らない。"}], "explanations": {"達成": "「全面クリアを」に続けて、目標を成し遂げる意味で使えるので正解。", "挑戦": "挑戦は「～に挑戦する」の形を取るので、「全面クリアを挑戦」とは言えず入らない。", "所属": "所属は組織に属することで、「全面クリアを所属」は成り立たないので入らない。", "漂流": "漂流は水に流されることで、「全面クリアを漂流」とは言えないので入らない。"}, "sentence_index": 6, "correct_answer": "達成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その事件の謎を達成した。", "explanation": "ここは〈解決〉の意味。謎を解く場合は解決を使い、達成は目標や課題を成し遂げたときに使う。"}, {"text": "洗濯物を達成した。", "explanation": "ここは〈完了〉の意味。家事や作業が終わることは完了で言い、達成は目標を成し遂げたときに使う。"}, {"text": "彼は大学の入試を達成した。", "explanation": "ここは〈合格〉の意味。試験に受かることは合格で言い、達成は目標を成し遂げたときに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大会で優勝するという目標に達成して、チームは大いに喜んだ。", "corrected_sentence": "大会で優勝するという目標を達成して、チームは大いに喜んだ。", "error_description": "誤りは助詞「に」。「達成する」は目標を目的語にするので「目標を達成」が正しい。「目標に達成」とは言わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36954, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みの宿題の目標を達成れて、母は喜んだ。", "corrected_sentence": "夏休みの宿題の目標を達成して、母は喜んだ。", "error_description": "「し」が抜けている。「達成れて」は活用が成り立たない。正しくは「達成して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
