INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36955, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「達成までの道のり」は目指す到達点を示す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「達成が道のりは長かった」は達成が主語になり、道のりを修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「達成を道のり」は目的語を示すが、道のりとつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「達成に道のり」は帰着点として成り立たず、文脈に合わない。"}], "correct_answer": "まで", "explanations": {"まで": "「達成までの道のり」は目指す到達点を示す正しい形。", "が": "「達成が道のりは長かった」は達成が主語になり、道のりを修飾できない。", "を": "「達成を道のり」は目的語を示すが、道のりとつながらない。", "に": "「達成に道のり」は帰着点として成り立たず、文脈に合わない。"}, "error_tags": {"まで": "到達点", "が": "主語", "を": "対象", "に": "方向・帰着"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36955, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "目標としていた状態や結果を、努力して実現すること。", "primary_collocate": null, "pronunciation": "たっせい", "ipa": "tasseː", "syllable_count": 4, "sentences": [{"text": "犯行の客観的裏付けという目的のため、この緻密な照合作業を経て、初めて不可謬な身元特定が達成されるのである。", "target_word": "達成", "complexity_tier": "T5", "furigana": "犯行[はんこう]の客観的[きゃっかんてき]裏付[うらづ]けという目的[もくてき]のため、この緻密[ちみつ]な照合[しょうごう]作業[さぎょう]を経[へ]て、初[はじ]めて不可謬[ふかびゅう]な身元[みもと]特定[とくてい]が達成[たっせい]されるのである。", "sentence_source": "mined"}, {"text": "チーム全員が力を合わせた結果、今年の売り上げ目標を達成した。", "target_word": "達成", "complexity_tier": "T3", "furigana": "チーム全員[ぜんいん]が力[ちから]を合[あ]わせた結果[けっか]、今年[ことし]の売[う]り上[あ]げ目標[もくひょう]を達成[たっせい]した。", "sentence_source": "generated"}, {"text": "毎日練習を続けたので、彼はついに目標の記録を達成できた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]を続[つづ]けたので、彼[かれ]はついに目標[もくひょう]の記録[きろく]を達成[たっせい]できた。", "sentence_source": "generated"}, {"text": "長い準備の末、計画は予定より早く達成された。", "target_word": "達成", "complexity_tier": "T3", "furigana": "長[なが]い準備[じゅんび]の末[すえ]、計画[けいかく]は予定[よてい]より早[はや]く達成[たっせい]された。", "sentence_source": "generated"}, {"text": "目標を達成するには、小さな努力を積み重ねることが大切だ。", "target_word": "達成", "complexity_tier": "T3", "furigana": "目標[もくひょう]を達成[たっせい]するには、小[ちい]さな努力[どりょく]を積[つ]み重[かさ]ねることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼女は三年かけて資格取得という目的を達成した。", "target_word": "達成", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は三年[さんねん]かけて資格[しかく]取得[しゅとく]という目的[もくてき]を達成[たっせい]した。", "sentence_source": "generated"}, {"text": "大きな目標を達成したあと、彼は家族と祝杯をあげた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "大[おお]きな目標[もくひょう]を達成[たっせい]したあと、彼[かれ]は家族[かぞく]と祝杯[しゅくはい]をあげた。", "sentence_source": "generated"}, {"text": "達成までの道のりは長かったが、あきらめずに続けてよかった。", "target_word": "達成", "complexity_tier": "T3", "furigana": "達成[たっせい]までの道[みち]のりは長[なが]かったが、あきらめずに続[つづ]けてよかった。", "sentence_source": "generated"}, {"text": "今月の節電目標が達成できず、会社は対策を見直すことにした。", "target_word": "達成", "complexity_tier": "T3", "furigana": "今月[こんげつ]の節電[せつでん]目標[もくひょう]が達成[たっせい]できず、会社[かいしゃ]は対策[たいさく]を見直[みなお]すことにした。", "sentence_source": "generated"}, {"text": "山の頂上に立った瞬間、長年の夢を達成した実感がわいた。", "target_word": "達成", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]に立[た]った瞬間[しゅんかん]、長年[ながねん]の夢[ゆめ]を達成[たっせい]した実感[じっかん]がわいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "達成", "label": "名詞形"}, {"form": "達成する", "label": "辞書形"}, {"form": "達成した", "label": "過去形"}, {"form": "達成できる", "label": "可能形"}, {"form": "達成される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "努力の末に、掲げた目標や目的を実現すること（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 謬 (Zipf 2.26)','sentence 9 above tier T2: contains vocabulary far above tier T2: 長年の夢 (Zipf 2.36)']::text[], '448d110d-502d-4765-a516-917bc7c1e24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36955, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "達成", "is_correct": true, "explanation": "身元特定という目標が実現したことを表し、「達成されるのである」で文が成り立つ。"}, {"text": "蒸留", "is_correct": false, "explanation": "液体を熱して成分を分ける作業で、身元特定には使わない。"}, {"text": "漂白", "is_correct": false, "explanation": "色を抜く作業で、身元特定の文脈では意味が通らない。"}, {"text": "脱臭", "is_correct": false, "explanation": "においを取る作業で、身元特定には合わない。"}], "explanations": {"達成": "身元特定という目標が実現したことを表し、「達成されるのである」で文が成り立つ。", "蒸留": "液体を熱して成分を分ける作業で、身元特定には使わない。", "漂白": "色を抜く作業で、身元特定の文脈では意味が通らない。", "脱臭": "においを取る作業で、身元特定には合わない。"}, "sentence_index": 0, "correct_answer": "達成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "登山隊は、ついに山頂に達成した。", "explanation": "ここは〈到達〉の意味（ある地点に着くこと）。達成は目標にしていた状態を実現することで、場所に着く意味では使わない。"}, {"text": "彼は三年がかりで描いた油絵を達成した。", "explanation": "ここは〈完成〉の意味（作品が仕上がること）。達成は目標を実現する意味なので、絵が仕上がる場面には使わない。"}, {"text": "工事は順調に達成している。", "explanation": "ここは〈進行〉の意味（物事が進むこと）。達成は目標を実現して終えることで、途中の経過には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36955, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "達成", "is_correct": true, "explanation": "「大きな目標を達成したあと」は目標を実現した意味で、文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける行為で、目標を対象にする文脈には合わない。"}, {"text": "呼吸", "is_correct": false, "explanation": "息をする行為で、目標とは結びつかない。"}, {"text": "放送", "is_correct": false, "explanation": "番組を流す行為で、目標を対象にする文脈には合わない。"}], "explanations": {"達成": "「大きな目標を達成したあと」は目標を実現した意味で、文脈に合う。", "採点": "点数をつける行為で、目標を対象にする文脈には合わない。", "呼吸": "息をする行為で、目標とは結びつかない。", "放送": "番組を流す行為で、目標を対象にする文脈には合わない。"}, "sentence_index": 6, "correct_answer": "達成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもは一年で大きく達成した。", "explanation": "ここは〈成長〉の意味（体や力が育つこと）。達成は目標を実現することで、育っていく過程には使わない。"}, {"text": "彼は長く続いた問題を達成した。", "explanation": "ここは〈解決〉の意味（問題を片づけること）。達成は目標を実現することで、問題を片づける意味では使わない。"}, {"text": "彼女は表彰状を達成された。", "explanation": "ここは〈授与〉の意味（賞状などを与えること）。達成は目標を実現することで、物を与えられる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36955, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "目標達成を喜びを、家族と分かち合った。", "corrected_sentence": "目標達成の喜びを、家族と分かち合った。", "error_description": "「目標達成」は「の」で「喜び」をつなぐ。「達成を喜び」と「を」を使うと達成が喜ぶ対象になり誤り。正しくは「達成の喜び」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36955, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仲間と力を合わせ、ついに目標を達成す、祝杯をあげた。", "corrected_sentence": "仲間と力を合わせ、ついに目標を達成して、祝杯をあげた。", "error_description": "文を続けるには「達成して」と連用形に「て」をつける必要がある。「達成す、」では文が切れて後ろに続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「認められる」の主語を表す「が」。「働きが認められ」で文意が通る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に付く。「認められ」は受け身なので「働きを認められ」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や結果を表すが、「働きに認められ」では誰に認められたかの文構造が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「働きへ認められ」は方向の関係が成り立たず不自然。"}], "correct_answer": "が", "explanations": {"が": "「認められる」の主語を表す「が」。「働きが認められ」で文意が通る。", "を": "「を」は他動詞の目的語に付く。「認められ」は受け身なので「働きを認められ」は不自然。", "に": "「に」は相手や結果を表すが、「働きに認められ」では誰に認められたかの文構造が崩れる。", "へ": "「へ」は方向を表す。「働きへ認められ」は方向の関係が成り立たず不自然。"}, "error_tags": {"を": "目的語", "に": "相手・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「働きによって」の「に」。働きを手段・原因として示す形で、文意が通る。"}, {"text": "を", "is_correct": false, "explanation": "「働きをよって」は「によって」の形にならず、目的語としても続かない。"}, {"text": "で", "is_correct": false, "explanation": "「働きでよって」は「によって」の形にならず、「で」は手段を示しても「よって」と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「働きへよって」は「によって」の形にならず不自然。"}], "correct_answer": "に", "explanations": {"に": "「働きによって」の「に」。働きを手段・原因として示す形で、文意が通る。", "を": "「働きをよって」は「によって」の形にならず、目的語としても続かない。", "で": "「働きでよって」は「によって」の形にならず、「で」は手段を示しても「よって」と続かない。", "へ": "「へ」は方向を示す。「働きへよって」は「によって」の形にならず不自然。"}, "error_tags": {"を": "目的語の誤用", "で": "手段の誤用", "へ": "方向の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするための力や役割のこと。", "primary_collocate": null, "pronunciation": "はたらき", "ipa": "hataɾaki", "syllable_count": 4, "sentences": [{"text": "彼の働きのおかげで、チームは大きな試合に勝てた。", "target_word": "働き", "complexity_tier": "T3", "furigana": "彼[かれ]の働[はたら]きのおかげで、チームは大[おお]きな試合[しあい]に勝[か]てた。", "sentence_source": "generated"}, {"text": "母は長年の働きが認められ、会社から表彰された。", "target_word": "働き", "complexity_tier": "T3", "furigana": "母[はは]は長年[ながねん]の働[はたら]きが認[みと]められ、会社[かいしゃ]から表彰[ひょうしょう]された。", "sentence_source": "generated"}, {"text": "新入社員にしては、よい働きをしてくれた。", "target_word": "働き", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]にしては、よい働[はたら]きをしてくれた。", "sentence_source": "generated"}, {"text": "新しい課長の働きで、部署の雰囲気が明るくなった。", "target_word": "働き", "complexity_tier": "T3", "furigana": "新[あたら]しい課長[かちょう]の働[はたら]きで、部署[ぶしょ]の雰囲気[ふんいき]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "父の働きだけでは家族を養えず、母も仕事を始めた。", "target_word": "働き", "complexity_tier": "T3", "furigana": "父[ちち]の働[はたら]きだけでは家族[かぞく]を養[やしな]えず、母[はは]も仕事[しごと]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "学級委員の働きで、文化祭の準備が早く終わった。", "target_word": "働き", "complexity_tier": "T3", "furigana": "学級委員[がっきゅういいん]の働[はたら]きで、文化祭[ぶんかさい]の準備[じゅんび]が早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "彼は目立たないが、会社で重要な働きをしている。", "target_word": "働き", "complexity_tier": "T3", "furigana": "彼[かれ]は目立[めだ]たないが、会社[かいしゃ]で重要[じゅうよう]な働[はたら]きをしている。", "sentence_source": "generated"}, {"text": "村の人々の働きによって、壊れた橋は三日で直った。", "target_word": "働き", "complexity_tier": "T3", "furigana": "村[むら]の人々[ひとびと]の働[はたら]きによって、壊[こわ]れた橋[はし]は三日[みっか]で直[なお]った。", "sentence_source": "generated"}, {"text": "働きに見合った給料をもらえず、彼女は不満だった。", "target_word": "働き", "complexity_tier": "T3", "furigana": "働[はたら]きに見合[みあ]った給料[きゅうりょう]をもらえず、彼女[かのじょ]は不満[ふまん]だった。", "sentence_source": "generated"}, {"text": "町の復興に大きな働きをした医者に、市から感謝状が贈られた。", "target_word": "働き", "complexity_tier": "T3", "furigana": "町[まち]の復興[ふっこう]に大[おお]きな働[はたら]きをした医者[いしゃ]に、市[し]から感謝状[かんしゃじょう]が贈[おく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "働き", "label": "基本形"}, {"form": "働きが", "label": "が格"}, {"form": "働きを", "label": "を格"}, {"form": "働きで", "label": "で格"}], "register": "標準", "sense_fingerprint": "人が仕事や活動で果たす役割や貢献", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "働き", "is_correct": true, "explanation": "「彼の働き」は仕事で果たした貢献を指し、「のおかげで」とつながってチームの勝利の理由になる。"}, {"text": "雨具", "is_correct": false, "explanation": "雨具は雨をよける道具で、人の貢献を表さない。「彼の雨具のおかげで試合に勝てた」は意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠たい感覚で、試合の勝利をもたらす理由にはならない。「彼の眠気のおかげで」は不自然。"}, {"text": "段差", "is_correct": false, "explanation": "段差は床や道の高低差を表す語で、人の行動の結果として勝利の理由になることはない。"}], "explanations": {"働き": "「彼の働き」は仕事で果たした貢献を指し、「のおかげで」とつながってチームの勝利の理由になる。", "雨具": "雨具は雨をよける道具で、人の貢献を表さない。「彼の雨具のおかげで試合に勝てた」は意味が通らない。", "眠気": "眠気は眠たい感覚で、試合の勝利をもたらす理由にはならない。「彼の眠気のおかげで」は不自然。", "段差": "段差は床や道の高低差を表す語で、人の行動の結果として勝利の理由になることはない。"}, "sentence_index": 0, "correct_answer": "働き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人は大きな働きを立てて、部長から表彰された。", "explanation": "ここは〈手柄〉の意味。働きは力や役割を指し、「立てる」と組むのは手柄の方なので合わない。"}, {"text": "この部品の働きが悪く、機械が動かなかった。", "explanation": "ここは〈機能〉の意味。働きは人の貢献や役割を指すので、物の機能を表す文脈では合わない。"}, {"text": "会議中によい働きが浮かんだ。", "explanation": "ここは〈考え〉の意味。「浮かぶ」と組むのは考えの方で、働きは力や役割を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "働き", "is_correct": true, "explanation": "「重要な働きをしている」は会社での貢献を述べる自然な表現で、この文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「重要な散歩をしている」は意味が通らず、会社での役割の文脈に合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "「重要な欠席をしている」は矛盾しており、目立たない人の貢献という文意に合わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "昼寝は休息の行為で、「重要な昼寝をしている」は文の内容と噛み合わない。"}], "explanations": {"働き": "「重要な働きをしている」は会社での貢献を述べる自然な表現で、この文脈に合う。", "散歩": "「重要な散歩をしている」は意味が通らず、会社での役割の文脈に合わない。", "欠席": "「重要な欠席をしている」は矛盾しており、目立たない人の貢献という文意に合わない。", "昼寝": "昼寝は休息の行為で、「重要な昼寝をしている」は文の内容と噛み合わない。"}, "sentence_index": 6, "correct_answer": "働き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "信号の働きを払わず、交差点に入ってしまった。", "explanation": "ここは〈注意〉の意味。「払う」と組むのは注意の方で、働きは力や役割を指すので合わない。"}, {"text": "新人は先輩に働きに乗ってもらい、仕事を覚えた。", "explanation": "ここは〈相談〉の意味。「乗る」と組むのは相談の方で、働きは力や役割を指すので合わない。"}, {"text": "彼は働きを言って、皆を笑わせた。", "explanation": "ここは〈冗談〉の意味。「言う」と組むのは冗談の方で、働きは力や役割を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社では、新人の働きをよく評価されている。", "corrected_sentence": "この会社では、新人の働きがよく評価されている。", "error_description": "受け身文の主語には「が」を使う。「働きを評価されている」は誤りで、正しくは「働きが評価されている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36956, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人々の働きに、市は高く評価した。", "corrected_sentence": "町の人々の働きを、市は高く評価した。", "error_description": "「評価する」の目的語には「を」を使う。「働きに評価した」は誤りで、正しくは「働きを評価した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「働きをする」の目的語を表す「を」。薬が胃の痛みをおさえるという機能を述べる。"}, {"text": "が", "is_correct": false, "explanation": "「働きがする」は主語と動詞が合わず、不自然な文になる。"}, {"text": "に", "is_correct": false, "explanation": "「働きにする」は意味が通らず、「する」の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表すが、「働きでする」は「する」と結びつかず成立しない。"}], "correct_answer": "を", "explanations": {"を": "「働きをする」の目的語を表す「を」。薬が胃の痛みをおさえるという機能を述べる。", "が": "「働きがする」は主語と動詞が合わず、不自然な文になる。", "に": "「働きにする」は意味が通らず、「する」の目的語にはならない。", "で": "「で」は手段を表すが、「働きでする」は「する」と結びつかず成立しない。"}, "error_tags": {"が": "主語", "に": "相手・結果", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「働きがある」の主語を表す「が」。物が持つ機能の存在を述べる自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「働きをある」は「ある」と結びつかず、存在を表す文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「働きとある」は文が完成せず、存在を表す文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「働きへある」は意味が通らず、存在を表せない。"}], "correct_answer": "が", "explanations": {"が": "「働きがある」の主語を表す「が」。物が持つ機能の存在を述べる自然な形になる。", "を": "「働きをある」は「ある」と結びつかず、存在を表す文が成立しない。", "と": "「働きとある」は文が完成せず、存在を表す文にならない。", "へ": "「へ」は方向を表す。「働きへある」は意味が通らず、存在を表せない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が他の物事に対して及ぼす作用や効果。また、機能や活動。", "primary_collocate": null, "pronunciation": "はたらき", "ipa": "hataɾaki", "syllable_count": 4, "sentences": [{"text": "心臓には、血を全身に送る働きがある。", "target_word": "働き", "complexity_tier": "T3", "furigana": "心臓[しんぞう]には、血[ち]を全身[ぜんしん]に送[おく]る働[はたら]きがある。", "sentence_source": "generated"}, {"text": "この薬は、胃の痛みをおさえる働きをする。", "target_word": "働き", "complexity_tier": "T3", "furigana": "この薬[くすり]は、胃[い]の痛[いた]みをおさえる働[はたら]きをする。", "sentence_source": "generated"}, {"text": "植物の葉には、光を受けて養分を作る働きがある。", "target_word": "働き", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の葉[は]には、光[ひかり]を受[う]けて養分[ようぶん]を作[つく]る働[はたら]きがある。", "sentence_source": "generated"}, {"text": "眼鏡のレンズは、光を集める働きをする。", "target_word": "働き", "complexity_tier": "T3", "furigana": "眼鏡[めがね]のレンズは、光[ひかり]を集[あつ]める働[はたら]きをする。", "sentence_source": "generated"}, {"text": "睡眠には、体の疲れをとる働きがある。", "target_word": "働き", "complexity_tier": "T3", "furigana": "睡眠[すいみん]には、体[からだ]の疲[つか]れをとる働[はたら]きがある。", "sentence_source": "generated"}, {"text": "年を取ると、腎臓の働きが弱くなることがある。", "target_word": "働き", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、腎臓[じんぞう]の働[はたら]きが弱[よわ]くなることがある。", "sentence_source": "generated"}, {"text": "酢には、食べ物が傷むのを防ぐ働きがある。", "target_word": "働き", "complexity_tier": "T3", "furigana": "酢[す]には、食[た]べ物[もの]が傷[いた]むのを防[ふせ]ぐ働[はたら]きがある。", "sentence_source": "generated"}, {"text": "日記を書くことには、気持ちを整理する働きがある。", "target_word": "働き", "complexity_tier": "T3", "furigana": "日記[にっき]を書[か]くことには、気持[きも]ちを整理[せいり]する働[はたら]きがある。", "sentence_source": "generated"}, {"text": "森は、雨水をたくわえる働きによって洪水を防ぐ。", "target_word": "働き", "complexity_tier": "T3", "furigana": "森[もり]は、雨水[あまみず]をたくわえる働[はたら]きによって洪水[こうずい]を防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "このボタンの働きがわからず、機械を止めてしまった。", "target_word": "働き", "complexity_tier": "T3", "furigana": "このボタンの働[はたら]きがわからず、機械[きかい]を止[と]めてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "働き", "label": "基本形"}, {"form": "働きが", "label": "が格"}, {"form": "働きを", "label": "を格"}, {"form": "働きの", "label": "の格"}], "register": "標準", "sense_fingerprint": "物や体の部分などが持つ作用・機能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: おさえる (Zipf 2.47)','sentence 6 above tier T2: contains vocabulary far above tier T2: 傷む (Zipf 2.46)','sentence 8 above tier T2: contains vocabulary far above tier T2: たくわえる (Zipf 1.5)']::text[], '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "働き", "is_correct": true, "explanation": "「血を全身に送る働き」は心臓の機能を表し、「がある」と自然につながる。"}, {"text": "色", "is_correct": false, "explanation": "「血を全身に送る色がある」は意味が通らず、心臓の機能の文脈に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「血を全身に送る値段がある」は成立せず、臓器の説明にならない。"}, {"text": "音楽", "is_correct": false, "explanation": "「血を全身に送る音楽がある」は意味がなく、心臓の働きの説明として合わない。"}], "explanations": {"働き": "「血を全身に送る働き」は心臓の機能を表し、「がある」と自然につながる。", "色": "「血を全身に送る色がある」は意味が通らず、心臓の機能の文脈に合わない。", "値段": "「血を全身に送る値段がある」は成立せず、臓器の説明にならない。", "音楽": "「血を全身に送る音楽がある」は意味がなく、心臓の働きの説明として合わない。"}, "sentence_index": 0, "correct_answer": "働き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人は大きな働きを立てて、部長から表彰された。", "explanation": "ここは〈手柄〉の意味。働きは作用や機能を指すので、手柄の意味では合わない。"}, {"text": "ボトルの働きを抜いて、中身を注いだ。", "explanation": "ここは〈栓〉の意味。「抜く」と組むのは栓の方で、働きは作用や機能を表す語なので合わない。"}, {"text": "風鈴の働きを聞いて、夏の涼しさを感じた。", "explanation": "ここは〈音〉の意味。「聞く」と組むのは音の方で、働きは作用や機能を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "働き", "is_correct": true, "explanation": "「食べ物が傷むのを防ぐ働き」は酢の機能を表し、「がある」と自然につながる。"}, {"text": "味", "is_correct": false, "explanation": "「食べ物が傷むのを防ぐ味がある」は意味が通らず、酢の保存効果を説明できない。"}, {"text": "教科書", "is_correct": false, "explanation": "「食べ物が傷むのを防ぐ教科書がある」は成立せず、文脈に合わない。"}, {"text": "漫画", "is_correct": false, "explanation": "「食べ物が傷むのを防ぐ漫画がある」は意味がなく、保存作用の説明にならない。"}], "explanations": {"働き": "「食べ物が傷むのを防ぐ働き」は酢の機能を表し、「がある」と自然につながる。", "味": "「食べ物が傷むのを防ぐ味がある」は意味が通らず、酢の保存効果を説明できない。", "教科書": "「食べ物が傷むのを防ぐ教科書がある」は成立せず、文脈に合わない。", "漫画": "「食べ物が傷むのを防ぐ漫画がある」は意味がなく、保存作用の説明にならない。"}, "sentence_index": 6, "correct_answer": "働き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は仲間のために大きな働きをして、部長から表彰された。", "explanation": "ここは〈人の手柄・貢献〉の意味。作用や機能を指す語義とは別なので合わない。"}, {"text": "古い機械は働きを吐いて、黒い煙を出した。", "explanation": "ここは〈煙〉の意味。「吐く」と組むのは煙の方で、働きは作用や機能を指すので合わない。"}, {"text": "地域の人々の働きを奏でて、祭りが始まった。", "explanation": "ここは〈音楽〉の意味。「奏でる」と組むのは音楽の方で、働きは作用や機能を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このボタンの働きに、説明書で確かめる。", "corrected_sentence": "このボタンの働きを、説明書で確かめる。", "error_description": "「確かめる」の目的語には「を」を使う。「働きに」は誤りで、正しくは「働きを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36957, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "腎臓の働きに調べるため、検査を受けた。", "corrected_sentence": "腎臓の働きを調べるため、検査を受けた。", "error_description": "「調べる」の目的語には「を」を使う。「働きに調べる」は誤りで、正しくは「働きを調べる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "組み立て", "is_correct": true, "explanation": "分解の対義語。部品を組み合わせて完成させる意味で、機械の場面で対になる。"}, {"text": "解説", "is_correct": false, "explanation": "分かりやすく説明すること。分解の対義語ではない。"}, {"text": "採用", "is_correct": false, "explanation": "人や案を選び入れること。分解の対義語ではない。"}, {"text": "登録", "is_correct": false, "explanation": "名前などを記録に載せること。分解の対義語ではない。"}], "correct_answer": "組み立て", "explanations": {"組み立て": "分解の対義語。部品を組み合わせて完成させる意味で、機械の場面で対になる。", "解説": "分かりやすく説明すること。分解の対義語ではない。", "採用": "人や案を選び入れること。分解の対義語ではない。", "登録": "名前などを記録に載せること。分解の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "組み立て", "is_correct": true, "explanation": "分解の対義語。部品を組み合わせて完成させる意味で、機械の場面で対になる。"}, {"text": "収集", "is_correct": false, "explanation": "集めること。分解の対義語ではない。"}, {"text": "増築", "is_correct": false, "explanation": "建物を増やすこと。分解の対義語ではない。"}, {"text": "解決", "is_correct": false, "explanation": "問題を解くこと。分解の対義語ではない。"}], "correct_answer": "組み立て", "explanations": {"組み立て": "分解の対義語。部品を組み合わせて完成させる意味で、機械の場面で対になる。", "収集": "集めること。分解の対義語ではない。", "増築": "建物を増やすこと。分解の対義語ではない。", "解決": "問題を解くこと。分解の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを細かくする。", "primary_collocate": null, "pronunciation": "ぶんかい", "ipa": "bɯŋkai", "syllable_count": 4, "sentences": [{"text": "古い時計を分解して、中の部品を一つずつ掃除した。", "target_word": "分解", "complexity_tier": "T3", "furigana": "古[ふる]い時計[とけい]を分解[ぶんかい]して、中[なか]の部品[ぶひん]を一[ひと]つずつ掃除[そうじ]した。", "sentence_source": "generated"}, {"text": "おもちゃが壊れたので、分解して原因を調べた。", "target_word": "分解", "complexity_tier": "T3", "furigana": "おもちゃが壊[こわ]れたので、分解[ぶんかい]して原因[げんいん]を調[しら]べた。", "sentence_source": "generated"}, {"text": "引っ越しの前に、大きな本棚を分解して運びやすくした。", "target_word": "分解", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの前[まえ]に、大[おお]きな本棚[ほんだな]を分解[ぶんかい]して運[はこ]びやすくした。", "sentence_source": "generated"}, {"text": "兄は自転車を分解するのが好きで、組み立てるのも上手だ。", "target_word": "分解", "complexity_tier": "T3", "furigana": "兄[あに]は自転車[じてんしゃ]を分解[ぶんかい]するのが好[す]きで、組[く]み立[た]てるのも上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "この机は簡単に分解できるので、狭い部屋でもしまいやすい。", "target_word": "分解", "complexity_tier": "T3", "furigana": "この机[つくえ]は簡単[かんたん]に分解[ぶんかい]できるので、狭[せま]い部屋[へや]でもしまいやすい。", "sentence_source": "generated"}, {"text": "エンジンを分解して点検したあと、もとどおりに組み立てた。", "target_word": "分解", "complexity_tier": "T3", "furigana": "エンジンを分解[ぶんかい]して点検[てんけん]したあと、もとどおりに組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "パソコンを分解すると、中にはたくさんの小さな部品が入っていた。", "target_word": "分解", "complexity_tier": "T3", "furigana": "パソコンを分解[ぶんかい]すると、中[なか]にはたくさんの小[ちい]さな部品[ぶひん]が入[はい]っていた。", "sentence_source": "generated"}, {"text": "説明書を見ながら、掃除機を分解してフィルターを洗った。", "target_word": "分解", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を見[み]ながら、掃除機[そうじき]を分解[ぶんかい]してフィルターを洗[あら]った。", "sentence_source": "generated"}, {"text": "このカメラは分解してしまったら、もとに戻せないかもしれない。", "target_word": "分解", "complexity_tier": "T3", "furigana": "このカメラは分解[ぶんかい]してしまったら、もとに戻[もど]せないかもしれない。", "sentence_source": "generated"}, {"text": "姉は壊れた傘を分解して、使える部品だけを取っておいた。", "target_word": "分解", "complexity_tier": "T3", "furigana": "姉[あね]は壊[こわ]れた傘[かさ]を分解[ぶんかい]して、使[つか]える部品[ぶひん]だけを取[と]っておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分解", "label": "基本形"}, {"form": "分解する", "label": "する形"}, {"form": "分解した", "label": "過去形"}, {"form": "分解できる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "機械や道具などをばらばらの部品に分けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分解", "is_correct": true, "explanation": "時計を部品にばらす意味で、掃除のために中を出す文脈に合う。"}, {"text": "暗記", "is_correct": false, "explanation": "覚える意味。時計を覚えるという文脈にはならない。"}, {"text": "感染", "is_correct": false, "explanation": "病気などがうつる意味で、時計には使えない。"}, {"text": "通過", "is_correct": false, "explanation": "通り抜ける意味で、時計をばらす意味にならない。"}], "explanations": {"分解": "時計を部品にばらす意味で、掃除のために中を出す文脈に合う。", "暗記": "覚える意味。時計を覚えるという文脈にはならない。", "感染": "病気などがうつる意味で、時計には使えない。", "通過": "通り抜ける意味で、時計をばらす意味にならない。"}, "sentence_index": 0, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バラバラの部品を分解して、一つの機械に仕上げた。", "explanation": "ここは〈組み立て〉（部品を組み合わせて一つにする）の意味。分解は細かくすることなので、組み立てる文では合わない。"}, {"text": "氷を分解して、水にした。", "explanation": "ここは〈融解〉（氷が溶けて水になる）の意味。氷を水に変えるのは細かくすることではないので、分解とは言わない。"}, {"text": "混ざった液体を分解して、上澄みを取った。", "explanation": "ここは〈分離〉（混ざったものを分ける）の意味。液体は部品に分かれるわけではないので、分解とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分解", "is_correct": true, "explanation": "パソコンを部品に分ける意味で、中の部品が出てくる文脈に合う。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かすこと。パソコンには使わない。"}, {"text": "繁殖", "is_correct": false, "explanation": "生物が増えること。パソコンを増やす意味にはならない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮ること。パソコンを分ける意味とは無関係。"}], "explanations": {"分解": "パソコンを部品に分ける意味で、中の部品が出てくる文脈に合う。", "解凍": "凍ったものを溶かすこと。パソコンには使わない。", "繁殖": "生物が増えること。パソコンを増やす意味にはならない。", "撮影": "写真や映像を撮ること。パソコンを分ける意味とは無関係。"}, "sentence_index": 6, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "濡れたタオルを分解して、外に干した。", "explanation": "ここは〈乾燥〉（水分を飛ばす）の意味。タオルを干すのは細かくすることではないので、分解とは言わない。"}, {"text": "台風で家が分解された。", "explanation": "ここは〈破壊〉（壊して使えなくする）の意味。家を部品に分けるだけでは壊れた状態にはならないので、分解とは言わない。"}, {"text": "約束を分解して、取り消した。", "explanation": "ここは〈取り消し〉（決めたことをなしにする）の意味。約束は細かく分けるものではないので、分解とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ねじを外して、パソコンを部品を分解した。", "corrected_sentence": "ねじを外して、パソコンを部品に分解した。", "error_description": "誤りは「部品を」。分解して何になるかは「部品に分解する」と「に」で示す。「を」を重ねると文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36958, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いラジオを分解されて、中の部品を調べた。", "corrected_sentence": "古いラジオが分解されて、中の部品を調べた。", "error_description": "誤りは「を」。分解される側は「が」で示す。「を」のままでは受け身文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合成", "is_correct": true, "explanation": "分解の対義語。物質を結びつけて別の物質を作る意味で、化学の場面で対になる。"}, {"text": "解決", "is_correct": false, "explanation": "問題を解くこと。分解の対義語ではない。"}, {"text": "収集", "is_correct": false, "explanation": "集めること。分解の対義語ではない。"}, {"text": "増築", "is_correct": false, "explanation": "建物を増やすこと。分解の対義語ではない。"}], "correct_answer": "合成", "explanations": {"合成": "分解の対義語。物質を結びつけて別の物質を作る意味で、化学の場面で対になる。", "解決": "問題を解くこと。分解の対義語ではない。", "収集": "集めること。分解の対義語ではない。", "増築": "建物を増やすこと。分解の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「汚れを分解する」の「を」。分解の対象（目的語）を示すので正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「汚れへ分解する」は方向を示すが、分解の対象にはならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「汚れより分解する」は比較の意味になり、文が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「汚れから分解する」は起点を示し、分解の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「汚れを分解する」の「を」。分解の対象（目的語）を示すので正しい。", "へ": "「汚れへ分解する」は方向を示すが、分解の対象にはならず不自然。", "より": "「汚れより分解する」は比較の意味になり、文が通らない。", "から": "「汚れから分解する」は起点を示し、分解の対象を表せない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合成", "is_correct": true, "explanation": "分解の対義語。複数の物質を結びつけて新しい物質を作る意味で、化学の場面で対になる。"}, {"text": "採用", "is_correct": false, "explanation": "人や案を選び入れること。分解と意味の関係がない。"}, {"text": "解説", "is_correct": false, "explanation": "分かりやすく説明すること。分解の対義語ではない。"}, {"text": "登録", "is_correct": false, "explanation": "名前などを記録に載せること。分解の対義語ではない。"}], "correct_answer": "合成", "explanations": {"合成": "分解の対義語。複数の物質を結びつけて新しい物質を作る意味で、化学の場面で対になる。", "採用": "人や案を選び入れること。分解と意味の関係がない。", "解説": "分かりやすく説明すること。分解の対義語ではない。", "登録": "名前などを記録に載せること。分解の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物質を化学的に変化させて、もとの形とは別のものにすること。", "primary_collocate": null, "pronunciation": "ぶんかい", "ipa": "bɯŋkai", "syllable_count": 4, "sentences": [{"text": "しかし、微生物の営みを経ることで、難消化性の成分は低分子化され、栄養価が劇的に向上するのみならず、フィチン酸などの抗栄養因子も分解される。", "target_word": "分解", "complexity_tier": "T3", "furigana": "しかし、微生物[びせいぶつ]の営[いとな]みを経[へ]ることで、難消化性[なんしょうかせい]の成分[せいぶん]は低分子化[ていぶんしか]され、栄養価[えいようか]が劇的[げきてき]に向上[こうじょう]するのみならず、フィチン酸[さん]などの抗栄養因子[こうえいよういんし]も分解[ぶんかい]される。", "sentence_source": "mined"}, {"text": "食べ物のでんぷんは、体の中で酵素によって糖に分解される。", "target_word": "分解", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]のでんぷんは、体[からだ]の中[なか]で酵素[こうそ]によって糖[とう]に分解[ぶんかい]される。", "sentence_source": "generated"}, {"text": "水に電気を流すと、水素と酸素に分解することができる。", "target_word": "分解", "complexity_tier": "T3", "furigana": "水[みず]に電気[でんき]を流[なが]すと、水素[すいそ]と酸素[さんそ]に分解[ぶんかい]することができる。", "sentence_source": "generated"}, {"text": "落ち葉は微生物に分解されて、やがて土の栄養になる。", "target_word": "分解", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]は微生物[びせいぶつ]に分解[ぶんかい]されて、やがて土[つち]の栄養[えいよう]になる。", "sentence_source": "generated"}, {"text": "過酸化水素水は光に当たると、水と酸素に分解しやすい。", "target_word": "分解", "complexity_tier": "T3", "furigana": "過酸化水素水[かさんかすいそすい]は光[ひかり]に当[あ]たると、水[みず]と酸素[さんそ]に分解[ぶんかい]しやすい。", "sentence_source": "generated"}, {"text": "プラスチックの中には、自然の中でなかなか分解されないものがある。", "target_word": "分解", "complexity_tier": "T3", "furigana": "プラスチックの中[なか]には、自然[しぜん]の中[なか]でなかなか分解[ぶんかい]されないものがある。", "sentence_source": "generated"}, {"text": "肝臓は、お酒に含まれるアルコールを分解する働きをしている。", "target_word": "分解", "complexity_tier": "T3", "furigana": "肝臓[かんぞう]は、お酒[さけ]に含[ふく]まれるアルコールを分解[ぶんかい]する働[はたら]きをしている。", "sentence_source": "generated"}, {"text": "この洗剤は、油の汚れを分解する成分が入っているので、よく落ちる。", "target_word": "分解", "complexity_tier": "T3", "furigana": "この洗剤[せんざい]は、油[あぶら]の汚[よご]れを分解[ぶんかい]する成分[せいぶん]が入[はい]っているので、よく落[お]ちる。", "sentence_source": "generated"}, {"text": "実験で、炭酸カルシウムを熱して二酸化炭素に分解した。", "target_word": "分解", "complexity_tier": "T3", "furigana": "実験[じっけん]で、炭酸[たんさん]カルシウムを熱[ねっ]して二酸化炭素[にさんかたんそ]に分解[ぶんかい]した。", "sentence_source": "generated"}, {"text": "生ごみを分解する機械を使うと、堆肥を作ることができる。", "target_word": "分解", "complexity_tier": "T3", "furigana": "生[なま]ごみを分解[ぶんかい]する機械[きかい]を使[つか]うと、堆肥[たいひ]を作[つく]ることができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分解", "label": "基本形"}, {"form": "分解する", "label": "する形"}, {"form": "分解した", "label": "過去形"}, {"form": "分解される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "化学的な変化で物質が別のものになること(酵素・微生物・熱などによる分解)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: フィチン (Zipf 1.72)']::text[], 'faf4c166-8f24-4fcf-989c-96dfbd3591b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分解", "is_correct": true, "explanation": "抗栄養因子が化学的に別のものへ変わる意味で、文の内容に合う。"}, {"text": "暗記", "is_correct": false, "explanation": "覚えることを表す。抗栄養因子を覚える意味にはならず、文が通らない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す意味で、成分の変化には使えない。"}, {"text": "感染", "is_correct": false, "explanation": "病原体がうつる意味で、栄養成分には当てはまらない。"}], "explanations": {"分解": "抗栄養因子が化学的に別のものへ変わる意味で、文の内容に合う。", "暗記": "覚えることを表す。抗栄養因子を覚える意味にはならず、文が通らない。", "修理": "壊れたものを直す意味で、成分の変化には使えない。", "感染": "病原体がうつる意味で、栄養成分には当てはまらない。"}, "sentence_index": 0, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水を火にかけると、分解して蒸気になった。", "explanation": "ここは〈蒸発〉（液体が気体に変わる）の意味。水が蒸気になるのは物質が変わらない状態変化なので、化学変化を表す分解とは言わない。"}, {"text": "水素と酸素を分解して、水を作った。", "explanation": "ここは〈化合〉（別々の物質が結びついて新しい物質になる）の意味。分解は一つの物質を別のものに変える反応で、その逆向きには使わない。"}, {"text": "砂糖を水に入れると、すぐに分解する。", "explanation": "ここは〈溶解〉（溶けて広がる）の意味。砂糖は水に溶けても別の物質にはならないので、分解とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分解", "is_correct": true, "explanation": "アルコールを化学的に分ける働きの意味で、肝臓の働きに合う。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かすこと。アルコールには使えず、文が通らない。"}, {"text": "繁殖", "is_correct": false, "explanation": "生物が増えること。アルコールを増やす意味にはならない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮ること。分解する働きとは無関係で文が通らない。"}], "explanations": {"分解": "アルコールを化学的に分ける働きの意味で、肝臓の働きに合う。", "解凍": "凍ったものを溶かすこと。アルコールには使えず、文が通らない。", "繁殖": "生物が増えること。アルコールを増やす意味にはならない。", "撮影": "写真や映像を撮ること。分解する働きとは無関係で文が通らない。"}, "sentence_index": 6, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "混ざった油と水を分解して、上の油だけを取った。", "explanation": "ここは〈分離〉（混ざったものを分ける）の意味。油と水は別の物質に変わらないので、分解とは言わない。"}, {"text": "大豆を分解して、きなこにした。", "explanation": "ここは〈粉砕〉（砕いて細かくする）の意味。大豆が別の物質になるわけではないので、分解とは言わない。"}, {"text": "野菜を分解して、冷蔵庫で新鮮に保った。", "explanation": "ここは〈保存〉（傷まないように保つ）の意味。野菜を保つことは物質を別のものに変えることではないので、分解とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胃の中では、たんぱく質が酵素によってアミノ酸を分解される。", "corrected_sentence": "胃の中では、たんぱく質が酵素によってアミノ酸に分解される。", "error_description": "誤りは「アミノ酸を」。変化の結果は「に」で示すので「アミノ酸に分解される」が正しい。「を」にすると受け身文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36959, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この酵素は脂肪を分解される働きがあるので、消化を助ける。", "corrected_sentence": "この酵素は脂肪を分解する働きがあるので、消化を助ける。", "error_description": "誤りは「分解される」。主語の酵素が脂肪を分解する能動の文なので、「分解する」が正しい。受け身にすると酵素が分解される側になってしまう。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ccebffa-0f39-48f3-8909-bc1524a181ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「熟成で」は時間の経過を手段として示し、後の「味が変わる」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「熟成を、味が」は目的語がなく、後の「味が」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「熟成へ、味が」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、「熟成と、味が」は味の変化とつながらない。"}], "correct_answer": "で", "explanations": {"で": "「熟成で」は時間の経過を手段として示し、後の「味が変わる」と自然につながる。", "を": "「熟成を、味が」は目的語がなく、後の「味が」とつながらない。", "へ": "「へ」は方向を示すので、「熟成へ、味が」は意味が通らない。", "と": "「と」は並列を示すので、「熟成と、味が」は味の変化とつながらない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りない」の主語は「熟成が」で示すので、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「熟成を足りない」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「熟成に足りない」は意味が通らず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「熟成へ足りない」は文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「足りない」の主語は「熟成が」で示すので、文に合う。", "を": "「熟成を足りない」は文が成り立たない。", "に": "「熟成に足りない」は意味が通らず、不自然。", "へ": "「へ」は方向を示すので、「熟成へ足りない」は文に合わない。"}, "error_tags": {"を": "対象", "に": "帰着点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "時間がたって、味や香りがよくなること。", "primary_collocate": null, "pronunciation": "じゅくせい", "ipa": "dʑɯkɯseː", "syllable_count": 4, "sentences": [{"text": "ワインは長く熟成させるほど、香りが深くなる。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "ワインは長[なが]く熟成[じゅくせい]させるほど、香[かお]りが深[ふか]くなる。", "sentence_source": "generated"}, {"text": "このチーズは半年の熟成で、味がまろやかになった。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "このチーズは半年[はんとし]の熟成[じゅくせい]で、味[あじ]がまろやかになった。", "sentence_source": "generated"}, {"text": "熟成が進んで、肉のうまみが増した。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "熟成[じゅくせい]が進[すす]んで、肉[にく]のうまみが増[ま]した。", "sentence_source": "generated"}, {"text": "酒蔵では、新しい酒を樽で熟成させている。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "酒蔵[さかぐら]では、新[あたら]しい酒[さけ]を樽[たる]で熟成[じゅくせい]させている。", "sentence_source": "generated"}, {"text": "時間をかけた熟成のおかげで、醤油の香りがよい。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "時間[じかん]をかけた熟成[じゅくせい]のおかげで、醤油[しょうゆ]の香[かお]りがよい。", "sentence_source": "generated"}, {"text": "熟成した味噌は、色が濃くて風味が豊かだ。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "熟成[じゅくせい]した味噌[みそ]は、色[いろ]が濃[こ]くて風味[ふうみ]が豊[ゆた]かだ。", "sentence_source": "generated"}, {"text": "このウイスキーは十年の熟成を経て、味が丸くなった。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "このウイスキーは十年[じゅうねん]の熟成[じゅくせい]を経[へ]て、味[あじ]が丸[まる]くなった。", "sentence_source": "generated"}, {"text": "熟成が足りないので、まだ味が尖っている。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "熟成[じゅくせい]が足[た]りないので、まだ味[あじ]が尖[とが]っている。", "sentence_source": "generated"}, {"text": "肉は冷蔵庫でゆっくり熟成すると、柔らかくなる。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "肉[にく]は冷蔵庫[れいぞうこ]でゆっくり熟成[じゅくせい]すると、柔[やわ]らかくなる。", "sentence_source": "generated"}, {"text": "日本酒は、熟成の期間によって味が変わる。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "日本酒[にほんしゅ]は、熟成[じゅくせい]の期間[きかん]によって味[あじ]が変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟成する", "label": "終止形"}, {"form": "熟成した", "label": "過去形"}, {"form": "熟成させる", "label": "使役形"}, {"form": "熟成が", "label": "が格"}], "register": "中立", "sense_fingerprint": "時間の経過で味や香りが良くなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熟成", "is_correct": true, "explanation": "「熟成させる」は時間をかけて香りを深める意味になり、文に合う。"}, {"text": "句読点", "is_correct": false, "explanation": "「句読点させる」は意味が通らず、文に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題させる」は文に合わず、意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気させる」は意味が通らず、文が成り立たない。"}], "explanations": {"熟成": "「熟成させる」は時間をかけて香りを深める意味になり、文に合う。", "句読点": "「句読点させる」は意味が通らず、文に合わない。", "宿題": "「宿題させる」は文に合わず、意味が通らない。", "天気": "「天気させる」は意味が通らず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "熟成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は長年の仕事で熟成し、どの作業も速い。", "explanation": "ここは〈熟練〉（腕前が上がる）の意味。熟成は食品の味や香りの変化に使い、人の腕前には言わないので合わない。"}, {"text": "このパンは熟成させて膨らませる。", "explanation": "ここは〈発酵〉の意味。「このパンは発酵させて膨らませる」の発酵を熟成に置き換えたもので、膨らませる働きは発酵にあたるので合わない。"}, {"text": "この子は年の割に熟成していて、考えが深い。", "explanation": "ここは〈成熟〉（人が大人らしく育つこと）の意味。熟成は食品の味や香りの変化に使うので、人の成長には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟成", "is_correct": true, "explanation": "「十年の熟成を経て」は長い時間の処理を意味し、文に合う。"}, {"text": "鍵盤", "is_correct": false, "explanation": "「十年の鍵盤を経て」は意味が通らない。"}, {"text": "段ボール", "is_correct": false, "explanation": "「十年の段ボールを経て」は文に合わず、意味が通らない。"}, {"text": "座布団", "is_correct": false, "explanation": "「十年の座布団を経て」は意味が通らず、文が成り立たない。"}], "explanations": {"熟成": "「十年の熟成を経て」は長い時間の処理を意味し、文に合う。", "鍵盤": "「十年の鍵盤を経て」は意味が通らない。", "段ボール": "「十年の段ボールを経て」は文に合わず、意味が通らない。", "座布団": "「十年の座布団を経て」は意味が通らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "熟成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中、彼は熟成して朝まで起きなかった。", "explanation": "ここは〈熟睡〉（ぐっすり眠る）の意味。熟成は食品の味の変化に使うので、眠りの深さには合わない。"}, {"text": "洗濯物は、風通しのよい所で熟成させる。", "explanation": "ここは〈乾燥〉の意味。「洗濯物は風通しのよい所で乾燥させる」の乾燥を熟成に置き換えたもので、洗濯物を乾かす意味には合わない。"}, {"text": "この町の道は、すでに熟成している。", "explanation": "ここは〈熟知〉（よく知っている）の意味。熟成は食品などに使う語で、道を知っている意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "梅酒は、冷暗所で熟成せると、味がまろやかになる。", "corrected_sentence": "梅酒は、冷暗所で熟成させると、味がまろやかになる。", "error_description": "「熟成する」の使役形は「熟成させる」。「熟成せる」は誤った形なので、「熟成させる」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36960, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熟成を十分になると、味が濃くなる。", "corrected_sentence": "熟成が十分になると、味が濃くなる。", "error_description": "「十分になる」の主語は「熟成が」。「熟成を」は文の構造が合わないので、「熟成が」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「熟成を経て」は工程を経る対象を示し、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「熟成に経て」は意味が通らず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「熟成へ経て」は文に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「熟成が経て」は文が成り立たず、主語としても合わない。"}], "correct_answer": "を", "explanations": {"を": "「熟成を経て」は工程を経る対象を示し、文に合う。", "に": "「熟成に経て」は意味が通らず、文が成り立たない。", "へ": "「へ」は方向を示すので、「熟成へ経て」は文に合わない。", "が": "「熟成が経て」は文が成り立たず、主語としても合わない。"}, "error_tags": {"に": "帰着点", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "時間をかけて発酵や乾燥などの処理を行い、価値や品質が向上した状態にすること。", "primary_collocate": null, "pronunciation": "じゅくせい", "ipa": "dʑɯkɯseː", "syllable_count": 4, "sentences": [{"text": "職人が低温で、ハムを三か月かけて熟成させる。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "職人[しょくにん]が低温[ていおん]で、ハムを三[さん]か月[げつ]かけて熟成[じゅくせい]させる。", "sentence_source": "generated"}, {"text": "この茶葉は発酵と熟成を経て、高い品質になる。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "この茶葉[ちゃば]は発酵[はっこう]と熟成[じゅくせい]を経[へ]て、高[たか]い品質[ひんしつ]になる。", "sentence_source": "generated"}, {"text": "乾燥と熟成の工程が、鰹節の価値を決める。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "乾燥[かんそう]と熟成[じゅくせい]の工程[こうてい]が、鰹節[かつおぶし]の価値[かち]を決[き]める。", "sentence_source": "generated"}, {"text": "蔵で熟成を行うことで、酒の品質が向上する。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "蔵[くら]で熟成[じゅくせい]を行[おこな]うことで、酒[さけ]の品質[ひんしつ]が向上[こうじょう]する。", "sentence_source": "generated"}, {"text": "味噌は発酵のあと、さらに熟成させて出荷する。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "味噌[みそ]は発酵[はっこう]のあと、さらに熟成[じゅくせい]させて出荷[しゅっか]する。", "sentence_source": "generated"}, {"text": "牛肉の熟成には、温度と湿度の管理が欠かせない。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "牛肉[ぎゅうにく]の熟成[じゅくせい]には、温度[おんど]と湿度[しつど]の管理[かんり]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "熟成の工程を省くと、製品の質が下がってしまう。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "熟成[じゅくせい]の工程[こうてい]を省[はぶ]くと、製品[せいひん]の質[しつ]が下[さ]がってしまう。", "sentence_source": "generated"}, {"text": "この店では、チーズを洞窟で熟成させている。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "この店[みせ]では、チーズを洞窟[どうくつ]で熟成[じゅくせい]させている。", "sentence_source": "generated"}, {"text": "熟成を終えた生ハムは、専用の部屋から運び出される。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "熟成[じゅくせい]を終[お]えた生[なま]ハムは、専用[せんよう]の部屋[へや]から運[はこ]び出[だ]される。", "sentence_source": "generated"}, {"text": "樽を地下に保管し、熟成を待っている。", "target_word": "熟成", "complexity_tier": "T3", "furigana": "樽[たる]を地下[ちか]に保管[ほかん]し、熟成[じゅくせい]を待[ま]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟成する", "label": "終止形"}, {"form": "熟成させる", "label": "使役形"}, {"form": "熟成を", "label": "を格"}, {"form": "熟成の", "label": "の格"}], "register": "中立", "sense_fingerprint": "発酵・乾燥などを時間をかけて行い品質を高める工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熟成", "is_correct": true, "explanation": "「熟成させる」は時間をかけた処理を指し、文の意味に合う。"}, {"text": "段ボール", "is_correct": false, "explanation": "「ハムを段ボールさせる」は意味が通らず、文に合わない。"}, {"text": "句読点", "is_correct": false, "explanation": "「ハムを句読点させる」は意味が通らず、文が成り立たない。"}, {"text": "湿度", "is_correct": false, "explanation": "「ハムを湿度させる」は文に合わず、意味が通らない。"}], "explanations": {"熟成": "「熟成させる」は時間をかけた処理を指し、文の意味に合う。", "段ボール": "「ハムを段ボールさせる」は意味が通らず、文に合わない。", "句読点": "「ハムを句読点させる」は意味が通らず、文が成り立たない。", "湿度": "「ハムを湿度させる」は文に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "熟成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は答えを出す前に、熟成して考えた。", "explanation": "ここは〈熟考〉（よく考えること）の意味。熟成は食品などの処理に使う語なので、考えを深める意味には合わない。"}, {"text": "職人は長年の経験で、熟成した技を持つ。", "explanation": "ここは〈熟練〉（腕前がよくなる）の意味。熟成は食品の品質に使い、人の技量には言わないので合わない。"}, {"text": "彼はこの地図を熟成している。", "explanation": "ここは〈熟知〉（よく知っている）の意味。熟成は品質を高める工程を指すので、知識の深さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟成", "is_correct": true, "explanation": "「熟成の工程」は品質に関わる処理を指し、文の意味に合う。"}, {"text": "鍵盤", "is_correct": false, "explanation": "「鍵盤の工程」は意味が通らず、文に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団の工程」は文に合わず、意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の工程」は意味が通らず、文が成り立たない。"}], "explanations": {"熟成": "「熟成の工程」は品質に関わる処理を指し、文の意味に合う。", "鍵盤": "「鍵盤の工程」は意味が通らず、文に合わない。", "座布団": "「座布団の工程」は文に合わず、意味が通らない。", "天気": "「天気の工程」は意味が通らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "熟成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は年の割に熟成していて、言葉が落ち着いている。", "explanation": "ここは〈成熟〉（人が大人らしく育つこと）の意味。熟成は食品の味や香りの変化に使うので、人の成長には合わない。"}, {"text": "ドライヤーで髪を熟成させる。", "explanation": "ここは〈乾燥〉の意味。熟成は時間をかけて品質を整える工程なので、髪を乾かす意味には合わない。"}, {"text": "彼は昨夜、熟成して朝まで眠った。", "explanation": "ここは〈熟睡〉（ぐっすり眠る）の意味。熟成は食品などに使うので、眠りの深さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熟成に行うと、味が安定する。", "corrected_sentence": "熟成を行うと、味が安定する。", "error_description": "「行う」の対象は「を」で示す。「熟成に行う」の「に」が誤りで、「熟成を行う」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36961, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熟成が十分に行うことが大切だ。", "corrected_sentence": "熟成を十分に行うことが大切だ。", "error_description": "「行う」の対象は「を」で示す。「熟成が行う」は熟成を主語にしてしまい、目的語にならないので「熟成を行う」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「堆肥を畑にまく」の目的語を表す「を」。肥料を畑にまく意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「堆肥が畑にまいたら」は堆肥が自分でまく意味になり、文脈が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「堆肥に畑にまいたら」は「に」の目的が不明で、まく対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「堆肥へ畑にまいたら」は、まく対象を示す形として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「堆肥を畑にまく」の目的語を表す「を」。肥料を畑にまく意味になる。", "が": "「堆肥が畑にまいたら」は堆肥が自分でまく意味になり、文脈が崩れる。", "に": "「堆肥に畑にまいたら」は「に」の目的が不明で、まく対象を表せない。", "へ": "「へ」は方向を表す。「堆肥へ畑にまいたら」は、まく対象を示す形として成り立たない。"}, "error_tags": {"が": "主語", "に": "相手・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "草や食べ物の残りなどを、小さな生き物の力で土に戻したもの。", "primary_collocate": null, "pronunciation": "たいひ", "ipa": "taiçi", "syllable_count": 3, "sentences": [{"text": "庭の落ち葉と野菜くずを集めて、堆肥を作っています。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "庭[にわ]の落[お]ち葉[ば]と野菜[やさい]くずを集[あつ]めて、堆肥[たいひ]を作[つく]っています。", "sentence_source": "generated"}, {"text": "堆肥を畑にまいたら、トマトが大きく育った。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "堆肥[たいひ]を畑[はたけ]にまいたら、トマトが大[おお]きく育[そだ]った。", "sentence_source": "generated"}, {"text": "生ごみを捨てずに堆肥にすると、ごみの量が減ります。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "生[なま]ごみを捨[す]てずに堆肥[たいひ]にすると、ごみの量[りょう]が減[へ]ります。", "sentence_source": "generated"}, {"text": "祖父は毎年、秋に堆肥を土に混ぜてから種をまく。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎年[まいとし]、秋[あき]に堆肥[たいひ]を土[つち]に混[ま]ぜてから種[たね]をまく。", "sentence_source": "generated"}, {"text": "堆肥の山の中は温かくて、小さな虫がたくさんいた。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "堆肥[たいひ]の山[やま]の中[なか]は温[あたた]かくて、小[ちい]さな虫[むし]がたくさんいた。", "sentence_source": "generated"}, {"text": "市は、堆肥を作るための容器を安く貸し出している。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "市[し]は、堆肥[たいひ]を作[つく]るための容器[ようき]を安[やす]く貸[か]し出[だ]している。", "sentence_source": "generated"}, {"text": "化学肥料を使わず、堆肥だけで野菜を育てる農家もある。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "化学肥料[かがくひりょう]を使[つか]わず、堆肥[たいひ]だけで野菜[やさい]を育[そだ]てる農家[のうか]もある。", "sentence_source": "generated"}, {"text": "草を刈ったあとは、そのまま捨てずに堆肥にしています。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "草[くさ]を刈[か]ったあとは、そのまま捨[す]てずに堆肥[たいひ]にしています。", "sentence_source": "generated"}, {"text": "この堆肥はよく分解していて、嫌なにおいがしない。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "この堆肥[たいひ]はよく分解[ぶんかい]していて、嫌[いや]なにおいがしない。", "sentence_source": "generated"}, {"text": "学校の花壇には、給食の残りから作った堆肥が使われている。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "学校[がっこう]の花壇[かだん]には、給食[きゅうしょく]の残[のこ]りから作[つく]った堆肥[たいひ]が使[つか]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆肥", "label": "基本形"}], "register": "標準", "sense_fingerprint": "草や生ごみを微生物で分解して土に戻した、畑や庭で使う肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "落ち葉や野菜くずを集めて作るものは堆肥で、「を作っています」と文脈が合う。"}, {"text": "石鹸", "is_correct": false, "explanation": "落ち葉と野菜くずから石鹸は作れず、文脈と合わない。"}, {"text": "缶詰", "is_correct": false, "explanation": "野菜くずを集めても缶詰は作れず、落ち葉を使う文脈に合わない。"}, {"text": "風鈴", "is_correct": false, "explanation": "落ち葉や野菜くずから風鈴は作れず、庭の材料の文脈と噛み合わない。"}], "explanations": {"堆肥": "落ち葉や野菜くずを集めて作るものは堆肥で、「を作っています」と文脈が合う。", "石鹸": "落ち葉と野菜くずから石鹸は作れず、文脈と合わない。", "缶詰": "野菜くずを集めても缶詰は作れず、落ち葉を使う文脈に合わない。", "風鈴": "落ち葉や野菜くずから風鈴は作れず、庭の材料の文脈と噛み合わない。"}, "sentence_index": 0, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川の底には、流れてきた泥が堆肥となって厚く積もっている。", "explanation": "ここは〈堆積〉の意味。堆肥は有機物を微生物で分解させた肥料で、川底の泥には使わないので合わない。"}, {"text": "祖父は冬の寒さに、堆肥を燃やして暖をとった。", "explanation": "ここは〈燃料〉の意味。堆肥は有機物を分解させた肥料で、燃やして暖をとるものではないので合わない。"}, {"text": "祖父は毎年、秋に堆肥を牛に食べさせる。", "explanation": "ここは〈飼料〉の意味。堆肥は畑に使う肥料で、牛の餌として与えるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "化学肥料を使わず、堆肥だけで野菜を育てるという文脈に合う肥料は堆肥。"}, {"text": "花火", "is_correct": false, "explanation": "「花火だけで野菜を育てる」は成立せず、肥料の文脈に合わない。"}, {"text": "手袋", "is_correct": false, "explanation": "「手袋だけで野菜を育てる」は意味が通らず、育てる手段として合わない。"}, {"text": "電池", "is_correct": false, "explanation": "「電池だけで野菜を育てる」は肥料の話として成り立たず、文脈と噛み合わない。"}], "explanations": {"堆肥": "化学肥料を使わず、堆肥だけで野菜を育てるという文脈に合う肥料は堆肥。", "花火": "「花火だけで野菜を育てる」は成立せず、肥料の文脈に合わない。", "手袋": "「手袋だけで野菜を育てる」は意味が通らず、育てる手段として合わない。", "電池": "「電池だけで野菜を育てる」は肥料の話として成り立たず、文脈と噛み合わない。"}, "sentence_index": 6, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋のにおいを消すため、堆肥を部屋にまいた。", "explanation": "ここは〈消臭剤〉の用途。堆肥は肥料で、においを消す目的では使わないので合わない。"}, {"text": "畑の虫を殺すため、堆肥をまいた。", "explanation": "ここは〈殺虫剤〉の用途。堆肥は虫を殺す薬品ではなく、微生物で分解した肥料なので合わない。"}, {"text": "食器の汚れを落とすため、堆肥を使った。", "explanation": "ここは〈洗剤〉の用途。堆肥は洗浄には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年の落ち葉で作った堆肥に、畑にまきました。", "corrected_sentence": "去年の落ち葉で作った堆肥を、畑にまきました。", "error_description": "「まく」の目的語には「を」を使う。「堆肥に」は誤りで、正しくは「堆肥を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36962, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この堆肥が畑に入れると、野菜がよく育つ。", "corrected_sentence": "この堆肥を畑に入れると、野菜がよく育つ。", "error_description": "「入れる」の目的語には「を」を使う。「堆肥が」は誤りで、正しくは「堆肥を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「堆肥を作る」の目的語を表す「を」。堆肥を作るときの水分と空気の大切さを述べる文になる。"}, {"text": "や", "is_correct": false, "explanation": "「堆肥や作る」は並列の形にならず、「作る」と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「堆肥へ作る」は作る対象を示せず、意味が通らない。"}, {"text": "か", "is_correct": false, "explanation": "「堆肥か作る」は選択の形にならず、文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "「堆肥を作る」の目的語を表す「を」。堆肥を作るときの水分と空気の大切さを述べる文になる。", "や": "「堆肥や作る」は並列の形にならず、「作る」と続かない。", "へ": "「へ」は方向を表す。「堆肥へ作る」は作る対象を示せず、意味が通らない。", "か": "「堆肥か作る」は選択の形にならず、文が成立しない。"}, "error_tags": {"や": "並列", "か": "選択", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「堆肥は、効き目がゆっくりだ」と主題を示す「は」。化学肥料との比較を述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「堆肥を効き目がゆっくりだ」は「効き目」と結びつかず、比較の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「堆肥へ効き目がゆっくりだ」は主語を示せず不自然。"}, {"text": "か", "is_correct": false, "explanation": "「堆肥か効き目がゆっくりだ」は選択の形にならず、文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "「堆肥は、効き目がゆっくりだ」と主題を示す「は」。化学肥料との比較を述べる文になる。", "を": "「堆肥を効き目がゆっくりだ」は「効き目」と結びつかず、比較の文として成り立たない。", "へ": "「へ」は方向を表す。「堆肥へ効き目がゆっくりだ」は主語を示せず不自然。", "か": "「堆肥か効き目がゆっくりだ」は選択の形にならず、文が成立しない。"}, "error_tags": {"を": "目的語", "か": "選択", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "有機物を微生物の働きで分解・発酵させて作られる、肥料として使える土のようなもの。", "primary_collocate": null, "pronunciation": "たいひ", "ipa": "taiçi", "syllable_count": 3, "sentences": [{"text": "堆肥は、有機物が微生物に分解されてできる。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "堆肥[たいひ]は、有機物[ゆうきぶつ]が微生物[びせいぶつ]に分解[ぶんかい]されてできる。", "sentence_source": "generated"}, {"text": "堆肥を作るときは、水分と空気の量が大切だ。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "堆肥[たいひ]を作[つく]るときは、水分[すいぶん]と空気[くうき]の量[りょう]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "発酵が進むと、堆肥の温度は六十度近くまで上がる。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "発酵[はっこう]が進[すす]むと、堆肥[たいひ]の温度[おんど]は六十度[ろくじゅうど]近[ちか]くまで上[あ]がる。", "sentence_source": "generated"}, {"text": "牛のふんと藁を混ぜて、堆肥を積み上げた。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "牛[うし]のふんと藁[わら]を混[ま]ぜて、堆肥[たいひ]を積[つ]み上[あ]げた。", "sentence_source": "generated"}, {"text": "堆肥を入れると、固い土がやわらかくなります。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "堆肥[たいひ]を入[い]れると、固[かた]い土[つち]がやわらかくなります。", "sentence_source": "generated"}, {"text": "この農園では、剪定した枝を砕いて堆肥にしている。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "この農園[のうえん]では、剪定[せんてい]した枝[えだ]を砕[くだ]いて堆肥[たいひ]にしている。", "sentence_source": "generated"}, {"text": "十分に熟成した堆肥でないと、根を傷めることがある。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]に熟成[じゅくせい]した堆肥[たいひ]でないと、根[ね]を傷[いた]めることがある。", "sentence_source": "generated"}, {"text": "化学肥料に比べて、堆肥は効き目がゆっくりだ。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "化学肥料[かがくひりょう]に比[くら]べて、堆肥[たいひ]は効[き]き目[め]がゆっくりだ。", "sentence_source": "generated"}, {"text": "堆肥を切り返して空気を入れると、発酵が早まる。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "堆肥[たいひ]を切[き]り返[かえ]して空気[くうき]を入[い]れると、発酵[はっこう]が早[はや]まる。", "sentence_source": "generated"}, {"text": "家庭菜園では、完成した堆肥をプランターの土に混ぜて使う。", "target_word": "堆肥", "complexity_tier": "T3", "furigana": "家庭菜園[かていさいえん]では、完成[かんせい]した堆肥[たいひ]をプランターの土[つち]に混[ま]ぜて使[つか]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆肥", "label": "基本形"}], "register": "標準", "sense_fingerprint": "有機物を微生物で分解・発酵させて作る、土壌改良や肥料に使う土状のもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "有機物が微生物に分解されてできるものは堆肥で、定義と一致する。"}, {"text": "風船", "is_correct": false, "explanation": "風船は微生物の分解でできないので、「有機物が微生物に分解されてできる」の主語にはならない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は機械で、有機物の分解によってできるものではないので合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は布製品で、微生物による分解でできるものではなく、定義に合わない。"}], "explanations": {"堆肥": "有機物が微生物に分解されてできるものは堆肥で、定義と一致する。", "風船": "風船は微生物の分解でできないので、「有機物が微生物に分解されてできる」の主語にはならない。", "時計": "時計は機械で、有機物の分解によってできるものではないので合わない。", "座布団": "座布団は布製品で、微生物による分解でできるものではなく、定義に合わない。"}, "sentence_index": 0, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ごみを燃やす焼却炉の中で、堆肥を作った。", "explanation": "ここは〈焼却〉の処理の意味。堆肥は微生物が有機物を分解して作るもので、燃やして作るものとは混同できないので合わない。"}, {"text": "堆肥は、工場で化学物質を合成してできる。", "explanation": "ここは〈化学肥料〉の意味。堆肥は有機物を微生物で分解させたもので、工場での化学合成とは混同できないので合わない。"}, {"text": "ぶどうの果汁を発酵させ、堆肥を作った。", "explanation": "ここは〈ワイン〉の作り方の意味。堆肥は有機物を分解させた肥料で、果汁の発酵で作る飲み物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "十分に熟成した堆肥でないと根を傷めるという文脈で、熟成が必要な肥料は堆肥。"}, {"text": "味噌", "is_correct": false, "explanation": "「熟成した味噌でないと根を傷める」は意味が通らず、植物の根の文脈に合わない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢は容器で、熟成させる必要がなく、根を傷めるかどうかの文脈に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は熟成させて根の状態を左右するものではなく、この文の意味に合わない。"}], "explanations": {"堆肥": "十分に熟成した堆肥でないと根を傷めるという文脈で、熟成が必要な肥料は堆肥。", "味噌": "「熟成した味噌でないと根を傷める」は意味が通らず、植物の根の文脈に合わない。", "植木鉢": "植木鉢は容器で、熟成させる必要がなく、根を傷めるかどうかの文脈に合わない。", "砂糖": "砂糖は熟成させて根の状態を左右するものではなく、この文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "害虫を退治するため、完成した堆肥を殺虫剤として使う。", "explanation": "ここは〈殺虫剤〉の用途。堆肥は害虫を退治する薬ではなく、有機物を分解させた肥料なので合わない。"}, {"text": "料理の甘みを出すため、完成した堆肥を砂糖の代わりに入れる。", "explanation": "ここは〈砂糖〉の用途。堆肥は食べ物ではなく、甘みづけに使う語ではないので合わない。"}, {"text": "プランターの色を塗り替えるため、完成した堆肥を塗る。", "explanation": "ここは〈ペンキ〉の用途。堆肥は塗料ではなく、土に混ぜて使う肥料なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "堆肥がかき混ぜると、空気が入って分解が進みます。", "corrected_sentence": "堆肥をかき混ぜると、空気が入って分解が進みます。", "error_description": "「かき混ぜる」の目的語には「を」を使う。「堆肥が」は誤りで、正しくは「堆肥を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36963, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "堆肥に切り返す回数を増やすと、発酵が早まる。", "corrected_sentence": "堆肥を切り返す回数を増やすと、発酵が早まる。", "error_description": "「切り返す」の目的語には「を」を使う。「堆肥に」は誤りで、正しくは「堆肥を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36968, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「模倣をする」で動作の対象を示す「を」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「する」の対象を示せず、「模倣へして」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「模倣よりして」となり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「模倣でして」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「模倣をする」で動作の対象を示す「を」が正しい。", "へ": "方向を表す「へ」は「する」の対象を示せず、「模倣へして」は成り立たない。", "より": "比較の「より」では「模倣よりして」となり、文が成り立たない。", "で": "「模倣でして」は文として成り立たない。"}, "error_tags": {"へ": "direction", "より": "comparison", "で": "means_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "創造", "is_correct": true, "explanation": "新しいものを生み出す「創造」は、まねる「模倣」の反対。"}, {"text": "複製", "is_correct": false, "explanation": "同じものを作る意味で、むしろ類義語である。"}, {"text": "模造", "is_correct": false, "explanation": "本物に似せて作ることで、類義語である。"}, {"text": "練習", "is_correct": false, "explanation": "繰り返し行うことで、「模倣」の反対ではない。"}], "correct_answer": "創造", "explanations": {"創造": "新しいものを生み出す「創造」は、まねる「模倣」の反対。", "複製": "同じものを作る意味で、むしろ類義語である。", "模造": "本物に似せて作ることで、類義語である。", "練習": "繰り返し行うことで、「模倣」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36968, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に頼る」で頼る相手を示す「に」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「頼る」の相手は「で」では示せず、「模倣で頼る」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「模倣と頼る」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「頼る」の相手を示せない。"}], "correct_answer": "に", "explanations": {"に": "「〜に頼る」で頼る相手を示す「に」が正しい。", "で": "「頼る」の相手は「で」では示せず、「模倣で頼る」は成り立たない。", "と": "「模倣と頼る」は文として成り立たない。", "へ": "方向の「へ」は「頼る」の相手を示せない。"}, "error_tags": {"で": "means_marker", "と": "comitative", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独創", "is_correct": true, "explanation": "自分で新しく考え出す「独創」は、まねる「模倣」の反対。"}, {"text": "盗作", "is_correct": false, "explanation": "他人の作品を盗むことで、類義に近い語である。"}, {"text": "再現", "is_correct": false, "explanation": "もう一度同じものを出すことで、反対の関係ではない。"}, {"text": "保存", "is_correct": false, "explanation": "そのまま残すことで、「模倣」の反対ではない。"}], "correct_answer": "独創", "explanations": {"独創": "自分で新しく考え出す「独創」は、まねる「模倣」の反対。", "盗作": "他人の作品を盗むことで、類義に近い語である。", "再現": "もう一度同じものを出すことで、反対の関係ではない。", "保存": "そのまま残すことで、「模倣」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36968, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他のものをまねること。また、まねて作ったもの。", "primary_collocate": null, "pronunciation": "もほう", "ipa": "mohoː", "syllable_count": 3, "sentences": [{"text": "この作品は模倣です。", "target_word": "模倣", "complexity_tier": "T2", "furigana": "この作品[さくひん]は模倣[もほう]です。", "sentence_source": "generated"}, {"text": "大人の模倣をして、子どもは言葉を覚える。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "大人[おとな]の模倣[もほう]をして、子[こ]どもは言葉[ことば]を覚[おぼ]える。", "sentence_source": "generated"}, {"text": "先生の絵を模倣して描いた。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "先生[せんせい]の絵[え]を模倣[もほう]して描[か]いた。", "sentence_source": "generated"}, {"text": "完全な模倣だ。", "target_word": "模倣", "complexity_tier": "T1", "furigana": "完全[かんぜん]な模倣[もほう]だ。", "sentence_source": "generated"}, {"text": "模倣だと分かれば、買う人はいない。", "target_word": "模倣", "complexity_tier": "T4", "furigana": "模倣[もほう]だと分[わ]かれば、買[か]う人[ひと]はいない。", "sentence_source": "generated"}, {"text": "その建物は、外国の城の模倣だった。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "その建物[たてもの]は、外国[がいこく]の城[しろ]の模倣[もほう]だった。", "sentence_source": "generated"}, {"text": "他社の製品の模倣を禁止する法律がある。", "target_word": "模倣", "complexity_tier": "T4", "furigana": "他社[たしゃ]の製品[せいひん]の模倣[もほう]を禁止[きんし]する法律[ほうりつ]がある。", "sentence_source": "generated"}, {"text": "模倣に頼るだけでは、新しい物は作れない。", "target_word": "模倣", "complexity_tier": "T4", "furigana": "模倣[もほう]に頼[たよ]るだけでは、新[あたら]しい物[もの]は作[つく]れない。", "sentence_source": "generated"}, {"text": "昔の名画を忠実に模倣する技術を、彼は身につけた。", "target_word": "模倣", "complexity_tier": "T5", "furigana": "昔[むかし]の名画[めいが]を忠実[ちゅうじつ]に模倣[もほう]する技術[ぎじゅつ]を、彼[かれ]は身[み]につけた。", "sentence_source": "generated"}, {"text": "模倣は上手でしたが、新しさがありません。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "模倣[もほう]は上手[じょうず]でしたが、新[あたら]しさがありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "模倣する", "label": "派生"}, {"form": "模倣した", "label": "派生"}, {"form": "模倣品", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 他のものをまねること・まねたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36968, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "模倣", "is_correct": true, "explanation": "見出し語そのものの「もほう」である。"}, {"text": "模様", "is_correct": false, "explanation": "「もよう」で、「ほ」が「よ」に変わった別の語。"}, {"text": "途方", "is_correct": false, "explanation": "「とほう」で、「も」が「と」に変わった別の語。"}, {"text": "予報", "is_correct": false, "explanation": "「よほう」で、「も」が「よ」に変わった別の語。"}], "explanations": {"模倣": "見出し語そのものの「もほう」である。", "模様": "「もよう」で、「ほ」が「よ」に変わった別の語。", "途方": "「とほう」で、「も」が「と」に変わった別の語。", "予報": "「よほう」で、「も」が「よ」に変わった別の語。"}, "sentence_index": null, "correct_answer": "模倣"}, "level_3": {"options": [{"text": "模倣", "is_correct": true, "explanation": "作品が他のものをそっくり真似たものだという意味で自然に合う。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、作品を「台風」と言うのは意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、作品が「約束」だという意味は合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、作品が「季節」だという意味は合わない。"}], "explanations": {"模倣": "作品が他のものをそっくり真似たものだという意味で自然に合う。", "台風": "形は合うが、作品を「台風」と言うのは意味が合わない。", "約束": "形は合うが、作品が「約束」だという意味は合わない。", "季節": "形は合うが、作品が「季節」だという意味は合わない。"}, "sentence_index": 0, "correct_answer": "模倣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の外で模倣が降っている。", "explanation": "「模倣」は降るものではなく、雨や雪のような天気の意味で使うのは誤り。"}, {"text": "彼は自分で考えた独創的な模倣を発表した。", "explanation": "「模倣」は他をまねることなので、「独創的」「自分で考えた」とは意味が矛盾する。"}, {"text": "毎朝七時に模倣を食べる。", "explanation": "「模倣」は行為・作ったものを表し、食べ物ではないので「食べる」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
