INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36969, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「模倣をします」で、する行為を示す。"}, {"text": "が", "is_correct": false, "explanation": "「模倣がします」は動詞「する」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「模倣へします」にならない。"}, {"text": "の", "is_correct": false, "explanation": "「模倣のします」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「模倣をします」で、する行為を示す。", "が": "「模倣がします」は動詞「する」と合わない。", "へ": "方向の「へ」では「模倣へします」にならない。", "の": "「模倣のします」は文法的に成り立たない。"}, "error_tags": {"が": "subject_object", "へ": "direction", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "創造", "is_correct": true, "explanation": "新しく作り出す意味で、真似る模倣と反対になる。"}, {"text": "複製", "is_correct": false, "explanation": "同じものを作る意味で、類義語に近い。"}, {"text": "再現", "is_correct": false, "explanation": "同じように示す意味で反対ではない。"}, {"text": "引用", "is_correct": false, "explanation": "他から借りる意味で反対ではない。"}], "correct_answer": "創造", "explanations": {"創造": "新しく作り出す意味で、真似る模倣と反対になる。", "複製": "同じものを作る意味で、類義語に近い。", "再現": "同じように示す意味で反対ではない。", "引用": "他から借りる意味で反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
