INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36969, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事や動作、状態などを、そのまま真似て似せること。または、そのようにして作られたもの。", "primary_collocate": null, "pronunciation": "もほう", "ipa": "mohoː", "syllable_count": 3, "sentences": [{"text": "童子の行為は、単なる日常的な営みの模倣を超え、生命の循環に対する原初的な祈りにも似た、崇高な儀式としてそこに刻まれるのである。", "target_word": "模倣", "complexity_tier": "T6", "furigana": "童子[どうじ]の行為[こうい]は、単[たん]なる日常的[にちじょうてき]な営[いとな]みの模倣[もほう]を超[こ]え、生命[せいめい]の循環[じゅんかん]に対[たい]する原初的[げんしょてき]な祈[いの]りにも似[に]た、崇高[すうこう]な儀式[ぎしき]としてそこに刻[きざ]まれるのである。", "sentence_source": "mined"}, {"text": "子どもは大人の模倣をします。", "target_word": "模倣", "complexity_tier": "T2", "furigana": "子[こ]どもは大人[おとな]の模倣[もほう]をします。", "sentence_source": "generated"}, {"text": "動物の鳴き声を模倣して遊んだ。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の鳴[な]き声[ごえ]を模倣[もほう]して遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "これは有名な絵の模倣だ。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "これは有名[ゆうめい]な絵[え]の模倣[もほう]だ。", "sentence_source": "generated"}, {"text": "模倣を恥じる必要はない。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "模倣[もほう]を恥[は]じる必要[ひつよう]はない。", "sentence_source": "generated"}, {"text": "模倣ばかりでは、新しいものは生まれない。", "target_word": "模倣", "complexity_tier": "T4", "furigana": "模倣[もほう]ばかりでは、新[あたら]しいものは生[う]まれない。", "sentence_source": "generated"}, {"text": "彼の話し方は父の模倣だった。", "target_word": "模倣", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]は父[ちち]の模倣[もほう]だった。", "sentence_source": "generated"}, {"text": "学びは模倣から始まると言われている。", "target_word": "模倣", "complexity_tier": "T4", "furigana": "学[まな]びは模倣[もほう]から始[はじ]まると言[い]われている。", "sentence_source": "generated"}, {"text": "優れた作品の模倣を重ねるうちに、自分の個性が見えてきた。", "target_word": "模倣", "complexity_tier": "T5", "furigana": "優[すぐ]れた作品[さくひん]の模倣[もほう]を重[かさ]ねるうちに、自分[じぶん]の個性[こせい]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "模倣は学びだ。", "target_word": "模倣", "complexity_tier": "T1", "furigana": "模倣[もほう]は学[まな]びだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "模倣する", "label": "派生"}, {"form": "模倣した", "label": "派生"}, {"form": "模倣的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事を真似て似せること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 童子 (Zipf 3.27), 営み (Zipf 3.27), 原初 (Zipf 2.75), 崇高 (Zipf 3.16)']::text[], 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36969, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "模倣", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "模造", "is_correct": false, "explanation": "ほとぞの一音だけが違う別語。"}, {"text": "模様", "is_correct": false, "explanation": "ほとようの一音だけが違う別語。"}, {"text": "魔法", "is_correct": false, "explanation": "もとまの一音だけが違う別語。"}, {"text": "家宝", "is_correct": false, "explanation": "もとかの一音だけが違う別語。"}], "explanations": {"模倣": "見出し語そのもの。", "模造": "ほとぞの一音だけが違う別語。", "模様": "ほとようの一音だけが違う別語。", "魔法": "もとまの一音だけが違う別語。", "家宝": "もとかの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "模倣"}, "level_3": {"options": [{"text": "模倣", "is_correct": true, "explanation": "日常の営みの真似を超えるという流れに合う。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、営みの地図を超えるでは意味が合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、営みの景色を超えるでは意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、営みの値段を超えるでは意味が合わない。"}], "explanations": {"模倣": "日常の営みの真似を超えるという流れに合う。", "地図": "形は合うが、営みの地図を超えるでは意味が合わない。", "景色": "形は合うが、営みの景色を超えるでは意味が合わない。", "値段": "形は合うが、営みの値段を超えるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "模倣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園で模倣を食べてから走る。", "explanation": "「模倣」は真似ることで、食べ物ではないので使い方が合わない。"}, {"text": "模倣が高いので、電車で行った。", "explanation": "「模倣」は値段や料金の意味ではないので誤り。"}, {"text": "明日の模倣は晴れるでしょう。", "explanation": "「模倣」は天気を表す語ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36969, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "模倣", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "予報", "is_correct": false, "explanation": "もとよの一音だけが違う別語。"}, {"text": "途方", "is_correct": false, "explanation": "もととの一音だけが違う別語。"}, {"text": "四方", "is_correct": false, "explanation": "もとしの一音だけが違う別語。"}, {"text": "作法", "is_correct": false, "explanation": "もとさの一音だけが違う別語。"}], "explanations": {"模倣": "見出し語そのもの。", "予報": "もとよの一音だけが違う別語。", "途方": "もととの一音だけが違う別語。", "四方": "もとしの一音だけが違う別語。", "作法": "もとさの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "模倣"}, "level_3": {"options": [{"text": "模倣", "is_correct": true, "explanation": "話し方が父の真似だったという意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、話し方が父の天気では意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、話し方が父の季節では意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、話し方が父の財布では意味が合わない。"}], "explanations": {"模倣": "話し方が父の真似だったという意味に合う。", "天気": "形は合うが、話し方が父の天気では意味が合わない。", "季節": "形は合うが、話し方が父の季節では意味が合わない。", "財布": "形は合うが、話し方が父の財布では意味が合わない。"}, "sentence_index": 6, "correct_answer": "模倣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は模倣を持って、買い物に行った。", "explanation": "「模倣」は持ち運ぶ物ではなく、真似る行為なので使い方が合わない。"}, {"text": "模倣は長くて、橋を渡るのに時間がかかる。", "explanation": "「模倣」は場所や橋の長さを表す語ではない。"}, {"text": "窓から模倣が見えて、とてもきれいだった。", "explanation": "「模倣」は景色のように見える物ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36969, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の絵は有名な画家を模倣だ。", "corrected_sentence": "彼の絵は有名な画家の模倣だ。", "error_description": "「模倣」の元を示すには「を」ではなく「の」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36969, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の歌い方は先生に模倣している。", "corrected_sentence": "彼女の歌い方は先生を模倣している。", "error_description": "「模倣する」の対象は「に」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「果皮には」の形で、果皮の上にある存在を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「果皮がは」と続けると助詞が重なり、不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「果皮をは」は目的語として成り立たず、ここでは存在の場所が必要。"}, {"text": "の", "is_correct": false, "explanation": "「果皮のは」は名詞をつなぐ形で、「には」の形にならない。"}], "correct_answer": "に", "explanations": {"に": "「果皮には」の形で、果皮の上にある存在を示す。正解。", "が": "「果皮がは」と続けると助詞が重なり、不自然になる。", "を": "「果皮をは」は目的語として成り立たず、ここでは存在の場所が必要。", "の": "「果皮のは」は名詞をつなぐ形で、「には」の形にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「バナナの果皮で」の形で、すべった原因となる物を表す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「果皮を、くつがすべって」では果皮が目的語になり、原因の文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「果皮の、くつがすべって」は名詞をつなぐ形にならず、文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「果皮と、くつがすべって」は並列を表し、すべった原因を示せない。"}], "correct_answer": "で", "explanations": {"で": "「バナナの果皮で」の形で、すべった原因となる物を表す。正解。", "を": "「果皮を、くつがすべって」では果皮が目的語になり、原因の文として成り立たない。", "の": "「果皮の、くつがすべって」は名詞をつなぐ形にならず、文が崩れる。", "と": "「果皮と、くつがすべって」は並列を表し、すべった原因を示せない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くだものや野菜の、一番外側の皮のことです。", "primary_collocate": null, "pronunciation": "かひ", "ipa": "kaçi", "syllable_count": 2, "sentences": [{"text": "みかんの果皮は、むいてからすてます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "みかんの果皮(かひ)は、むいてからすてます。", "sentence_source": "generated"}, {"text": "りんごの果皮には、赤い色がついています。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "りんごの果皮(かひ)には、赤(あか)い色(いろ)がついています。", "sentence_source": "generated"}, {"text": "果皮がかたいので、ナイフで切ってください。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)がかたいので、ナイフで切(き)ってください。", "sentence_source": "generated"}, {"text": "レモンの果皮をすりおろして、ケーキに入れました。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "レモンの果皮(かひ)をすりおろして、ケーキに入(い)れました。", "sentence_source": "generated"}, {"text": "ぶどうの果皮は薄いので、そのまま食べられます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "ぶどうの果皮(かひ)は薄(うす)いので、そのまま食(た)べられます。", "sentence_source": "generated"}, {"text": "トマトの果皮が破れて、中の水が出てきました。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "トマトの果皮(かひ)が破(やぶ)れて、中(なか)の水(みず)が出(で)てきました。", "sentence_source": "generated"}, {"text": "果皮にきずがあるものは、安く売られています。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)にきずがあるものは、安(やす)く売(う)られています。", "sentence_source": "generated"}, {"text": "バナナの果皮で、くつがすべって転びそうになりました。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "バナナの果皮(かひ)で、くつがすべって転(ころ)びそうになりました。", "sentence_source": "generated"}, {"text": "果皮の色が緑から黄色に変わると、食べごろです。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)の色(いろ)が緑(みどり)から黄色(きいろ)に変(か)わると、食(た)べごろです。", "sentence_source": "generated"}, {"text": "農薬が心配なので、果皮をむいて食べます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "農薬(のうやく)が心配(しんぱい)なので、果皮(かひ)をむいて食(た)べます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "果皮", "label": "基本形"}], "register": "中立", "sense_fingerprint": "果物や野菜の一番外側の皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果皮", "is_correct": true, "explanation": "果物の一番外側の皮を指す。「みかんの果皮」を捨てる文として正しい。"}, {"text": "味", "is_correct": false, "explanation": "「みかんの味は、むいてからすてます」は意味をなさない。捨てるのは味ではなく皮。"}, {"text": "香り", "is_correct": false, "explanation": "「香りを捨てる」は文として成り立たず、むいて捨てる対象にならない。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さは、むいてからすてます」は不自然で、捨てる対象を表せない。"}], "explanations": {"果皮": "果物の一番外側の皮を指す。「みかんの果皮」を捨てる文として正しい。", "味": "「みかんの味は、むいてからすてます」は意味をなさない。捨てるのは味ではなく皮。", "香り": "「香りを捨てる」は文として成り立たず、むいて捨てる対象にならない。", "重さ": "「重さは、むいてからすてます」は不自然で、捨てる対象を表せない。"}, "sentence_index": 0, "correct_answer": "果皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レモンの果皮を絞って、中の果汁を取り出しました。", "explanation": "「果汁」を取り出すのは果肉の部分で、「果皮」は果汁を絞る部分ではない。果汁を取る文に「果皮」を使うのは誤り。"}, {"text": "レモンの果皮を割って、中の種を取り出しました。", "explanation": "「果皮」は外側の皮で、割って種を取り出す対象ではない。種を取る文の場面には合わない。"}, {"text": "レモンの果皮が甘いと聞いて、むかずに食べました。", "explanation": "「果皮」は苦みのある外側の皮を指すので、甘さを示す部分として語られる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果皮", "is_correct": true, "explanation": "果物の外側を覆う皮を指す。「果皮にきずがある」は正しい表現。"}, {"text": "日曜日", "is_correct": false, "explanation": "「日曜日にきずがある」は意味をなさず、商品の状態を表せない。"}, {"text": "感情", "is_correct": false, "explanation": "「感情にきずがある」は商品の状態の説明にならず、文として不自然。"}, {"text": "音", "is_correct": false, "explanation": "「音にきずがある」は商品の傷を表す言い方として成り立たない。"}], "explanations": {"果皮": "果物の外側を覆う皮を指す。「果皮にきずがある」は正しい表現。", "日曜日": "「日曜日にきずがある」は意味をなさず、商品の状態を表せない。", "感情": "「感情にきずがある」は商品の状態の説明にならず、文として不自然。", "音": "「音にきずがある」は商品の傷を表す言い方として成り立たない。"}, "sentence_index": 6, "correct_answer": "果皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農薬が心配なので、果皮を土に植えて育てます。", "explanation": "果皮は植えて育てる部分ではない。育てるのは種や苗で、果皮ではない。"}, {"text": "農薬が心配なので、果皮を水に溶かして飲みます。", "explanation": "「果皮」は固い外側の皮で、水に溶かして飲む対象ではない。溶かして飲む場面では「果汁」を使う。"}, {"text": "農薬が心配なので、果皮を電子レンジで果肉に変えます。", "explanation": "「果皮」は外側の皮で、果肉に変わる部分ではない。果肉を指す場面で「果皮」を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "りんごの果皮の薄いので、むいて食べます。", "corrected_sentence": "りんごの果皮は薄いので、むいて食べます。", "error_description": "「果皮」の状態を述べるには「は」で受ける。「果皮の薄い」は名詞の修飾として成り立たず、誤り。正しくは「果皮は薄い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36970, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農薬が心配な日は、果皮でむいて食べます。", "corrected_sentence": "農薬が心配な日は、果皮をむいて食べます。", "error_description": "「むく」の対象は「を」で示す。「果皮で」は誤りで、正しくは「果皮を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36971, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「果皮は厚い」と話題として示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「果皮を厚いので」は目的語として成り立たず、状態を述べる文にならない。"}, {"text": "に", "is_correct": false, "explanation": "「果皮に厚いので」は場所や方向の意味になり、状態を説明できない。"}, {"text": "で", "is_correct": false, "explanation": "「果皮で厚いので」は手段や場所の意味になり、厚さを表せない。"}], "correct_answer": "は", "explanations": {"は": "「果皮は厚い」と話題として示す。正解。", "を": "「果皮を厚いので」は目的語として成り立たず、状態を述べる文にならない。", "に": "「果皮に厚いので」は場所や方向の意味になり、状態を説明できない。", "で": "「果皮で厚いので」は手段や場所の意味になり、厚さを表せない。"}, "error_tags": {"を": "目的語", "に": "場所・方向", "で": "手段・場所"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36971, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「果皮のにおい」と名詞をつなぎ、果皮から出るにおいを示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「オレンジの果皮がにおいは」と主語が二つ重なり、「におい」を「果皮の」で修飾する形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「果皮へにおい」は方向を示す形になり、においを修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「果皮をにおい」は目的語として名詞をつなげず、文が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「果皮のにおい」と名詞をつなぎ、果皮から出るにおいを示す。正解。", "が": "「オレンジの果皮がにおいは」と主語が二つ重なり、「におい」を「果皮の」で修飾する形にならない。", "へ": "「果皮へにおい」は方向を示す形になり、においを修飾できない。", "を": "「果皮をにおい」は目的語として名詞をつなげず、文が崩れる。"}, "error_tags": {"が": "主語", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36971, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "果物や野菜の外側を覆っている皮のこと。食べる前にむいたり、そのまま食べることもある。", "primary_collocate": null, "pronunciation": "かひ", "ipa": "kaçi", "syllable_count": 2, "sentences": [{"text": "なしの果皮は厚いので、むいてから食べます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "なしの果皮(かひ)は厚(あつ)いので、むいてから食(た)べます。", "sentence_source": "generated"}, {"text": "このみかんは、果皮ごと食べられるそうです。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "このみかんは、果皮(かひ)ごと食(た)べられるそうです。", "sentence_source": "generated"}, {"text": "果皮をよく洗えば、そのままでも食べられます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)をよく洗(あら)えば、そのままでも食(た)べられます。", "sentence_source": "generated"}, {"text": "果皮にはビタミンが多いと聞いて、むかずに食べました。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)にはビタミンが多(おお)いと聞(き)いて、むかずに食(た)べました。", "sentence_source": "generated"}, {"text": "ゆずの果皮を細く切って、お茶に入れます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "ゆずの果皮(かひ)を細(ほそ)く切(き)って、お茶(ちゃ)に入(い)れます。", "sentence_source": "generated"}, {"text": "果皮がやわらかいので、手で簡単にむけます。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)がやわらかいので、手(て)で簡単(かんたん)にむけます。", "sentence_source": "generated"}, {"text": "柿の果皮をむいて、ひもでつるして干します。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "柿(かき)の果皮(かひ)をむいて、ひもでつるして干(ほ)します。", "sentence_source": "generated"}, {"text": "オレンジの果皮のにおいは、さわやかです。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "オレンジの果皮(かひ)のにおいは、さわやかです。", "sentence_source": "generated"}, {"text": "果皮がしわしわになったのは、古くなったからです。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)がしわしわになったのは、古(ふる)くなったからです。", "sentence_source": "generated"}, {"text": "果皮ごとジャムにすると、少し苦くなります。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "果皮(かひ)ごとジャムにすると、少(すこ)し苦(にが)くなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "果皮", "label": "基本形"}], "register": "中立", "sense_fingerprint": "果物や野菜を覆う皮（むく・そのまま食べる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36971, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果皮", "is_correct": true, "explanation": "果物の外側を覆う皮を指す。「なしの果皮は厚い」と述べる文として正しい。"}, {"text": "味", "is_correct": false, "explanation": "「なしの味は厚い」は意味をなさず、厚さの主語にならない。"}, {"text": "香り", "is_correct": false, "explanation": "「なしの香りは厚い」は不自然で、むいて食べる部分の状態を表せない。"}, {"text": "色", "is_correct": false, "explanation": "「なしの色は厚い」は成り立たず、厚さを説明する主語にならない。"}], "explanations": {"果皮": "果物の外側を覆う皮を指す。「なしの果皮は厚い」と述べる文として正しい。", "味": "「なしの味は厚い」は意味をなさず、厚さの主語にならない。", "香り": "「なしの香りは厚い」は不自然で、むいて食べる部分の状態を表せない。", "色": "「なしの色は厚い」は成り立たず、厚さを説明する主語にならない。"}, "sentence_index": 0, "correct_answer": "果皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "果皮を絞ってジュースにしました。", "explanation": "「果皮」は絞って果汁を取る部分ではない。果汁を取る文に「果皮」を使うのは誤り。"}, {"text": "果皮を割って、中の種を取り出しました。", "explanation": "「果皮」は外側の皮で、割って中身を取り出す対象ではない。ここでの「果皮」の使い方に合わない。"}, {"text": "果皮の中の果汁を、むかずに飲みました。", "explanation": "「果皮」は外側の皮で、中の果汁を指す語ではない。果汁を飲む場面で「果皮」を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36971, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果皮", "is_correct": true, "explanation": "柿の外側の皮を指す。「柿の果皮をむいて」と続く文として正しい。"}, {"text": "種", "is_correct": false, "explanation": "「柿の種をむいて」は不自然で、むいて干す対象にならない。"}, {"text": "芯", "is_correct": false, "explanation": "「柿の芯をむいて」は成り立たず、干す前に取り除く部分として文が崩れる。"}, {"text": "果汁", "is_correct": false, "explanation": "「果汁をむいて」は液体をむく動作として成り立たず、文が崩れる。"}], "explanations": {"果皮": "柿の外側の皮を指す。「柿の果皮をむいて」と続く文として正しい。", "種": "「柿の種をむいて」は不自然で、むいて干す対象にならない。", "芯": "「柿の芯をむいて」は成り立たず、干す前に取り除く部分として文が崩れる。", "果汁": "「果汁をむいて」は液体をむく動作として成り立たず、文が崩れる。"}, "sentence_index": 6, "correct_answer": "果皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゆずの果皮の中身をジャムにすると、少し苦くなります。", "explanation": "果皮の内側の食べる部分は「果肉」と言う。「果皮」は外側の皮を指し、中身を表す語ではない。"}, {"text": "ゆずの果皮を溶かして、ジャムの生地にします。", "explanation": "「果皮」は固い外側の皮で、溶かしてジャムの生地にする対象ではない。生地には「果肉」を使う。"}, {"text": "ゆずの果皮を泡立てて、ジャムにします。", "explanation": "「果皮」は泡立てる材料ではない。泡立てる対象は卵や生クリームなどで、果皮には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
