INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36971, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゆずの果皮を苦いので、ジャムには入れません。", "corrected_sentence": "ゆずの果皮は苦いので、ジャムには入れません。", "error_description": "「苦い」は形容詞で、「を」は目的語を示す。「果皮を苦い」は成り立たず、状態を述べるには「は」で受ける。正しくは「果皮は苦い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
