INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36972, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "使わないで残った小さな材料。", "primary_collocate": null, "pronunciation": "はざい", "ipa": "hazai", "syllable_count": 3, "sentences": [{"text": "木の端材で、小さな箱を作りました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "木(き)の端材(はざい)で、小(ちい)さな箱(はこ)を作(つく)りました。", "sentence_source": "generated"}, {"text": "工事が終わると、端材がたくさん残りました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "工事(こうじ)が終(お)わると、端材(はざい)がたくさん残(のこ)りました。", "sentence_source": "generated"}, {"text": "端材は捨てずに、子どもの工作に使います。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)は捨(す)てずに、子(こ)どもの工作(こうさく)に使(つか)います。", "sentence_source": "generated"}, {"text": "この店では、家具の端材を安く売っています。", "target_word": "端材", "complexity_tier": "T3", "furigana": "この店(みせ)では、家具(かぐ)の端材(はざい)を安(やす)く売(う)っています。", "sentence_source": "generated"}, {"text": "端材を集めて、ストーブの火にしました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)を集(あつ)めて、ストーブの火(ひ)にしました。", "sentence_source": "generated"}, {"text": "板を切ったあとの端材を、箱にまとめます。", "target_word": "端材", "complexity_tier": "T3", "furigana": "板(いた)を切(き)ったあとの端材(はざい)を、箱(はこ)にまとめます。", "sentence_source": "generated"}, {"text": "使わなかった端材は、庭の花だんの仕切りにしました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "使(つか)わなかった端材(はざい)は、庭(にわ)の花(はな)だんの仕切(しき)りにしました。", "sentence_source": "generated"}, {"text": "端材なので、形も大きさもばらばらです。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)なので、形(かたち)も大(おお)きさもばらばらです。", "sentence_source": "generated"}, {"text": "端材の中から、ちょうどいい長さの木を探しました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)の中(なか)から、ちょうどいい長(なが)さの木(き)を探(さが)しました。", "sentence_source": "generated"}, {"text": "彼は端材でペン立てを作る方法を教えてくれました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "彼(かれ)は端材(はざい)でペン立(た)てを作(つく)る方法(ほうほう)を教(おし)えてくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "端材", "label": "基本形"}], "register": "中立", "sense_fingerprint": "使わずに残った小さな材料（木材など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36972, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "端材", "is_correct": true, "explanation": "「木の＿で箱を作る」の材料として合う。使わずに残った小さな材料のこと。"}, {"text": "木の実", "is_correct": false, "explanation": "木の実は果実で、箱を作る材料にはならない。"}, {"text": "木の葉", "is_correct": false, "explanation": "葉は箱の材料として使えず、文として成り立たない。"}, {"text": "木の根", "is_correct": false, "explanation": "根は木の一部で、箱を作るための材料としては使わない。"}], "explanations": {"端材": "「木の＿で箱を作る」の材料として合う。使わずに残った小さな材料のこと。", "木の実": "木の実は果実で、箱を作る材料にはならない。", "木の葉": "葉は箱の材料として使えず、文として成り立たない。", "木の根": "根は木の一部で、箱を作るための材料としては使わない。"}, "sentence_index": 0, "correct_answer": "端材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テレビの端材を取り替えて、画面を見ました。", "explanation": "ここは〈端末〉の意味。端材は材料の切れ端で、機器の部品を指さない。"}, {"text": "会社は若い端材を毎年採用しています。", "explanation": "ここは〈人材〉の意味。端材は材料の切れ端で、人を指す言葉ではない。"}, {"text": "電池の端材をきれいにふいて、コードをつなぎました。", "explanation": "ここは〈端子〉の意味。端材は使わずに残った材料で、電気をつなぐ部品の端子ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36972, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "端材", "is_correct": true, "explanation": "「使わなかった＿は、庭の仕切りにした」の材料として合う。"}, {"text": "肥料", "is_correct": false, "explanation": "肥料は仕切りの材料にならず、文として不自然。"}, {"text": "種", "is_correct": false, "explanation": "種は仕切りを作る材料ではなく、文が成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "花は仕切りの材料にならず、「使わなかった花」という表現も不自然。"}], "explanations": {"端材": "「使わなかった＿は、庭の仕切りにした」の材料として合う。", "肥料": "肥料は仕切りの材料にならず、文として不自然。", "種": "種は仕切りを作る材料ではなく、文が成り立たない。", "花": "花は仕切りの材料にならず、「使わなかった花」という表現も不自然。"}, "sentence_index": 6, "correct_answer": "端材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "1000円未満の端材は切り捨てます。", "explanation": "ここは〈端数〉の意味。端材は材料の切れ端で、金額の1000円未満の部分には使わない。"}, {"text": "彼は端材で映画に出ています。", "explanation": "ここは〈端役〉の意味。端材は人ではなく材料なので、映画に出る役にはならない。"}, {"text": "工場では、端材を毎日新しく作ります。", "explanation": "ここは〈完成品〉の意味。端材は製品を作ったあとに残る切れ端で、新しく作る対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36972, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業のあと、端材を残りました。", "corrected_sentence": "作業のあと、端材が残りました。", "error_description": "「残る」は自動詞なので、主語の「端材」には「が」を使う。「を」は誤りで、正しくは「端材が残りました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36972, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は端材に小さな棚を作りました。", "corrected_sentence": "祖父は端材で小さな棚を作りました。", "error_description": "材料を表すには「で」を使う。「に」は誤りで、正しくは「端材で小さな棚を作りました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の対象を示すので、「革の端材を使う」と「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「革の端材が使って」では端材が主語になり、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「革の端材の使って」は名詞をつなぐ形にならず、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「使う」の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の対象を示すので、「革の端材を使う」と「を」が入る。", "が": "「革の端材が使って」では端材が主語になり、意味が通らない。", "の": "「革の端材の使って」は名詞をつなぐ形にならず、文が崩れる。", "へ": "「へ」は方向を示すので、「使う」の対象を表せない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「端材」が「落ちている」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「落ちている」は自動詞なので、目的語を示す「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「落ちている」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「端材へ」では端材が落下先になってしまう。"}], "correct_answer": "が", "explanations": {"が": "「端材」が「落ちている」の主語を示す。", "を": "「落ちている」は自動詞なので、目的語を示す「を」は合わない。", "で": "「で」は場所や手段を示すので、「落ちている」の主語にはならない。", "へ": "「へ」は方向を示し、「端材へ」では端材が落下先になってしまう。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "製品を作る際に使い切れずに出る、小さいかけらや切れ端。", "primary_collocate": null, "pronunciation": "はざい", "ipa": "hazai", "syllable_count": 3, "sentences": [{"text": "工場では、金属の端材が毎日出ます。", "target_word": "端材", "complexity_tier": "T3", "furigana": "工場(こうじょう)では、金属(きんぞく)の端材(はざい)が毎日(まいにち)出(で)ます。", "sentence_source": "generated"}, {"text": "革の端材を使って、小さなキーホルダーを作りました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "革(かわ)の端材(はざい)を使(つか)って、小(ちい)さなキーホルダーを作(つく)りました。", "sentence_source": "generated"}, {"text": "服を作るとき、布の端材はほとんど出ません。", "target_word": "端材", "complexity_tier": "T3", "furigana": "服(ふく)を作(つく)るとき、布(ぬの)の端材(はざい)はほとんど出(で)ません。", "sentence_source": "generated"}, {"text": "端材を減らすために、切り方を工夫しています。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)を減(へ)らすために、切(き)り方(かた)を工夫(くふう)しています。", "sentence_source": "generated"}, {"text": "パン屋は、パンの端材でラスクを作って売っています。", "target_word": "端材", "complexity_tier": "T3", "furigana": "パン屋(や)は、パンの端材(はざい)でラスクを作(つく)って売(う)っています。", "sentence_source": "generated"}, {"text": "端材が出ても、リサイクルして新しい製品にします。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)が出(で)ても、リサイクルして新(あたら)しい製品(せいひん)にします。", "sentence_source": "generated"}, {"text": "紙の端材は、メモ用紙として事務所で使われています。", "target_word": "端材", "complexity_tier": "T3", "furigana": "紙(かみ)の端材(はざい)は、メモ用紙(ようし)として事務所(じむしょ)で使(つか)われています。", "sentence_source": "generated"}, {"text": "端材が床に落ちているので、そうじしてください。", "target_word": "端材", "complexity_tier": "T3", "furigana": "端材(はざい)が床(ゆか)に落(お)ちているので、そうじしてください。", "sentence_source": "generated"}, {"text": "型紙どおりに切ったので、端材の量が少なくなりました。", "target_word": "端材", "complexity_tier": "T3", "furigana": "型紙(かたがみ)どおりに切(き)ったので、端材(はざい)の量(りょう)が少(すく)なくなりました。", "sentence_source": "generated"}, {"text": "鉄の端材は、集めて業者に引き取ってもらいます。", "target_word": "端材", "complexity_tier": "T3", "furigana": "鉄(てつ)の端材(はざい)は、集(あつ)めて業者(ぎょうしゃ)に引(ひ)き取(と)ってもらいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "端材", "label": "基本形"}], "register": "中立", "sense_fingerprint": "製品を作るときに出る小さなかけら・切れ端", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "端材", "is_correct": true, "explanation": "「金属の＿が毎日出ます」に入り、製品作りで出る切れ端として自然。"}, {"text": "工場", "is_correct": false, "explanation": "工場は場所なので、「金属の工場が毎日出る」とは言えない。"}, {"text": "機械", "is_correct": false, "explanation": "機械は出てくるものではなく、「金属の機械が毎日出る」は不自然。"}, {"text": "工具", "is_correct": false, "explanation": "工具は作業で使う道具で、毎日出てくるものとしては合わない。"}], "explanations": {"端材": "「金属の＿が毎日出ます」に入り、製品作りで出る切れ端として自然。", "工場": "工場は場所なので、「金属の工場が毎日出る」とは言えない。", "機械": "機械は出てくるものではなく、「金属の機械が毎日出る」は不自然。", "工具": "工具は作業で使う道具で、毎日出てくるものとしては合わない。"}, "sentence_index": 0, "correct_answer": "端材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パソコンの端材を買い替えました。", "explanation": "ここは〈端末〉の意味。端材は製品作りで出る切れ端で、機器を指さない。"}, {"text": "この店では、家具の端材を一脚ずつ売っています。", "explanation": "ここは〈完成品〉の意味。端材は製品を作る途中で残る切れ端で、一脚単位で売る完成品ではない。"}, {"text": "優秀な端材を育てる研修をします。", "explanation": "ここは〈人材〉の意味。端材は材料の切れ端で、育成の対象になる人を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "端材", "is_correct": true, "explanation": "「紙の＿は、メモ用紙として使われている」に入り、紙の切れ端として自然。"}, {"text": "湿気", "is_correct": false, "explanation": "湿気は紙の状態で、「紙の湿気はメモ用紙として使われる」とは言えない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは紙の性質で、メモ用紙として使われる対象ではない。"}, {"text": "色", "is_correct": false, "explanation": "色は紙の性質で、「紙の色がメモ用紙として使われる」は不自然。"}], "explanations": {"端材": "「紙の＿は、メモ用紙として使われている」に入り、紙の切れ端として自然。", "湿気": "湿気は紙の状態で、「紙の湿気はメモ用紙として使われる」とは言えない。", "匂い": "匂いは紙の性質で、メモ用紙として使われる対象ではない。", "色": "色は紙の性質で、「紙の色がメモ用紙として使われる」は不自然。"}, "sentence_index": 6, "correct_answer": "端材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の内容は、必ず端材に残してください。", "explanation": "ここは〈記録〉の意味。端材は製品作りで出る切れ端で、会議の内容を書き残す記録とは違う。"}, {"text": "この端材は毎朝、多くの人を運びます。", "explanation": "ここは〈路線〉の意味。端材は材料の切れ端で、人を運ぶものではない。"}, {"text": "電池の端材をしっかり接続します。", "explanation": "ここは〈端子〉の意味。端材は材料の切れ端で、電気を接続する部品ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "製造所では、金属の端材を毎日出ます。", "corrected_sentence": "製造所では、金属の端材が毎日出ます。", "error_description": "「出る」は自動詞なので、主語の「端材」には「が」を使う。「を」は誤りで、正しくは「金属の端材が毎日出ます」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36973, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙の端材を、メモ用紙として会社で使われています。", "corrected_sentence": "紙の端材は、メモ用紙として会社で使われています。", "error_description": "「使われる」は受け身なので、主語の「紙の端材」には「は」を使う。「を」は誤りで、正しくは「紙の端材は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「日常」と「中」をつなぐ連体修飾の「の」。「日常の中」として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「日常を中で使う」とは続かず、ここは修飾関係。"}, {"text": "に", "is_correct": false, "explanation": "場所や位置を示す「に」。「日常に中で」と続かず不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」。「日常で中で」と重なり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「日常」と「中」をつなぐ連体修飾の「の」。「日常の中」として自然に続く。", "を": "目的語を示す「を」。「日常を中で使う」とは続かず、ここは修飾関係。", "に": "場所や位置を示す「に」。「日常に中で」と続かず不自然。", "で": "場所や手段を示す「で」。「日常で中で」と重なり、意味が通らない。"}, "error_tags": {"を": "目的語", "に": "場所・位置", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非日常", "is_correct": true, "explanation": "「日常」の対義語で、ふだんと違う特別な生活や出来事を指す。旅行から日常にもどる文脈で対になる。"}, {"text": "旅行", "is_correct": false, "explanation": "出かけて過ごす行動を表し、日常と対になる語ではない。"}, {"text": "台所", "is_correct": false, "explanation": "料理をする場所を表す語で、日常と対義関係にはない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表す語で、日常の反対語ではない。"}], "correct_answer": "非日常", "explanations": {"非日常": "「日常」の対義語で、ふだんと違う特別な生活や出来事を指す。旅行から日常にもどる文脈で対になる。", "旅行": "出かけて過ごす行動を表し、日常と対になる語ではない。", "台所": "料理をする場所を表す語で、日常と対義関係にはない。", "機械": "装置を表す語で、日常の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「日常」と「会話」をつなぐ連体修飾の「の」。「日常の会話」として自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「日常が会話なら」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「日常から会話なら」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「日常へ会話なら」では続かない。"}], "correct_answer": "の", "explanations": {"の": "「日常」と「会話」をつなぐ連体修飾の「の」。「日常の会話」として自然。", "が": "主語を示す「が」。「日常が会話なら」では意味が通らない。", "から": "起点を示す「から」。「日常から会話なら」では成り立たない。", "へ": "方向を示す「へ」。「日常へ会話なら」では続かない。"}, "error_tags": {"が": "主語", "から": "起点", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非日常", "is_correct": true, "explanation": "「日常」の対義語で、ふだんと違う特別な生活や出来事を指す。忙しい日常と対になる。"}, {"text": "試験", "is_correct": false, "explanation": "能力を測るための行事を表し、日常と対義関係にはない。"}, {"text": "音楽", "is_correct": false, "explanation": "芸術の一種を表し、日常の反対語ではない。"}, {"text": "食品", "is_correct": false, "explanation": "飲食物の総称で、日常と対になる語ではない。"}], "correct_answer": "非日常", "explanations": {"非日常": "「日常」の対義語で、ふだんと違う特別な生活や出来事を指す。忙しい日常と対になる。", "試験": "能力を測るための行事を表し、日常と対義関係にはない。", "音楽": "芸術の一種を表し、日常の反対語ではない。", "食品": "飲食物の総称で、日常と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "毎日の生活でよくあること。", "primary_collocate": null, "pronunciation": "にちじょう", "ipa": "nitɕidʑoː", "syllable_count": 4, "sentences": [{"text": "日常の小さな出来事を、毎日日記に書いています。", "target_word": "日常", "complexity_tier": "T3", "furigana": "日常[にちじょう]の小[ちい]さな出来事[できごと]を、毎日[まいにち]日記[にっき]に書[か]いています。", "sentence_source": "generated"}, {"text": "日常の中で使う英語を、まず勉強しましょう。", "target_word": "日常", "complexity_tier": "T3", "furigana": "日常[にちじょう]の中[なか]で使[つか]う英語[えいご]を、まず勉強[べんきょう]しましょう。", "sentence_source": "generated"}, {"text": "電車で本を読むのは、私の日常です。", "target_word": "日常", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で本[ほん]を読[よ]むのは、私[わたし]の日常[にちじょう]です。", "sentence_source": "generated"}, {"text": "旅行から帰って、いつもの日常にもどりました。", "target_word": "日常", "complexity_tier": "T3", "furigana": "旅行[りょこう]から帰[かえ]って、いつもの日常[にちじょう]にもどりました。", "sentence_source": "generated"}, {"text": "日常の買い物は、近くのスーパーですませます。", "target_word": "日常", "complexity_tier": "T3", "furigana": "日常[にちじょう]の買[か]い物[もの]は、近[ちか]くのスーパーですませます。", "sentence_source": "generated"}, {"text": "地震のあと、人々の日常が大きく変わりました。", "target_word": "日常", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、人々[ひとびと]の日常[にちじょう]が大[おお]きく変[か]わりました。", "sentence_source": "generated"}, {"text": "この漫画は、高校生の日常をやさしく描いています。", "target_word": "日常", "complexity_tier": "T3", "furigana": "この漫画[まんが]は、高校生[こうこうせい]の日常[にちじょう]をやさしく描[えが]いています。", "sentence_source": "generated"}, {"text": "日常の会話なら、もう困らないくらい話せます。", "target_word": "日常", "complexity_tier": "T3", "furigana": "日常[にちじょう]の会話[かいわ]なら、もう困[こま]らないくらい話[はな]せます。", "sentence_source": "generated"}, {"text": "毎朝走ることが、今では日常になりました。", "target_word": "日常", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]走[はし]ることが、今[いま]では日常[にちじょう]になりました。", "sentence_source": "generated"}, {"text": "忙しい日常の中でも、家族との時間を大切にしています。", "target_word": "日常", "complexity_tier": "T3", "furigana": "忙[いそが]しい日常[にちじょう]の中[なか]でも、家族[かぞく]との時間[じかん]を大切[たいせつ]にしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日常", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "everyday life: the ordinary, repeated things of daily living", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日常", "is_correct": true, "explanation": "「毎日の生活」の意味で、「日常の小さな出来事」として自然につながる。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、「小さな出来事」を修飾すると意味が通らない。"}, {"text": "容量", "is_correct": false, "explanation": "入る量を表す語で、出来事の性質を述べる言い方にならない。"}, {"text": "機能", "is_correct": false, "explanation": "働きを表す語で、「小さな出来事」の前に置いても意味が通らない。"}], "explanations": {"日常": "「毎日の生活」の意味で、「日常の小さな出来事」として自然につながる。", "体重": "体の重さを表す語で、「小さな出来事」を修飾すると意味が通らない。", "容量": "入る量を表す語で、出来事の性質を述べる言い方にならない。", "機能": "働きを表す語で、「小さな出来事」の前に置いても意味が通らない。"}, "sentence_index": 0, "correct_answer": "日常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎年八月に、この祭りは日常として開かれます。", "explanation": "ここは〈恒例〉（毎年決まって行われる）の意味。日常は毎日の生活を表すので、年に一度の行事には使えない。"}, {"text": "日常の営業時間は、午前九時から午後五時です。", "explanation": "ここは〈通常〉（決まった標準）の意味。日常は毎日の生活を表すので、営業時間の決まりには使えない。"}, {"text": "日常より大変お世話になっております。", "explanation": "ここは〈平素〉（ふだん）という決まった挨拶の言い方。日常はこの挨拶の形では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日常", "is_correct": true, "explanation": "「毎日の生活」の意味で、高校生の暮らしを描く対象として自然。"}, {"text": "学費", "is_correct": false, "explanation": "学校に払うお金を指し、「高校生の〜をやさしく描く」の対象にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "生き物が生きる期間を表し、漫画が描く対象としては不自然。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、「描く」の対象として意味が通らない。"}], "explanations": {"日常": "「毎日の生活」の意味で、高校生の暮らしを描く対象として自然。", "学費": "学校に払うお金を指し、「高校生の〜をやさしく描く」の対象にならない。", "寿命": "生き物が生きる期間を表し、漫画が描く対象としては不自然。", "体温": "体の温度を表す語で、「描く」の対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "日常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地域の日常気温は、十五度ほどです。", "explanation": "ここは〈平均〉の意味。日常は毎日の生活を表し、気温の数値には使わない。"}, {"text": "会議の日常は、来週の火曜日です。", "explanation": "ここは〈日時〉（いつか）の意味。日常は生活の様子を表すので、会議の日程には使えない。"}, {"text": "この店の日常は、カレーです。", "explanation": "ここは〈定番〉（いつも決まって出るもの）の意味。日常は生活そのものを表し、店の看板料理は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "音楽を日常でとり入れています。", "corrected_sentence": "音楽を日常にとり入れています。", "error_description": "「日常で」は誤り。正しくは「日常に」。「取り入れる」は取り込む先を「に」で示すため、「で」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36974, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝、静かな日常を食べています。", "corrected_sentence": "毎朝、静かな日常を送っています。", "error_description": "「食べています」は誤り。正しくは「送っています」。日常は「送る」と組んで、生活の過ごし方を表すため。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正しい。「日本酒の原料」と名詞を結ぶ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すため、「日本酒を原料」では名詞同士の関係が作れない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や帰属を示すため、「日本酒に原料」では成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「日本酒で原料」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正しい。「日本酒の原料」と名詞を結ぶ「の」。", "を": "「を」は動作の対象を示すため、「日本酒を原料」では名詞同士の関係が作れない。", "に": "「に」は到達点や帰属を示すため、「日本酒に原料」では成り立たない。", "で": "「で」は手段や場所を示すため、「日本酒で原料」は意味が通らない。"}, "error_tags": {"を": "対象の格", "に": "帰属・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正しい。「原料を買う」の対象を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すため、「原料と安く買えた」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、「原料から安く買えた」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「原料へ安く買えた」は対象の関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "正しい。「原料を買う」の対象を示す「を」。", "と": "「と」は並列を示すため、「原料と安く買えた」は文が成り立たない。", "から": "「から」は起点を示すため、「原料から安く買えた」は意味が通らない。", "へ": "「へ」は方向を示すため、「原料へ安く買えた」は対象の関係が合わない。"}, "error_tags": {"と": "並列", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かを作るときにもとになるもの。", "primary_collocate": null, "pronunciation": "げんりょう", "ipa": "ɡeɴɾʲoː", "syllable_count": 4, "sentences": [{"text": "この豆腐の原料は、国産の大豆だけです。", "target_word": "原料", "complexity_tier": "T3", "furigana": "この豆腐[とうふ]の原料[げんりょう]は、国産[こくさん]の大豆[だいず]だけです。", "sentence_source": "generated"}, {"text": "日本酒の原料は米と水です。", "target_word": "原料", "complexity_tier": "T3", "furigana": "日本酒[にほんしゅ]の原料[げんりょう]は米[こめ]と水[みず]です。", "sentence_source": "generated"}, {"text": "パンの原料になる小麦が、値上がりしている。", "target_word": "原料", "complexity_tier": "T3", "furigana": "パンの原料[げんりょう]になる小麦[こむぎ]が、値上[ねあ]がりしている。", "sentence_source": "generated"}, {"text": "原料が足りなくて、工場は今週お菓子を作れない。", "target_word": "原料", "complexity_tier": "T3", "furigana": "原料[げんりょう]が足[た]りなくて、工場[こうじょう]は今週[こんしゅう]お菓子[かし]を作[つく]れない。", "sentence_source": "generated"}, {"text": "母は原料にこだわって、手作りのみそを作っている。", "target_word": "原料", "complexity_tier": "T3", "furigana": "母[はは]は原料[げんりょう]にこだわって、手作[てづく]りのみそを作[つく]っている。", "sentence_source": "generated"}, {"text": "ラベルを見ると、このジュースの原料はりんごだと分かる。", "target_word": "原料", "complexity_tier": "T3", "furigana": "ラベルを見[み]ると、このジュースの原料[げんりょう]はりんごだと分[わ]かる。", "sentence_source": "generated"}, {"text": "チョコレートの原料はカカオです。", "target_word": "原料", "complexity_tier": "T3", "furigana": "チョコレートの原料[げんりょう]はカカオです。", "sentence_source": "generated"}, {"text": "原料を安く買えたので、商品の値段も下げられた。", "target_word": "原料", "complexity_tier": "T3", "furigana": "原料[げんりょう]を安[やす]く買[か]えたので、商品[しょうひん]の値段[ねだん]も下[さ]げられた。", "sentence_source": "generated"}, {"text": "紙の原料は木なので、森を守ることも大切だ。", "target_word": "原料", "complexity_tier": "T3", "furigana": "紙[かみ]の原料[げんりょう]は木[き]なので、森[もり]を守[まも]ることも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "店の人は、原料の産地を丁寧に説明してくれた。", "target_word": "原料", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]は、原料[げんりょう]の産地[さんち]を丁寧[ていねい]に説明[せつめい]してくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原料", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "食品や日用品を作るときのもとになる素材", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原料", "is_correct": true, "explanation": "正しい。豆腐を作るもとの材料を表し、「原料は国産の大豆だけ」と説明が成り立つ。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は部屋の種類で、豆腐の材料を表せないので文の意味が通らない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う紙片で、豆腐の材料にならないため文が成り立たない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は人の体の温度で、豆腐の材料を表せないので意味が通らない。"}], "explanations": {"原料": "正しい。豆腐を作るもとの材料を表し、「原料は国産の大豆だけ」と説明が成り立つ。", "寝室": "寝室は部屋の種類で、豆腐の材料を表せないので文の意味が通らない。", "切手": "切手は郵便に使う紙片で、豆腐の材料にならないため文が成り立たない。", "体温": "体温は人の体の温度で、豆腐の材料を表せないので意味が通らない。"}, "sentence_index": 0, "correct_answer": "原料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れた原料を取り替えたので、車がまた動くようになった。", "explanation": "ここは〈部品〉の意味。車を組み立てる部分は「部品」で、「原料」は作るもとの材料なので合わない。"}, {"text": "この工場では毎日、原料を仕上げて店に送っている。", "explanation": "ここは〈製品〉の意味。完成して出荷するものは「製品」で、「原料」は作る前の材料なので合わない。"}, {"text": "この教室は原料がかかるので、毎月払っている。", "explanation": "ここは〈料金〉の意味。お金の支払いには「料金」を使い、「原料」は物の材料なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原料", "is_correct": true, "explanation": "正しい。チョコレートを作るもとの材料を示し、「はカカオです」と説明が成り立つ。"}, {"text": "工具", "is_correct": false, "explanation": "工具は作業に使う道具で、「チョコレートの工具はカカオです」と材料の説明にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、チョコレートの材料を表せないので文の意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学ぶための本で、チョコレートの材料を表せないため文が成り立たない。"}], "explanations": {"原料": "正しい。チョコレートを作るもとの材料を示し、「はカカオです」と説明が成り立つ。", "工具": "工具は作業に使う道具で、「チョコレートの工具はカカオです」と材料の説明にはならない。", "天気": "天気は空の状態で、チョコレートの材料を表せないので文の意味が通らない。", "教科書": "教科書は学ぶための本で、チョコレートの材料を表せないため文が成り立たない。"}, "sentence_index": 6, "correct_answer": "原料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理では、原料として包丁を使う。", "explanation": "ここは〈道具〉の意味。作業に使う器具は「道具」で、「原料」は作る材料なので合わない。"}, {"text": "頭痛がひどいので、原料を飲んだ。", "explanation": "ここは〈薬〉の意味。飲んで体を治すものは「薬」で、「原料」は作るもとの材料なので合わない。"}, {"text": "英語の原料を翻訳して、本にした。", "explanation": "ここは〈原文〉の意味。翻訳のもとになる文章は「原文」で、「原料」は物の材料なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この菓子の原料を、主に砂糖と小麦粉です。", "corrected_sentence": "この菓子の原料は、主に砂糖と小麦粉です。", "error_description": "主題を示す「は」が正しい。「を」は動作の対象を示すので、「です」の文には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36976, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店では、国産の原料を開いてパンを焼いている。", "corrected_sentence": "この店では、国産の原料を使ってパンを焼いている。", "error_description": "原料には「使う」が合う。「開く」は合わないので「使って」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36977, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正しい。「原料を加工する」の対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点を示すため、「原料に加工して」では対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「原料へ加工して」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示すため、「原料より加工して」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正しい。「原料を加工する」の対象を示す「を」。", "に": "「に」は到達点を示すため、「原料に加工して」では対象を示せない。", "へ": "「へ」は方向を示すため、「原料へ加工して」は成り立たない。", "より": "「より」は比較や起点を示すため、「原料より加工して」は文が成り立たない。"}, "error_tags": {"に": "到達点", "へ": "方向", "より": "比較・起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
