INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36977, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "製品を作るための、もとになる材料や物質。", "primary_collocate": null, "pronunciation": "げんりょう", "ipa": "ɡeɴɾʲoː", "syllable_count": 4, "sentences": [{"text": "ペットボトルの原料は、主に石油です。", "target_word": "原料", "complexity_tier": "T3", "furigana": "ペットボトルの原料[げんりょう]は、主[おも]に石油[せきゆ]です。", "sentence_source": "generated"}, {"text": "この工場では、輸入した原料を加工して部品を作る。", "target_word": "原料", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、輸入[ゆにゅう]した原料[げんりょう]を加工[かこう]して部品[ぶひん]を作[つく]る。", "sentence_source": "generated"}, {"text": "原料の価格が上がり、製品の値段も高くなった。", "target_word": "原料", "complexity_tier": "T3", "furigana": "原料[げんりょう]の価格[かかく]が上[あ]がり、製品[せいひん]の値段[ねだん]も高[たか]くなった。", "sentence_source": "generated"}, {"text": "ガラスの原料は主に砂で、高い温度で溶かして作る。", "target_word": "原料", "complexity_tier": "T3", "furigana": "ガラスの原料[げんりょう]は主[おも]に砂[すな]で、高[たか]い温度[おんど]で溶[と]かして作[つく]る。", "sentence_source": "generated"}, {"text": "会社は、リサイクルした紙を原料にして、ノートを作っている。", "target_word": "原料", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、リサイクルした紙[かみ]を原料[げんりょう]にして、ノートを作[つく]っている。", "sentence_source": "generated"}, {"text": "鉄鉱石は鉄の原料として、船で運ばれてくる。", "target_word": "原料", "complexity_tier": "T3", "furigana": "鉄鉱石[てっこうせき]は鉄[てつ]の原料[げんりょう]として、船[ふね]で運[はこ]ばれてくる。", "sentence_source": "generated"}, {"text": "化粧品の原料に、植物から取った成分を使っている。", "target_word": "原料", "complexity_tier": "T3", "furigana": "化粧品[けしょうひん]の原料[げんりょう]に、植物[しょくぶつ]から取[と]った成分[せいぶん]を使[つか]っている。", "sentence_source": "generated"}, {"text": "原料の輸入が止まると、多くの製品が作れなくなる。", "target_word": "原料", "complexity_tier": "T3", "furigana": "原料[げんりょう]の輸入[ゆにゅう]が止[と]まると、多[おお]くの製品[せいひん]が作[つく]れなくなる。", "sentence_source": "generated"}, {"text": "この布は、古い服を原料にして作られた。", "target_word": "原料", "complexity_tier": "T3", "furigana": "この布[ぬの]は、古[ふる]い服[ふく]を原料[げんりょう]にして作[つく]られた。", "sentence_source": "generated"}, {"text": "工場の入り口に、原料を積んだトラックが並んでいた。", "target_word": "原料", "complexity_tier": "T3", "furigana": "工場[こうじょう]の入[い]り口[ぐち]に、原料[げんりょう]を積[つ]んだトラックが並[なら]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原料", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "工場で製品に加工される、もとの材料や物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36977, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原料", "is_correct": true, "explanation": "正しい。ペットボトルのもとになる材料を示し、「主に石油です」と続く。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は部屋の種類で、ペットボトルの材料を表せないので文が成り立たない。"}, {"text": "駅員", "is_correct": false, "explanation": "駅員は仕事をする人で、「ペットボトルの駅員は石油です」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態で、材料を表せないため「天気は主に石油です」は成り立たない。"}], "explanations": {"原料": "正しい。ペットボトルのもとになる材料を示し、「主に石油です」と続く。", "寝室": "寝室は部屋の種類で、ペットボトルの材料を表せないので文が成り立たない。", "駅員": "駅員は仕事をする人で、「ペットボトルの駅員は石油です」は意味が通らない。", "天気": "天気は空の状態で、材料を表せないため「天気は主に石油です」は成り立たない。"}, "sentence_index": 0, "correct_answer": "原料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、原料としてハンマーを使って、部品を作る。", "explanation": "ここは〈道具〉の意味。ハンマーのような器具は「道具」で、「原料」は作るもとの材料なので合わない。"}, {"text": "風邪をひいたので、原料を飲んで寝た。", "explanation": "ここは〈薬〉の意味。飲んで体を治すものは「薬」で、「原料」は作るもとの材料なので合わない。"}, {"text": "英語の原料を翻訳して、本にした。", "explanation": "ここは〈原文〉の意味。翻訳のもとになる文章は「原文」で、「原料」は物の材料なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36977, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原料", "is_correct": true, "explanation": "正しい。化粧品を作る材料を示し、「原料に成分を使う」と自然につながる。"}, {"text": "工具", "is_correct": false, "explanation": "工具は作業の道具で、「化粧品の工具に成分を使う」は材料の関係として成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学習用の本で、化粧品の材料を表せないため文が成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う紙片で、化粧品の材料を表せないため意味が通らない。"}], "explanations": {"原料": "正しい。化粧品を作る材料を示し、「原料に成分を使う」と自然につながる。", "工具": "工具は作業の道具で、「化粧品の工具に成分を使う」は材料の関係として成り立たない。", "教科書": "教科書は学習用の本で、化粧品の材料を表せないため文が成り立たない。", "切手": "切手は郵便に使う紙片で、化粧品の材料を表せないため意味が通らない。"}, "sentence_index": 6, "correct_answer": "原料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い原料を動かして、ベルトをゆっくり回した。", "explanation": "ここは〈機械〉の意味。動かして作業させるものは「機械」で、「原料」は加工される材料なので合わない。"}, {"text": "寒かったので、原料を体にかけて寝た。", "explanation": "ここは〈布団〉の意味。体にかけて寝るものは「布団」で、「原料」は作るもとの材料なので合わない。"}, {"text": "この原料を読んで、試験に備えた。", "explanation": "ここは〈教科書〉の意味。試験のために読むものは「教科書」で、「原料」は作るもとの材料なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36977, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガラスの製造には、砂を原料として食べる。", "corrected_sentence": "ガラスの製造には、砂を原料として使う。", "error_description": "原料には「使う」が合う。「食べる」は合わないので「使う」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36977, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この食品の原料で、国内産の米だけです。", "corrected_sentence": "この食品の原料は、国内産の米だけです。", "error_description": "主題を示す「は」が正しい。「で」は手段や場所を示すので、「です」の文には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正しい。「信頼を得る」の対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示すため、「信頼に得た」は対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「信頼へ得た」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「信頼より得た」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正しい。「信頼を得る」の対象を示す「を」。", "に": "「に」は到達点や相手を示すため、「信頼に得た」は対象を示せない。", "へ": "「へ」は方向を示すため、「信頼へ得た」は成り立たない。", "より": "「より」は比較を示すため、「信頼より得た」は文が成り立たない。"}, "error_tags": {"に": "到達点・相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失う", "is_correct": true, "explanation": "正しい。「収入を得る」の対義にあたる「収入を失う」が成り立つ対義語。"}, {"text": "使う", "is_correct": false, "explanation": "「使う」は得る・失うの対義関係ではなく、この文の対義語にはならない。"}, {"text": "探す", "is_correct": false, "explanation": "「探す」は手に入れようとする行為で、得るの対義語ではないため不適切。"}, {"text": "作る", "is_correct": false, "explanation": "「作る」は生み出す意味で、得るの対義語には当たらない。"}], "correct_answer": "失う", "explanations": {"失う": "正しい。「収入を得る」の対義にあたる「収入を失う」が成り立つ対義語。", "使う": "「使う」は得る・失うの対義関係ではなく、この文の対義語にはならない。", "探す": "「探す」は手に入れようとする行為で、得るの対義語ではないため不適切。", "作る": "「作る」は生み出す意味で、得るの対義語には当たらない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正しい。「支持を得る」の対象を示す「を」。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、動詞「得る」の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「支持と得て」では対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「支持で得る」は対象を示す形として不自然で、文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正しい。「支持を得る」の対象を示す「を」。", "の": "「の」は名詞を修飾するため、動詞「得る」の対象にはならない。", "と": "「と」は並列や相手を示すため、「支持と得て」では対象を示せない。", "で": "「で」は手段を示すが、「支持で得る」は対象を示す形として不自然で、文の意味が通らない。"}, "error_tags": {"の": "修飾", "と": "並列", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失う", "is_correct": true, "explanation": "正しい。「学びを得る」の対義にあたる「学びを失う」が成り立つ対義語。"}, {"text": "残す", "is_correct": false, "explanation": "「残す」は後に留める意味で、得る・失うの対義関係にはない。"}, {"text": "増やす", "is_correct": false, "explanation": "「増やす」は数を多くする意味で、得るの対義語とはならない。"}, {"text": "描く", "is_correct": false, "explanation": "「描く」は絵や文章を表す意味で、得るの対義語ではない。"}], "correct_answer": "失う", "explanations": {"失う": "正しい。「学びを得る」の対義にあたる「学びを失う」が成り立つ対義語。", "残す": "「残す」は後に留める意味で、得る・失うの対義関係にはない。", "増やす": "「増やす」は数を多くする意味で、得るの対義語とはならない。", "描く": "「描く」は絵や文章を表す意味で、得るの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを自分のものとして手に入れる。", "primary_collocate": null, "pronunciation": "える", "ipa": "eɾɯ", "syllable_count": 2, "sentences": [{"text": "先生の許可を得てから、教室で写真を撮りました。", "target_word": "得て", "complexity_tier": "T3", "furigana": "先生[せんせい]の許可[きょか]を得[え]てから、教室[きょうしつ]で写真[しゃしん]を撮[と]りました。", "sentence_source": "generated"}, {"text": "彼は長い努力の結果、みんなの信頼を得た。", "target_word": "得た", "complexity_tier": "T3", "furigana": "彼[かれ]は長[なが]い努力[どりょく]の結果[けっか]、みんなの信頼[しんらい]を得[え]た。", "sentence_source": "generated"}, {"text": "新聞やネットから情報を得る人が多い。", "target_word": "得る", "complexity_tier": "T3", "furigana": "新聞[しんぶん]やネットから情報[じょうほう]を得[え]る人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "アルバイトをして収入を得ないと、学費が払えない。", "target_word": "得ない", "complexity_tier": "T3", "furigana": "アルバイトをして収入[しゅうにゅう]を得[え]ないと、学費[がくひ]が払[はら]えない。", "sentence_source": "generated"}, {"text": "留学で多くの経験を得たので、将来の仕事に役立つだろう。", "target_word": "得た", "complexity_tier": "T3", "furigana": "留学[りゅうがく]で多[おお]くの経験[けいけん]を得[え]たので、将来[しょうらい]の仕事[しごと]に役立[やくだ]つだろう。", "sentence_source": "generated"}, {"text": "会社は新しい商品で大きな利益を得た。", "target_word": "得た", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい商品[しょうひん]で大[おお]きな利益[りえき]を得[え]た。", "sentence_source": "generated"}, {"text": "親の同意を得ないで契約することはできません。", "target_word": "得ない", "complexity_tier": "T3", "furigana": "親[おや]の同意[どうい]を得[え]ないで契約[けいやく]することはできません。", "sentence_source": "generated"}, {"text": "市長は多くの市民の支持を得て、選挙に勝った。", "target_word": "得て", "complexity_tier": "T3", "furigana": "市長[しちょう]は多[おお]くの市民[しみん]の支持[しじ]を得[え]て、選挙[せんきょ]に勝[か]った。", "sentence_source": "generated"}, {"text": "試験に合格して、医者の資格を得ることができた。", "target_word": "得る", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]して、医者[いしゃ]の資格[しかく]を得[え]ることができた。", "sentence_source": "generated"}, {"text": "失敗から学びを得るために、毎日日記を書いている。", "target_word": "得る", "complexity_tier": "T3", "furigana": "失敗[しっぱい]から学[まな]びを得[え]るために、毎日[まいにち]日記[にっき]を書[か]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "得る", "label": "基本形"}, {"form": "得ます", "label": "丁寧形"}, {"form": "得た", "label": "過去形"}, {"form": "得て", "label": "て形"}, {"form": "得ない", "label": "否定形"}, {"form": "得れば", "label": "仮定形"}, {"form": "得よう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "許可・信頼・情報・利益などを自分のものとして手に入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得て", "is_correct": true, "explanation": "正しい。「得てから」で前の動作を示し、「許可を得てから写真を撮った」と続く。"}, {"text": "得れば", "is_correct": false, "explanation": "仮定形「得れば」は「てから」の前に置けず、文が続かない。"}, {"text": "得よう", "is_correct": false, "explanation": "意志形「得よう」は「てから」の前に置けず、文が続かない。"}, {"text": "得ず", "is_correct": false, "explanation": "「得ず」は打ち消しの形で、「てから」にはつながらず文が成り立たない。"}], "explanations": {"得て": "正しい。「得てから」で前の動作を示し、「許可を得てから写真を撮った」と続く。", "得れば": "仮定形「得れば」は「てから」の前に置けず、文が続かない。", "得よう": "意志形「得よう」は「てから」の前に置けず、文が続かない。", "得ず": "「得ず」は打ち消しの形で、「てから」にはつながらず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "得て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな声を得て、みんなを驚かせた。", "explanation": "ここは〈出す〉の意味。声を発することには「出す」を使い、「得る」は手に入れる意味なので合わない。"}, {"text": "大雨を得て、服がびしょぬれになった。", "explanation": "ここは〈浴びる〉の意味。雨を身に受けることには「浴びる」を使い、「得る」は合わない。"}, {"text": "大きな音を得て、ドアが閉まった。", "explanation": "ここは〈立てる〉の意味。音を発することには「立てる」を使い、「得る」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得ない", "is_correct": true, "explanation": "正しい。打ち消しの「得ない」に「で」がつながり、「同意を得ないで」となる。"}, {"text": "得る", "is_correct": false, "explanation": "辞書形「得る」は「で」に続かず、「同意を得るで」は文が成り立たない。"}, {"text": "得た", "is_correct": false, "explanation": "過去形「得た」は「で」に続かず、「同意を得たで」は文が成り立たない。"}, {"text": "得ます", "is_correct": false, "explanation": "丁寧形「得ます」は「で」に続かず、「得ますで」は文が成り立たない。"}], "explanations": {"得ない": "正しい。打ち消しの「得ない」に「で」がつながり、「同意を得ないで」となる。", "得る": "辞書形「得る」は「で」に続かず、「同意を得るで」は文が成り立たない。", "得た": "過去形「得た」は「で」に続かず、「同意を得たで」は文が成り立たない。", "得ます": "丁寧形「得ます」は「で」に続かず、「得ますで」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "得ない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑さで汗を得て、服がぬれた。", "explanation": "ここは〈かく〉の意味。汗が出ることには「かく」を使い、「得る」は合わない。"}, {"text": "朝ご飯を得て、学校へ出かけた。", "explanation": "ここは〈食べる〉の意味。食事をすることには「食べる」を使い、「得る」は合わない。"}, {"text": "毎日、日記を得るために、ペンを持つ。", "explanation": "ここは〈書く〉の意味。文章を作ることには「書く」を使い、「得る」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の許可を得に、教室で写真を撮る。", "corrected_sentence": "先生の許可を得て、教室で写真を撮る。", "error_description": "「得て」のて形が正しい。「得に」は接続が成り立たず、文が続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "得た", "is_correct": true, "explanation": "正しい。過去形で「信頼を得た」と完了した動作を示す。"}, {"text": "得ない", "is_correct": false, "explanation": "打ち消し形にすると「信頼を得ない」となり、結果を述べる文の意味と合わない。"}, {"text": "得て", "is_correct": false, "explanation": "て形は文を言い切れず、「信頼を得て。」では文が終わらない。"}, {"text": "得れば", "is_correct": false, "explanation": "仮定形は条件を示すため、結果を述べるこの文と合わない。"}], "correct_form": "得た", "base_form": "得る", "form_label": "過去形", "sentence_index": 1, "explanations": {"得た": "正しい。過去形で「信頼を得た」と完了した動作を示す。", "得ない": "打ち消し形にすると「信頼を得ない」となり、結果を述べる文の意味と合わない。", "得て": "て形は文を言い切れず、「信頼を得て。」では文が終わらない。", "得れば": "仮定形は条件を示すため、結果を述べるこの文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36978, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学を卒業して、教員免許に得た。", "corrected_sentence": "大学を卒業して、教員免許を得た。", "error_description": "「得る」の対象は「を」で示すので「教員免許を得た」が正しい。「に」では対象を示せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "得て", "is_correct": true, "explanation": "正しい。「得て、」で後の「選挙に勝った」へ続くて形。"}, {"text": "得る", "is_correct": false, "explanation": "辞書形は「、」の前で文の流れが続かず、「得る、選挙に勝った」は成り立たない。"}, {"text": "得よう", "is_correct": false, "explanation": "意志形は言い切りの形で、「、」で続けると文の意味が成り立たない。"}, {"text": "得ます", "is_correct": false, "explanation": "丁寧形は「得ます、」と続かず、文の流れが成り立たない。"}], "correct_form": "得て", "base_form": "得る", "form_label": "て形", "sentence_index": 7, "explanations": {"得て": "正しい。「得て、」で後の「選挙に勝った」へ続くて形。", "得る": "辞書形は「、」の前で文の流れが続かず、「得る、選挙に勝った」は成り立たない。", "得よう": "意志形は言い切りの形で、「、」で続けると文の意味が成り立たない。", "得ます": "丁寧形は「得ます、」と続かず、文の流れが成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「油脂が多い」は主語を示す基本の形。"}, {"text": "を", "is_correct": false, "explanation": "「多い」は「〜が多い」の形をとるので、「油脂を多い」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「油脂に多い」では場所や方向にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「油脂で多い」では手段や場所にならず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「油脂が多い」は主語を示す基本の形。", "を": "「多い」は「〜が多い」の形をとるので、「油脂を多い」は成り立たない。", "に": "「油脂に多い」では場所や方向にならず、文が成り立たない。", "で": "「油脂で多い」では手段や場所にならず、意味が通らない。"}, "error_tags": {"を": "目的格", "に": "位置", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。「油脂から作られる」で原料を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すため、「油脂と作られる」は主語がなく文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を示すので、原料を表す文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「油脂の作られる」は名詞を修飾する形にしかならず、文の述語が立たない。"}], "correct_answer": "から", "explanations": {"から": "正解。「油脂から作られる」で原料を示す。", "と": "「と」は並列を示すため、「油脂と作られる」は主語がなく文が成り立たない。", "へ": "「へ」は行き先を示すので、原料を表す文には合わない。", "の": "「油脂の作られる」は名詞を修飾する形にしかならず、文の述語が立たない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物や植物からとれる、水に溶けず、べたべたするもの。", "primary_collocate": null, "pronunciation": "ゆし", "ipa": "jɯɕi", "syllable_count": 2, "sentences": [{"text": "油脂は水に溶けないので、皿を洗うときは洗剤が必要だ。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]は水[みず]に溶[と]けないので、皿[さら]を洗[あら]うときは洗剤[せんざい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "揚げ物は油脂が多いので、食べすぎると太りやすい。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "揚[あ]げ物[もの]は油脂[ゆし]が多[おお]いので、食[た]べすぎると太[ふと]りやすい。", "sentence_source": "generated"}, {"text": "ごまや菜種などの植物から油脂を搾り取る。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "ごまや菜種[なたね]などの植物[しょくぶつ]から油脂[ゆし]を搾[しぼ]り取[と]る。", "sentence_source": "generated"}, {"text": "洗剤は、食器についた油脂を落とすために使う。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "洗剤[せんざい]は、食器[しょっき]についた油脂[ゆし]を落[お]とすために使[つか]う。", "sentence_source": "generated"}, {"text": "この牛乳は、油脂を減らしてあるので、あっさりしている。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "この牛乳[ぎゅうにゅう]は、油脂[ゆし]を減[へ]らしてあるので、あっさりしている。", "sentence_source": "generated"}, {"text": "油脂は水と混ざらないので、スープの表面に浮かぶ。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]は水[みず]と混[ま]ざらないので、スープの表面[ひょうめん]に浮[う]かぶ。", "sentence_source": "generated"}, {"text": "油脂のとりすぎは健康によくないと、医者に言われた。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]のとりすぎは健康[けんこう]によくないと、医者[いしゃ]に言[い]われた。", "sentence_source": "generated"}, {"text": "石けんは、動物や植物の油脂から作られる。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "石[せっ]けんは、動物[どうぶつ]や植物[しょくぶつ]の油脂[ゆし]から作[つく]られる。", "sentence_source": "generated"}, {"text": "台所の壁に油脂がべたべたとついて、掃除が大変だった。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "台所[だいどころ]の壁[かべ]に油脂[ゆし]がべたべたとついて、掃除[そうじ]が大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "チョコレートには、カカオから取った油脂が含まれている。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "チョコレートには、カカオから取[と]った油脂[ゆし]が含[ふく]まれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "油脂", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "料理や食品・石けんなど身近な場面で出てくる、水と混ざらないべたつく油や脂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正解。油脂は水と混ざらないので、皿の油汚れには洗剤が必要になる。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は水によく溶けるので、「水に溶けない」の主語にならない。"}, {"text": "食塩", "is_correct": false, "explanation": "食塩も水に溶けるので、「水に溶けないので」という理由と合わない。"}, {"text": "醤油", "is_correct": false, "explanation": "醤油は水と混ざるので、「水に溶けない」の主語にできない。"}], "explanations": {"油脂": "正解。油脂は水と混ざらないので、皿の油汚れには洗剤が必要になる。", "砂糖": "砂糖は水によく溶けるので、「水に溶けない」の主語にならない。", "食塩": "食塩も水に溶けるので、「水に溶けないので」という理由と合わない。", "醤油": "醤油は水と混ざるので、「水に溶けない」の主語にできない。"}, "sentence_index": 0, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "緊張で、額に油脂汗がにじんだ。", "explanation": "「脂汗」（緊張や暑さでにじむ汗）の「脂」を「油脂」に入れ替えた。脂汗は汗の様子を表す語で、食べ物からとれる油脂とは結びつかない。"}, {"text": "このサーモンは油脂がのっていて、とてもおいしい。", "explanation": "「脂がのる」の「脂」を「油脂」に入れ替えた。油脂はこの慣用句では使わず、今回の意味とも結びつかない。"}, {"text": "遅刻を繰り返す後輩が、部長に油脂を絞られた。", "explanation": "「油を絞る」（厳しく叱る）の「油」を「油脂」に入れ替えた。油脂は食べ物や植物からとれる成分で、この慣用句には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正解。油脂のとりすぎが健康によくないという文になる。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は食べ物ではないので、「とりすぎ」の対象にならない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は口にする物ではないので、「とりすぎ」と合わない。"}, {"text": "食器", "is_correct": false, "explanation": "食器をとりすぎるという言い方は成り立たず、文が意味をなさない。"}], "explanations": {"油脂": "正解。油脂のとりすぎが健康によくないという文になる。", "包丁": "包丁は食べ物ではないので、「とりすぎ」の対象にならない。", "鍋": "鍋は口にする物ではないので、「とりすぎ」と合わない。", "食器": "食器をとりすぎるという言い方は成り立たず、文が意味をなさない。"}, "sentence_index": 6, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "そのベテラン選手は今、油脂が乗っていて絶好調だ。", "explanation": "「脂が乗る」（調子がいい）の「脂」を「油脂」に入れ替えた。油脂は食べ物の成分で、人の調子を表すこの言い方には使わない。"}, {"text": "小麦粉を入れる前に、油脂をふるっておく。", "explanation": "「粉をふるう」の「粉」を入れ替えた。ふるうのは粉の作業で、油脂は液体や固体の脂なのでふるう対象にならない。"}, {"text": "花瓶に油脂を挿して、きれいに飾る。", "explanation": "ここは〈生け花〉の意味。油脂は花瓶に生けるものではないので、この文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "フライパンに油脂をこびりついて、洗うのに時間がかかった。", "corrected_sentence": "フライパンに油脂がこびりついて、洗うのに時間がかかった。", "error_description": "「こびりつく」は「〜が」で主語を示す動詞。「油脂を」は誤りで、正しくは「油脂が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36980, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗剤で皿の油脂を溶く。", "corrected_sentence": "洗剤で皿の油脂を落とす。", "error_description": "「溶く」は粉や卵などを液に混ぜる動詞。汚れや脂を取り除く意味なら「落とす」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「油脂は」で文の主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「油脂を」では目的語になり、「並ぶ栄養素だ」と続く文の主題にならない。"}, {"text": "に", "is_correct": false, "explanation": "「油脂に」では場所や方向になり、主題の文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「油脂で」では手段や材料になり、栄養素の主題としては成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「油脂は」で文の主題を示す。", "を": "「油脂を」では目的語になり、「並ぶ栄養素だ」と続く文の主題にならない。", "に": "「油脂に」では場所や方向になり、主題の文が成り立たない。", "で": "「油脂で」では手段や材料になり、栄養素の主題としては成り立たない。"}, "error_tags": {"を": "目的格", "に": "位置・方向", "で": "手段・材料"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「油脂が多くたまる」の形で、油脂が主語になる。"}, {"text": "と", "is_correct": false, "explanation": "「油脂とたまりすぎる」では並列や相手を表す形になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「油脂をたまりすぎると」では、自動詞「たまる」に目的語の「を」は付かず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「油脂からたまりすぎる」では起点の形になり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「油脂が多くたまる」の形で、油脂が主語になる。", "と": "「油脂とたまりすぎる」では並列や相手を表す形になり、文が成り立たない。", "を": "「油脂をたまりすぎると」では、自動詞「たまる」に目的語の「を」は付かず、文が成り立たない。", "から": "「油脂からたまりすぎる」では起点の形になり、意味が通らない。"}, "error_tags": {"と": "並列・相手", "を": "自動詞に目的語不可", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物の体内に含まれる、水に溶けにくい有機物の総称。常温で固体のものを脂肪、液体のものを油という。", "primary_collocate": null, "pronunciation": "ゆし", "ipa": "jɯɕi", "syllable_count": 2, "sentences": [{"text": "油脂は、常温で固体のものを脂肪、液体のものを油という。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]は、常温[じょうおん]で固体[こたい]のものを脂肪[しぼう]、液体[えきたい]のものを油[あぶら]という。", "sentence_source": "generated"}, {"text": "油脂は、炭水化物やたんぱく質と並ぶ大切な栄養素だ。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]は、炭水化物[たんすいかぶつ]やたんぱく質[しつ]と並[なら]ぶ大切[たいせつ]な栄養素[えいようそ]だ。", "sentence_source": "generated"}, {"text": "体内に蓄えられた油脂は、エネルギー不足のときに使われる。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "体内[たいない]に蓄[たくわ]えられた油脂[ゆし]は、エネルギー不足[ぶそく]のときに使[つか]われる。", "sentence_source": "generated"}, {"text": "動物は、皮の下に油脂をためて寒さから体を守る。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "動物[どうぶつ]は、皮[かわ]の下[した]に油脂[ゆし]をためて寒[さむ]さから体[からだ]を守[まも]る。", "sentence_source": "generated"}, {"text": "油脂には、水に溶けにくいという性質がある。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]には、水[みず]に溶[と]けにくいという性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "理科の授業で、種子に含まれる油脂を調べる実験をした。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、種子[しゅし]に含[ふく]まれる油脂[ゆし]を調[しら]べる実験[じっけん]をした。", "sentence_source": "generated"}, {"text": "油脂1グラムは、約9キロカロリーのエネルギーを出す。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "油脂[ゆし]1グラムは、約[やく]9キロカロリーのエネルギーを出[だ]す。", "sentence_source": "generated"}, {"text": "肝臓に油脂がたまりすぎると、病気の原因になる。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "肝臓[かんぞう]に油脂[ゆし]がたまりすぎると、病気[びょうき]の原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "ナッツ類は油脂を多く含むが、体に必要な成分も多い。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "ナッツ類[るい]は油脂[ゆし]を多[おお]く含[ふく]むが、体[からだ]に必要[ひつよう]な成分[せいぶん]も多[おお]い。", "sentence_source": "generated"}, {"text": "人の体は、食べた油脂を分解して吸収する。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "人[ひと]の体[からだ]は、食[た]べた油脂[ゆし]を分解[ぶんかい]して吸収[きゅうしゅう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "油脂", "label": "基本形"}], "register": "formal", "sense_fingerprint": "栄養・生物の体の働きを説明する、脂肪と油をまとめた学術的な呼び名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正解。脂肪と油をまとめた呼び名なので、定義文の主語になる。"}, {"text": "炭水化物", "is_correct": false, "explanation": "炭水化物は脂肪や油の区分ではないので、定義文の主語として合わない。"}, {"text": "たんぱく質", "is_correct": false, "explanation": "たんぱく質は脂肪や油とは別の栄養素なので、この定義文には入らない。"}, {"text": "ビタミン", "is_correct": false, "explanation": "ビタミンは定義の対象である脂肪・油とは別の栄養素なので、この文に合わない。"}], "explanations": {"油脂": "正解。脂肪と油をまとめた呼び名なので、定義文の主語になる。", "炭水化物": "炭水化物は脂肪や油の区分ではないので、定義文の主語として合わない。", "たんぱく質": "たんぱく質は脂肪や油とは別の栄養素なので、この定義文には入らない。", "ビタミン": "ビタミンは定義の対象である脂肪・油とは別の栄養素なので、この文に合わない。"}, "sentence_index": 0, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい部長は、油脂が乗っていて仕事がはかどっている。", "explanation": "「脂が乗る」（調子が出る）の「脂」を「油脂」に入れ替えた。油脂は食べ物や体の成分で、仕事の調子を表すこの言い方には使わない。"}, {"text": "彼は冬の間、油脂絵で海の風景を描いた。", "explanation": "「油絵」（油で描いた絵）の「油」を「油脂」に入れ替えた。油脂絵という言い方はなく、絵の具の材料を指す語ではない。"}, {"text": "面接の途中、額に油脂汗がにじんで焦った。", "explanation": "「脂汗」（緊張でにじむ汗）の「脂」を「油脂」に入れ替えた。脂汗は汗の様子を表す語で、油脂とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正解。油脂は1グラムあたり約9キロカロリーのエネルギーを出す。"}, {"text": "水", "is_correct": false, "explanation": "水はエネルギーを出さないので、この文の主語にならない。"}, {"text": "空気", "is_correct": false, "explanation": "空気はエネルギー源となる栄養素ではないので、この文に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂はエネルギー源ではないので、カロリーの文と合わない。"}], "explanations": {"油脂": "正解。油脂は1グラムあたり約9キロカロリーのエネルギーを出す。", "水": "水はエネルギーを出さないので、この文の主語にならない。", "空気": "空気はエネルギー源となる栄養素ではないので、この文に合わない。", "砂": "砂はエネルギー源ではないので、カロリーの文と合わない。"}, "sentence_index": 6, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この牛肉は油脂身が少なく、さっぱりしている。", "explanation": "「脂身」（肉の脂の部分）の「脂」を「油脂」に入れ替えた。脂身は肉の部位を指す語で、油脂とは言い換えない。"}, {"text": "その国は、大きな油脂田を見つけて沸いた。", "explanation": "「油田」（石油の採れる場所）の「油」を「油脂」に入れ替えた。油脂は食べ物や体の成分で、地中から採る資源を指す語ではない。"}, {"text": "仕事をさぼった部下が、油脂を絞られた。", "explanation": "「油を絞る」（厳しく叱る）の「油」を入れ替えた。油脂は食品や体の成分を指すので、この慣用句には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "動物の体では、油脂をエネルギーとして燃える。", "corrected_sentence": "動物の体では、油脂がエネルギーとして燃える。", "error_description": "「燃える」は自動詞なので、主語の油脂は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36981, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体は、食べた油脂の分解してから吸収する。", "corrected_sentence": "体は、食べた油脂をいったん分解してから吸収する。", "error_description": "「分解する」は他動詞なので、目的語の油脂は「の」ではなく「を」で示す。「の分解して」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「残渣」を話題として示し、「捨てます」と続けて文の主題にする。"}, {"text": "に", "is_correct": false, "explanation": "「排水口に」のような位置を示す「に」。「残渣に、〜捨てます」では主題にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」。「残渣で、〜捨てます」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「残渣へ、〜捨てます」は対象を示せず不自然。"}], "correct_answer": "は", "explanations": {"は": "「残渣」を話題として示し、「捨てます」と続けて文の主題にする。", "に": "「排水口に」のような位置を示す「に」。「残渣に、〜捨てます」では主題にならない。", "で": "手段を示す「で」。「残渣で、〜捨てます」は意味が通らない。", "へ": "方向を示す「へ」。「残渣へ、〜捨てます」は対象を示せず不自然。"}, "error_tags": {"に": "場所・位置", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "残渣を「牛のえさにする」対象として示す目的語の「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「残渣へ牛のえさにする」では対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す「より」。ここでは文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。「残渣と牛のえさにする」では対象にならない。"}], "correct_answer": "を", "explanations": {"を": "残渣を「牛のえさにする」対象として示す目的語の「を」。", "へ": "方向を示す「へ」。「残渣へ牛のえさにする」では対象を示せない。", "より": "比較の基準を示す「より」。ここでは文が成立しない。", "と": "並列や相手を示す「と」。「残渣と牛のえさにする」では対象にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物のあとに残った、いらないもの。", "primary_collocate": null, "pronunciation": "ざんさ", "ipa": "dzansa", "syllable_count": 3, "sentences": [{"text": "ジュースを作ったあとに残る果物の残渣を、堆肥にしています。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "ジュースを作[つく]ったあとに残[のこ]る果物[くだもの]の残渣[ざんさ]を、堆肥[たいひ]にしています。", "sentence_source": "generated"}, {"text": "排水口にたまった残渣は、ネットで受けてから捨てます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "排水口[はいすいこう]にたまった残渣[ざんさ]は、ネットで受[う]けてから捨[す]てます。", "sentence_source": "generated"}, {"text": "コーヒーの残渣は、冷蔵庫のにおいを消すのに使えます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "コーヒーの残渣[ざんさ]は、冷蔵庫[れいぞうこ]のにおいを消[け]すのに使[つか]えます。", "sentence_source": "generated"}, {"text": "豆乳を作るときに出る残渣が、おからです。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "豆乳[とうにゅう]を作[つく]るときに出[で]る残渣[ざんさ]が、おからです。", "sentence_source": "generated"}, {"text": "調理場から出る残渣は、毎日まとめて捨てられます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "調理場[ちょうりば]から出[で]る残渣[ざんさ]は、毎日[まいにち]まとめて捨[す]てられます。", "sentence_source": "generated"}, {"text": "食べ物の残渣を流すと、台所の排水管がつまります。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の残渣[ざんさ]を流[なが]すと、台所[だいどころ]の排水管[はいすいかん]がつまります。", "sentence_source": "generated"}, {"text": "野菜をすりつぶしたあとの残渣も、スープに入れて使えます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "野菜[やさい]をすりつぶしたあとの残渣[ざんさ]も、スープに入[い]れて使[つか]えます。", "sentence_source": "generated"}, {"text": "この店では、野菜の残渣を牛のえさにしています。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "この店[みせ]では、野菜[やさい]の残渣[ざんさ]を牛[うし]のえさにしています。", "sentence_source": "generated"}, {"text": "食べ物の残渣が多いと、ごみ箱に虫が来やすくなります。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の残渣[ざんさ]が多[おお]いと、ごみ箱[ばこ]に虫[むし]が来[き]やすくなります。", "sentence_source": "generated"}, {"text": "給食の残渣の量を、毎日重さで記録しています。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]の残渣[ざんさ]の量[りょう]を、毎日[まいにち]重[おも]さで記録[きろく]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残渣", "label": "基本形"}], "register": "written", "sense_fingerprint": "food residue: unneeded leftovers such as pulp, grounds or scraps remaining after food is made or eaten", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残渣", "is_correct": true, "explanation": "搾ったあとに残るかすを指し、堆肥にする対象として自然。"}, {"text": "香り", "is_correct": false, "explanation": "においを表す語で、堆肥にできる物ではない。"}, {"text": "糖分", "is_correct": false, "explanation": "成分の一種で、物として堆肥にする対象にはならない。"}, {"text": "重さ", "is_correct": false, "explanation": "物の量の性質で、「果物の重さを堆肥にする」とは言わない。"}], "explanations": {"残渣": "搾ったあとに残るかすを指し、堆肥にする対象として自然。", "香り": "においを表す語で、堆肥にできる物ではない。", "糖分": "成分の一種で、物として堆肥にする対象にはならない。", "重さ": "物の量の性質で、「果物の重さを堆肥にする」とは言わない。"}, "sentence_index": 0, "correct_answer": "残渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故現場には、車の残渣が散らばっていました。", "explanation": "ここは〈残骸〉（壊れた物の残り）の意味。残渣は食品などのかすを指し、車の残がいには使わない。"}, {"text": "口座の残渣が、月末に足りなくなりました。", "explanation": "ここは〈残高〉（口座にある金額）の意味。残渣は物質のかすで、金額には使えない。"}, {"text": "予測値と実測値の残渣を計算します。", "explanation": "ここは〈残差〉（予測と実測のずれ）の意味。残渣はかすの意味で、数値の差には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残渣", "is_correct": true, "explanation": "すりつぶしたあとに残るかすで、スープに入れて使う対象として自然。"}, {"text": "食器", "is_correct": false, "explanation": "料理に使う器で、すりつぶしたあとに残る物ではない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表す語で、食材として残るものではない。"}, {"text": "洗剤", "is_correct": false, "explanation": "汚れを落とす液体で、スープに入れて使う物ではない。"}], "explanations": {"残渣": "すりつぶしたあとに残るかすで、スープに入れて使う対象として自然。", "食器": "料理に使う器で、すりつぶしたあとに残る物ではない。", "機械": "装置を表す語で、食材として残るものではない。", "洗剤": "汚れを落とす液体で、スープに入れて使う物ではない。"}, "sentence_index": 6, "correct_answer": "残渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電力の残渣を売ります。", "explanation": "ここは〈余剰〉（使い切れずに余った分）の意味。残渣は食品などのかすで、電力には使わない。"}, {"text": "スマホの残渣が少なくなりました。", "explanation": "ここは〈残量〉（まだ残っている量）の意味。残渣は使い終えたあとのかすで、充電の残りには使わない。"}, {"text": "敗れた組織の残渣が、山に隠れていました。", "explanation": "ここは〈残党〉（逃れた仲間）の意味。残渣は物質のかすを指し、人の集団には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "豆を煮出したあとの残渣が、庭の肥料に使います。", "corrected_sentence": "豆を煮出したあとの残渣を、庭の肥料に使います。", "error_description": "「残渣が」は誤り。正しくは「残渣を」。「使う」は使う物を「を」で示す他動詞なので、主語の「が」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36982, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下ごしらえで、野菜の残渣が大量に食べます。", "corrected_sentence": "下ごしらえで、野菜の残渣が大量に出ます。", "error_description": "「食べます」は誤り。正しくは「出ます」。残渣は食べる物ではなく、下ごしらえの結果として出るものなので、「出る」と組む。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「残渣」を話題として示し、「運ばれます」と続けて文の主題にする。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。受け身の「運ばれます」の主語にはできず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」。「残渣で、運ばれます」は主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。文の主題として続かず、文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "「残渣」を話題として示し、「運ばれます」と続けて文の主題にする。", "を": "目的語の「を」。受け身の「運ばれます」の主語にはできず不自然。", "で": "手段や場所を示す「で」。「残渣で、運ばれます」は主語にならない。", "の": "連体修飾の「の」。文の主題として続かず、文が成立しない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "残渣を主語として示し、「残ります」と続ける。"}, {"text": "に", "is_correct": false, "explanation": "場所や位置を示す「に」。「残渣に残ります」とは続かない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。「残渣と残ります」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「残渣へ残ります」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "残渣を主語として示し、「残ります」と続ける。", "に": "場所や位置を示す「に」。「残渣に残ります」とは続かない。", "と": "並列や相手を示す「と」。「残渣と残ります」では成り立たない。", "へ": "方向を示す「へ」。「残渣へ残ります」は意味が通らない。"}, "error_tags": {"に": "場所・位置", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かを処理したあとに残る、不要な物質や部分。", "primary_collocate": null, "pronunciation": "ざんさ", "ipa": "dzansa", "syllable_count": 3, "sentences": [{"text": "ろ過したあと、紙に残った残渣を乾かして重さをはかりました。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "ろ過[かろ]したあと、紙[かみ]に残[のこ]った残渣[ざんさ]を乾[かわ]かして重[おも]さをはかりました。", "sentence_source": "generated"}, {"text": "焼却炉から出る残渣は、特別な場所に運ばれます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "焼却炉[しょうきゃくろ]から出[で]る残渣[ざんさ]は、特別[とくべつ]な場所[ばしょ]に運[はこ]ばれます。", "sentence_source": "generated"}, {"text": "実験のあとの残渣は、そのまま流さず容器に集めてください。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "実験[じっけん]のあとの残渣[ざんさ]は、そのまま流[なが]さず容器[ようき]に集[あつ]めてください。", "sentence_source": "generated"}, {"text": "薬の成分を取り出したあとの残渣は、廃棄されます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "薬[くすり]の成分[せいぶん]を取[と]り出[だ]したあとの残渣[ざんさ]は、廃棄[はいき]されます。", "sentence_source": "generated"}, {"text": "溶かしても残る残渣があるときは、もう一度ろ過します。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "溶[と]かしても残[のこ]る残渣[ざんさ]があるときは、もう一度[いちど]ろ過[か]します。", "sentence_source": "generated"}, {"text": "工場では、金属を精錬したあとの残渣を再利用しています。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、金属[きんぞく]を精錬[せいれん]したあとの残渣[ざんさ]を再利用[さいりよう]しています。", "sentence_source": "generated"}, {"text": "検査では、フィルターに残った残渣の成分を調べます。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "検査[けんさ]では、フィルターに残[のこ]った残渣[ざんさ]の成分[せいぶん]を調[しら]べます。", "sentence_source": "generated"}, {"text": "石油の精製の過程で、重くて黒い残渣が残ります。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "石油[せきゆ]の精製[せいせい]の過程[かてい]で、重[おも]くて黒[くろ]い残渣[ざんさ]が残[のこ]ります。", "sentence_source": "generated"}, {"text": "機械を洗うと、中に残っていた残渣が水に混ざって出てきました。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "機械[きかい]を洗[あら]うと、中[なか]に残[のこ]っていた残渣[ざんさ]が水[みず]に混[ま]ざって出[で]てきました。", "sentence_source": "generated"}, {"text": "残渣の処理には費用がかかるため、量を減らす工夫が必要です。", "target_word": "残渣", "complexity_tier": "T3", "furigana": "残渣[ざんさ]の処理[しょり]には費用[ひよう]がかかるため、量[りょう]を減[へ]らす工夫[くふう]が必要[ひつよう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残渣", "label": "基本形"}], "register": "written", "sense_fingerprint": "process residue: unneeded matter left after filtering, burning, extracting or refining", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残渣", "is_correct": true, "explanation": "ろ過したあとに紙に残るかすで、乾かして重さをはかる対象として自然。"}, {"text": "教科書", "is_correct": false, "explanation": "紙に残って乾かし、重さをはかる対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態を表す語で、紙に残って乾かす対象ではない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表す語で、ろ過したあとに紙に残る物ではない。"}], "explanations": {"残渣": "ろ過したあとに紙に残るかすで、乾かして重さをはかる対象として自然。", "教科書": "紙に残って乾かし、重さをはかる対象にはならない。", "天気": "空の状態を表す語で、紙に残って乾かす対象ではない。", "機械": "装置を表す語で、ろ過したあとに紙に残る物ではない。"}, "sentence_index": 0, "correct_answer": "残渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "完成した残渣は、出荷されます。", "explanation": "ここは〈製品〉の意味。残渣は不要物なので、完成品として出荷する文にはならない。"}, {"text": "予算の残渣は、次の年に繰り越します。", "explanation": "ここは〈残余〉（使い残しの予算）の意味。残渣は物質のかすで、お金の余りには使わない。"}, {"text": "強い光を見たあとも、残渣が目に残っています。", "explanation": "ここは〈残像〉（見たものが消えたあとに見える姿）の意味。残渣は物質のかすで、視覚の残りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残渣", "is_correct": true, "explanation": "フィルターに残ったかすで、その成分を調べる対象として自然。"}, {"text": "年齢", "is_correct": false, "explanation": "人の経過年数を表す語で、フィルターに残ったものの成分ではない。"}, {"text": "注文", "is_correct": false, "explanation": "品物を頼む行為を表す語で、フィルターに残る物ではない。"}, {"text": "制服", "is_correct": false, "explanation": "着る服を表す語で、フィルターに残る物ではない。"}], "explanations": {"残渣": "フィルターに残ったかすで、その成分を調べる対象として自然。", "年齢": "人の経過年数を表す語で、フィルターに残ったものの成分ではない。", "注文": "品物を頼む行為を表す語で、フィルターに残る物ではない。", "制服": "着る服を表す語で、フィルターに残る物ではない。"}, "sentence_index": 6, "correct_answer": "残渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "請求書の残渣を確認してください。", "explanation": "ここは〈金額〉の意味。請求書で確認するのは金額で、残渣は処理後のかすなので合わない。"}, {"text": "今月は残渣が多かったです。", "explanation": "ここは〈残業〉（勤務時間を超えた仕事）の意味。残渣は物質のかすで、勤務時間には使わない。"}, {"text": "会議の残渣を配りました。", "explanation": "ここは〈資料〉（会議で配る書類）の意味。残渣は不要物で、配る書類には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蒸留したあとの残渣が、特別な容器に集めます。", "corrected_sentence": "蒸留したあとの残渣を、特別な容器に集めます。", "error_description": "「残渣が」は誤り。正しくは「残渣を」。「集める」は集める対象を「を」で示す他動詞なので、「が」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36983, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "溶媒で洗ったあとの残渣を、もう一度食べます。", "corrected_sentence": "溶媒で洗ったあとの残渣を、もう一度乾かします。", "error_description": "「食べます」は誤り。正しくは「乾かします」。残渣は食べる物ではなく、乾かして重さを量るなどの処理をする対象なので、「乾かす」と組む。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「異臭がする」で、においが主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「異臭をする」では成り立たず、「する」の主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「異臭でするので」では述語「する」の主語にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「異臭よりする」では比較の形になり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「異臭がする」で、においが主語になる。", "を": "「異臭をする」では成り立たず、「する」の主語を示せない。", "で": "「異臭でするので」では述語「する」の主語にならず、文が成り立たない。", "より": "「異臭よりする」では比較の形になり、意味が通らない。"}, "error_tags": {"を": "目的格", "で": "手段・材料", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「異臭がひどくて」で、異臭が主語になる。"}, {"text": "に", "is_correct": false, "explanation": "「異臭にひどくて」では場所や対象の形になり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「異臭からひどくて」では起点の形になり、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「異臭のひどくて」は名詞修飾の形にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「異臭がひどくて」で、異臭が主語になる。", "に": "「異臭にひどくて」では場所や対象の形になり、文が成り立たない。", "から": "「異臭からひどくて」では起点の形になり、意味が通らない。", "の": "「異臭のひどくて」は名詞修飾の形にならず、文が成り立たない。"}, "error_tags": {"に": "位置・対象", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いやなにおいのこと。", "primary_collocate": null, "pronunciation": "いしゅう", "ipa": "iɕɯː", "syllable_count": 3, "sentences": [{"text": "冷蔵庫を開けると、異臭がして思わず顔をしかめた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]を開[あ]けると、異臭[いしゅう]がして思[おも]わず顔[かお]をしかめた。", "sentence_source": "generated"}, {"text": "台所から異臭がするので、生ごみを確認した。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "台所[だいどころ]から異臭[いしゅう]がするので、生[なま]ごみを確認[かくにん]した。", "sentence_source": "generated"}, {"text": "部屋に入ったとたん、異臭が鼻をついた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "部屋[へや]に入[はい]ったとたん、異臭[いしゅう]が鼻[はな]をついた。", "sentence_source": "generated"}, {"text": "川の水が腐って、異臭を放っている。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が腐[くさ]って、異臭[いしゅう]を放[はな]っている。", "sentence_source": "generated"}, {"text": "異臭の原因は、床下に置いたままの魚だった。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "異臭[いしゅう]の原因[げんいん]は、床下[ゆかした]に置[お]いたままの魚[さかな]だった。", "sentence_source": "generated"}, {"text": "近所の工場から異臭が漂い、住民が窓を閉めた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "近所[きんじょ]の工場[こうじょう]から異臭[いしゅう]が漂[ただよ]い、住民[じゅうみん]が窓[まど]を閉[し]めた。", "sentence_source": "generated"}, {"text": "長く閉めきった倉庫には、異臭がこもっていた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "長[なが]く閉[し]めきった倉庫[そうこ]には、異臭[いしゅう]がこもっていた。", "sentence_source": "generated"}, {"text": "異臭がひどくて、教室の窓を全部開けた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "異臭[いしゅう]がひどくて、教室[きょうしつ]の窓[まど]を全部[ぜんぶ]開[あ]けた。", "sentence_source": "generated"}, {"text": "古い靴箱から異臭がするので、中身を捨てた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "古[ふる]い靴箱[くつばこ]から異臭[いしゅう]がするので、中身[なかみ]を捨[す]てた。", "sentence_source": "generated"}, {"text": "異臭を感じたら、すぐに管理人に知らせてください。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "異臭[いしゅう]を感[かん]じたら、すぐに管理人[かんりにん]に知[し]らせてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "異臭", "label": "基本形"}, {"form": "異臭が", "label": "主格"}, {"form": "異臭を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "不快で嫌なにおい。腐敗やごみなどから出る悪臭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "異臭", "is_correct": true, "explanation": "正解。「異臭がして」は、いやなにおいがして顔をしかめる文になる。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは見るものなので、「がして」と受けて顔をしかめる文に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は物で、「がする」と結びつかず、顔をしかめる理由にならない。"}, {"text": "段差", "is_correct": false, "explanation": "段差はにおいにならないので、「がして」の形で文が成り立たない。"}], "explanations": {"異臭": "正解。「異臭がして」は、いやなにおいがして顔をしかめる文になる。", "夕焼け": "夕焼けは見るものなので、「がして」と受けて顔をしかめる文に合わない。", "教科書": "教科書は物で、「がする」と結びつかず、顔をしかめる理由にならない。", "段差": "段差はにおいにならないので、「がして」の形で文が成り立たない。"}, "sentence_index": 0, "correct_answer": "異臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "異臭を聞いて、窓を閉めた。", "explanation": "ここは〈音〉の意味。異臭はにおいなので、耳で「聞く」とは言わない。"}, {"text": "いい異臭が、店の前から漂ってくる。", "explanation": "ここは〈良いにおい〉の意味。異臭は不快なにおいなので、良いにおいを表す言い方とは組まない。"}, {"text": "夜中、台所で異臭が鳴った。", "explanation": "「異音が鳴る」の「異音」を入れ替えた。においは鳴らないので、「鳴る」と組む言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "異臭", "is_correct": true, "explanation": "正解。「異臭がこもっていた」で、倉庫のいやなにおいを表す。"}, {"text": "段ボール", "is_correct": false, "explanation": "段ボールは物なので、「こもっていた」とは結びつかない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便はにおいを表さないので、「こもっていた」と合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は物なので、においがこもるという文に合わない。"}], "explanations": {"異臭": "正解。「異臭がこもっていた」で、倉庫のいやなにおいを表す。", "段ボール": "段ボールは物なので、「こもっていた」とは結びつかない。", "郵便": "郵便はにおいを表さないので、「こもっていた」と合わない。", "冷蔵庫": "冷蔵庫は物なので、においがこもるという文に合わない。"}, "sentence_index": 6, "correct_answer": "異臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの人の異臭に、みんなが引き込まれた。", "explanation": "ここは〈魅力的な香り〉の意味。異臭は不快なにおいなので、人を引きつけるものとは合わない。"}, {"text": "台所からは、いつも異臭が香ってくる。", "explanation": "ここは〈良い香り〉の意味。異臭は不快なにおいなので、香りを表す言い方とは合わない。"}, {"text": "その絵は、異臭の色が鮮やかで評判だ。", "explanation": "ここは〈香り〉の意味。異臭は色を持たないにおいなので、色を言い表す文とは組まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "料理中に異臭が感じて、ガスを止めた。", "corrected_sentence": "料理中に異臭を感じて、ガスを止めた。", "error_description": "「感じる」は目的語に「を」をとる。「が」は誤りで、正しくは「異臭を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36984, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ごみが異臭を投げている。", "corrected_sentence": "ごみが異臭を放っている。", "error_description": "「異臭」は「放つ」と組む。「投げる」は物を飛ばす動詞で、においには使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「異臭がして」で、においが主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「異臭をして」では成り立たず、においの主語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「異臭にして」では場所や対象の形になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「異臭のして」では名詞修飾の形にならず、述語が立たないので文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「異臭がして」で、においが主語になる。", "を": "「異臭をして」では成り立たず、においの主語を示せない。", "に": "「異臭にして」では場所や対象の形になり、文が成り立たない。", "の": "「異臭のして」では名詞修飾の形にならず、述語が立たないので文が成り立たない。"}, "error_tags": {"を": "目的格", "に": "位置・対象", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「工場から異臭が出た」で、異臭が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「異臭へ出た」では行き先の形になり、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「異臭より出た」では比較の形になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「異臭の出た」は名詞修飾の形にしかならず、文の述語が立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「工場から異臭が出た」で、異臭が主語になる。", "へ": "「異臭へ出た」では行き先の形になり、意味が通らない。", "より": "「異臭より出た」では比較の形になり、文が成り立たない。", "の": "「異臭の出た」は名詞修飾の形にしかならず、文の述語が立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "普通とは違う、不快なにおい。", "primary_collocate": null, "pronunciation": "いしゅう", "ipa": "iɕɯː", "syllable_count": 3, "sentences": [{"text": "いつもと違う異臭がしたので、ガスの元栓を閉めた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "いつもと違[ちが]う異臭[いしゅう]がしたので、ガスの元栓[もとせん]を閉[し]めた。", "sentence_source": "generated"}, {"text": "車から焦げたような異臭がして、すぐに路肩に止めた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "車[くるま]から焦[こ]げたような異臭[いしゅう]がして、すぐに路肩[ろかた]に止[と]めた。", "sentence_source": "generated"}, {"text": "普段は無臭の部屋に異臭が漂い、住人は不安になった。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "普段[ふだん]は無臭[むしゅう]の部屋[へや]に異臭[いしゅう]が漂[ただよ]い、住人[じゅうにん]は不安[ふあん]になった。", "sentence_source": "generated"}, {"text": "駅の構内で異臭が発生し、一時、電車が止まった。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "駅[えき]の構内[こうない]で異臭[いしゅう]が発生[はっせい]し、一時[いちじ]、電車[でんしゃ]が止[と]まった。", "sentence_source": "generated"}, {"text": "水道水から異臭がしたため、市は原因を調べている。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "水道水[すいどうすい]から異臭[いしゅう]がしたため、市[し]は原因[げんいん]を調[しら]べている。", "sentence_source": "generated"}, {"text": "異臭に気づいた店員が、すぐに換気扇を回した。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "異臭[いしゅう]に気[き]づいた店員[てんいん]が、すぐに換気扇[かんきせん]を回[まわ]した。", "sentence_source": "generated"}, {"text": "夜中に家の外から異臭がして、目が覚めた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "夜中[よなか]に家[いえ]の外[そと]から異臭[いしゅう]がして、目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "工場から異臭が出たため、近くの学校は授業を中止した。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "工場[こうじょう]から異臭[いしゅう]が出[で]たため、近[ちか]くの学校[がっこう]は授業[じゅぎょう]を中止[ちゅうし]した。", "sentence_source": "generated"}, {"text": "毎日使う掃除機から異臭がしたら、故障の合図かもしれない。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "毎日[まいにち]使[つか]う掃除機[そうじき]から異臭[いしゅう]がしたら、故障[こしょう]の合図[あいず]かもしれない。", "sentence_source": "generated"}, {"text": "異臭の正体がわからず、消防が建物の中を調べた。", "target_word": "異臭", "complexity_tier": "T3", "furigana": "異臭[いしゅう]の正体[しょうたい]がわからず、消防[しょうぼう]が建物[たてもの]の中[なか]を調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "異臭", "label": "基本形"}, {"form": "異臭が", "label": "主格"}, {"form": "異臭を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "いつものにおいとは違う、異常で不快なにおい。事故や故障の兆しとして感じられる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "異臭", "is_correct": true, "explanation": "正解。「いつもと違う異臭」は、普段と違ういやなにおいを表す。"}, {"text": "風景", "is_correct": false, "explanation": "風景は見るものなので、「いつもと違う」の後に「がした」と続く文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「がした」と結びつかず、ガスの元栓を閉める理由にならない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所なので、においを表す「がした」と合わない。"}], "explanations": {"異臭": "正解。「いつもと違う異臭」は、普段と違ういやなにおいを表す。", "風景": "風景は見るものなので、「いつもと違う」の後に「がした」と続く文に合わない。", "天気": "天気は「がした」と結びつかず、ガスの元栓を閉める理由にならない。", "教室": "教室は場所なので、においを表す「がした」と合わない。"}, "sentence_index": 0, "correct_answer": "異臭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の異臭は、清潔感があると評判だ。", "explanation": "ここは〈さわやかな香り〉の意味。異臭は不快なにおいなので、好ましいにおいを表す言い方とは組まない。"}, {"text": "会場には異臭の雰囲気が漂い、人々が静まった。", "explanation": "「異様な雰囲気」の「異様」を入れ替えた。異臭は雰囲気を表す語ではない。"}, {"text": "夜中、台所で異臭が鳴った。", "explanation": "「異音が鳴る」の「異音」を入れ替えた。においは鳴らないので、「鳴る」と組む言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "異臭", "is_correct": true, "explanation": "正解。「夜中に家の外から異臭がして」は、いやなにおいが外からしたことを表す。"}, {"text": "花束", "is_correct": false, "explanation": "花束は物なので、「がして」と結びつかず、目が覚める理由にならない。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は家具なので、においを表す「がして」と合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便はにおいを表さないので、「がして」と組む語として成り立たない。"}], "explanations": {"異臭": "正解。「夜中に家の外から異臭がして」は、いやなにおいが外からしたことを表す。", "花束": "花束は物なので、「がして」と結びつかず、目が覚める理由にならない。", "本棚": "本棚は家具なので、においを表す「がして」と合わない。", "郵便": "郵便はにおいを表さないので、「がして」と組む語として成り立たない。"}, "sentence_index": 6, "correct_answer": "異臭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "異臭の値段が高く、誰も買わない。", "explanation": "ここは〈売り買いされる品物〉の意味。異臭は不快なにおいを表す語で、売買される商品にはならない。"}, {"text": "異臭がするので、耳をすませた。", "explanation": "「物音がするので耳をすませた」の「物音」を入れ替えた。においは耳で聞くものではないので、この流れに合わない。"}, {"text": "その絵は、異臭の色が鮮やかで評判だ。", "explanation": "ここは〈香り〉の意味。異臭は色を持たないにおいなので、色を言い表す文とは組まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けたら、異臭を消えた。", "corrected_sentence": "窓を開けたら、異臭が消えた。", "error_description": "「消える」は自動詞で、主語に「が」をとる。「を」は誤りで、正しくは「異臭が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36985, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "建物の中に異臭が割れている。", "corrected_sentence": "建物の中に異臭が漂っている。", "error_description": "「異臭が漂う」は定番の表現。「割れる」は物に使う動詞で、においと組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「出ない」の主語にあたり、害虫が現れる動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は自動詞なので「を」を取れない。"}, {"text": "へ", "is_correct": false, "explanation": "「出る」は移動先を示す動詞ではなく、現れる意味なので「へ」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」にすると「害虫と出ない」となり、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「出ない」の主語にあたり、害虫が現れる動作の主体を示す。", "を": "「出る」は自動詞なので「を」を取れない。", "へ": "「出る」は移動先を示す動詞ではなく、現れる意味なので「へ」は合わない。", "と": "並列の「と」にすると「害虫と出ない」となり、文の意味が通らない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「いて」の主語として、存在するものを示す。"}, {"text": "を", "is_correct": false, "explanation": "「いる」は目的語を取らない動詞なので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「いる」の場所は「に」で示すので、「へ」は合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味にはならず、「害虫より〜いて」は文として通らない。"}], "correct_answer": "が", "explanations": {"が": "「いて」の主語として、存在するものを示す。", "を": "「いる」は目的語を取らない動詞なので、「を」は合わない。", "へ": "「いる」の場所は「に」で示すので、「へ」は合わない。", "より": "比較の意味にはならず、「害虫より〜いて」は文として通らない。"}, "error_tags": {"を": "対象", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の生活にいやな虫のこと。", "primary_collocate": null, "pronunciation": "がいちゅう", "ipa": "ɡaitɕɯː", "syllable_count": 4, "sentences": [{"text": "夏は庭に害虫が増えて困る。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "夏[なつ]は庭[にわ]に害虫[がいちゅう]が増[ふ]えて困[こま]る。", "sentence_source": "generated"}, {"text": "台所に害虫が出ないよう、毎日そうじしている。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "台所[だいどころ]に害虫[がいちゅう]が出[で]ないよう、毎日[まいにち]そうじしている。", "sentence_source": "generated"}, {"text": "野菜を育てるときは、害虫に気をつけたい。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "野菜[やさい]を育[そだ]てるときは、害虫[がいちゅう]に気[き]をつけたい。", "sentence_source": "generated"}, {"text": "害虫を見つけたので、すぐに退治した。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "害虫[がいちゅう]を見[み]つけたので、すぐに退治[たいじ]した。", "sentence_source": "generated"}, {"text": "暑い季節は、家の中にも害虫が入りやすい。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "暑[あつ]い季節[きせつ]は、家[いえ]の中[なか]にも害虫[がいちゅう]が入[はい]りやすい。", "sentence_source": "generated"}, {"text": "窓に網戸をつけて、害虫が入るのを防いだ。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "窓[まど]に網戸[あみど]をつけて、害虫[がいちゅう]が入[はい]るのを防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "害虫は見た目がいやなので、子どもが怖がる。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "害虫[がいちゅう]は見[み]た目[め]がいやなので、子[こ]どもが怖[こわ]がる。", "sentence_source": "generated"}, {"text": "古い本棚に害虫がいて、本がかじられていた。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "古[ふる]い本棚[ほんだな]に害虫[がいちゅう]がいて、本[ほん]がかじられていた。", "sentence_source": "generated"}, {"text": "花が好きな祖母は、害虫の対策に毎年苦労している。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "花[はな]が好[す]きな祖母[そぼ]は、害虫[がいちゅう]の対策[たいさく]に毎年[まいとし]苦労[くろう]している。", "sentence_source": "generated"}, {"text": "蚊も、人を刺す害虫の一つだ。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "蚊[か]も、人[ひと]を刺[さ]す害虫[がいちゅう]の一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "害虫", "label": "基本形"}, {"form": "害虫が", "label": "が格"}, {"form": "害虫を", "label": "を格"}], "register": "中立", "sense_fingerprint": "生活の中で人がいやがる虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "「増えて困る」の対象として合う、害を与える虫を指す語。文に合う唯一の選択肢。"}, {"text": "花火", "is_correct": false, "explanation": "花火は庭に増えて困るものではないので、文として成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は庭で増えて困る対象ではないので、文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は庭に増えても困らないものなので、「困る」と結びつかない。"}], "explanations": {"害虫": "「増えて困る」の対象として合う、害を与える虫を指す語。文に合う唯一の選択肢。", "花火": "花火は庭に増えて困るものではないので、文として成り立たない。", "電池": "電池は庭で増えて困る対象ではないので、文脈に合わない。", "座布団": "座布団は庭に増えても困らないものなので、「困る」と結びつかない。"}, "sentence_index": 0, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お腹の害虫を、薬で駆除して治した。", "explanation": "ここは〈寄生虫〉の意味。体の中に住む虫は寄生虫と言い、害虫とは言わない。"}, {"text": "庭に来たイノシシを、害虫として捕まえた。", "explanation": "ここは〈害獣〉の意味。害虫は昆虫を指すので、イノシシのような動物には使わない。"}, {"text": "食中毒を起こす害虫を、熱湯で殺菌した。", "explanation": "ここは〈病原菌〉の意味。殺菌の対象になる細菌は病原菌と言い、害虫とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "見た目がいやで子どもが怖がる対象として文に合う、虫の害虫。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムは見た目がいやで子どもが怖がる対象とは言えず、文が不自然になる。"}, {"text": "砂時計", "is_correct": false, "explanation": "砂時計は見た目がいやという理由で怖がられるものではないので、文脈に合わない。"}, {"text": "絵筆", "is_correct": false, "explanation": "絵筆は見た目を理由に子どもが怖がるものではなく、「見た目がいやなので」と結びつかない。"}], "explanations": {"害虫": "見た目がいやで子どもが怖がる対象として文に合う、虫の害虫。", "消しゴム": "消しゴムは見た目がいやで子どもが怖がる対象とは言えず、文が不自然になる。", "砂時計": "砂時計は見た目がいやという理由で怖がられるものではないので、文脈に合わない。", "絵筆": "絵筆は見た目を理由に子どもが怖がるものではなく、「見た目がいやなので」と結びつかない。"}, "sentence_index": 6, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑の作物をついばむカラスは、典型的な害虫だ。", "explanation": "ここは〈害鳥〉の意味。鳥を指すときは害鳥と言い、害虫は昆虫に限るので合わない。"}, {"text": "顕微鏡で見ると、この害虫は一つの細胞でできている。", "explanation": "ここは〈雑菌〉の意味。一つの細胞でできた微生物は雑菌と言い、害虫は肉眼で見える虫を指す。"}, {"text": "腸内で害虫が増えると、お腹をこわしやすい。", "explanation": "ここは〈悪玉菌〉の意味。腸の中で増える細菌は悪玉菌と言い、害虫とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭に害虫を増えて困る。", "corrected_sentence": "庭に害虫が増えて困る。", "error_description": "「増える」は自動詞なので、主語には「が」を使う。「を」は誤りで、正しくは「害虫が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36986, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "害虫を見た目が気持ち悪いので、子どもが怖がる。", "corrected_sentence": "害虫は見た目が気持ち悪いので、子どもが怖がる。", "error_description": "「害虫」は文の主題になるので「は」を使う。「を」は目的語を示す助詞で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「畑の害虫」として、畑に属する害虫を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「減らす」の対象に「へ」は取れず、「畑へ害虫を減らした」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」が二つ重なり、「畑を害虫を減らした」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味にならず、「畑より害虫を減らした」は不自然で文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「畑の害虫」として、畑に属する害虫を示す。", "へ": "「減らす」の対象に「へ」は取れず、「畑へ害虫を減らした」は意味が通らない。", "を": "「を」が二つ重なり、「畑を害虫を減らした」は文が成り立たない。", "より": "比較の意味にならず、「畑より害虫を減らした」は不自然で文が通らない。"}, "error_tags": {"へ": "方向", "を": "対象", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の生活に害をあたえる虫。ゴキブリやハエなど。", "primary_collocate": null, "pronunciation": "がいちゅう", "ipa": "ɡaitɕɯː", "syllable_count": 4, "sentences": [{"text": "ゴキブリやハエは、代表的な害虫だ。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "ゴキブリやハエは、代表的[だいひょうてき]な害虫[がいちゅう]だ。", "sentence_source": "generated"}, {"text": "害虫は食べ物を汚し、病気をうつすことがある。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "害虫[がいちゅう]は食[た]べ物[もの]を汚[よご]し、病気[びょうき]をうつすことがある。", "sentence_source": "generated"}, {"text": "倉庫では、害虫から穀物を守る必要がある。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "倉庫[そうこ]では、害虫[がいちゅう]から穀物[こくもつ]を守[まも]る必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "ハエのような害虫は、食品工場で特に問題になる。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "ハエのような害虫[がいちゅう]は、食品工場[しょくひんこうじょう]で特[とく]に問題[もんだい]になる。", "sentence_source": "generated"}, {"text": "農家は、作物を食べる害虫に悩まされている。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "農家[のうか]は、作物[さくもつ]を食[た]べる害虫[がいちゅう]に悩[なや]まされている。", "sentence_source": "generated"}, {"text": "害虫が出た店は、保健所から注意を受けた。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "害虫[がいちゅう]が出[で]た店[みせ]は、保健所[ほけんじょ]から注意[ちゅうい]を受[う]けた。", "sentence_source": "generated"}, {"text": "ゴキブリは家庭で最もきらわれる害虫だ。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "ゴキブリは家庭[かてい]で最[もっと]もきらわれる害虫[がいちゅう]だ。", "sentence_source": "generated"}, {"text": "薬をまいて、畑の害虫を減らした。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "薬[くすり]をまいて、畑[はたけ]の害虫[がいちゅう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "害虫による被害で、今年は米の収穫が減った。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "害虫[がいちゅう]による被害[ひがい]で、今年[ことし]は米[こめ]の収穫[しゅうかく]が減[へ]った。", "sentence_source": "generated"}, {"text": "衛生のために、飲食店は害虫の発生を防がなければならない。", "target_word": "害虫", "complexity_tier": "T3", "furigana": "衛生[えいせい]のために、飲食店[いんしょくてん]は害虫[がいちゅう]の発生[はっせい]を防[ふせ]がなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "害虫", "label": "基本形"}, {"form": "害虫が", "label": "が格"}, {"form": "害虫から", "label": "から格"}], "register": "中立", "sense_fingerprint": "人の生活や作物に害を与える虫(ゴキブリ・ハエなど)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "ゴキブリやハエを例に挙げて「代表的な〜」と言える、人の生活に害を与える虫。"}, {"text": "益虫", "is_correct": false, "explanation": "益虫は役に立つ虫なので、ゴキブリやハエを「代表的な益虫」とするのは内容が矛盾する。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は虫ではないので、ゴキブリやハエの説明に合わない。"}, {"text": "肥料", "is_correct": false, "explanation": "肥料は虫ではないので、ゴキブリやハエの例として文が成り立たない。"}], "explanations": {"害虫": "ゴキブリやハエを例に挙げて「代表的な〜」と言える、人の生活に害を与える虫。", "益虫": "益虫は役に立つ虫なので、ゴキブリやハエを「代表的な益虫」とするのは内容が矛盾する。", "花粉": "花粉は虫ではないので、ゴキブリやハエの説明に合わない。", "肥料": "肥料は虫ではないので、ゴキブリやハエの例として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "畑を荒らすシカは、ゴキブリと並ぶ害虫だ。", "explanation": "ここは〈害獣〉の意味。シカのような動物には害獣を使い、害虫は虫に限るので合わない。"}, {"text": "畑を荒らすカラスは、農家にとって典型的な害虫だ。", "explanation": "ここは〈害鳥〉の意味。鳥は害虫ではなく害鳥と言うので、この文脈では合わない。"}, {"text": "まな板に残った害虫が増えて、食中毒の原因になった。", "explanation": "ここは〈雑菌〉の意味。目に見えない菌が増える場合は雑菌と言い、害虫は虫を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害虫", "is_correct": true, "explanation": "「最もきらわれる」の対象として文に合う、人の生活に害を与える虫。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、家庭で最もきらわれる対象とは言えず、文が成り立たない。"}, {"text": "日時計", "is_correct": false, "explanation": "日時計は時刻を知る道具で、家庭で最もきらわれるものとは言えず、文脈に合わない。"}, {"text": "紙粘土", "is_correct": false, "explanation": "紙粘土は工作の材料で、家庭で最もきらわれる対象とは言えず、文が不自然になる。"}], "explanations": {"害虫": "「最もきらわれる」の対象として文に合う、人の生活に害を与える虫。", "夕焼け": "夕焼けは空の現象で、家庭で最もきらわれる対象とは言えず、文が成り立たない。", "日時計": "日時計は時刻を知る道具で、家庭で最もきらわれるものとは言えず、文脈に合わない。", "紙粘土": "紙粘土は工作の材料で、家庭で最もきらわれる対象とは言えず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "害虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場から出る害虫で、川が汚れてしまった。", "explanation": "ここは〈公害〉の意味。環境を汚す問題は公害と言い、害虫とは言わない。"}, {"text": "漏れた害虫を吸って、作業員が倒れた。", "explanation": "ここは〈毒ガス〉の意味。漏れて吸い込むものはガスで、虫を吸うという使い方はしない。"}, {"text": "害虫を浴びた作業員が、体調を崩した。", "explanation": "ここは〈放射線〉の意味。浴びるのは放射線で、虫を浴びるという使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "倉庫では、害虫へ食品を守る必要がある。", "corrected_sentence": "倉庫では、害虫から食品を守る必要がある。", "error_description": "「守る」の相手となる脅威の出どころは「から」で示す。「へ」は方向を表し、ここでは意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36987, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家では、ゴキブリが最も嫌われる害虫を一つだ。", "corrected_sentence": "家では、ゴキブリが最も嫌われる害虫の一つだ。", "error_description": "「〜の一つ」と所属を示すには「の」を使う。「を」は誤りで、正しくは「害虫の一つ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈客を誘引している〉で、誘引の対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "客が誘引しているでは、客が引き寄せる主体になり、意味が逆になる。"}, {"text": "に", "is_correct": false, "explanation": "客に誘引しているでは相手を示すが、誘引は対象を引き寄せる語なので文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "客で誘引しているでは手段になり、引き寄せる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "〈客を誘引している〉で、誘引の対象を示す正しい助詞。", "が": "客が誘引しているでは、客が引き寄せる主体になり、意味が逆になる。", "に": "客に誘引しているでは相手を示すが、誘引は対象を引き寄せる語なので文が成り立たない。", "で": "客で誘引しているでは手段になり、引き寄せる対象を示せない。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈人を誘引する〉で、誘引の対象を示す正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "人と誘引するでは並ぶ相手を示すだけで、引き寄せる対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "人へ誘引するでは方向を示すが、誘引は対象を引き寄せる語なので文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "人から誘引するでは起点を示すことになり、引き寄せる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "〈人を誘引する〉で、誘引の対象を示す正しい助詞。", "と": "人と誘引するでは並ぶ相手を示すだけで、引き寄せる対象を表せない。", "へ": "人へ誘引するでは方向を示すが、誘引は対象を引き寄せる語なので文が成り立たない。", "から": "人から誘引するでは起点を示すことになり、引き寄せる対象を表せない。"}, "error_tags": {"を": "対象", "と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や動物を、ある場所に来るようにさせること。", "primary_collocate": null, "pronunciation": "ゆういん", "ipa": "jɯːiɴ", "syllable_count": 4, "sentences": [{"text": "甘い香りでハチを誘引し、花は花粉を運んでもらう。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "甘[あま]い香[かお]りでハチを誘引[ゆういん]し、花[はな]は花粉[かふん]を運[はこ]んでもらう。", "sentence_source": "generated"}, {"text": "店は無料の試食で客を誘引している。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "店[みせ]は無料[むりょう]の試食[ししょく]で客[きゃく]を誘引[ゆういん]している。", "sentence_source": "generated"}, {"text": "明るい光が虫を誘引するので、夜は窓を閉める。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "明[あか]るい光[ひかり]が虫[むし]を誘引[ゆういん]するので、夜[よる]は窓[まど]を閉[し]める。", "sentence_source": "generated"}, {"text": "畑にシカを誘引しないよう、残った野菜は片づけた。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "畑[はたけ]にシカを誘引[ゆういん]しないよう、残[のこ]った野菜[やさい]は片[かた]づけた。", "sentence_source": "generated"}, {"text": "駅前の大きな広告は、観光客を誘引する目的で作られた。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の大[おお]きな広告[こうこく]は、観光客[かんこうきゃく]を誘引[ゆういん]する目的[もくてき]で作[つく]られた。", "sentence_source": "generated"}, {"text": "魚の誘引には、においの強いえさが効果的だ。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "魚[さかな]の誘引[ゆういん]には、においの強[つよ]いえさが効果的[こうかてき]だ。", "sentence_source": "generated"}, {"text": "動物の誘引を防ぐため、ごみは必ず袋に入れて出す。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の誘引[ゆういん]を防[ふせ]ぐため、ごみは必[かなら]ず袋[ふくろ]に入[い]れて出[だ]す。", "sentence_source": "generated"}, {"text": "祭りは遠くの町からも人を誘引する。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "祭[まつ]りは遠[とお]くの町[まち]からも人[ひと]を誘引[ゆういん]する。", "sentence_source": "generated"}, {"text": "池のほとりにパンくずを置くと、カモを誘引してしまう。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "いけのほとりにぱんくずをおくと、かもをゆういんしてしまう。", "sentence_source": "generated"}, {"text": "森の入り口にえさを置くと、クマを誘引する恐れがある。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "森[もり]の入[い]り口[ぐち]にえさを置[お]くと、クマを誘引[ゆういん]する恐[おそ]れがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誘引", "label": "基本形"}, {"form": "誘引する", "label": "終止形"}, {"form": "誘引した", "label": "過去形"}, {"form": "誘引される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "人や動物をある場所へ来るよう仕向けること。においや光、えさなどで呼び寄せる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誘引", "is_correct": true, "explanation": "香りでハチを花へ引き寄せる意味で、ここにだけ合う語。"}, {"text": "分解", "is_correct": false, "explanation": "分解は物を部品や成分に分けること。ハチを対象に香りで導く文脈とは合わず、文が成り立たない。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物の働きで物質が変化すること。生き物を呼び寄せる場面には使えない。"}, {"text": "凍結", "is_correct": false, "explanation": "凍結は凍らせること。香りの働きとも花粉の運搬とも結びつかず、文の流れに合わない。"}], "explanations": {"誘引": "香りでハチを花へ引き寄せる意味で、ここにだけ合う語。", "分解": "分解は物を部品や成分に分けること。ハチを対象に香りで導く文脈とは合わず、文が成り立たない。", "発酵": "発酵は微生物の働きで物質が変化すること。生き物を呼び寄せる場面には使えない。", "凍結": "凍結は凍らせること。香りの働きとも花粉の運搬とも結びつかず、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "誘引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝不足が事故の誘引になった。", "explanation": "ここは〈誘因〉（きっかけ・原因）の意味。誘引は引き寄せる働きを指すので、事故の原因を表す場面では誘因と書く。"}, {"text": "係員が来場者の荷物を誘引した。", "explanation": "「預かった」を「誘引した」に入れ替えた。荷物は人や動物ではないので、誘引とは組まない。"}, {"text": "会議で若手の意見を誘引した。", "explanation": "ここは〈引き出す〉の意味。誘引は刺激によって引き寄せることを指し、話の内容を引き出す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誘引", "is_correct": true, "explanation": "ごみや餌で動物を引き寄せることを指し、防ぐ対象としてぴったり合う。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替えること。動物の換気を防ぐとは言えず、文が成り立たない。"}, {"text": "採光", "is_correct": false, "explanation": "採光は光を取り入れること。防ぐ対象として意味が通らない。"}, {"text": "洗浄", "is_correct": false, "explanation": "洗浄は汚れを洗い流すこと。動物を対象にした『防ぐ』の文には合わない。"}], "explanations": {"誘引": "ごみや餌で動物を引き寄せることを指し、防ぐ対象としてぴったり合う。", "換気": "換気は空気を入れ替えること。動物の換気を防ぐとは言えず、文が成り立たない。", "採光": "採光は光を取り入れること。防ぐ対象として意味が通らない。", "洗浄": "洗浄は汚れを洗い流すこと。動物を対象にした『防ぐ』の文には合わない。"}, "sentence_index": 6, "correct_answer": "誘引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は会社の規則を誘引した。", "explanation": "「改定した」を「誘引した」に入れ替えた。規則は人や動物ではないので、誘引の対象にならない。"}, {"text": "監督は有望な若手を代表に誘引した。", "explanation": "ここは〈招集〉の意味。誘引は人を場所へ引き寄せる語で、役目に呼び集めて選ぶ場面には招集を使う。"}, {"text": "先生が生徒の答案を誘引した。", "explanation": "「採点した」を「誘引した」に入れ替えた。答案は人や動物ではないので、誘引とは組まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の夜、街灯は虫に誘引する。", "corrected_sentence": "夏の夜、街灯は虫を誘引する。", "error_description": "助詞の誤り。誘引の対象は『を』で示す。『に』にすると『虫に引き寄せる』という不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36988, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の虫は街灯の光に誘引れる。", "corrected_sentence": "夜の虫は街灯の光に誘引される。", "error_description": "動詞の活用の誤り。受身の形は『誘引される』で、『誘引れる』は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
