INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36989, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈犬を誘引するために〉で、誘引の対象を示す正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "犬と誘引するためには並ぶ相手を示すだけで、引き寄せる対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "犬へ誘引するためには方向を示すが、誘引は対象を引き寄せる語なので文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "犬から誘引するためには起点を示すことになり、引き寄せる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "〈犬を誘引するために〉で、誘引の対象を示す正しい助詞。", "と": "犬と誘引するためには並ぶ相手を示すだけで、引き寄せる対象を表せない。", "へ": "犬へ誘引するためには方向を示すが、誘引は対象を引き寄せる語なので文が成り立たない。", "から": "犬から誘引するためには起点を示すことになり、引き寄せる対象を表せない。"}, "error_tags": {"を": "対象", "と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36989, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や動物を引き寄せて、自分の方へ来させること。", "primary_collocate": null, "pronunciation": "ゆういん", "ipa": "jɯːiɴ", "syllable_count": 4, "sentences": [{"text": "この植物は甘い蜜でアリを誘引し、種を運ばせる。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は甘[あま]い蜜[みつ]でアリを誘引[ゆういん]し、種[たね]を運[はこ]ばせる。", "sentence_source": "generated"}, {"text": "釣り人は音を出して魚を誘引する。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "釣[つ]り人[びと]は音[おと]を出[だ]して魚[さかな]を誘引[ゆういん]する。", "sentence_source": "generated"}, {"text": "店の前で歌い、通る人を誘引する。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "店[みせ]の前[まえ]で歌[うた]い、通[とお]る人[ひと]を誘引[ゆういん]する。", "sentence_source": "generated"}, {"text": "灯りで虫を誘引して捕まえる道具を作った。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "灯[あか]りで虫[むし]を誘引[ゆういん]して捕[つか]まえる道具[どうぐ]を作[つく]った。", "sentence_source": "generated"}, {"text": "メスは鳴き声でオスを誘引する。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "メスは鳴[な]き声[ごえ]でオスを誘引[ゆういん]する。", "sentence_source": "generated"}, {"text": "花の色は、虫を誘引するための工夫だ。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "花[はな]の色[いろ]は、虫[むし]を誘引[ゆういん]するための工夫[くふう]だ。", "sentence_source": "generated"}, {"text": "彼は笛の音で子どもたちを誘引し、広場に集めた。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "彼[かれ]は笛[ふえ]の音[ね]で子[こ]どもたちを誘引[ゆういん]し、広場[ひろば]に集[あつ]めた。", "sentence_source": "generated"}, {"text": "犬を誘引するために、飼い主はおやつを手に持った。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "犬[いぬ]を誘引[ゆういん]するために、飼[か]い主[ぬし]はおやつを手[て]に持[も]った。", "sentence_source": "generated"}, {"text": "光に誘引されて、夜の虫が街灯に集まる。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "光[ひかり]に誘引[ゆういん]されて、夜[よる]の虫[むし]が街灯[がいとう]に集[あつ]まる。", "sentence_source": "generated"}, {"text": "店主は焼き鳥の煙で通行人を誘引している。", "target_word": "誘引", "complexity_tier": "T3", "furigana": "店主[てんしゅ]は焼[や]き鳥[とり]の煙[けむり]で通行人[つうこうにん]を誘引[ゆういん]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誘引", "label": "基本形"}, {"form": "誘引する", "label": "終止形"}, {"form": "誘引して", "label": "テ形"}, {"form": "誘引される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "音・色・においなどで相手を自分の方へ引き寄せること。誘う側の働きかけに重点がある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36989, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誘引", "is_correct": true, "explanation": "甘い蜜でアリを植物へ引き寄せる意味で、ここにだけ合う語。"}, {"text": "分解", "is_correct": false, "explanation": "分解は成分へ分けること。アリを対象に種を運ばせる文とは成り立たない。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分を失わせること。アリを乾かして種を運ばせるという文は合わない。"}, {"text": "中和", "is_correct": false, "explanation": "中和は酸とアルカリを打ち消し合うこと。生き物には使えず、文の流れに合わない。"}], "explanations": {"誘引": "甘い蜜でアリを植物へ引き寄せる意味で、ここにだけ合う語。", "分解": "分解は成分へ分けること。アリを対象に種を運ばせる文とは成り立たない。", "乾燥": "乾燥は水分を失わせること。アリを乾かして種を運ばせるという文は合わない。", "中和": "中和は酸とアルカリを打ち消し合うこと。生き物には使えず、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "誘引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜更かしが事故の誘引になる。", "explanation": "ここは〈誘因〉（きっかけ・原因）の意味。誘引は引き寄せる働きを指し、事故の原因を表す場面では誘因を使う。"}, {"text": "係員が案内板を搭乗口へ誘引した。", "explanation": "案内板は人や動物ではないため、誘引の対象になりえない。定義の対象外の使い方。"}, {"text": "薬は副作用を誘引することがある。", "explanation": "ここは〈誘発〉の意味。誘引は引き寄せる語で、副作用のような望ましくない結果を引き起こす場面では誘発を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36989, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誘引", "is_correct": true, "explanation": "笛の音で子どもを集める意味で、ここにだけ合う語。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集団を散らせること。後半の『広場に集めた』と逆の動きになり、文が成り立たない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は調べ確かめること。子どもを対象にすると文の流れに合わない。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替えること。子どもに使えず、文が成り立たない。"}], "explanations": {"誘引": "笛の音で子どもを集める意味で、ここにだけ合う語。", "解散": "解散は集団を散らせること。後半の『広場に集めた』と逆の動きになり、文が成り立たない。", "点検": "点検は調べ確かめること。子どもを対象にすると文の流れに合わない。", "換気": "換気は空気を入れ替えること。子どもに使えず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "誘引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コーチは若手を代表に誘引した。", "explanation": "ここは〈招集〉の意味。誘引は人を場所へ引き寄せる語で、代表チームに選び呼び集める場面には招集を使う。"}, {"text": "先生が黒板を校庭へ誘引した。", "explanation": "黒板は人や動物ではなく、誘引の対象になりえない。定義にそぐわない使い方。"}, {"text": "会議で若手の意見を誘引した。", "explanation": "ここは〈引き出す〉の意味。誘引は刺激で引き寄せることを指し、話の内容を引き出す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36989, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "灯りは虫と誘引する。", "corrected_sentence": "灯りは虫を誘引する。", "error_description": "助詞の誤り。引き寄せる対象は『を』で示す。『と』では『虫と引き寄せ合う』という不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36989, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の虫は光に誘引れる。", "corrected_sentence": "夜の虫は光に誘引される。", "error_description": "動詞の活用の誤り。受身の形は『誘引される』で、『誘引れる』は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安全", "is_correct": true, "explanation": "〈危険〉の対義語。危険がなく、悪い結果が起こらない状態を指す。"}, {"text": "健康", "is_correct": false, "explanation": "健康は体の調子が良いこと。危険の対義語ではない。"}, {"text": "平和", "is_correct": false, "explanation": "平和は争いがない状態。危険と対になる語ではない。"}, {"text": "繁栄", "is_correct": false, "explanation": "繁栄は栄えて発展すること。危険の対義語ではない。"}], "correct_answer": "安全", "explanations": {"安全": "〈危険〉の対義語。危険がなく、悪い結果が起こらない状態を指す。", "健康": "健康は体の調子が良いこと。危険の対義語ではない。", "平和": "平和は争いがない状態。危険と対になる語ではない。", "繁栄": "繁栄は栄えて発展すること。危険の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈危険を承知で〉で、承知する対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "危険が承知でと続けると、危険が承知する主体になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "危険に承知でと続けると、相手や場所を示すが、承知の対象にはならず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "危険で承知でと続けると、危険が手段になり、承知する対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "〈危険を承知で〉で、承知する対象を示す正しい助詞。", "が": "危険が承知でと続けると、危険が承知する主体になり、文が成り立たない。", "に": "危険に承知でと続けると、相手や場所を示すが、承知の対象にはならず文が成り立たない。", "で": "危険で承知でと続けると、危険が手段になり、承知する対象を示せない。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・相手", "で": "手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安全", "is_correct": true, "explanation": "〈危険〉の対義語。危険がなく、悪い結果が起こらない状態を指す。"}, {"text": "清潔", "is_correct": false, "explanation": "清潔は汚れがなく衛生的なこと。危険の対義語ではない。"}, {"text": "利益", "is_correct": false, "explanation": "利益は得となるもの。危険の対義語ではない。"}, {"text": "繁盛", "is_correct": false, "explanation": "繁盛は店などが栄えること。危険の対義語ではない。"}], "correct_answer": "安全", "explanations": {"安全": "〈危険〉の対義語。危険がなく、悪い結果が起こらない状態を指す。", "清潔": "清潔は汚れがなく衛生的なこと。危険の対義語ではない。", "利益": "利益は得となるもの。危険の対義語ではない。", "繁盛": "繁盛は店などが栄えること。危険の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "わるいことがおこりそうなこと。", "primary_collocate": null, "pronunciation": "きけん", "ipa": "kikeɴ", "syllable_count": 3, "sentences": [{"text": "雨で川の水が増え、危険なので近づかないでください。", "target_word": "危険", "complexity_tier": "T3", "furigana": "雨[あめ]で川[かわ]の水[みず]が増[ふ]え、危険[きけん]なので近[ちか]づかないでください。", "sentence_source": "generated"}, {"text": "この道は夜になると暗くて危険だ。", "target_word": "危険", "complexity_tier": "T3", "furigana": "この道[みち]は夜[よる]になると暗[くら]くて危険[きけん]だ。", "sentence_source": "generated"}, {"text": "冬の山は雪崩の危険がある。", "target_word": "危険", "complexity_tier": "T3", "furigana": "冬[ふゆ]の山[やま]は雪崩[なだれ]の危険[きけん]がある。", "sentence_source": "generated"}, {"text": "危険を感じて、子どもはすぐに母親の後ろに隠れた。", "target_word": "危険", "complexity_tier": "T3", "furigana": "危険[きけん]を感[かん]じて、子[こ]どもはすぐに母親[ははおや]の後[うし]ろに隠[かく]れた。", "sentence_source": "generated"}, {"text": "工事中の場所は危険なので、立ち入り禁止になっている。", "target_word": "危険", "complexity_tier": "T3", "furigana": "工事中[こうじちゅう]の場所[ばしょ]は危険[きけん]なので、立[た]ち入[い]り禁止[きんし]になっている。", "sentence_source": "generated"}, {"text": "信号を無視して渡るのは、とても危険だ。", "target_word": "危険", "complexity_tier": "T3", "furigana": "信号[しんごう]を無視[むし]して渡[わた]るのは、とても危険[きけん]だ。", "sentence_source": "generated"}, {"text": "地震のとき、窓の近くにいると危険です。", "target_word": "危険", "complexity_tier": "T3", "furigana": "地震[じしん]のとき、窓[まど]の近[ちか]くにいると危険[きけん]です。", "sentence_source": "generated"}, {"text": "彼は危険を承知で、燃える家に入った。", "target_word": "危険", "complexity_tier": "T3", "furigana": "彼[かれ]は危険[きけん]を承知[しょうち]で、燃[も]える家[いえ]に入[はい]った。", "sentence_source": "generated"}, {"text": "海が荒れてきたので、危険を避けて船は港に戻った。", "target_word": "危険", "complexity_tier": "T3", "furigana": "海[うみ]が荒[あ]れてきたので、危険[きけん]を避[さ]けて船[ふね]は港[みなと]に戻[もど]った。", "sentence_source": "generated"}, {"text": "危険が迫ったら、大きな声で周りに知らせてください。", "target_word": "危険", "complexity_tier": "T3", "furigana": "危険[きけん]が迫[せま]ったら、大[おお]きな声[こえ]で周[まわ]りに知[し]らせてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "危険", "label": "基本形"}, {"form": "危険な", "label": "連体形"}, {"form": "危険だ", "label": "終止形"}, {"form": "危険で", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "けがや事故など、悪いことが起こりそうな状態や場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e32450b-51ff-46a1-a189-b64c993948ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "危険", "is_correct": true, "explanation": "増水した川に近づくと悪いことが起きそうな状態を表す語で、ここにだけ合う。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は華やかで立派なこと。増水の川に近づかない理由として意味が通らない。"}, {"text": "愉快", "is_correct": false, "explanation": "愉快は楽しく心地よいこと。近づかないよう求める文脈と噛み合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "新鮮は鮮度が高いこと。川に近づかないでという理由にならず、文が成り立たない。"}], "explanations": {"危険": "増水した川に近づくと悪いことが起きそうな状態を表す語で、ここにだけ合う。", "豪華": "豪華は華やかで立派なこと。増水の川に近づかない理由として意味が通らない。", "愉快": "愉快は楽しく心地よいこと。近づかないよう求める文脈と噛み合わない。", "新鮮": "新鮮は鮮度が高いこと。川に近づかないでという理由にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "危険"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は経済の危険を乗り越えた。", "explanation": "ここは〈危機〉の意味。危険は事故や損害が起こりそうな可能性を指すので、経済の大きな困難には危機を使う。"}, {"text": "試験の結果が危険で、眠れなかった。", "explanation": "ここは〈不安〉の意味。危険は悪い結果の可能性を表すので、結果を気に病む気持ちには不安を使う。"}, {"text": "夜道は危険が必要だ。", "explanation": "ここは〈注意〉の意味。危険は状況そのものを指し、必要とされる心構えは注意で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "危険", "is_correct": true, "explanation": "地震のときに窓の近くにいることが招く悪い結果の可能性を表す語で、ここにだけ合う。"}, {"text": "快適", "is_correct": false, "explanation": "快適は心地よく過ごせること。窓の近くにいると快適、とは言えず文が成り立たない。"}, {"text": "上品", "is_correct": false, "explanation": "上品は品があること。地震の場面で窓の近くにいる理由と噛み合わない。"}, {"text": "静か", "is_correct": false, "explanation": "静かは音が少ないこと。地震のときに窓の近くにいると静か、では文の意味が通らない。"}], "explanations": {"危険": "地震のときに窓の近くにいることが招く悪い結果の可能性を表す語で、ここにだけ合う。", "快適": "快適は心地よく過ごせること。窓の近くにいると快適、とは言えず文が成り立たない。", "上品": "上品は品があること。地震の場面で窓の近くにいる理由と噛み合わない。", "静か": "静かは音が少ないこと。地震のときに窓の近くにいると静か、では文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "危険"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隣の工事の音が危険だと苦情が出た。", "explanation": "ここは〈迷惑〉の意味。危険は身の安全への可能性を表すので、騒音で困らせる場面には迷惑を使う。"}, {"text": "店内の音楽が危険で、落ち着かなかった。", "explanation": "ここは〈不快〉の意味。危険は健康や安全への可能性を指すので、音に悩まされる感覚には不快を使う。"}, {"text": "彼の笑顔は危険なほど魅力的だった。", "explanation": "ここは〈非常に〉という程度の強調の用法。悪い結果の可能性を表す義項とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の山道は、落石の危険をある。", "corrected_sentence": "夜の山道は、落石の危険がある。", "error_description": "助詞の誤り。『ある』と結ぶ危険には『が』を使う。『を』は動作の対象を示すので、存在を表す文では使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36990, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の登山は、遭難の危険を伴い。", "corrected_sentence": "夜の登山は、遭難の危険を伴う。", "error_description": "活用の誤り。『伴う』は終止形で文を結ぶが、『伴い』では文が途中で止まり不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f15fc1d-d722-4e8b-9628-d5e9e122bb9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36992, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「計算から除外する」の「から」は、外す範囲の起点を示す。"}, {"text": "に", "is_correct": false, "explanation": "「計算に除外してください」は不自然。除外は「〜から」で範囲を示す。"}, {"text": "で", "is_correct": false, "explanation": "「計算で除外」は手段の意味になり、ここでは意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「計算へ除外」は方向を示すが、除外の範囲を表せない。"}], "correct_answer": "から", "explanations": {"から": "「計算から除外する」の「から」は、外す範囲の起点を示す。", "に": "「計算に除外してください」は不自然。除外は「〜から」で範囲を示す。", "で": "「計算で除外」は手段の意味になり、ここでは意味が通らない。", "へ": "「計算へ除外」は方向を示すが、除外の範囲を表せない。"}, "error_tags": {"に": "位置・対象", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "算入", "is_correct": true, "explanation": "数や計算に入れること。計算から除外することの対義語で、正解。"}, {"text": "提出", "is_correct": false, "explanation": "書類などを差し出すこと。計算に入れるかどうかとは対義関係にない。"}, {"text": "決定", "is_correct": false, "explanation": "方針や結論を決めること。除外の対義語ではない。"}, {"text": "採取", "is_correct": false, "explanation": "材料や標本を採って集めること。数に入れるかどうかの対義語ではない。"}], "correct_answer": "算入", "explanations": {"算入": "数や計算に入れること。計算から除外することの対義語で、正解。", "提出": "書類などを差し出すこと。計算に入れるかどうかとは対義関係にない。", "決定": "方針や結論を決めること。除外の対義語ではない。", "採取": "材料や標本を採って集めること。数に入れるかどうかの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36992, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36992, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「入れるのをやめる」という意味です。", "primary_collocate": null, "pronunciation": "じょがい", "ipa": "d͡ʑoɡai", "syllable_count": 3, "sentences": [{"text": "今回の調査から、高校生のデータは除外しました。", "target_word": "除外", "complexity_tier": "T3", "furigana": "今回[こんかい]の調査[ちょうさ]から、高校生[こうこうせい]のデータは除外[じょがい]しました。", "sentence_source": "generated"}, {"text": "間違った答えは、計算から除外してください。", "target_word": "除外", "complexity_tier": "T3", "furigana": "間違[まちが]った答[こた]えは、計算[けいさん]から除外[じょがい]してください。", "sentence_source": "generated"}, {"text": "古い名簿は、リストから除外しました。", "target_word": "除外", "complexity_tier": "T3", "furigana": "古[ふる]い名簿[めいぼ]は、リストから除外[じょがい]しました。", "sentence_source": "generated"}, {"text": "体調が悪い人は、今日の練習から除外します。", "target_word": "除外", "complexity_tier": "T3", "furigana": "体調[たいちょう]が悪[わる]い人[ひと]は、今日[きょう]の練習[れんしゅう]から除外[じょがい]します。", "sentence_source": "generated"}, {"text": "日曜日は忙しいので、候補から除外しました。", "target_word": "除外", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は忙[いそが]しいので、候補[こうほ]から除外[じょがい]しました。", "sentence_source": "generated"}, {"text": "値段が高すぎる店は、最初に除外しましょう。", "target_word": "除外", "complexity_tier": "T3", "furigana": "値段[ねだん]が高[たか]すぎる店[みせ]は、最初[さいしょ]に除外[じょがい]しましょう。", "sentence_source": "generated"}, {"text": "不良品は、売る商品から除外しました。", "target_word": "除外", "complexity_tier": "T3", "furigana": "不良品[ふりょうひん]は、売[う]る商品[しょうひん]から除外[じょがい]しました。", "sentence_source": "generated"}, {"text": "参加者の数から、先生は除外して数えます。", "target_word": "除外", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の数[かず]から、先生[せんせい]は除外[じょがい]して数[かぞ]えます。", "sentence_source": "generated"}, {"text": "このアンケートでは、十代の回答は除外されました。", "target_word": "除外", "complexity_tier": "T3", "furigana": "このアンケートでは、十代[じゅうだい]の回答[かいとう]は除外[じょがい]されました。", "sentence_source": "generated"}, {"text": "特別な日は、今回の計算から除外します。", "target_word": "除外", "complexity_tier": "T3", "furigana": "特別[とくべつ]な日[ひ]は、今回[こんかい]の計算[けいさん]から除外[じょがい]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "除外する", "label": "辞書形"}, {"form": "除外した", "label": "過去形"}, {"form": "除外して", "label": "て形"}, {"form": "除外される", "label": "受身形"}, {"form": "除外しない", "label": "否定形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "数・リスト・計算などに入れないことにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36992, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除外", "is_correct": true, "explanation": "調査の集計から高校生のデータを外したという意味で、この文に入る正しい語。"}, {"text": "出発", "is_correct": false, "explanation": "場所を離れて出かける意味。データを主語にすると文が成り立たない。"}, {"text": "冷蔵", "is_correct": false, "explanation": "食品などを冷やして保存する意味。データには使えず、文が通らない。"}, {"text": "就寝", "is_correct": false, "explanation": "寝ることを表し、人にしか使えない。データを主語にすると不自然で文が成り立たない。"}], "explanations": {"除外": "調査の集計から高校生のデータを外したという意味で、この文に入る正しい語。", "出発": "場所を離れて出かける意味。データを主語にすると文が成り立たない。", "冷蔵": "食品などを冷やして保存する意味。データには使えず、文が通らない。", "就寝": "寝ることを表し、人にしか使えない。データを主語にすると不自然で文が成り立たない。"}, "sentence_index": 0, "correct_answer": "除外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シャツについたコーヒーの汚れを、除外して落としました。", "explanation": "ここは〈除去〉の意味。除外は集まりや計算から外すことで、汚れを取り去る意味では使わない。"}, {"text": "この薬は、体の中のウイルスを除外する働きがあります。", "explanation": "ここは〈排除〉の意味。除外は仲間や対象の範囲から外すことで、ウイルスを体から追い払う意味では使わない。"}, {"text": "チームを除外して、自分から出ていきました。", "explanation": "ここは〈脱退〉の意味。自分から組織を離れるのは脱退で、除外は外の側が集まりから外す意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36992, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除外", "is_correct": true, "explanation": "売る商品の範囲から不良品を外したという意味で、この文に入る正しい語。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味。不良品を商品から外す文には合わない。"}, {"text": "離陸", "is_correct": false, "explanation": "飛行機などが飛び立つ意味で、商品には使えず文が通らない。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が煮え立つ意味。商品を主語にすると文が成り立たない。"}], "explanations": {"除外": "売る商品の範囲から不良品を外したという意味で、この文に入る正しい語。", "点火": "火をつける意味。不良品を商品から外す文には合わない。", "離陸": "飛行機などが飛び立つ意味で、商品には使えず文が通らない。", "沸騰": "液体が煮え立つ意味。商品を主語にすると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "除外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちからの誘いを、除外してきっぱり断りました。", "explanation": "ここは〈拒絶〉の意味。除外は集まりや計算から外すことで、申し出を退ける意味では使わない。"}, {"text": "壊れたケーブルを、除外して短くしました。", "explanation": "ここは〈切断〉の意味。除外は対象から外すことで、物を切って分ける意味では使わない。"}, {"text": "店に侵入した泥棒を、除外して追い返しました。", "explanation": "ここは〈撃退〉の意味。除外は集まりから外すことで、相手を打ち負かして追い払う意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
