INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36992, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ回答は、集計から除外しないません。", "corrected_sentence": "同じ回答は、集計から除外しません。", "error_description": "否定形は「除外しません」。「しないません」は「しない」と「ません」を重ねた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36993, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「対象から除外されています」の「から」は、外される範囲の起点を示す。"}, {"text": "を", "is_correct": false, "explanation": "「対象を除外されています」は受身の文で、目的語の「を」が主語の位置に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「子どもと除外されています」は並列の意味になり、受身の文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「対象へ除外されています」は方向の意味になり、除外の範囲を表せない。"}], "correct_answer": "から", "explanations": {"から": "「対象から除外されています」の「から」は、外される範囲の起点を示す。", "を": "「対象を除外されています」は受身の文で、目的語の「を」が主語の位置に合わない。", "と": "「子どもと除外されています」は並列の意味になり、受身の文に合わない。", "へ": "「対象へ除外されています」は方向の意味になり、除外の範囲を表せない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "包含", "is_correct": true, "explanation": "範囲の中に含めること。対象の範囲から外す除外の対義語で、正解。"}, {"text": "公開", "is_correct": false, "explanation": "広く知らせること。範囲に入れるかどうかの対義語ではない。"}, {"text": "配布", "is_correct": false, "explanation": "配って渡すこと。対象の範囲とは対義関係にない。"}, {"text": "連絡", "is_correct": false, "explanation": "知らせること。範囲に入れるかどうかの対義語ではない。"}], "correct_answer": "包含", "explanations": {"包含": "範囲の中に含めること。対象の範囲から外す除外の対義語で、正解。", "公開": "広く知らせること。範囲に入れるかどうかの対義語ではない。", "配布": "配って渡すこと。対象の範囲とは対義関係にない。", "連絡": "知らせること。範囲に入れるかどうかの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
