INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36993, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "仲間やグループの中に入れないこと。扱わないこと。取り除くこと。", "primary_collocate": null, "pronunciation": "じょがい", "ipa": "d͡ʑoɡai", "syllable_count": 3, "sentences": [{"text": "彼だけを仲間から除外するのは、ひどいと思います。", "target_word": "除外", "complexity_tier": "T3", "furigana": "彼[かれ]だけを仲間[なかま]から除外[じょがい]するのは、ひどいと思[おも]います。", "sentence_source": "generated"}, {"text": "子どもは、このルールの対象から除外されています。", "target_word": "除外", "complexity_tier": "T3", "furigana": "子[こ]どもは、このルールの対象[たいしょう]から除外[じょがい]されています。", "sentence_source": "generated"}, {"text": "けがをした選手は、今回の試合から除外しました。", "target_word": "除外", "complexity_tier": "T3", "furigana": "けがをした選手[せんしゅ]は、今回[こんかい]の試合[しあい]から除外[じょがい]しました。", "sentence_source": "generated"}, {"text": "特別な場合は除外して、考えましょう。", "target_word": "除外", "complexity_tier": "T3", "furigana": "特別[とくべつ]な場合[ばあい]は除外[じょがい]して、考[かんが]えましょう。", "sentence_source": "generated"}, {"text": "保険の対象から、古い建物は除外されます。", "target_word": "除外", "complexity_tier": "T3", "furigana": "保険[ほけん]の対象[たいしょう]から、古[ふる]い建物[たてもの]は除外[じょがい]されます。", "sentence_source": "generated"}, {"text": "新しいメンバーを除外せず、みんなで遊びましょう。", "target_word": "除外", "complexity_tier": "T3", "furigana": "新[あたら]しいメンバーを除外[じょがい]せず、みんなで遊[あそ]びましょう。", "sentence_source": "generated"}, {"text": "悪い点を除外すれば、この計画はとても良いです。", "target_word": "除外", "complexity_tier": "T3", "furigana": "悪[わる]い点[てん]を除外[じょがい]すれば、この計画[けいかく]はとても良[よ]いです。", "sentence_source": "generated"}, {"text": "彼女はグループから除外されて、さびしそうでした。", "target_word": "除外", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はグループから除外[じょがい]されて、さびしそうでした。", "sentence_source": "generated"}, {"text": "大人は除外して、子どもだけで話し合います。", "target_word": "除外", "complexity_tier": "T3", "furigana": "大人[おとな]は除外[じょがい]して、子[こ]どもだけで話[はな]し合[あ]います。", "sentence_source": "generated"}, {"text": "税金の対象から、食べ物は除外されています。", "target_word": "除外", "complexity_tier": "T3", "furigana": "税金[ぜいきん]の対象[たいしょう]から、食[た]べ物[もの]は除外[じょがい]されています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "除外する", "label": "辞書形"}, {"form": "除外した", "label": "過去形"}, {"form": "除外して", "label": "て形"}, {"form": "除外される", "label": "受身形"}, {"form": "除外しない", "label": "否定形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "仲間・対象の範囲から外す、取り除く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36993, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除外", "is_correct": true, "explanation": "仲間から外すという意味で、この文に入る正しい語。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味。人を仲間から外す文には合わない。"}, {"text": "着席", "is_correct": false, "explanation": "席につく意味。「仲間から着席する」は成り立たない。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物の働きで物質が変わる意味。人を仲間にする文には使えない。"}], "explanations": {"除外": "仲間から外すという意味で、この文に入る正しい語。", "点灯": "明かりをつける意味。人を仲間から外す文には合わない。", "着席": "席につく意味。「仲間から着席する」は成り立たない。", "発酵": "微生物の働きで物質が変わる意味。人を仲間にする文には使えない。"}, "sentence_index": 0, "correct_answer": "除外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前に言ったことを、除外して取り消しました。", "explanation": "ここは〈撤回〉の意味。除外は対象から外すことで、言ったことを取り消す意味では使わない。"}, {"text": "混んだ電車で、お年寄りに席を除外して譲った。", "explanation": "ここは〈席を空けて人に渡す〉の意味。除外は集まりや計算から外す意味で使い、人に席を渡す意味では使わない。"}, {"text": "祖父の大切な写真を、除外してアルバムに貼りました。", "explanation": "ここは〈貼る〉の意味。写真をアルバムに貼るのは貼る行為で、除外は集まりや計算から外す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36993, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除外", "is_correct": true, "explanation": "悪い点を外すという意味で、この文に入る正しい語。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味。悪い点を主語にすると文が成り立たない。"}, {"text": "離陸", "is_correct": false, "explanation": "飛行機などが飛び立つ意味。悪い点には使えず文が通らない。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が煮え立つ意味。悪い点に使うと文が成り立たない。"}], "explanations": {"除外": "悪い点を外すという意味で、この文に入る正しい語。", "点火": "火をつける意味。悪い点を主語にすると文が成り立たない。", "離陸": "飛行機などが飛び立つ意味。悪い点には使えず文が通らない。", "沸騰": "液体が煮え立つ意味。悪い点に使うと文が成り立たない。"}, "sentence_index": 6, "correct_answer": "除外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "頼まれた仕事を、除外して引き受けました。", "explanation": "ここは〈承諾〉の意味。頼みを受け入れる意味で、除外は対象から外す意味では使わない。"}, {"text": "レストランで、料理を除外しました。", "explanation": "ここは〈注文〉の意味。品物を頼むのは注文で、除外は集まりや計算から外す意味では使わない。"}, {"text": "新しいスマホを除外しました。", "explanation": "ここは〈購入〉の意味。お金を払って買うのは購入で、除外は対象から外す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36993, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遅刻した人は、今日の練習から除外れました。", "corrected_sentence": "遅刻した人は、今日の練習から除外されました。", "error_description": "受身の「除外される」が正しい。「除外れ」は「さ」が抜けた誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36993, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い記録は、今回のデータから除外くて数えます。", "corrected_sentence": "古い記録は、今回のデータから除外して数えます。", "error_description": "「除外する」のて形は「除外して」。「除外くて」は形容詞のて形を当てはめた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「材料」を主語にして、「足りない」と述べる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「足りない」は主語を取る形で、「を」では続かない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」。「材料で足りない」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「材料へ足りない」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「材料」を主語にして、「足りない」と述べる。", "を": "目的語の「を」。「足りない」は主語を取る形で、「を」では続かない。", "で": "場所や手段を示す「で」。「材料で足りない」は成り立たない。", "へ": "方向を示す「へ」。「材料へ足りない」は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「こだわる」が向かう対象を示す「に」。「材料にこだわる」と自然に続く。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「新鮮な材料のこだわって」とは続かない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。「材料とこだわって」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「材料からこだわって」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「こだわる」が向かう対象を示す「に」。「材料にこだわる」と自然に続く。", "の": "連体修飾の「の」。「新鮮な材料のこだわって」とは続かない。", "と": "並列や相手を示す「と」。「材料とこだわって」は意味が通らない。", "から": "起点を示す「から」。「材料からこだわって」は成り立たない。"}, "error_tags": {"の": "連体修飾", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かを作るときに使うもの。", "primary_collocate": null, "pronunciation": "ざいりょう", "ipa": "dzaiɾjoː", "syllable_count": 4, "sentences": [{"text": "カレーの材料を買いに、スーパーへ行きました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "カレーの材料[ざいりょう]を買[か]いに、スーパーへ行[い]きました。", "sentence_source": "generated"}, {"text": "材料が足りないので、ケーキは作れません。", "target_word": "材料", "complexity_tier": "T3", "furigana": "材料[ざいりょう]が足[た]りないので、ケーキは作[つく]れません。", "sentence_source": "generated"}, {"text": "紙と布など、工作の材料を机に並べました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "紙[かみ]と布[ぬの]など、工作[こうさく]の材料[ざいりょう]を机[つくえ]に並[なら]べました。", "sentence_source": "generated"}, {"text": "このお菓子の材料は、小麦粉と卵と砂糖だけです。", "target_word": "材料", "complexity_tier": "T3", "furigana": "このお菓子[かし]の材料[ざいりょう]は、小麦粉[こむぎこ]と卵[たまご]と砂糖[さとう]だけです。", "sentence_source": "generated"}, {"text": "料理の前に、必要な材料をすべて切っておきます。", "target_word": "材料", "complexity_tier": "T3", "furigana": "料理[りょうり]の前[まえ]に、必要[ひつよう]な材料[ざいりょう]をすべて切[き]っておきます。", "sentence_source": "generated"}, {"text": "手作りのマフラーの材料は、毛糸だけで十分です。", "target_word": "材料", "complexity_tier": "T3", "furigana": "手作[てづく]りのマフラーの材料[ざいりょう]は、毛糸[けいと]だけで十分[じゅうぶん]です。", "sentence_source": "generated"}, {"text": "材料はすべて近くの店で買えるので、簡単です。", "target_word": "材料", "complexity_tier": "T3", "furigana": "材料[ざいりょう]はすべて近[ちか]くの店[みせ]で買[か]えるので、簡単[かんたん]です。", "sentence_source": "generated"}, {"text": "母は新鮮な材料にこだわって、毎日料理しています。", "target_word": "材料", "complexity_tier": "T3", "furigana": "母[はは]は新鮮[しんせん]な材料[ざいりょう]にこだわって、毎日[まいにち]料理[りょうり]しています。", "sentence_source": "generated"}, {"text": "石けんを作る材料を、ネットで注文しました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "石[せっ]けんを作[つく]る材料[ざいりょう]を、ネットで注文[ちゅうもん]しました。", "sentence_source": "generated"}, {"text": "材料を量ってから、ボウルに順番に入れてください。", "target_word": "材料", "complexity_tier": "T3", "furigana": "材料[ざいりょう]を量[はか]ってから、ボウルに順番[じゅんばん]に入[い]れてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "材料", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ingredients or supplies: the things you gather to cook or craft something by hand", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "材料", "is_correct": true, "explanation": "料理に使う食材で、買いに行く対象として自然。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るときに使う道具で、カレーの材料ではない。"}, {"text": "機械", "is_correct": false, "explanation": "装置を表す語で、カレーの材料として買いに行く物ではない。"}, {"text": "保険", "is_correct": false, "explanation": "契約の一種で、「カレーの保険」とは言えず意味が通らない。"}], "explanations": {"材料": "料理に使う食材で、買いに行く対象として自然。", "寝具": "寝るときに使う道具で、カレーの材料ではない。", "機械": "装置を表す語で、カレーの材料として買いに行く物ではない。", "保険": "契約の一種で、「カレーの保険」とは言えず意味が通らない。"}, "sentence_index": 0, "correct_answer": "材料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社には、優秀な材料が必要です。", "explanation": "ここは〈人材〉（能力を持つ人）の意味。材料は物の素材で、人の能力を表さない。"}, {"text": "毎日、栄養のある材料をとります。", "explanation": "ここは〈食事〉の意味。材料は料理の素材で、食べる行為そのものを表さない。"}, {"text": "大工さんが、材料を手入れしています。", "explanation": "ここは〈道具〉（繰り返し使う工具）の意味。材料は使って消える素材で、手入れの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "材料", "is_correct": true, "explanation": "店で買える対象として自然で、「材料はすべて〜で買える」と合う。"}, {"text": "天気", "is_correct": false, "explanation": "空の様子を表す語で、店で買えるものではない。"}, {"text": "寝室", "is_correct": false, "explanation": "寝るための部屋を表す語で、店で買えるものではない。"}, {"text": "住所", "is_correct": false, "explanation": "居場所を示す語で、店で買えるものではない。"}], "explanations": {"材料": "店で買える対象として自然で、「材料はすべて〜で買える」と合う。", "天気": "空の様子を表す語で、店で買えるものではない。", "寝室": "寝るための部屋を表す語で、店で買えるものではない。", "住所": "居場所を示す語で、店で買えるものではない。"}, "sentence_index": 6, "correct_answer": "材料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓の外の美しい材料を描きます。", "explanation": "ここは〈風景〉の意味。材料は素材で、描く対象としての景色を表さない。"}, {"text": "彼の悲しい材料が伝わってきました。", "explanation": "ここは〈感情〉の意味。材料は物の素材で、人の気持ちは表さない。"}, {"text": "友人の材料を撮りました。", "explanation": "ここは〈写真〉（撮って残す画像）の意味。材料は素材で、撮影の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕食を作る材料が、冷蔵庫から出しました。", "corrected_sentence": "夕食を作る材料を、冷蔵庫から出しました。", "error_description": "「材料が」は誤り。正しくは「材料を」。「出す」は取り出す対象を「を」で示す他動詞なので、「が」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36994, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作る前に、材料を食べておきます。", "corrected_sentence": "作る前に、材料をそろえておきます。", "error_description": "「食べておきます」は誤り。正しくは「そろえておきます」。材料は食べる物ではなく、作る前に集めて揃える対象なので、「そろえる」と組む。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜になる」は変化の結果を表す形で、「車の材料になる鉄」の「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「材料がなる」は成り立たず、「なる」の前には置けない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「なる」は目的語を取らないため「材料を〜になる」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「材料でなる」は成り立たず、「なる」と結びつかない。"}], "correct_answer": "に", "explanations": {"に": "「〜になる」は変化の結果を表す形で、「車の材料になる鉄」の「に」が正しい。", "が": "「が」は主語を示すが、「材料がなる」は成り立たず、「なる」の前には置けない。", "を": "「を」は目的語を示すが、「なる」は目的語を取らないため「材料を〜になる」は成立しない。", "で": "「で」は手段や場所を示すが、「材料でなる」は成り立たず、「なる」と結びつかない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「材料で作られる」の「で」は、材料や手段を示す。この文の正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「材料と作られる」では材料を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「材料へ作られる」では材料の位置関係を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞同士を結ぶが、「材料の作られています」では述語との関係が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「材料で作られる」の「で」は、材料や手段を示す。この文の正しい助詞。", "と": "「と」は並列や相手を示すが、「材料と作られる」では材料を示せず不自然。", "へ": "「へ」は方向を示すが、「材料へ作られる」では材料の位置関係を表せない。", "の": "「の」は名詞同士を結ぶが、「材料の作られています」では述語との関係が成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を作るために必要な原料や部品のこと。", "primary_collocate": null, "pronunciation": "ざいりょう", "ipa": "dzaiɾjoː", "syllable_count": 4, "sentences": [{"text": "この椅子の材料は、軽くて丈夫な木です。", "target_word": "材料", "complexity_tier": "T3", "furigana": "この椅子[いす]の材料[ざいりょう]は、軽[かる]くて丈夫[じょうぶ]な木[き]です。", "sentence_source": "generated"}, {"text": "工場では、車の材料になる鉄を大量に使います。", "target_word": "材料", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、車[くるま]の材料[ざいりょう]になる鉄[てつ]を大量[たいりょう]に使[つか]います。", "sentence_source": "generated"}, {"text": "建物の材料の値段が上がって、工事費が高くなりました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "建物[たてもの]の材料[ざいりょう]の値段[ねだん]が上[あ]がって、工事費[こうじひ]が高[たか]くなりました。", "sentence_source": "generated"}, {"text": "プラスチックは、さまざまな製品の材料として使われます。", "target_word": "材料", "complexity_tier": "T3", "furigana": "プラスチックは、さまざまな製品[せいひん]の材料[ざいりょう]として使[つか]われます。", "sentence_source": "generated"}, {"text": "新しい服を作るため、会社は布の材料になる綿を外国から輸入しています。", "target_word": "材料", "complexity_tier": "T3", "furigana": "新[あたら]しい服[ふく]を作[つく]るため、会社[かいしゃ]は布[ぬの]の材料[ざいりょう]になる綿[わた]を外国[がいこく]から輸入[ゆにゅう]しています。", "sentence_source": "generated"}, {"text": "材料が届かなかったので、機械の組み立てが遅れました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "材料[ざいりょう]が届[とど]かなかったので、機械[きかい]の組[く]み立[た]てが遅[おく]れました。", "sentence_source": "generated"}, {"text": "古い新聞紙を、紙の材料として再利用します。", "target_word": "材料", "complexity_tier": "T3", "furigana": "古[ふる]い新聞紙[しんぶんし]を、紙[かみ]の材料[ざいりょう]として再利用[さいりよう]します。", "sentence_source": "generated"}, {"text": "この橋は、さびにくい材料で作られています。", "target_word": "材料", "complexity_tier": "T3", "furigana": "この橋[はし]は、さびにくい材料[ざいりょう]で作[つく]られています。", "sentence_source": "generated"}, {"text": "家の材料には、地元の木が選ばれました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "家[いえ]の材料[ざいりょう]には、地元[じもと]の木[き]が選[えら]ばれました。", "sentence_source": "generated"}, {"text": "製品の材料を変えたら、値段を安くできました。", "target_word": "材料", "complexity_tier": "T3", "furigana": "製品[せいひん]の材料[ざいりょう]を変[か]えたら、値段[ねだん]を安[やす]くできました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "材料", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "raw material: the stuff or parts from which a manufactured or built product is made", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ccc050-8e2e-4945-adb4-0419425842d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "天候を表す語で、椅子を構成するものの意味では空欄に入らない。"}, {"text": "材料", "is_correct": true, "explanation": "椅子を作る原料を指す語。空欄に入るのはこの語だけ。"}, {"text": "工具", "is_correct": false, "explanation": "作業に使う道具のことで、椅子の素材としては成り立たない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を送る仕組みを指し、椅子の構成とは無関係。"}], "explanations": {"天気": "天候を表す語で、椅子を構成するものの意味では空欄に入らない。", "材料": "椅子を作る原料を指す語。空欄に入るのはこの語だけ。", "工具": "作業に使う道具のことで、椅子の素材としては成り立たない。", "郵便": "手紙や荷物を送る仕組みを指し、椅子の構成とは無関係。"}, "sentence_index": 0, "correct_answer": "材料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火事の材料は、ストーブの消し忘れだと警察は言った。", "explanation": "ここは〈原因〉の意味。火事の原因を言うなら「原因」と言い、材料（原料）とは言わないので合わない。"}, {"text": "この車は材料が切れてしまい、途中で動かなくなった。", "explanation": "ここは〈燃料〉の意味。車を動かすのは燃料で、物を作る原料の材料とは合わない。"}, {"text": "リモコンの材料が切れたので、ボタンを押しても反応しなくなった。", "explanation": "ここは〈電池〉の意味。リモコンが動かなくなるのは電池の切れが原因で、材料（原料）とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "機械", "is_correct": false, "explanation": "動力で動く装置の意味で、古い新聞紙を紙として再利用する文脈には入らない。"}, {"text": "照明", "is_correct": false, "explanation": "明かりを出す器具のことで、紙の代わりに再利用するという意味にはならない。"}, {"text": "材料", "is_correct": true, "explanation": "紙を作る原料を指す語。古い新聞紙を紙の原料として再利用するという意味に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "扉や錠を開ける道具で、紙の原料としての再利用とは無関係。"}], "explanations": {"機械": "動力で動く装置の意味で、古い新聞紙を紙として再利用する文脈には入らない。", "照明": "明かりを出す器具のことで、紙の代わりに再利用するという意味にはならない。", "材料": "紙を作る原料を指す語。古い新聞紙を紙の原料として再利用するという意味に合う。", "鍵": "扉や錠を開ける道具で、紙の原料としての再利用とは無関係。"}, "sentence_index": 6, "correct_answer": "材料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大工は、のこぎりという材料で木を切った。", "explanation": "ここは〈道具〉の意味。のこぎりは木を切るための道具で、物を作る原料の材料とは言わない。"}, {"text": "春になったので、庭に花の材料をまいた。", "explanation": "ここは〈種〉の意味。庭にまくのは種であり、材料（原料）をまくとは言わない。"}, {"text": "工場の材料が故障して、生産が止まった。", "explanation": "ここは〈機械〉の意味。故障するのは機械で、材料（原料）は故障しないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この机の材料に、軽くて丈夫な鉄です。", "corrected_sentence": "この机の材料は、軽くて丈夫な鉄です。", "error_description": "正しくは「材料は」。主題を示す「は」が必要で、「に」は方向や対象を示すため、この文では不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36995, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い缶を、アルミの材料で再利用します。", "corrected_sentence": "古い缶を、アルミの材料として再利用します。", "error_description": "正しくは「材料として」。役割を示す「として」が必要で、「で」は手段や場所を示すため、「再利用する」の役割を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22ee7b7c-1355-4a71-bbb0-01c83d1e4d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
