INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36997, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものが向かい合うこと。また、比べること。対応すること。", "primary_collocate": null, "pronunciation": "たい", "ipa": "tai", "syllable_count": 2, "sentences": [{"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。", "target_word": "対", "complexity_tier": "T3", "furigana": "次[つぎ]いで、ラズベリー等[とう]のジャムを対[つい]になる片割[かたわ]れ、あるいは同一[どういつ]の切片上[せっぺんじょう]に重[かさ]ね合[あ]わせる。", "sentence_source": "generated"}, {"text": "今日の試合は、日本対ブラジルで、とても盛り上がった。", "target_word": "対", "complexity_tier": "T3", "furigana": "今日[きょう]の試合[しあい]は、日本[にほん]対[たい]ブラジルで、とても盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "この映画は、人間対自然の戦いを描いている。", "target_word": "対", "complexity_tier": "T3", "furigana": "この映画[えいが]は、人間[にんげん]対[たい]自然[しぜん]の戦[たたか]いを描[えが]いている。", "sentence_source": "generated"}, {"text": "赤組対白組のリレーは、最後まで勝負がわからなかった。", "target_word": "対", "complexity_tier": "T3", "furigana": "赤組[あかぐみ]対[たい]白組[しろぐみ]のリレーは、最後[さいご]まで勝負[しょうぶ]がわからなかった。", "sentence_source": "generated"}, {"text": "決勝戦は、三対二でうちのチームが勝った。", "target_word": "対", "complexity_tier": "T3", "furigana": "決勝戦[けっしょうせん]は、三[さん]対[たい]二[に]でうちのチームが勝[か]った。", "sentence_source": "generated"}, {"text": "会議では、賛成対反対の意見がはっきり分かれた。", "target_word": "対", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、賛成[さんせい]対[たい]反対[はんたい]の意見[いけん]がはっきり分[わ]かれた。", "sentence_source": "generated"}, {"text": "物語は、理想対現実のぶつかり合いを軸に進む。", "target_word": "対", "complexity_tier": "T3", "furigana": "物語[ものがたり]は、理想[りそう]対[たい]現実[げんじつ]のぶつかり合[あ]いを軸[じく]に進[すす]む。", "sentence_source": "generated"}, {"text": "裁判は、原告対被告の形で争われた。", "target_word": "対", "complexity_tier": "T3", "furigana": "裁判[さいばん]は、原告[げんこく]対[たい]被告[ひこく]の形[かたち]で争[あらそ]われた。", "sentence_source": "generated"}, {"text": "この大会は、東軍対西軍に分かれて競う。", "target_word": "対", "complexity_tier": "T3", "furigana": "この大会[たいかい]は、東軍[とうぐん]対[たい]西軍[せいぐん]に分[わ]かれて競[きそ]う。", "sentence_source": "generated"}, {"text": "天才対努力家の勝負として注目された。", "target_word": "対", "complexity_tier": "T3", "furigana": "天才[てんさい]対[たい]努力家[どりょくか]の勝負[しょうぶ]として注目[ちゅうもく]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "二つのものが向かい合う関係。「AたいB」の形で、対戦や対立を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 切片 (Zipf 1.86)']::text[], 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36997, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対", "is_correct": true, "explanation": "「対になる」で、二つで一組になる片割れを表す。文の意味に合う。"}, {"text": "面", "is_correct": false, "explanation": "「面になる」は成り立たず、片割れの関係を表さないので合わない。"}, {"text": "外", "is_correct": false, "explanation": "「外になる」は不自然で、対になる相手の意味にならない。"}, {"text": "間", "is_correct": false, "explanation": "「間になる」は場所を表す語で、組になる片割れの意味にはならない。"}], "explanations": {"対": "「対になる」で、二つで一組になる片割れを表す。文の意味に合う。", "面": "「面になる」は成り立たず、片割れの関係を表さないので合わない。", "外": "「外になる」は不自然で、対になる相手の意味にならない。", "間": "「間になる」は場所を表す語で、組になる片割れの意味にはならない。"}, "sentence_index": 0, "correct_answer": "対"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議では、対の声が上がり、計画は中止になった。", "explanation": "ここは〈反対〉の意味。〈対〉は向かい合う・比べるという意味で、反対する声の意味にはならないので、〈反対〉と言う。"}, {"text": "二人は対の立場で話し合った。", "explanation": "ここは〈対等〉の意味。〈対〉は向かい合う・比べるという意味で、対等な関係は表さないので合わない。"}, {"text": "地震への対を考えて、非常袋を用意した。", "explanation": "ここは〈対策〉の意味。〈対〉は向かい合う・比べることで、〈対策〉の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36997, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対", "is_correct": true, "explanation": "「理想対現実」で、向かい合って対立する二つを表し、文の意味に合う。"}, {"text": "内", "is_correct": false, "explanation": "「理想内現実」は成り立たず、ぶつかり合う二つを表さないので合わない。"}, {"text": "元", "is_correct": false, "explanation": "「理想元現実」は不自然で、対立する二つをつなぐ語にならない。"}, {"text": "側", "is_correct": false, "explanation": "「理想側現実」は意味が通らず、二つの対立の関係を表さない。"}], "explanations": {"対": "「理想対現実」で、向かい合って対立する二つを表し、文の意味に合う。", "内": "「理想内現実」は成り立たず、ぶつかり合う二つを表さないので合わない。", "元": "「理想元現実」は不自然で、対立する二つをつなぐ語にならない。", "側": "「理想側現実」は意味が通らず、二つの対立の関係を表さない。"}, "sentence_index": 6, "correct_answer": "対"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "調査の対は、十八歳以上の男女だ。", "explanation": "ここは〈対象〉（調べる相手・目的）の意味。〈対〉は向かい合う・比べるという意味で、調べる対象は表さないので合わない。"}, {"text": "二つの案には大きな対がある。", "explanation": "ここは〈相違〉（違い）の意味。〈対〉は比べる組み合わせを表し、違いそのものは表さないので合わない。"}, {"text": "映画の対を友達と話した。", "explanation": "ここは〈感想〉（見て感じたこと）の意味。〈対〉は向かい合う・比べることで、感じたことは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36997, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その試合は三対一に勝った。", "corrected_sentence": "その試合は三対一で勝った。", "error_description": "スコアを表す「三対一」に続く助詞が誤り。正しくは「で」で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36997, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩対応後輩の練習試合が、雨で中止になった。", "corrected_sentence": "先輩対後輩の練習試合が、雨で中止になった。", "error_description": "対戦を表す「対」を「対応」と取り違えている。正しくは「対」で、「対応」は別の語のため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「窒素がないと」の「が」は、ない（存在しないこと）の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「窒素をないと」は、ない（形容詞）に目的語が続かないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「窒素にないと」は位置を示す「に」で、ない（形容詞）の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「窒素へないと」は方向を示すが、存在の否定には合わない。"}], "correct_answer": "が", "explanations": {"が": "「窒素がないと」の「が」は、ない（存在しないこと）の主語を示す。", "を": "「窒素をないと」は、ない（形容詞）に目的語が続かないので不自然。", "に": "「窒素にないと」は位置を示す「に」で、ない（形容詞）の主語にはならない。", "へ": "「窒素へないと」は方向を示すが、存在の否定には合わない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気の中にたくさんある、生き物や植物に必要な気体です。", "primary_collocate": null, "pronunciation": "ちっそ", "ipa": "t͡ɕisso", "syllable_count": 3, "sentences": [{"text": "空気の中には、窒素がたくさんあります。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "空気[くうき]の中[なか]には、窒素[ちっそ]がたくさんあります。", "sentence_source": "generated"}, {"text": "植物は、窒素がないと元気に育ちません。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は、窒素[ちっそ]がないと元気[げんき]に育[そだ]ちません。", "sentence_source": "generated"}, {"text": "空気の約八割は、窒素です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "空気[くうき]の約[やく]八割[はちわり]は、窒素[ちっそ]です。", "sentence_source": "generated"}, {"text": "窒素は見えませんが、私たちのまわりにあります。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]は見[み]えませんが、私[わたし]たちのまわりにあります。", "sentence_source": "generated"}, {"text": "畑の土に窒素が足りないと、野菜が小さくなります。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "畑[はたけ]の土[つち]に窒素[ちっそ]が足[た]りないと、野菜[やさい]が小[ちい]さくなります。", "sentence_source": "generated"}, {"text": "動物の体にも、窒素は必要です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の体[からだ]にも、窒素[ちっそ]は必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "私たちは毎日、空気といっしょに窒素を吸っています。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "私[わたし]たちは毎日[まいにち]、空気[くうき]といっしょに窒素[ちっそ]を吸[す]っています。", "sentence_source": "generated"}, {"text": "理科の授業で、空気の中の窒素について習いました。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、空気[くうき]の中[なか]の窒素[ちっそ]について習[なら]いました。", "sentence_source": "generated"}, {"text": "葉の色が悪いのは、窒素が足りないからです。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "葉[は]の色[いろ]が悪[わる]いのは、窒素[ちっそ]が足[た]りないからです。", "sentence_source": "generated"}, {"text": "窒素は空気の主な成分で、植物にも大切です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]は空気[くうき]の主[おも]な成分[せいぶん]で、植物[しょくぶつ]にも大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "窒素", "label": "基本形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "空気に多く、植物や生き物に必要な気体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窒素", "is_correct": true, "explanation": "空気に多く含まれる気体のことで、この文に入る正しい語。"}, {"text": "砂糖", "is_correct": false, "explanation": "食べ物の一種で、空気の中に多くあるものではないので文が不自然。"}, {"text": "石油", "is_correct": false, "explanation": "燃料になる液体で、空気の中に多くあるものではない。"}, {"text": "鉄", "is_correct": false, "explanation": "金属で、空気の中に気体として多くあるものではない。"}], "explanations": {"窒素": "空気に多く含まれる気体のことで、この文に入る正しい語。", "砂糖": "食べ物の一種で、空気の中に多くあるものではないので文が不自然。", "石油": "燃料になる液体で、空気の中に多くあるものではない。", "鉄": "金属で、空気の中に気体として多くあるものではない。"}, "sentence_index": 0, "correct_answer": "窒素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体の細胞は、窒素を燃やしてエネルギーを作っています。", "explanation": "ここは〈酸素〉の意味。細胞のエネルギーに必要なのは酸素で、窒素は燃えないので合わない。"}, {"text": "料理の味を整えるため、窒素を少し入れました。", "explanation": "ここは〈塩〉の意味。料理の味を整えるのは塩で、窒素は味付けに使わないので合わない。"}, {"text": "木が燃えると、窒素が二酸化炭素に変わります。", "explanation": "ここは〈炭素〉の意味。燃えて二酸化炭素になるのは炭素で、窒素の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窒素", "is_correct": true, "explanation": "空気と一緒に吸うものとして、この文に入る正しい語。"}, {"text": "教科書", "is_correct": false, "explanation": "読むための本で、吸うものではないので文が成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "体を洗うための物で、空気と一緒に吸うものではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "字を書く道具で、吸うものではないので文が成り立たない。"}], "explanations": {"窒素": "空気と一緒に吸うものとして、この文に入る正しい語。", "教科書": "読むための本で、吸うものではないので文が成り立たない。", "石鹸": "体を洗うための物で、空気と一緒に吸うものではない。", "鉛筆": "字を書く道具で、吸うものではないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "窒素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プールの水を消毒するために、窒素を入れています。", "explanation": "ここは〈塩素〉の意味。プールの消毒に使うのは塩素で、窒素は消毒には使わない。"}, {"text": "温泉から、窒素の独特のにおいがします。", "explanation": "ここは〈硫黄〉の意味。温泉の独特のにおいは硫黄によるもので、窒素は無臭なので合わない。"}, {"text": "料理の味をととのえるために、窒素を少し入れます。", "explanation": "ここは〈塩〉の意味。料理の味を整えるのは塩で、窒素は味付けには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土は窒素を多いと、野菜がよく育ちます。", "corrected_sentence": "土は窒素が多いと、野菜がよく育ちます。", "error_description": "「窒素が多い」の主語は「が」。「を」は形容詞「多い」の主語には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36998, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "植物は、根から窒素を吸収ます。", "corrected_sentence": "植物は、根から窒素を吸収します。", "error_description": "「吸収します」が正しい。「吸収ます」は「し」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「窒素と酸素」の「と」は、二つの物質を並べる並列の「と」。"}, {"text": "が", "is_correct": false, "explanation": "「窒素が酸素は」と主語が重なり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「窒素を酸素は」は目的語の「を」が主語に続かず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「窒素の酸素は」は連体の「の」で、並列の意味にならない。"}], "correct_answer": "と", "explanations": {"と": "「窒素と酸素」の「と」は、二つの物質を並べる並列の「と」。", "が": "「窒素が酸素は」と主語が重なり、文が成り立たない。", "を": "「窒素を酸素は」は目的語の「を」が主語に続かず、不自然。", "の": "「窒素の酸素は」は連体の「の」で、並列の意味にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体・所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気中に多く含まれる無色・無臭の気体で、生物の体を作るタンパク質の成分として重要です。", "primary_collocate": null, "pronunciation": "ちっそ", "ipa": "t͡ɕisso", "syllable_count": 3, "sentences": [{"text": "窒素は色もにおいもない気体です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]は色[いろ]もにおいもない気体[きたい]です。", "sentence_source": "generated"}, {"text": "窒素は、タンパク質を作る大切な成分です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]は、タンパク質[たんぱくしつ]を作[つく]る大切[たいせつ]な成分[せいぶん]です。", "sentence_source": "generated"}, {"text": "空気の大部分は、無色の窒素です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "空気[くうき]の大部分[だいぶぶん]は、無色[むしょく]の窒素[ちっそ]です。", "sentence_source": "generated"}, {"text": "窒素はにおいがないので、そばにあっても気づきません。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]はにおいがないので、そばにあっても気[き]づきません。", "sentence_source": "generated"}, {"text": "先生は窒素の性質を、実験で説明しました。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "先生[せんせい]は窒素[ちっそ]の性質[せいしつ]を、実験[じっけん]で説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "肉や魚のタンパク質には、窒素が含まれています。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "肉[にく]や魚[さかな]のタンパク質[たんぱくしつ]には、窒素[ちっそ]が含[ふく]まれています。", "sentence_source": "generated"}, {"text": "窒素の中では、火が消えてしまいます。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]の中[なか]では、火[ひ]が消[き]えてしまいます。", "sentence_source": "generated"}, {"text": "窒素と酸素は、空気の主な成分です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]と酸素[さんそ]は、空気[くうき]の主[おも]な成分[せいぶん]です。", "sentence_source": "generated"}, {"text": "体を作るには、窒素を含む栄養が必要です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "体[からだ]を作[つく]るには、窒素[ちっそ]を含[ふく]む栄養[えいよう]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "窒素は他の物質と反応しにくい気体です。", "target_word": "窒素", "complexity_tier": "T3", "furigana": "窒素[ちっそ]は他[ほか]の物質[ぶっしつ]と反応[はんのう]しにくい気体[きたい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "窒素", "label": "基本形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "無色無臭の気体で、タンパク質の成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窒素", "is_correct": true, "explanation": "色もにおいもない気体のことで、この文の主語に入る正しい語。"}, {"text": "鉄", "is_correct": false, "explanation": "金属で、色もにおいもない気体ではないので文が成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "体を洗う固形の物で、気体ではないので文が合わない。"}, {"text": "木材", "is_correct": false, "explanation": "建材などに使う固体で、気体ではないので文が成り立たない。"}], "explanations": {"窒素": "色もにおいもない気体のことで、この文の主語に入る正しい語。", "鉄": "金属で、色もにおいもない気体ではないので文が成り立たない。", "石鹸": "体を洗う固形の物で、気体ではないので文が合わない。", "木材": "建材などに使う固体で、気体ではないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "窒素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プールの消毒には、窒素を水に溶かして使います。", "explanation": "ここは〈塩素〉の意味。プールの消毒に使うのは塩素で、窒素は消毒の働きがないので合わない。"}, {"text": "料理の味を整えるため、窒素を少し入れました。", "explanation": "ここは〈塩〉の意味。料理の味を整えるのは塩で、窒素は味付けに使わないので合わない。"}, {"text": "火山の近くでは、卵のような強いにおいの窒素が漂っています。", "explanation": "ここは〈硫黄〉の意味。卵のような強いにおいは硫黄によるもので、窒素は無臭なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窒素", "is_correct": true, "explanation": "火が消える気体の雰囲気を作るものとして、この文に入る正しい語。"}, {"text": "教科書", "is_correct": false, "explanation": "読むための本で、火を消す気体ではないので文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "字を書く道具で、火が消える場所を表さない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "文字を消す道具で、火が消える場所を表さないので文が成り立たない。"}], "explanations": {"窒素": "火が消える気体の雰囲気を作るものとして、この文に入る正しい語。", "教科書": "読むための本で、火を消す気体ではないので文が成り立たない。", "鉛筆": "字を書く道具で、火が消える場所を表さない。", "消しゴム": "文字を消す道具で、火が消える場所を表さないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "窒素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窒素は他の物質と反応しやすい気体です。", "explanation": "ここは〈酸素〉の意味。酸素は他の物質と反応しやすく、窒素は反応しにくいので合わない。"}, {"text": "窒素は、火をつけると燃えやすい気体です。", "explanation": "ここは〈水素〉の意味。燃えやすいのは水素で、窒素は燃えにくいので合わない。"}, {"text": "窒素は、ダイヤモンドや鉛筆の芯になります。", "explanation": "ここは〈炭素〉の意味。ダイヤモンドや鉛筆の芯になるのは炭素で、窒素の性質とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空気の中には、窒素を多く含まれています。", "corrected_sentence": "空気の中には、窒素が多く含まれています。", "error_description": "「含まれています」は「窒素が」を取る。「窒素を」は受身の文の主語に目的格を使った誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36999, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窒素の、冷やすと液体になります。", "corrected_sentence": "窒素は、冷やすと液体になります。", "error_description": "「窒素は」の「は」を「の」にした誤り。「窒素の、冷やすと…」は主語として文を続けられず、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
