INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37000, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人数の比を」の「を」。比は表にまとめる対象なので、直後に目的語の「を」が付く。"}, {"text": "に", "is_correct": false, "explanation": "到達・位置の「に」を入れると「比に、表にまとめました」となり、まとめる対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」を入れると「比が表にまとめました」となり、比が作業主体になって不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」を入れると「比より表にまとめました」となり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「人数の比を」の「を」。比は表にまとめる対象なので、直後に目的語の「を」が付く。", "に": "到達・位置の「に」を入れると「比に、表にまとめました」となり、まとめる対象を示せない。", "が": "主語の「が」を入れると「比が表にまとめました」となり、比が作業主体になって不自然。", "より": "比較の「より」を入れると「比より表にまとめました」となり、文が成り立たない。"}, "error_tags": {"に": "到達・位置", "が": "主語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37000, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ふたつのものをくらべるときに、どちらがどれだけ多いかを表す言い方です。", "primary_collocate": null, "pronunciation": "ひ", "ipa": "çi", "syllable_count": 1, "sentences": [{"text": "男の子と女の子の比は、二対三です。", "target_word": "比", "complexity_tier": "T3", "furigana": "男[おとこ]の子[こ]と女[おんな]の子[こ]の比[ひ]は、二[に]対[たい]三[さん]です。", "sentence_source": "generated"}, {"text": "犬と猫の数の比は、三対一です。", "target_word": "比", "complexity_tier": "T3", "furigana": "犬[いぬ]と猫[ねこ]の数[かず]の比[ひ]は、三[さん]対[たい]一[いち]です。", "sentence_source": "generated"}, {"text": "去年と今年の水の量の比を調べました。", "target_word": "比", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]の水[みず]の量[りょう]の比[ひ]を調[しら]べました。", "sentence_source": "generated"}, {"text": "兄と私の身長の比は、およそ四対三です。", "target_word": "比", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]の身長[しんちょう]の比[ひ]は、およそ四[よん]対[たい]三[さん]です。", "sentence_source": "generated"}, {"text": "赤い玉と白い玉の比は、一対二です。", "target_word": "比", "complexity_tier": "T3", "furigana": "赤[あか]い玉[たま]と白[しろ]い玉[たま]の比[ひ]は、一[いち]対[たい]二[に]です。", "sentence_source": "generated"}, {"text": "冬の北国では、昼と夜の長さの比が一対二に近づきます。", "target_word": "比", "complexity_tier": "T3", "furigana": "冬[ふゆ]の北国[きたぐに]では、昼[ひる]と夜[よる]の長[なが]さの比[ひ]が一[いち]対[たい]二[に]に近[ちか]づきます。", "sentence_source": "generated"}, {"text": "この町の大人と子どもの比は、七対三です。", "target_word": "比", "complexity_tier": "T3", "furigana": "この町[まち]の大人[おとな]と子[こ]どもの比[ひ]は、七[なな]対[たい]三[さん]です。", "sentence_source": "generated"}, {"text": "二つのクラスの人数の比を、表にまとめました。", "target_word": "比", "complexity_tier": "T3", "furigana": "二[ふた]つのクラスの人数[にんずう]の比[ひ]を、表[ひょう]にまとめました。", "sentence_source": "generated"}, {"text": "砂糖と塩の量の比が、レシピと違います。", "target_word": "比", "complexity_tier": "T3", "furigana": "砂糖[さとう]と塩[しお]の量[りょう]の比[ひ]が、レシピと違[ちが]います。", "sentence_source": "generated"}, {"text": "この学校の日本人と外国人の比は、九対一です。", "target_word": "比", "complexity_tier": "T3", "furigana": "この学校[がっこう]の日本人[にほんじん]と外国人[がいこくじん]の比[ひ]は、九[きゅう]対[たい]一[いち]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比", "label": "基本形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "二つの数を比べて、どちらがどれだけ多いかを示す言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37000, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比", "is_correct": true, "explanation": "二つの数量を比べる関係を表す「比」が入り、「男の子と女の子の比は、二対三です」と自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "「男の子と女の子の色は、二対三です」は意味をなさず、人数の割合を述べる文に合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は数量の割合で表すものではなく、「二対三の味」は成り立たない。"}, {"text": "温度", "is_correct": false, "explanation": "温度は人数どうしの割合を表す対象ではなく、文の意味が通らない。"}], "explanations": {"比": "二つの数量を比べる関係を表す「比」が入り、「男の子と女の子の比は、二対三です」と自然に続く。", "色": "「男の子と女の子の色は、二対三です」は意味をなさず、人数の割合を述べる文に合わない。", "味": "味は数量の割合で表すものではなく、「二対三の味」は成り立たない。", "温度": "温度は人数どうしの割合を表す対象ではなく、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "男の子と女の子の比は、二人です。", "explanation": "比は二つの量の割合を表す語なので、人数そのものを示す「二人」とは言えない。"}, {"text": "夏は比が長くて、夜が短いです。", "explanation": "ここは〈日〉(ひ・昼の時間)の意味。比は二つの量の割合を表すので、昼の長さには使わない。"}, {"text": "チームの中で、彼の比は大きいです。", "explanation": "「比」単独には「重要さ・影響の大きさ」の意味はなく、その意味は「比重」という別の語が担う。比は二つの量の割合を表すので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37000, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比", "is_correct": true, "explanation": "「大人と子どもの比は、七対三です」と、人数の割合を表す「比」が自然に入る。"}, {"text": "香り", "is_correct": false, "explanation": "「大人と子どもの香りは、七対三です」は人数の割合を述べる文として成り立たない。"}, {"text": "手触り", "is_correct": false, "explanation": "手触りは数量の割合で表せないので、「七対三です」と続けると意味が通らない。"}, {"text": "音", "is_correct": false, "explanation": "音は人数の割合の対象ではなく、「大人と子どもの音は、七対三です」は文として不自然。"}], "explanations": {"比": "「大人と子どもの比は、七対三です」と、人数の割合を表す「比」が自然に入る。", "香り": "「大人と子どもの香りは、七対三です」は人数の割合を述べる文として成り立たない。", "手触り": "手触りは数量の割合で表せないので、「七対三です」と続けると意味が通らない。", "音": "音は人数の割合の対象ではなく、「大人と子どもの音は、七対三です」は文として不自然。"}, "sentence_index": 6, "correct_answer": "比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つのクラスの人数の比は、合計六十人です。", "explanation": "比は二つの量の割合を表すので、人数の総数である「合計六十人」は表さない。"}, {"text": "町の中心に、古い比が建っています。", "explanation": "ここは〈碑〉(石の記念碑)の意味。比は割合を表す言葉で、建てられる物には使わない。"}, {"text": "男女の身長の比は、百五十五センチです。", "explanation": "比は二つの量の割合を表すので、単位のついた値「百五十五センチ」は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37000, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赤と青の比を、一対四です。", "corrected_sentence": "赤と青の比は、一対四です。", "error_description": "「比」の直後は主題の「は」が正しい。「を」は目的語の助詞で、「一対四です」と続く文には合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37000, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このクラスの男子と女子の比を求まりました。", "corrected_sentence": "このクラスの男子と女子の比を求めました。", "error_description": "「比を求める」の「求める」は他動詞で、目的語「比」に「を」が続く。「求まる」は自動詞なので「を」と結べず、「比を求まりました」は不自然。正しくは「比を求めました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語の「が」。「比が同じなら」で、比が同じことを条件として示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」を入れると「比へ同じなら」となり、比を同じ条件として示せない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」を入れると「縦と横の比を同じなら」となり、「比」が「同じ」の目的語になれず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」を入れると「比から同じなら」となり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "主語の「が」。「比が同じなら」で、比が同じことを条件として示す。", "へ": "方向の「へ」を入れると「比へ同じなら」となり、比を同じ条件として示せない。", "を": "目的語の「を」を入れると「縦と横の比を同じなら」となり、「比」が「同じ」の目的語になれず不自然。", "から": "起点の「から」を入れると「比から同じなら」となり、意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「比を求める」の「を」。比は求める対象なので、直後に目的語の「を」が付く。"}, {"text": "に", "is_correct": false, "explanation": "到達・位置の「に」を入れると「比に求める方法」となり、求める対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」を入れると「比より求める方法」となり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」を入れると「比と求める方法」となり、求める対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「比を求める」の「を」。比は求める対象なので、直後に目的語の「を」が付く。", "に": "到達・位置の「に」を入れると「比に求める方法」となり、求める対象を示せない。", "より": "比較の「より」を入れると「比より求める方法」となり、文が成り立たない。", "と": "並列の「と」を入れると「比と求める方法」となり、求める対象として不自然。"}, "error_tags": {"に": "到達・位置", "より": "比較", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの数量や程度を比較したときの、一方に対する他方の割合や関係を表すこと。", "primary_collocate": null, "pronunciation": "ひ", "ipa": "çi", "syllable_count": 1, "sentences": [{"text": "水と砂糖の比を二対一にして、混ぜます。", "target_word": "比", "complexity_tier": "T3", "furigana": "水[みず]と砂糖[さとう]の比[ひ]を二[に]対[たい]一[いち]にして、混[ま]ぜます。", "sentence_source": "generated"}, {"text": "縦と横の比が同じなら、形は似ています。", "target_word": "比", "complexity_tier": "T3", "furigana": "縦[たて]と横[よこ]の比[ひ]が同[おな]じなら、形[かたち]は似[に]ています。", "sentence_source": "generated"}, {"text": "地図の長さと実際の長さの比を、縮尺といいます。", "target_word": "比", "complexity_tier": "T3", "furigana": "地図[ちず]の長[なが]さと実際[じっさい]の長[なが]さの比[ひ]を、縮尺[しゅくしゃく]といいます。", "sentence_source": "generated"}, {"text": "比は、できるだけ簡単な数に直して考えます。", "target_word": "比", "complexity_tier": "T3", "furigana": "比[ひ]は、できるだけ簡単[かんたん]な数[かず]に直[なお]して考[かんが]えます。", "sentence_source": "generated"}, {"text": "算数の問題で、六対九の比を簡単にしました。", "target_word": "比", "complexity_tier": "T3", "furigana": "算数[さんすう]の問題[もんだい]で、六[ろく]対[たい]九[きゅう]の比[ひ]を簡単[かんたん]にしました。", "sentence_source": "generated"}, {"text": "この絵は縦と横の比が、三対四になっています。", "target_word": "比", "complexity_tier": "T3", "furigana": "この絵[え]は縦[たて]と横[よこ]の比[ひ]が、三[さん]対[たい]四[よん]になっています。", "sentence_source": "generated"}, {"text": "薬の量は、体重との比で決めます。", "target_word": "比", "complexity_tier": "T3", "furigana": "薬[くすり]の量[りょう]は、体重[たいじゅう]との比[ひ]で決[き]めます。", "sentence_source": "generated"}, {"text": "二つの量の比を求める方法を習いました。", "target_word": "比", "complexity_tier": "T3", "furigana": "二[ふた]つの量[りょう]の比[ひ]を求[もと]める方法[ほうほう]を習[なら]いました。", "sentence_source": "generated"}, {"text": "材料の比を変えると、味も変わります。", "target_word": "比", "complexity_tier": "T3", "furigana": "材料[ざいりょう]の比[ひ]を変[か]えると、味[あじ]も変[か]わります。", "sentence_source": "generated"}, {"text": "円の直径と円周の比は、いつも同じです。", "target_word": "比", "complexity_tier": "T3", "furigana": "円[えん]の直径[ちょっけい]と円周[えんしゅう]の比[ひ]は、いつも同[おな]じです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "比", "label": "基本形"}], "register": "丁寧(です・ます体)", "sense_fingerprint": "算数・数学で、二つの量の割合(比率)の関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比", "is_correct": true, "explanation": "材料どうしの割合を表す「比」が入り、「水と砂糖の比を二対一にして、混ぜます」と自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "色は割合で配合する対象ではなく、「水と砂糖の色を二対一にして」は文が成り立たない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは割合を決めて混ぜるものではなく、「香りを二対一にして混ぜます」は不自然。"}, {"text": "温度", "is_correct": false, "explanation": "温度は割合で混ぜる対象ではなく、「温度を二対一にして」は意味が通らない。"}], "explanations": {"比": "材料どうしの割合を表す「比」が入り、「水と砂糖の比を二対一にして、混ぜます」と自然に続く。", "色": "色は割合で配合する対象ではなく、「水と砂糖の色を二対一にして」は文が成り立たない。", "香り": "香りは割合を決めて混ぜるものではなく、「香りを二対一にして混ぜます」は不自然。", "温度": "温度は割合で混ぜる対象ではなく、「温度を二対一にして」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は比が暑くて、汗が出ました。", "explanation": "ここは〈日〉(太陽・日中)の意味。比は二つの量の割合を表すので、天気や暑さの意味では使わない。"}, {"text": "この詩では、春を人生に例える比が使われています。", "explanation": "「比」単独にはたとえの意味はなく、たとえは「比喩」という別の語が担う。比は二つの数量の関係を表すので、この文には使えない。"}, {"text": "ストーブに比をつけました。", "explanation": "ここは〈火〉(燃える火)の意味。比は二つの量を比べる言葉で、ストーブにつける火は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比", "is_correct": true, "explanation": "「体重との比で決めます」の「比」。体重と薬の量の割合を表す名詞として自然に入る。"}, {"text": "手触り", "is_correct": false, "explanation": "手触りは体重との割合で決める対象ではなく、「体重との手触りで決めます」は不自然。"}, {"text": "音", "is_correct": false, "explanation": "音で薬の量を決める文は成り立たず、体重との関係を表せない。"}, {"text": "味", "is_correct": false, "explanation": "味は体重との割合で決めるものではなく、「体重との味で決めます」は文として意味が通らない。"}], "explanations": {"比": "「体重との比で決めます」の「比」。体重と薬の量の割合を表す名詞として自然に入る。", "手触り": "手触りは体重との割合で決める対象ではなく、「体重との手触りで決めます」は不自然。", "音": "音で薬の量を決める文は成り立たず、体重との関係を表せない。", "味": "味は体重との割合で決めるものではなく、「体重との味で決めます」は文として意味が通らない。"}, "sentence_index": 6, "correct_answer": "比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの班の人数の比は、合計十二人です。", "explanation": "比は二つの量の割合を表すので、人数の総数である「合計十二人」は表さない。"}, {"text": "公園に大きな比が建っています。", "explanation": "ここは〈碑〉(石の記念碑)の意味。比は割合を表す言葉で、建てられる物には使わない。"}, {"text": "テストの点数の比は、七十点です。", "explanation": "比は割合を表す語なので、単位のついた点数「七十点」の平均は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "正方形の縦と横の比を、一対一です。", "corrected_sentence": "正方形の縦と横の比は、一対一です。", "error_description": "「比」の直後は主題の「は」が正しい。「を」は目的語の助詞で、「一対一です」と続く文には合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37001, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの辺の比が求めました。", "corrected_sentence": "二つの辺の比を求めました。", "error_description": "「比」の直後は目的語の「を」が正しい。「が」は主語の助詞で、「求めました」の目的語にならず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
