INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37002, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「炭素」という元素の記号です。", "primary_collocate": null, "pronunciation": "しー", "ipa": "ɕiː", "syllable_count": 2, "sentences": [{"text": "炭素の元素記号は「C」です。", "target_word": "C", "complexity_tier": "T3", "furigana": "炭素[たんそ]の元素記号[げんそきごう]は「C」です。", "sentence_source": "generated"}, {"text": "周期表で、「C」は炭素を表す記号です。", "target_word": "C", "complexity_tier": "T3", "furigana": "周期表[しゅうきひょう]で、「C」は炭素[たんそ]を表[あらわ]す記号[きごう]です。", "sentence_source": "generated"}, {"text": "ダイヤモンドは、「C」という元素だけからなる物質です。", "target_word": "C", "complexity_tier": "T3", "furigana": "ダイヤモンドは、「C」という元素[げんそ]だけからなる物質[ぶっしつ]です。", "sentence_source": "generated"}, {"text": "元素記号の「C」は、炭素のことです。", "target_word": "C", "complexity_tier": "T3", "furigana": "元素記号[げんそきごう]の「C」は、炭素[たんそ]のことです。", "sentence_source": "generated"}, {"text": "メタンの分子には、「C」が一つとHが四つあります。", "target_word": "C", "complexity_tier": "T3", "furigana": "メタンの分子[ぶんし]には、「C」が一[ひと]つとHが四[よっ]つあります。", "sentence_source": "generated"}, {"text": "テストでは、元素記号の「C」を書いて炭素と答えました。", "target_word": "C", "complexity_tier": "T3", "furigana": "テストでは、元素記号[げんそきごう]の「C」を書[か]いて炭素[たんそ]と答[こた]えました。", "sentence_source": "generated"}, {"text": "鉛筆の芯の黒い部分には、元素の「C」が多く含まれています。", "target_word": "C", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]の芯[しん]の黒[くろ]い部分[ぶぶん]には、元素[げんそ]の「C」が多[おお]く含[ふく]まれています。", "sentence_source": "generated"}, {"text": "酸素の記号はOで、炭素の記号は「C」です。", "target_word": "C", "complexity_tier": "T3", "furigana": "酸素[さんそ]の記号[きごう]はOで、炭素[たんそ]の記号[きごう]は「C」です。", "sentence_source": "generated"}, {"text": "先生は黒板に大きく「C」と書いて、炭素だと説明しました。", "target_word": "C", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に大[おお]きく「C」と書[か]いて、炭素[たんそ]だと説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "有機物には必ず「C」が含まれているので、化学では大切な元素です。", "target_word": "C", "complexity_tier": "T3", "furigana": "有機物[ゆうきぶつ]には必[かなら]ず「C」が含[ふく]まれているので、化学[かがく]では大切[たいせつ]な元素[げんそ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "C", "label": "基本形"}], "register": "technical", "sense_fingerprint": "元素記号Cが表す炭素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 炭素 (Zipf 3.73), 元素 (Zipf 3.5), 記号 (Zipf 3.85)','sentence 1 above tier T1: 3 words above tier T1 (max 2): 周期 (Zipf 3.8), 炭素 (Zipf 3.73), 記号 (Zipf 3.85)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 元素 (Zipf 3.5), 記号 (Zipf 3.85), 炭素 (Zipf 3.73)','sentence 4 above tier T1: 3 words above tier T1 (max 2): メタン (Zipf 2.85), 分子 (Zipf 3.97), 四つ (Zipf 3.58)','sentence 5 above tier T1: 3 words above tier T1 (max 2): 元素 (Zipf 3.5), 記号 (Zipf 3.85), 炭素 (Zipf 3.73)','sentence 6 above tier T1: 3 words above tier T1 (max 2): 鉛筆 (Zipf 3.71), 芯 (Zipf 3.83), 元素 (Zipf 3.5)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 記号 (Zipf 3.85), 炭素 (Zipf 3.73), 記号 (Zipf 3.85)']::text[], 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37002, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "C", "is_correct": true, "explanation": "炭素の元素記号は「C」なので、「炭素の元素記号は「C」です」が成り立つ。"}, {"text": "O", "is_correct": false, "explanation": "「O」は酸素の元素記号で、炭素の記号としては誤り。"}, {"text": "H", "is_correct": false, "explanation": "「H」は水素の元素記号で、炭素の記号ではない。"}, {"text": "N", "is_correct": false, "explanation": "「N」は窒素の元素記号で、炭素の記号ではない。"}], "explanations": {"C": "炭素の元素記号は「C」なので、「炭素の元素記号は「C」です」が成り立つ。", "O": "「O」は酸素の元素記号で、炭素の記号としては誤り。", "H": "「H」は水素の元素記号で、炭素の記号ではない。", "N": "「N」は窒素の元素記号で、炭素の記号ではない。"}, "sentence_index": 0, "correct_answer": "C"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "元素記号の「C」は、酸素のことです。", "explanation": "「C」は炭素の記号なので、酸素を指す文では使えない。酸素の記号はOである。"}, {"text": "カルシウムの元素記号は「C」です。", "explanation": "「C」は炭素の記号で、カルシウムの記号はCaである。したがって「C」をカルシウムの記号とする文は誤り。"}, {"text": "銅の元素記号は「C」です。", "explanation": "「C」は炭素の記号で、銅の記号はCuである。したがって「C」を銅の記号とする文は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37002, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "C", "is_correct": true, "explanation": "黒い部分に多く含まれる元素は炭素なので、「元素の「C」が多く含まれています」が正しい。"}, {"text": "Fe", "is_correct": false, "explanation": "「Fe」は鉄の記号で、鉛筆の芯に鉄が多く含まれるという文は誤り。"}, {"text": "Mg", "is_correct": false, "explanation": "「Mg」はマグネシウムの記号で、鉛筆の芯に多く含まれる元素ではない。"}, {"text": "Cl", "is_correct": false, "explanation": "「Cl」は塩素の記号で、鉛筆の芯の黒い部分に多く含まれる元素ではない。"}], "explanations": {"C": "黒い部分に多く含まれる元素は炭素なので、「元素の「C」が多く含まれています」が正しい。", "Fe": "「Fe」は鉄の記号で、鉛筆の芯に鉄が多く含まれるという文は誤り。", "Mg": "「Mg」はマグネシウムの記号で、鉛筆の芯に多く含まれる元素ではない。", "Cl": "「Cl」は塩素の記号で、鉛筆の芯の黒い部分に多く含まれる元素ではない。"}, "sentence_index": 6, "correct_answer": "C"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二酸化炭素の化学式は「C」です。", "explanation": "「C」は炭素一つを表す元素記号で、二酸化炭素の化学式（CO₂）にはならない。"}, {"text": "コバルトを表す記号は「C」です。", "explanation": "「C」は炭素の記号で、コバルトの記号はCoである。したがって「C」をコバルトの記号とする文は誤り。"}, {"text": "この飲み物は、Cが強くてしゅわしゅわします。", "explanation": "「Cが強くて」は文として成り立たず、「C」は元素記号なので炭酸の強さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37002, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "元素記号の「C」を、炭素を表します。", "corrected_sentence": "元素記号の「C」は、炭素を表します。", "error_description": "「C」の直後は主題の「は」が正しい。「を」は目的語の助詞で、直後の「炭素を表す」と目的語が重なり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37002, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "「C」に記号は炭素を表します。", "corrected_sentence": "「C」の記号は炭素を表します。", "error_description": "「C」の直後は「の」で「記号」に続くのが正しい。「に」は場所や相手を示す助詞で、「「C」に記号」と名詞を結べないため不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37006, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不適切", "is_correct": true, "explanation": "「不適切」は合っていないことで、「適切」の反対。"}, {"text": "的確", "is_correct": false, "explanation": "「的確」は「適切」に近く、反対ではない。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は音がしないことで、「適切」の反対ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧」は注意深いことで、「適切」の反対ではない。"}], "correct_answer": "不適切", "explanations": {"不適切": "「不適切」は合っていないことで、「適切」の反対。", "的確": "「的確」は「適切」に近く、反対ではない。", "静か": "「静か」は音がしないことで、「適切」の反対ではない。", "丁寧": "「丁寧」は注意深いことで、「適切」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
