INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37006, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ちょうどいい、合っている。", "primary_collocate": null, "pronunciation": "てきせつ", "ipa": "tekisetsɯ", "syllable_count": 4, "sentences": [{"text": "この部屋の温度は適切です。", "target_word": "適切", "complexity_tier": "T2", "furigana": "この部屋[へや]の温度[おんど]は適切[てきせつ]です。", "sentence_source": "generated"}, {"text": "この服は場面に適切だ。", "target_word": "適切", "complexity_tier": "T2", "furigana": "この服[ふく]は場面[ばめん]に適切[てきせつ]だ。", "sentence_source": "generated"}, {"text": "適切な量を入れてください。", "target_word": "適切", "complexity_tier": "T3", "furigana": "適切[てきせつ]な量[りょう]を入[い]れてください。", "sentence_source": "generated"}, {"text": "水の量は適切でした。", "target_word": "適切", "complexity_tier": "T2", "furigana": "水[みず]の量[りょう]は適切[てきせつ]でした。", "sentence_source": "generated"}, {"text": "先生は適切に教えてくれた。", "target_word": "適切", "complexity_tier": "T3", "furigana": "先生[せんせい]は適切[てきせつ]に教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "温度が適切でないと、花は育たない。", "target_word": "適切", "complexity_tier": "T4", "furigana": "温度[おんど]が適切[てきせつ]でないと、花[はな]は育[そだ]たない。", "sentence_source": "generated"}, {"text": "その答えは、質問に適切だと思います。", "target_word": "適切", "complexity_tier": "T3", "furigana": "その答[こた]えは、質問[しつもん]に適切[てきせつ]だと思[おも]います。", "sentence_source": "generated"}, {"text": "適切な時に、適切な言葉を使うのは難しい。", "target_word": "適切", "complexity_tier": "T4", "furigana": "適切[てきせつ]な時[とき]に、適切[てきせつ]な言葉[ことば]を使[つか]うのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "適切に使えば、この薬はとても役に立つ。", "target_word": "適切", "complexity_tier": "T4", "furigana": "適切[てきせつ]に使[つか]えば、この薬[くすり]はとても役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "部屋の広さに適切な家具を選ぶことが、快適に暮らすコツです。", "target_word": "適切", "complexity_tier": "T5", "furigana": "部屋[へや]の広[ひろ]さに適切[てきせつ]な家具[かぐ]を選[えら]ぶことが、快適[かいてき]に暮[く]らすコツです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適切な", "label": "活用"}, {"form": "適切に", "label": "活用"}, {"form": "適切だ", "label": "活用"}, {"form": "適切でした", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | ちょうどよく合っているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37006, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "適切", "is_correct": true, "explanation": "「てきせつ」は見出し語そのもの。"}, {"text": "適性", "is_correct": false, "explanation": "「てきせい」は最後の音が違う別の語。"}, {"text": "敵船", "is_correct": false, "explanation": "「てきせん」は最後の音が違う別の語。"}, {"text": "定説", "is_correct": false, "explanation": "「ていせつ」は二音目が違う別の語。"}, {"text": "積雪", "is_correct": false, "explanation": "「せきせつ」は最初の音が違う別の語。"}], "explanations": {"適切": "「てきせつ」は見出し語そのもの。", "適性": "「てきせい」は最後の音が違う別の語。", "敵船": "「てきせん」は最後の音が違う別の語。", "定説": "「ていせつ」は二音目が違う別の語。", "積雪": "「せきせつ」は最初の音が違う別の語。"}, "sentence_index": null, "correct_answer": "適切"}, "level_3": {"options": [{"text": "適切", "is_correct": true, "explanation": "部屋の温度がちょうどいいという意味になる。"}, {"text": "頑丈", "is_correct": false, "explanation": "形は合うが、「温度が頑丈」は意味が合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、温度について「空腹」とは言わない。"}, {"text": "正直", "is_correct": false, "explanation": "形は合うが、「温度が正直」は意味が合わない。"}], "explanations": {"適切": "部屋の温度がちょうどいいという意味になる。", "頑丈": "形は合うが、「温度が頑丈」は意味が合わない。", "空腹": "形は合うが、温度について「空腹」とは言わない。", "正直": "形は合うが、「温度が正直」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "適切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この荷物はとても適切で、持てません。", "explanation": "「適切」は「重い」の意味ではなく、荷物の重さを表せない。"}, {"text": "昨日の映画は適切で、泣いてしまった。", "explanation": "「適切」は「感動的」の意味ではなく、映画の印象を表せない。"}, {"text": "この靴は適切で、足が痛い。", "explanation": "「適切」は「きつい」の意味ではなく、ちょうどよいはずの靴で足が痛いと矛盾し誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37006, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "適切", "is_correct": true, "explanation": "「てきせつ」は見出し語そのもの。"}, {"text": "摘出", "is_correct": false, "explanation": "「てきしゅつ」は三音目が違う別の語。"}, {"text": "適正", "is_correct": false, "explanation": "「てきせい」は最後の音が違う別の語。"}, {"text": "定説", "is_correct": false, "explanation": "「ていせつ」は二音目が違う別の語。"}], "explanations": {"適切": "「てきせつ」は見出し語そのもの。", "摘出": "「てきしゅつ」は三音目が違う別の語。", "適正": "「てきせい」は最後の音が違う別の語。", "定説": "「ていせつ」は二音目が違う別の語。"}, "sentence_index": null, "correct_answer": "適切"}, "level_3": {"options": [{"text": "適切", "is_correct": true, "explanation": "質問に合う答えという意味で合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "形は合うが、「答えが質問に頑丈だ」は意味が合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、「答えが質問に空腹だ」は意味が合わない。"}, {"text": "平坦", "is_correct": false, "explanation": "形は合うが、「答えが質問に平坦だ」は意味が合わない。"}], "explanations": {"適切": "質問に合う答えという意味で合う。", "頑丈": "形は合うが、「答えが質問に頑丈だ」は意味が合わない。", "空腹": "形は合うが、「答えが質問に空腹だ」は意味が合わない。", "平坦": "形は合うが、「答えが質問に平坦だ」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "適切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は適切に寒くて、手が凍った。", "explanation": "「適切」は「とても」の意味の副詞ではなく、程度を強める語として誤用。"}, {"text": "そのカレーは適切で、舌が痛くなった。", "explanation": "「適切」は「辛い」の意味ではなく、味の強さを表せない。"}, {"text": "彼は適切な人で、約束を何度も忘れる。", "explanation": "「適切」は「いい加減」の意味ではなく、人の性格を表すのに誤用で、後の内容とも矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37006, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温度が適切をないと、花は育たない。", "corrected_sentence": "温度が適切でないと、花は育たない。", "error_description": "「適切」を否定するときは「適切でない」と言い、「適切をない」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "適切", "is_correct": true, "explanation": "「適切だ」と語幹に「だ」が付く。"}, {"text": "適切な", "is_correct": false, "explanation": "「適切なだ」は連体形に「だ」が付かず非文。"}, {"text": "適切に", "is_correct": false, "explanation": "「適切にだ」は連用形のあとに「だ」が付かず非文。"}, {"text": "適切で", "is_correct": false, "explanation": "「適切でだ」は「で」のあとに「だ」が付かず非文。"}], "correct_form": "適切", "base_form": "適切", "form_label": "語幹", "sentence_index": 1, "explanations": {"適切": "「適切だ」と語幹に「だ」が付く。", "適切な": "「適切なだ」は連体形に「だ」が付かず非文。", "適切に": "「適切にだ」は連用形のあとに「だ」が付かず非文。", "適切で": "「適切でだ」は「で」のあとに「だ」が付かず非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37006, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "適切の量を入れてください。", "corrected_sentence": "適切な量を入れてください。", "error_description": "名詞を修飾するときは「適切の」ではなく「適切な」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "適切", "is_correct": true, "explanation": "「適切な時」と語幹に「な」が付く。"}, {"text": "適切な", "is_correct": false, "explanation": "「適切なな時」と「な」が重なり非文。"}, {"text": "適切で", "is_correct": false, "explanation": "「適切でな時」は「で」のあとに「な」が付かず非文。"}, {"text": "適切さ", "is_correct": false, "explanation": "「適切さな時」は名詞化した形に「な」が付かず非文。"}], "correct_form": "適切", "base_form": "適切", "form_label": "語幹", "sentence_index": 7, "explanations": {"適切": "「適切な時」と語幹に「な」が付く。", "適切な": "「適切なな時」と「な」が重なり非文。", "適切で": "「適切でな時」は「で」のあとに「な」が付かず非文。", "適切さ": "「適切さな時」は名詞化した形に「な」が付かず非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
