INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37007, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある状況や目的にぴったり合っていて、不足や過剰がないこと。", "primary_collocate": null, "pronunciation": "てきせつ", "ipa": "tekisetsɯ", "syllable_count": 4, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "適切", "complexity_tier": "T6", "furigana": "誰[だれ]に何[なに]を求[もと]めているか分析[ぶんせき]し、適切[てきせつ]な言葉[ことば]で発信[はっしん]することで、小[ちい]さくても確実[かくじつ]なファンを獲得[かくとく]できます。", "sentence_source": "mined"}, {"text": "この言葉は適切ではありません。", "target_word": "適切", "complexity_tier": "T2", "furigana": "この言葉[ことば]は適切[てきせつ]ではありません。", "sentence_source": "generated"}, {"text": "適切に説明してください。", "target_word": "適切", "complexity_tier": "T3", "furigana": "適切[てきせつ]に説明[せつめい]してください。", "sentence_source": "generated"}, {"text": "場面に適切な服装を選んでいる。", "target_word": "適切", "complexity_tier": "T3", "furigana": "場面[ばめん]に適切[てきせつ]な服装[ふくそう]を選[えら]んでいる。", "sentence_source": "generated"}, {"text": "薬は適切な量を飲むことが大切だ。", "target_word": "適切", "complexity_tier": "T3", "furigana": "薬[くすり]は適切[てきせつ]な量[りょう]を飲[の]むことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "先生は、質問に適切に答えてくれた。", "target_word": "適切", "complexity_tier": "T3", "furigana": "先生[せんせい]は、質問[しつもん]に適切[てきせつ]に答[こた]えてくれた。", "sentence_source": "generated"}, {"text": "この場合、どの方法が適切だと思いますか。", "target_word": "適切", "complexity_tier": "T3", "furigana": "この場合[ばあい]、どの方法[ほうほう]が適切[てきせつ]だと思[おも]いますか。", "sentence_source": "generated"}, {"text": "適切な判断ができなければ、仕事は任せられない。", "target_word": "適切", "complexity_tier": "T4", "furigana": "適切[てきせつ]な判断[はんだん]ができなければ、仕事[しごと]は任[まか]せられない。", "sentence_source": "generated"}, {"text": "適切だったかどうか、もう一度確認してみよう。", "target_word": "適切", "complexity_tier": "T4", "furigana": "適切[てきせつ]だったかどうか、もう一度[いちど]確認[かくにん]してみよう。", "sentence_source": "generated"}, {"text": "子どもの年齢に適切な本を選ぶのは、意外と難しい。", "target_word": "適切", "complexity_tier": "T4", "furigana": "子[こ]どもの年齢[ねんれい]に適切[てきせつ]な本[ほん]を選[えら]ぶのは、意外[いがい]と難[むずか]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適切な", "label": "活用"}, {"form": "適切に", "label": "活用"}, {"form": "適切だ", "label": "活用"}, {"form": "適切さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 状況や目的にぴったり合うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37007, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "適切", "is_correct": true, "explanation": "「てきせつ」は見出し語そのもの。"}, {"text": "適性", "is_correct": false, "explanation": "「てきせい」は最後の音が違う別の語。"}, {"text": "敵船", "is_correct": false, "explanation": "「てきせん」は最後の音が違う別の語。"}, {"text": "定説", "is_correct": false, "explanation": "「ていせつ」は二音目が違う別の語。"}, {"text": "積雪", "is_correct": false, "explanation": "「せきせつ」は最初の音が違う別の語。"}], "explanations": {"適切": "「てきせつ」は見出し語そのもの。", "適性": "「てきせい」は最後の音が違う別の語。", "敵船": "「てきせん」は最後の音が違う別の語。", "定説": "「ていせつ」は二音目が違う別の語。", "積雪": "「せきせつ」は最初の音が違う別の語。"}, "sentence_index": null, "correct_answer": "適切"}, "level_3": {"options": [{"text": "適切", "is_correct": true, "explanation": "相手に合う「適切な言葉」で、意味が合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "形は合うが、「頑丈な言葉」は意味が合わない。"}, {"text": "暇", "is_correct": false, "explanation": "形は合うが、「暇な言葉」は意味が合わない。"}, {"text": "平気", "is_correct": false, "explanation": "形は合うが、「平気な言葉」では発信の意味が通らない。"}], "explanations": {"適切": "相手に合う「適切な言葉」で、意味が合う。", "頑丈": "形は合うが、「頑丈な言葉」は意味が合わない。", "暇": "形は合うが、「暇な言葉」は意味が合わない。", "平気": "形は合うが、「平気な言葉」では発信の意味が通らない。"}, "sentence_index": 0, "correct_answer": "適切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は私にとても適切で、毎日お菓子をくれる。", "explanation": "「適切」は状況に合うことで、人に優しい意味の「親切」の代わりには使えない。"}, {"text": "適切な雨が降って、川があふれた。", "explanation": "「適切」は雨の激しさを表さず、「激しい」の意味で使うのは誤り。"}, {"text": "彼の部屋はいつも適切で、ゴミが一つもない。", "explanation": "「適切」は「きれい」の意味ではなく、清潔さを表す語として誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37007, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "適切", "is_correct": true, "explanation": "「てきせつ」は見出し語そのもの。"}, {"text": "摘出", "is_correct": false, "explanation": "「てきしゅつ」は三音目が違う別の語。"}, {"text": "適正", "is_correct": false, "explanation": "「てきせい」は最後の音が違う別の語。"}, {"text": "定説", "is_correct": false, "explanation": "「ていせつ」は二音目が違う別の語。"}], "explanations": {"適切": "「てきせつ」は見出し語そのもの。", "摘出": "「てきしゅつ」は三音目が違う別の語。", "適正": "「てきせい」は最後の音が違う別の語。", "定説": "「ていせつ」は二音目が違う別の語。"}, "sentence_index": null, "correct_answer": "適切"}, "level_3": {"options": [{"text": "適切", "is_correct": true, "explanation": "どの方法が目的に合うかを尋ねる文で意味が合う。"}, {"text": "豊富", "is_correct": false, "explanation": "形は合うが、「方法が豊富だと思う」は問いの意味に合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、「方法が空腹だ」は意味が合わない。"}, {"text": "頑固", "is_correct": false, "explanation": "形は合うが、「方法が頑固だ」は意味が合わない。"}], "explanations": {"適切": "どの方法が目的に合うかを尋ねる文で意味が合う。", "豊富": "形は合うが、「方法が豊富だと思う」は問いの意味に合わない。", "空腹": "形は合うが、「方法が空腹だ」は意味が合わない。", "頑固": "形は合うが、「方法が頑固だ」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "適切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この荷物は適切で、一人では持てない。", "explanation": "「適切」は「重い」の意味を持たず、荷物の重さを表すのは誤用。"}, {"text": "そのスープは適切で、舌をやけどした。", "explanation": "「適切」は「熱い」の意味ではなく、温度の高さを表すのは誤用。"}, {"text": "この道は適切で、走ると危ない。", "explanation": "「適切」は道の狭さや状態を表す語ではなく、誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37007, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では適切の言葉を使いましょう。", "corrected_sentence": "会議では適切な言葉を使いましょう。", "error_description": "名詞を修飾するときは「適切の」ではなく「適切な」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "適切", "is_correct": true, "explanation": "「適切ではありません」と語幹に「ではありません」が付く。"}, {"text": "適切な", "is_correct": false, "explanation": "「適切なではありません」は連体形に「ではありません」が付かず非文。"}, {"text": "適切に", "is_correct": false, "explanation": "「適切にではありません」は連用形のあとで文が成り立たない。"}, {"text": "適切だ", "is_correct": false, "explanation": "「適切だではありません」は断定形の後に付かず非文。"}], "correct_form": "適切", "base_form": "適切", "form_label": "語幹", "sentence_index": 1, "explanations": {"適切": "「適切ではありません」と語幹に「ではありません」が付く。", "適切な": "「適切なではありません」は連体形に「ではありません」が付かず非文。", "適切に": "「適切にではありません」は連用形のあとで文が成り立たない。", "適切だ": "「適切だではありません」は断定形の後に付かず非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37007, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は質問に適切な答えてくれた。", "corrected_sentence": "先生は質問に適切に答えてくれた。", "error_description": "動詞を修飾するには「適切な」ではなく「適切に」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "適切", "is_correct": true, "explanation": "「適切な判断」と語幹に「な」が付く。"}, {"text": "適切な", "is_correct": false, "explanation": "「適切なな判断」と「な」が重なって非文。"}, {"text": "適切に", "is_correct": false, "explanation": "「適切にな判断」は「に」のあとに「な」が付かず非文。"}, {"text": "適切だ", "is_correct": false, "explanation": "「適切だな判断」は断定形のあとに名詞を修飾できず非文。"}], "correct_form": "適切", "base_form": "適切", "form_label": "語幹", "sentence_index": 7, "explanations": {"適切": "「適切な判断」と語幹に「な」が付く。", "適切な": "「適切なな判断」と「な」が重なって非文。", "適切に": "「適切にな判断」は「に」のあとに「な」が付かず非文。", "適切だ": "「適切だな判断」は断定形のあとに名詞を修飾できず非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「問題の回避」の「の」。「問題」と「回避」をつなぐ連体修飾の助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」を入れると「問題へ回避ばかり考えて」となり、回避の対象を示す形にならない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」を入れると「問題が回避ばかり考えていては」となり、問題が考える主体になって不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」を入れると「問題で回避ばかり」となり、名詞をつなげない。"}], "correct_answer": "の", "explanations": {"の": "「問題の回避」の「の」。「問題」と「回避」をつなぐ連体修飾の助詞。", "へ": "方向の「へ」を入れると「問題へ回避ばかり考えて」となり、回避の対象を示す形にならない。", "が": "主語の「が」を入れると「問題が回避ばかり考えていては」となり、問題が考える主体になって不自然。", "で": "手段の「で」を入れると「問題で回避ばかり」となり、名詞をつなげない。"}, "error_tags": {"へ": "方向", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「議論を回避した」の「を」。回避の対象である議論に直接付く目的語の助詞。"}, {"text": "に", "is_correct": false, "explanation": "到達・位置の「に」を入れると「議論に回避したので」となり、回避の対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」を入れると「議論が回避したので」となり、議論が避ける主体になって不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」を入れると「議論と回避したので」となり、回避の対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「議論を回避した」の「を」。回避の対象である議論に直接付く目的語の助詞。", "に": "到達・位置の「に」を入れると「議論に回避したので」となり、回避の対象を示せない。", "が": "主語の「が」を入れると「議論が回避したので」となり、議論が避ける主体になって不自然。", "と": "並列の「と」を入れると「議論と回避したので」となり、回避の対象として不自然。"}, "error_tags": {"に": "到達・位置", "が": "主語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "いやなことや責任を、しなくてすむようにさけて逃れること。", "primary_collocate": null, "pronunciation": "かいひ", "ipa": "kaihi", "syllable_count": 3, "sentences": [{"text": "彼は責任を回避するために、会議を休みました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "彼[かれ]は責任[せきにん]を回避[かいひ]するために、会議[かいぎ]を休[やす]みました。", "sentence_source": "generated"}, {"text": "問題の回避ばかり考えていては、何も解決しません。", "target_word": "回避", "complexity_tier": "T3", "furigana": "問題[もんだい]の回避[かいひ]ばかり考[かんが]えていては、何[なに]も解決[かいけつ]しません。", "sentence_source": "generated"}, {"text": "彼女は質問への回答を回避して、話題を変えました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は質問[しつもん]への回答[かいとう]を回避[かいひ]して、話題[わだい]を変[か]えました。", "sentence_source": "generated"}, {"text": "税金の回避を考える会社が、批判されました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "税金[ぜいきん]の回避[かいひ]を考[かんが]える会社[かいしゃ]が、批判[ひはん]されました。", "sentence_source": "generated"}, {"text": "面倒な仕事の回避が上手な同僚に、みんな困っています。", "target_word": "回避", "complexity_tier": "T3", "furigana": "面倒[めんどう]な仕事[しごと]の回避[かいひ]が上手[じょうず]な同僚[どうりょう]に、みんな困[こま]っています。", "sentence_source": "generated"}, {"text": "弟は宿題の回避のために、病気のふりをしました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "弟[おとうと]は宿題[しゅくだい]の回避[かいひ]のために、病気[びょうき]のふりをしました。", "sentence_source": "generated"}, {"text": "責任の回避は、信用をなくす原因になります。", "target_word": "回避", "complexity_tier": "T3", "furigana": "責任[せきにん]の回避[かいひ]は、信用[しんよう]をなくす原因[げんいん]になります。", "sentence_source": "generated"}, {"text": "彼は議論を回避したので、意見が分からないままでした。", "target_word": "回避", "complexity_tier": "T3", "furigana": "彼[かれ]は議論[ぎろん]を回避[かいひ]したので、意見[いけん]が分[わ]からないままでした。", "sentence_source": "generated"}, {"text": "いやなことの回避を続けると、あとで大きな問題になります。", "target_word": "回避", "complexity_tier": "T3", "furigana": "いやなことの回避[かいひ]を続[つづ]けると、あとで大[おお]きな問題[もんだい]になります。", "sentence_source": "generated"}, {"text": "社長は記者の質問を回避し、何も説明しませんでした。", "target_word": "回避", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は記者[きしゃ]の質問[しつもん]を回避[かいひ]し、何[なに]も説明[せつめい]しませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回避", "label": "基本形"}, {"form": "回避する", "label": "辞書形"}, {"form": "回避した", "label": "過去形"}, {"form": "回避して", "label": "て形"}, {"form": "回避しない", "label": "否定形"}, {"form": "回避できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "いやなことや責任をさけて逃れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "責任を避けることを表す「回避」が入り、「責任を回避するために、会議を休みました」と自然に続く。"}, {"text": "集計", "is_correct": false, "explanation": "「責任を集計するために会議を休みました」は意味をなさず、避けるという意味にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「責任を採点するために」は不自然で、避けるという行動を表せない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「責任を翻訳するために」は意味が通らず、避ける行動の文にならない。"}], "explanations": {"回避": "責任を避けることを表す「回避」が入り、「責任を回避するために、会議を休みました」と自然に続く。", "集計": "「責任を集計するために会議を休みました」は意味をなさず、避けるという意味にならない。", "採点": "「責任を採点するために」は不自然で、避けるという行動を表せない。", "翻訳": "「責任を翻訳するために」は意味が通らず、避ける行動の文にならない。"}, "sentence_index": 0, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れた商品を回避しました。", "explanation": "「回避」は避ける行動で、商品を集め戻す意味はない。"}, {"text": "会議を来週に回避しました。", "explanation": "「回避」は嫌なことを避ける行動で、日程をずらす意味はない。"}, {"text": "故郷へ回避する人が増えました。", "explanation": "「回避」は避けることで、故郷へ戻る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "「責任の回避は、信用をなくす原因になります」の主語となる「回避」が自然に入る。"}, {"text": "混線", "is_correct": false, "explanation": "「責任の混線は、信用をなくす原因になります」は、避けるという意味にならず不自然。"}, {"text": "計量", "is_correct": false, "explanation": "「責任の計量は」は意味が通らず、避ける行動を表せない。"}, {"text": "誤訳", "is_correct": false, "explanation": "「責任の誤訳は」は避けることとは関係なく、文として成り立たない。"}], "explanations": {"回避": "「責任の回避は、信用をなくす原因になります」の主語となる「回避」が自然に入る。", "混線": "「責任の混線は、信用をなくす原因になります」は、避けるという意味にならず不自然。", "計量": "「責任の計量は」は意味が通らず、避ける行動を表せない。", "誤訳": "「責任の誤訳は」は避けることとは関係なく、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "扇風機の羽が勢いよく回避しています。", "explanation": "「回避」は避ける行動で、羽が回り続ける動きは表さない。"}, {"text": "荷物を全国へ回避しました。", "explanation": "「回避」は避けることで、荷物を別の場所へ送る意味にはならない。"}, {"text": "クラスの回避を集めました。", "explanation": "ここは〈会費〉(かいひ)の意味。回避は避けることなので、お金を集める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は責任を回避でして、話をそらしました。", "corrected_sentence": "彼は責任を回避して、話をそらしました。", "error_description": "「回避」に続く形は「回避して」が正しい。「回避でして」は名詞に「で」を余計に付けた誤りで、不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "危険の回避に心がけてください。", "corrected_sentence": "危険の回避を心がけてください。", "error_description": "「心がける」は目的語に「を」を取るので「回避を心がける」が正しい。「に」は誤りで不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「回避のため」と名詞に続けるための「の」。回避の後に「ため」が続く形になる。"}, {"text": "を", "is_correct": false, "explanation": "回避を目的語にすると後ろに動詞が必要になり、「回避を、ため」では文が続かない。"}, {"text": "に", "is_correct": false, "explanation": "回避に（対象）と続けると「ため」との結びつきが不自然になり、文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "回避で（手段）は「ため」の前に置けず、この文の形では成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「回避のため」と名詞に続けるための「の」。回避の後に「ため」が続く形になる。", "を": "回避を目的語にすると後ろに動詞が必要になり、「回避を、ため」では文が続かない。", "に": "回避に（対象）と続けると「ため」との結びつきが不自然になり、文が崩れる。", "で": "回避で（手段）は「ため」の前に置けず、この文の形では成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着・対象", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "危険や問題が起こらないように、前もって避けること。", "primary_collocate": null, "pronunciation": "かいひ", "ipa": "kaihi", "syllable_count": 3, "sentences": [{"text": "運転手はブレーキをかけて、衝突の回避に成功しました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]はブレーキをかけて、衝突[しょうとつ]の回避[かいひ]に成功[せいこう]しました。", "sentence_source": "generated"}, {"text": "事故の回避のため、雨の日は車の速度を落とします。", "target_word": "回避", "complexity_tier": "T3", "furigana": "事故[じこ]の回避[かいひ]のため、雨[あめ]の日[ひ]は車[くるま]の速度[そくど]を落[お]とします。", "sentence_source": "generated"}, {"text": "この車には、危険を回避する機能がついています。", "target_word": "回避", "complexity_tier": "T3", "furigana": "この車[くるま]には、危険[きけん]を回避[かいひ]する機能[きのう]がついています。", "sentence_source": "generated"}, {"text": "リスクの回避を考えて、会社は投資の額を減らしました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "リスクの回避[かいひ]を考[かんが]えて、会社[かいしゃ]は投資[とうし]の額[がく]を減[へ]らしました。", "sentence_source": "generated"}, {"text": "台風が来る前に避難して、被害の回避ができました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前[まえ]に避難[ひなん]して、被害[ひがい]の回避[かいひ]ができました。", "sentence_source": "generated"}, {"text": "渋滞の回避のために、朝早く家を出ました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]の回避[かいひ]のために、朝早[あさはや]く家[いえ]を出[で]ました。", "sentence_source": "generated"}, {"text": "火事の回避には、ふだんの点検が大切です。", "target_word": "回避", "complexity_tier": "T3", "furigana": "火事[かじ]の回避[かいひ]には、ふだんの点検[てんけん]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "パイロットは急いで進路を変え、衝突を回避しました。", "target_word": "回避", "complexity_tier": "T3", "furigana": "パイロットは急[いそ]いで進路[しんろ]を変[か]え、衝突[しょうとつ]を回避[かいひ]しました。", "sentence_source": "generated"}, {"text": "感染の回避には、手洗いとマスクが役に立ちます。", "target_word": "回避", "complexity_tier": "T3", "furigana": "感染[かんせん]の回避[かいひ]には、手洗[てあら]いとマスクが役[やく]に立[た]ちます。", "sentence_source": "generated"}, {"text": "危険の回避は、登山では最も大切な考え方です。", "target_word": "回避", "complexity_tier": "T3", "furigana": "危険[きけん]の回避[かいひ]は、登山[とざん]では最[もっと]も大切[たいせつ]な考[かんが]え方[かた]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "回避", "label": "基本形"}, {"form": "回避する", "label": "辞書形"}, {"form": "回避した", "label": "過去形"}, {"form": "回避して", "label": "て形"}, {"form": "回避しない", "label": "否定形"}, {"form": "回避できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "事故や危険を前もって防ぎ避けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "「衝突の回避に成功」は、危険を前もって避けたという意味で文の流れに合う。"}, {"text": "回転", "is_correct": false, "explanation": "回るという意味で、衝突の場面では「衝突の回転」となり意味が通らない。"}, {"text": "保存", "is_correct": false, "explanation": "物を残しておく意味で、衝突を保存するという文は成り立たない。"}, {"text": "解凍", "is_correct": false, "explanation": "冷凍した物を元に戻す意味で、衝突の場面には合わない。"}], "explanations": {"回避": "「衝突の回避に成功」は、危険を前もって避けたという意味で文の流れに合う。", "回転": "回るという意味で、衝突の場面では「衝突の回転」となり意味が通らない。", "保存": "物を残しておく意味で、衝突を保存するという文は成り立たない。", "解凍": "冷凍した物を元に戻す意味で、衝突の場面には合わない。"}, "sentence_index": 0, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トラブルが起きてから、落ち着いて回避しました。", "explanation": "ここは〈対処〉（起きた問題に後から手を打つこと）の意味。回避は危険や問題が起こる前に避けることで、起きたあとの対応には使わない。"}, {"text": "そのコマは勢いよく回避して、机の上で止まりました。", "explanation": "ここは〈回転〉の意味。回避は危険を避けることで、コマが回ることには使わない。"}, {"text": "この歯車は一分間に千回回避します。", "explanation": "ここは〈回転〉の意味。回避は危険を避けることなので、歯車が回ることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回避", "is_correct": true, "explanation": "「火事の回避」は火事を前もって避けるという意味で、点検が大切だという文に合う。"}, {"text": "観光", "is_correct": false, "explanation": "各地を見て回る意味で、火事の対策の文では「火事の観光」となり意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味で、火事の場面では成り立たない。"}, {"text": "通信", "is_correct": false, "explanation": "情報をやり取りする意味で、火事の点検の話には合わない。"}], "explanations": {"回避": "「火事の回避」は火事を前もって避けるという意味で、点検が大切だという文に合う。", "観光": "各地を見て回る意味で、火事の対策の文では「火事の観光」となり意味が通らない。", "採点": "点数をつける意味で、火事の場面では成り立たない。", "通信": "情報をやり取りする意味で、火事の点検の話には合わない。"}, "sentence_index": 6, "correct_answer": "回避"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい橋が三年かけて回避しました。", "explanation": "ここは〈完成〉の意味。回避は危険を前もって避けることで、橋が仕上がったことには使わない。"}, {"text": "旅先で、美しい景色を回避しました。", "explanation": "ここは〈撮影〉（写真や映像に写し取ること）の意味。回避は危険を前もって避けることで、景色を記録する意味にはならない。"}, {"text": "彼は五年かけて交響曲を回避しました。", "explanation": "ここは〈作曲〉の意味。回避は危険を避けることで、曲を作る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船長は嵐を回避のために、進路を変えました。", "corrected_sentence": "船長は嵐の回避のために、進路を変えました。", "error_description": "誤りは「を回避」の部分。正しくは「嵐の回避」と「の」で名詞につなぐ。回避は名詞なので、「を」を付けて名詞に続けることはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37011, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは危険を回避を学びました。", "corrected_sentence": "子どもたちは危険の回避を学びました。", "error_description": "誤りは「を回避」の部分。正しくは「危険の回避」と「の」で名詞につなぐ。「を」が二つ重なると、学ぶの目的語が二つになり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嫌気", "is_correct": true, "explanation": "技術用語で、酸素を必要としない性質を表し、好気と対になる。"}, {"text": "酸素", "is_correct": false, "explanation": "物質の名前で、性質を表す好気の対義語にはならない。"}, {"text": "微生物", "is_correct": false, "explanation": "生き物の総称で、性質の対義語にはならない。"}, {"text": "空気", "is_correct": false, "explanation": "混合気体の名前で、好気の対義語にはならない。"}], "correct_answer": "嫌気", "explanations": {"嫌気": "技術用語で、酸素を必要としない性質を表し、好気と対になる。", "酸素": "物質の名前で、性質を表す好気の対義語にはならない。", "微生物": "生き物の総称で、性質の対義語にはならない。", "空気": "混合気体の名前で、好気の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嫌気", "is_correct": true, "explanation": "技術用語で、酸素を必要としない性質を表し、好気と対になる。"}, {"text": "細菌", "is_correct": false, "explanation": "微生物の一種の名前で、性質の対義語にはならない。"}, {"text": "植物", "is_correct": false, "explanation": "生き物の分類で、性質の対義語にはならない。"}, {"text": "温度", "is_correct": false, "explanation": "物の熱さの度合いを表す語で、好気の対義語にはならない。"}], "correct_answer": "嫌気", "explanations": {"嫌気": "技術用語で、酸素を必要としない性質を表し、好気と対になる。", "細菌": "微生物の一種の名前で、性質の対義語にはならない。", "植物": "生き物の分類で、性質の対義語にはならない。", "温度": "物の熱さの度合いを表す語で、好気の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "酸素を必要とする性質。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "この菌は好気の性質をもつため、酸素がないと育ちません。", "target_word": "好気", "complexity_tier": "T3", "furigana": "この菌[きん]は好気[こうき]の性質[せいしつ]をもつため、酸素[さんそ]がないと育[そだ]ちません。", "sentence_source": "generated"}, {"text": "好気の細菌は、空気のある所でよく増えます。", "target_word": "好気", "complexity_tier": "T3", "furigana": "好気[こうき]の細菌[さいきん]は、空気[くうき]のある所[ところ]でよく増[ふ]えます。", "sentence_source": "generated"}, {"text": "好気の生物は、酸素を使ってエネルギーを作ります。", "target_word": "好気", "complexity_tier": "T3", "furigana": "好気[こうき]の生物[せいぶつ]は、酸素[さんそ]を使[つか]ってエネルギーを作[つく]ります。", "sentence_source": "generated"}, {"text": "この菌は好気の性質がないので、酸素のない容器でも育ちます。", "target_word": "好気", "complexity_tier": "T3", "furigana": "この菌[きん]は好気[こうき]の性質[せいしつ]がないので、酸素[さんそ]のない容器[ようき]でも育[そだ]ちます。", "sentence_source": "generated"}, {"text": "菌が好気の性質をもつかどうかは、酸素を必要とするかどうかで決まります。", "target_word": "好気", "complexity_tier": "T3", "furigana": "菌[きん]が好気[こうき]の性質[せいしつ]をもつかどうかは、酸素[さんそ]を必要[ひつよう]とするかどうかで決[き]まります。", "sentence_source": "generated"}, {"text": "実験では、好気の菌を入れた容器に、空気を送り続けました。", "target_word": "好気", "complexity_tier": "T3", "furigana": "実験[じっけん]では、好気[こうき]の菌[きん]を入[い]れた容器[ようき]に、空気[くうき]を送[おく]り続[つづ]けました。", "sentence_source": "generated"}, {"text": "好気の菌は、水に酸素が少ないと、増えにくくなります。", "target_word": "好気", "complexity_tier": "T3", "furigana": "好気[こうき]の菌[きん]は、水[みず]に酸素[さんそ]が少[すく]ないと、増[ふ]えにくくなります。", "sentence_source": "generated"}, {"text": "土の表面には、好気の微生物が多く住んでいます。", "target_word": "好気", "complexity_tier": "T3", "furigana": "土[つち]の表面[ひょうめん]には、好気[こうき]の微生物[びせいぶつ]が多[おお]く住[す]んでいます。", "sentence_source": "generated"}, {"text": "先生は、好気の意味を「酸素を必要とする性質」と説明しました。", "target_word": "好気", "complexity_tier": "T3", "furigana": "先生[せんせい]は、好気[こうき]の意味[いみ]を「酸素[さんそ]を必要[ひつよう]とする性質[せいしつ]」と説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "下水の処理では、好気の微生物の力を使って、水をきれいにします。", "target_word": "好気", "complexity_tier": "T3", "furigana": "下水[げすい]の処理[しょり]では、好気[こうき]の微生物[びせいぶつ]の力[ちから]を使[つか]って、水[みず]をきれいにします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "好気", "label": "基本形"}, {"form": "好気の", "label": "連体形"}], "register": "technical", "sense_fingerprint": "生物や菌が生きるのに酸素を必要とする性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd334127-ff51-4a1c-97cd-0dd1edc90297') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好気", "is_correct": true, "explanation": "「好気の性質」は酸素を必要とする性質を表し、酸素がないと育たないという文に合う。"}, {"text": "硬度", "is_correct": false, "explanation": "物の硬さを表す語で、「硬度の性質」では菌の酸素との関係を表せない。"}, {"text": "味覚", "is_correct": false, "explanation": "味を感じる感覚の語で、菌の性質には使えない。"}, {"text": "色彩", "is_correct": false, "explanation": "色の特徴を表す語で、酸素の必要性という文脈に合わない。"}], "explanations": {"好気": "「好気の性質」は酸素を必要とする性質を表し、酸素がないと育たないという文に合う。", "硬度": "物の硬さを表す語で、「硬度の性質」では菌の酸素との関係を表せない。", "味覚": "味を感じる感覚の語で、菌の性質には使えない。", "色彩": "色の特徴を表す語で、酸素の必要性という文脈に合わない。"}, "sentence_index": 0, "correct_answer": "好気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事の毎日に好気がさして、旅に出ました。", "explanation": "ここは〈嫌気〉（うんざりすること）の意味。好気は酸素を必要とする性質で、気持ちの話には使わない。"}, {"text": "魚は水の中の好気を取り込んで呼吸します。", "explanation": "ここは〈酸素〉の意味。好気は性質を表す語で、魚が取り込む物質の名前ではない。"}, {"text": "エンジンは好気を増やすと、力が出ます。", "explanation": "ここは〈吸気〉（空気を吸い込むこと）の意味。好気は酸素を必要とする性質を表す語で、エンジンが空気を取り込む働きは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好気", "is_correct": true, "explanation": "「好気の菌」は酸素を必要とする菌を表し、酸素が少ないと増えにくいという文に合う。"}, {"text": "体積", "is_correct": false, "explanation": "物の大きさを表す語で、菌の性質を表す文には合わない。"}, {"text": "音階", "is_correct": false, "explanation": "音の高さの並びを表す語で、菌の性質には使えない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分量を表す語で、菌の性質を表す形にはならない。"}], "explanations": {"好気": "「好気の菌」は酸素を必要とする菌を表し、酸素が少ないと増えにくいという文に合う。", "体積": "物の大きさを表す語で、菌の性質を表す文には合わない。", "音階": "音の高さの並びを表す語で、菌の性質には使えない。", "湿度": "空気中の水分量を表す語で、菌の性質を表す形にはならない。"}, "sentence_index": 6, "correct_answer": "好気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水の中に好気を送ると、微生物が元気になります。", "explanation": "ここは〈空気〉の意味。好気は性質を表す語で、水に送る物質の名前ではない。"}, {"text": "彼は雨の日の散歩が好気です。", "explanation": "ここは〈好き〉（気に入ること）の意味。好気は酸素を必要とする性質で、人の好みの話には使わない。"}, {"text": "その映画は好気で、観客が多く集まりました。", "explanation": "ここは〈好評〉（評判がよいこと）の意味。好気は酸素を必要とする性質で、評判の話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この細菌は好気を性質をもつので、酸素が多い水でよく育ちます。", "corrected_sentence": "この細菌は好気の性質をもつので、酸素が多い水でよく育ちます。", "error_description": "誤りは「好気を性質」の部分。正しくは「好気の性質」と「の」で名詞につなぐ。好気は名詞なので、「を」を付けて性質に続けることはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37013, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土の中の好気な微生物は、酸素を使ってよく増えます。", "corrected_sentence": "土の中の好気の微生物は、酸素を使ってよく増えます。", "error_description": "誤りは「好気な」の部分。正しくは「好気の微生物」と「の」で名詞を修飾する。好気は名詞なので、「な」を付けて微生物を修飾することはできない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7767d63f-0b0b-4d92-8e11-8ce5c49c6bf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「理想の友だち」のように名詞を修飾する「の」。"}, {"text": "を", "is_correct": false, "explanation": "「理想を友だち」は目的語にならず、名詞修飾が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「理想が友だち」は主語と名詞の関係にならず、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「理想で友だち」は手段や場所にならず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「理想の友だち」のように名詞を修飾する「の」。", "を": "「理想を友だち」は目的語にならず、名詞修飾が成り立たない。", "が": "「理想が友だち」は主語と名詞の関係にならず、文が通らない。", "で": "「理想で友だち」は手段や場所にならず、意味が通らない。"}, "error_tags": {"を": "直接目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
