INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37014, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "理想は、これがいいなと思うことです。", "primary_collocate": null, "pronunciation": "りそう", "ipa": "ɾisoː", "syllable_count": 3, "sentences": [{"text": "私の理想の部屋は、広くて日当たりがよい部屋だ。", "target_word": "理想", "complexity_tier": "T3", "furigana": "私[わたし]の理想[りそう]の部屋[へや]は、広[ひろ]くて日当[ひあ]たりがよい部屋[へや]だ。", "sentence_source": "generated"}, {"text": "理想の友だちは、いつも優しく話を聞いてくれる人だ。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]の友[とも]だちは、いつも優[やさ]しく話[はなし]を聞[き]いてくれる人[ひと]だ。", "sentence_source": "generated"}, {"text": "理想の夏休みは、海の近くでゆっくり過ごすことだ。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]の夏休[なつやす]みは、海[うみ]の近[ちか]くでゆっくり過[す]ごすことだ。", "sentence_source": "generated"}, {"text": "理想どおりの服が見つかって、とてもうれしかった。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]どおりの服[ふく]が見[み]つかって、とてもうれしかった。", "sentence_source": "generated"}, {"text": "姉の理想の朝は、静かな公園で走ることから始まる。", "target_word": "理想", "complexity_tier": "T3", "furigana": "姉[あね]の理想[りそう]の朝[あさ]は、静[しず]かな公園[こうえん]で走[はし]ることから始[はじ]まる。", "sentence_source": "generated"}, {"text": "理想を言えば、駅から近くて家賃が安い家に住みたい。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]を言[い]えば、駅[えき]から近[ちか]くて家賃[やちん]が安[やす]い家[いえ]に住[す]みたい。", "sentence_source": "generated"}, {"text": "理想の仕事とは、好きなことをして生活できる仕事だと思う。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]の仕事[しごと]とは、好[す]きなことをして生活[せいかつ]できる仕事[しごと]だと思[おも]う。", "sentence_source": "generated"}, {"text": "この店のケーキは、私の理想の甘さだった。", "target_word": "理想", "complexity_tier": "T3", "furigana": "この店[みせ]のケーキは、私[わたし]の理想[りそう]の甘[あま]さだった。", "sentence_source": "generated"}, {"text": "理想の先生に出会えて、勉強が楽しくなった。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]の先生[せんせい]に出会[であ]えて、勉強[べんきょう]が楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "彼は理想の相手に会えず、まだ結婚していない。", "target_word": "理想", "complexity_tier": "T3", "furigana": "彼[かれ]は理想[りそう]の相手[あいて]に会[あ]えず、まだ結婚[けっこん]していない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理想", "label": "基本形"}, {"form": "理想的", "label": "派生形（形状詞）"}], "register": "neutral", "sense_fingerprint": "自分がこうだったらいいなと思う姿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "自分がこうだったらいいと思う部屋を指し、「私の理想の部屋」として文に合う。"}, {"text": "欠点", "is_correct": false, "explanation": "直したい点を指し、「欠点の部屋」は部屋の好みを表す文に合わない。"}, {"text": "義務", "is_correct": false, "explanation": "果たすべき務めで、「義務の部屋」は文の意味が通らない。"}, {"text": "予定", "is_correct": false, "explanation": "これから行う計画で、「予定の部屋」は部屋の好みを表さない。"}], "explanations": {"理想": "自分がこうだったらいいと思う部屋を指し、「私の理想の部屋」として文に合う。", "欠点": "直したい点を指し、「欠点の部屋」は部屋の好みを表す文に合わない。", "義務": "果たすべき務めで、「義務の部屋」は文の意味が通らない。", "予定": "これから行う計画で、「予定の部屋」は部屋の好みを表さない。"}, "sentence_index": 0, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本の理想は、電気が流れる仕組みを分かりやすく説明している。", "explanation": "ここは〈理論〉の意味。理想は望ましい姿で、説明の体系には使わないので合わない。"}, {"text": "道路が渋滞した理想は、事故があったからだ。", "explanation": "ここは〈原因〉の意味。理想は望ましい姿で、出来事の原因には使わないので合わない。"}, {"text": "この箱は理想が重く、一人では持ち上がらない。", "explanation": "ここは〈重さ〉の意味。理想は望ましい姿で、物の重さの説明には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "自分にとって望ましい仕事の姿を指し、「理想の仕事とは」として文に合う。"}, {"text": "不満", "is_correct": false, "explanation": "不足を感じる気持ちで、「不満の仕事とは」は仕事の姿を述べず文が通らない。"}, {"text": "苦労", "is_correct": false, "explanation": "骨の折れる思いを指し、「苦労の仕事とは」は文の意味が通らない。"}, {"text": "悩み", "is_correct": false, "explanation": "気にかかる問題を指し、「悩みの仕事とは」は仕事の性質を表さない。"}], "explanations": {"理想": "自分にとって望ましい仕事の姿を指し、「理想の仕事とは」として文に合う。", "不満": "不足を感じる気持ちで、「不満の仕事とは」は仕事の姿を述べず文が通らない。", "苦労": "骨の折れる思いを指し、「苦労の仕事とは」は文の意味が通らない。", "悩み": "気にかかる問題を指し、「悩みの仕事とは」は仕事の性質を表さない。"}, "sentence_index": 6, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は理想がすぐれず、会社を休んだ。", "explanation": "ここは〈体調〉の意味。理想は望ましい姿で、体の状態には使わないので合わない。"}, {"text": "テレビの理想を大きくしたら、隣の人に怒られた。", "explanation": "ここは〈音量〉の意味。理想は望ましい姿で、音の大きさには使わないので合わない。"}, {"text": "この煮物は理想が濃くて、ご飯が進む。", "explanation": "ここは〈味〉の意味。理想は望ましい姿で、味の濃さには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37014, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄の理想的の休日は、山へ登ることだ。", "corrected_sentence": "兄の理想的な休日は、山へ登ることだ。", "error_description": "「理想的」は形状詞なので、名詞を修飾するときは「な」が必要。「の」だと誤り。正しくは「理想的な」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37014, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の紅茶は、私の理想に香りだった。", "corrected_sentence": "この店の紅茶は、私の理想の香りだった。", "error_description": "「理想の香り」の「の」を「に」にすると、位置を示す助詞になり文が崩れる。正しくは「理想の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「理想の上司」のように名詞を修飾する「の」。"}, {"text": "が", "is_correct": false, "explanation": "「理想が上司」は名詞修飾の関係にならず、文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「理想を上司」は目的語にならず、文が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「理想で上司」は手段や場所にならず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「理想の上司」のように名詞を修飾する「の」。", "が": "「理想が上司」は名詞修飾の関係にならず、文が通らない。", "を": "「理想を上司」は目的語にならず、文が通らない。", "で": "「理想で上司」は手段や場所にならず、意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "現実", "is_correct": true, "explanation": "理想の対義語として辞典に並ぶ。完全な姿と実際の姿が対になる。"}, {"text": "空想", "is_correct": false, "explanation": "現実離れした想像を指し、理想と対になる語ではない。"}, {"text": "目標", "is_correct": false, "explanation": "達成を目指す到達点で、理想の対義語ではない。"}, {"text": "計画", "is_correct": false, "explanation": "行動の段取りを指し、理想と対になる語ではない。"}], "correct_answer": "現実", "explanations": {"現実": "理想の対義語として辞典に並ぶ。完全な姿と実際の姿が対になる。", "空想": "現実離れした想像を指し、理想と対になる語ではない。", "目標": "達成を目指す到達点で、理想の対義語ではない。", "計画": "行動の段取りを指し、理想と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "理想について述べる主題を示す「は」で、「立派だ」と評価する文になる。"}, {"text": "に", "is_correct": false, "explanation": "「理想に立派だが」は成り立たず、位置や相手を示す語が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「立派だが」という評価の文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」で、評価の文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "理想について述べる主題を示す「は」で、「立派だ」と評価する文になる。", "に": "「理想に立派だが」は成り立たず、位置や相手を示す語が合わない。", "へ": "方向を示す「へ」で、「立派だが」という評価の文に合わない。", "から": "起点を示す「から」で、評価の文が成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "現実", "is_correct": true, "explanation": "理想の対義語として辞典に並ぶ。完全な姿と実際の姿が対になる。"}, {"text": "目的", "is_correct": false, "explanation": "行動の到達点を指し、理想と対になる語ではない。"}, {"text": "原則", "is_correct": false, "explanation": "基本の決まりで、理想の対義語ではない。"}, {"text": "常識", "is_correct": false, "explanation": "一般に通じる判断を指し、理想と対になる語ではない。"}], "correct_answer": "現実", "explanations": {"現実": "理想の対義語として辞典に並ぶ。完全な姿と実際の姿が対になる。", "目的": "行動の到達点を指し、理想と対になる語ではない。", "原則": "基本の決まりで、理想の対義語ではない。", "常識": "一般に通じる判断を指し、理想と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "理想とは、ある状態や条件が完全に満たされていると考える、最も望ましい姿や目標のことです。", "primary_collocate": null, "pronunciation": "りそう", "ipa": "ɾisoː", "syllable_count": 3, "sentences": [{"text": "現実的な設計図とは異なるが、その絵には彼が求める理想の世界が詰まっている。", "target_word": "理想", "complexity_tier": "T3", "furigana": "現実的[げんじつてき]な設計図[せっけいず]とは異[こと]なるが、その絵[え]には彼[かれ]が求[もと]める理想[りそう]の世界[せかい]が詰[つ]まっている。", "sentence_source": "mined"}, {"text": "理想の上司は、部下の意見をきちんと聞いてくれる人だと思う。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]の上司[じょうし]は、部下[ぶか]の意見[いけん]をきちんと聞[き]いてくれる人[ひと]だと思[おも]う。", "sentence_source": "generated"}, {"text": "理想を高く持つのはよいが、現実との差に悩むこともある。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]を高[たか]く持[も]つのはよいが、現実[げんじつ]との差[さ]に悩[なや]むこともある。", "sentence_source": "generated"}, {"text": "彼女は理想の家を建てるために、十年間お金をためてきた。", "target_word": "理想", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は理想[りそう]の家[いえ]を建[た]てるために、十年間[じゅうねんかん]お金[かね]をためてきた。", "sentence_source": "generated"}, {"text": "理想と現実は違うと分かっていても、夢をあきらめたくない。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]と現実[げんじつ]は違[ちが]うと分[わ]かっていても、夢[ゆめ]をあきらめたくない。", "sentence_source": "generated"}, {"text": "この学校は、生徒が自分で考える力を育てる理想を掲げている。", "target_word": "理想", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、生徒[せいと]が自分[じぶん]で考[かんが]える力[ちから]を育[そだ]てる理想[りそう]を掲[かか]げている。", "sentence_source": "generated"}, {"text": "理想どおりの結果にはならなかったが、チームは最後までやりきった。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]どおりの結果[けっか]にはならなかったが、チームは最後[さいご]までやりきった。", "sentence_source": "generated"}, {"text": "彼の語る理想は立派だが、具体的な計画がなくて信じにくい。", "target_word": "理想", "complexity_tier": "T3", "furigana": "彼[かれ]の語[かた]る理想[りそう]は立派[りっぱ]だが、具体的[ぐたいてき]な計画[けいかく]がなくて信[しん]じにくい。", "sentence_source": "generated"}, {"text": "理想の社会とは何かについて、クラスで意見を出し合った。", "target_word": "理想", "complexity_tier": "T3", "furigana": "理想[りそう]の社会[しゃかい]とは何[なに]かについて、クラスで意見[いけん]を出[だ]し合[あ]った。", "sentence_source": "generated"}, {"text": "若いころの理想を、今も心のどこかで大切にしている。", "target_word": "理想", "complexity_tier": "T3", "furigana": "若[わか]いころの理想[りそう]を、今[いま]も心[こころ]のどこかで大切[たいせつ]にしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理想", "label": "基本形"}, {"form": "理想的", "label": "派生形（形状詞）"}], "register": "neutral", "sense_fingerprint": "完全で最も望ましいと考える姿や目標", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd66ca9ef-9312-4a67-9de0-fc2cea46199e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "彼が求める完全な姿を指し、「理想の世界」として絵の中身に合う。"}, {"text": "手続き", "is_correct": false, "explanation": "事務の手順を指し、絵の中に世界が詰まっているという文には合わない。"}, {"text": "方針", "is_correct": false, "explanation": "行動の指針で、「方針の世界が詰まっている」は意味が通らない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の枠で、絵の中に世界が詰まるという文に合わない。"}], "explanations": {"理想": "彼が求める完全な姿を指し、「理想の世界」として絵の中身に合う。", "手続き": "事務の手順を指し、絵の中に世界が詰まっているという文には合わない。", "方針": "行動の指針で、「方針の世界が詰まっている」は意味が通らない。", "予算": "お金の枠で、絵の中に世界が詰まるという文に合わない。"}, "sentence_index": 0, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒りのあまり理想がきかなくなり、大声で怒鳴ってしまった。", "explanation": "ここは〈理性〉の意味。『理性がきかなくなる』と言うので、理想では合わない。"}, {"text": "彼は理想をこねて、皆を言い負かした。", "explanation": "ここは〈理屈〉の意味。『理屈をこねる』と言うので、理想を使うのは合わない。"}, {"text": "彼が遅れた理想は、電車が止まっていたからだ。", "explanation": "ここは〈理由〉の意味。理想は目指す姿で、遅れた原因の説明には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "結果を基準にする語として「理想どおり」が成り立ち、文に合う。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「悲しみどおりの結果」は不自然で、文の基準として成り立たない。"}, {"text": "喜び", "is_correct": false, "explanation": "「喜びどおりの結果」は成り立たず、文の意味が通らない。"}, {"text": "怒り", "is_correct": false, "explanation": "「怒りどおりの結果」は不自然で、文に合わない。"}], "explanations": {"理想": "結果を基準にする語として「理想どおり」が成り立ち、文に合う。", "悲しみ": "「悲しみどおりの結果」は不自然で、文の基準として成り立たない。", "喜び": "「喜びどおりの結果」は成り立たず、文の意味が通らない。", "怒り": "「怒りどおりの結果」は不自然で、文に合わない。"}, "sentence_index": 6, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫は理想で獲物を追いかける。", "explanation": "ここは〈本能〉の意味。理想は目指す姿で、生まれつきの衝動には使わないので合わない。"}, {"text": "彼は理想に恵まれていて、どんな楽器も弾ける。", "explanation": "ここは〈才能〉の意味。理想は目指す姿で、生まれ持った能力には使わないので合わない。"}, {"text": "彼は今日の理想がとても悪く、口もきかなかった。", "explanation": "ここは〈機嫌〉の意味。理想は望ましい姿で、気分の良し悪しには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は理想を暮らしを夢見て、田舎に引っ越した。", "corrected_sentence": "彼は理想の暮らしを夢見て、田舎に引っ越した。", "error_description": "「理想の暮らし」の「の」を「を」にすると、理想が目的語になり文が壊れる。正しくは「理想の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37015, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は理想に高く持っているので、自分に厳しい。", "corrected_sentence": "彼女は理想を高く持っているので、自分に厳しい。", "error_description": "「理想を高く持つ」の対象は「を」で示す。「理想に」と誤ると、位置を示す「に」になり文が崩れる。正しくは「理想を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e63b9f7-c4ee-47e6-b371-282846474932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「新聞には」の「に」。「書いてある」の場所・媒体を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「書いてある」には場所を示す「に」が必要なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここは書かれている場所なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここは比べる文脈ではないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「新聞には」の「に」。「書いてある」の場所・媒体を示す正しい助詞。", "を": "「を」は目的語を示す。「書いてある」には場所を示す「に」が必要なので合わない。", "へ": "「へ」は方向を示すが、ここは書かれている場所なので合わない。", "より": "「より」は比較を示すが、ここは比べる文脈ではないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「新聞でテレビ番組を調べて」の「で」。手段・媒体を示し、「調べる」に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、新聞が番組を調べる主体にはならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここは比べる文脈ではないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や場所を示すが、「調べる」の手段としては合わない。"}], "correct_answer": "で", "explanations": {"で": "「新聞でテレビ番組を調べて」の「で」。手段・媒体を示し、「調べる」に合う。", "が": "「が」は主語を示すが、新聞が番組を調べる主体にはならず不自然。", "より": "「より」は比較を示すが、ここは比べる文脈ではないので合わない。", "に": "「に」は方向や場所を示すが、「調べる」の手段としては合わない。"}, "error_tags": {"が": "主語", "より": "比較", "に": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "毎日、新しいことを知らせる紙のことです。", "primary_collocate": null, "pronunciation": "しんぶん", "ipa": "ɕimbɯɴ", "syllable_count": 4, "sentences": [{"text": "毎朝、父は新聞を読んでから会社へ行きます。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、父[ちち]は新聞[しんぶん]を読[よ]んでから会社[かいしゃ]へ行[い]きます。", "sentence_source": "generated"}, {"text": "新聞には、昨日のできごとがたくさん書いてあります。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]には、昨日[きのう]のできごとがたくさん書[か]いてあります。", "sentence_source": "generated"}, {"text": "駅の前で新聞を買って、電車の中で読みました。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]で新聞[しんぶん]を買[か]って、電車[でんしゃ]の中[なか]で読[よ]みました。", "sentence_source": "generated"}, {"text": "祖母は目が悪いので、大きな字の新聞を読んでいます。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "祖母[そぼ]は目[め]が悪[わる]いので、大[おお]きな字[じ]の新聞[しんぶん]を読[よ]んでいます。", "sentence_source": "generated"}, {"text": "新聞が家に届くのは、朝の五時ごろです。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]が家[いえ]に届[とど]くのは、朝[あさ]の五時[ごじ]ごろです。", "sentence_source": "generated"}, {"text": "雨の日は、新聞がぬれないように、ふくろに入れて届けてくれます。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、新聞[しんぶん]がぬれないように、ふくろに入[い]れて届[とど]けてくれます。", "sentence_source": "generated"}, {"text": "古い新聞は、ひもでしばって、ごみの日に出します。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "古[ふる]い新聞[しんぶん]は、ひもでしばって、ごみの日[ひ]に出[だ]します。", "sentence_source": "generated"}, {"text": "新聞でテレビ番組を調べてから、見たい番組を決めました。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]でテレビ番組[ばんぐみ]を調[しら]べてから、見[み]たい番組[ばんぐみ]を決[き]めました。", "sentence_source": "generated"}, {"text": "窓ガラスをふくときは、古い新聞を使うときれいになります。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "窓[まど]ガラスをふくときは、古[ふる]い新聞[しんぶん]を使[つか]うときれいになります。", "sentence_source": "generated"}, {"text": "先生は、今日の新聞を持ってきて、みんなに見せました。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "先生[せんせい]は、今日[きょう]の新聞[しんぶん]を持[も]ってきて、みんなに見[み]せました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "新聞", "label": "基本形"}], "register": "polite", "sense_fingerprint": "毎日届く、ニュースが書かれた紙の印刷物(日常・やさしい説明)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: しばっ (Zipf 2.15)']::text[], '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電話", "is_correct": false, "explanation": "「読む」の目的語にならない。電話は読むものではないので文が成り立たない。"}, {"text": "新聞", "is_correct": true, "explanation": "読んでから会社へ行くという文脈で、読む印刷物として自然に入る。"}, {"text": "写真", "is_correct": false, "explanation": "写真は見るものなので、「読んでから」とは合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は聞くもので、読む対象ではないので合わない。"}], "explanations": {"電話": "「読む」の目的語にならない。電話は読むものではないので文が成り立たない。", "新聞": "読んでから会社へ行くという文脈で、読む印刷物として自然に入る。", "写真": "写真は見るものなので、「読んでから」とは合わない。", "音楽": "音楽は聞くもので、読む対象ではないので合わない。"}, "sentence_index": 0, "correct_answer": "新聞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新聞は、再生すると好きな音楽が流れる円盤です。", "explanation": "ここは〈CD〉の意味。新聞は社会の出来事を伝える紙で、音楽を再生する円盤ではないので合わない。"}, {"text": "この新聞には、毎日の出費を書き込むための欄が一つずつ並んでいます。", "explanation": "ここは〈家計簿〉の意味。新聞は出来事を伝える紙で、家計の出費を記録する帳面ではないので合わない。"}, {"text": "この新聞は、ボタンを押すと明かりがつく懐中電灯です。", "explanation": "ここは〈懐中電灯〉の意味。新聞は出来事を伝える紙で、明かりをつける器具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "天気はひもでしばって出す紙類ではないので、この文に入らない。"}, {"text": "料理", "is_correct": false, "explanation": "「古い料理」をひもでしばってごみの日に出す、という文脈には合わない。"}, {"text": "運動", "is_correct": false, "explanation": "運動は物として出せないので、ごみの日に出す対象にならない。"}, {"text": "新聞", "is_correct": true, "explanation": "古い紙として、ひもでしばってごみの日に出すという文脈に合う。"}], "explanations": {"天気": "天気はひもでしばって出す紙類ではないので、この文に入らない。", "料理": "「古い料理」をひもでしばってごみの日に出す、という文脈には合わない。", "運動": "運動は物として出せないので、ごみの日に出す対象にならない。", "新聞": "古い紙として、ひもでしばってごみの日に出すという文脈に合う。"}, "sentence_index": 6, "correct_answer": "新聞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新聞は、冷たい飲み物を入れて持ち歩く水筒です。", "explanation": "ここは〈水筒〉の意味。新聞は出来事を伝える紙で、飲み物を入れる容器ではないので合わない。"}, {"text": "この新聞は、電車の出発時刻を一本ずつ正確に示しています。", "explanation": "ここは〈時刻表〉の意味。新聞は出来事を伝える紙で、列車の発車時刻を示す表ではないので合わない。"}, {"text": "毎晩、この新聞は自分の気持ちを静かに聞いてくれる相手です。", "explanation": "ここは〈話し相手〉の意味。新聞は人ではなく、気持ちを聞いてくれる相手ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日の夜、弟は新聞に読みながら寝てしまいました。", "corrected_sentence": "昨日の夜、弟は新聞を読みながら寝てしまいました。", "error_description": "「読む」の目的語は「を」。「新聞に」は誤りで、正しくは「新聞を」（格助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は毎晩、新聞を読むてから寝ます。", "corrected_sentence": "母は毎晩、新聞を読んでから寝ます。", "error_description": "「読む」の連用形の音便は「読んで」。「読むて」は誤りで、正しくは「読んで」（活用形の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「その新聞は」の「は」。文の主題を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここは主題の位置で文が成立しないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここでは主題にならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここは比べる文脈ではないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「その新聞は」の「は」。文の主題を示す正しい助詞。", "を": "「を」は目的語を示すが、ここは主題の位置で文が成立しないので合わない。", "へ": "「へ」は方向を示すが、ここでは主題にならないので合わない。", "より": "「より」は比較を示すが、ここは比べる文脈ではないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「新聞に投書したら」の「に」。投書先・相手を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、投書の相手は「に」で示すので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、投書先としては合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、新聞が投書する主体ではないので不自然。"}], "correct_answer": "に", "explanations": {"に": "「新聞に投書したら」の「に」。投書先・相手を示す正しい助詞。", "を": "「を」は目的語を示すが、投書の相手は「に」で示すので合わない。", "と": "「と」は並列や相手を示すが、投書先としては合わない。", "が": "「が」は主語を示すが、新聞が投書する主体ではないので不自然。"}, "error_tags": {"を": "目的語", "と": "並列", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "社会で起こったできごとや情報を伝えるために、毎日発行される印刷物。", "primary_collocate": null, "pronunciation": "しんぶん", "ipa": "ɕimbɯɴ", "syllable_count": 4, "sentences": [{"text": "選挙の結果は、すべての新聞が一面で大きく報じた。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "選挙[せんきょ]の結果[けっか]は、すべての新聞[しんぶん]が一面[いちめん]で大[おお]きく報[ほう]じた。", "sentence_source": "generated"}, {"text": "その新聞は、毎日百万部以上が発行されている。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "その新聞[しんぶん]は、毎日[まいにち]百万部[ひゃくまんぶ]以上[いじょう]が発行[はっこう]されている。", "sentence_source": "generated"}, {"text": "事故の原因について、新聞は詳しく伝えていた。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]について、新聞[しんぶん]は詳[くわ]しく伝[つた]えていた。", "sentence_source": "generated"}, {"text": "新聞を読む習慣のある学生は、社会の問題に詳しい。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]を読[よ]む習慣[しゅうかん]のある学生[がくせい]は、社会[しゃかい]の問題[もんだい]に詳[くわ]しい。", "sentence_source": "generated"}, {"text": "新聞に広告を出したところ、問い合わせが増えた。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]に広告[こうこく]を出[だ]したところ、問[と]い合[あ]わせが増[ふ]えた。", "sentence_source": "generated"}, {"text": "最近はスマートフォンで新聞を読む人が増えている。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "最近[さいきん]はスマートフォンで新聞[しんぶん]を読[よ]む人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "各社の新聞を比べると、同じ出来事でも書き方がちがう。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "各社[かくしゃ]の新聞[しんぶん]を比[くら]べると、同[おな]じ出来事[できごと]でも書[か]き方[かた]がちがう。", "sentence_source": "generated"}, {"text": "新聞に投書したら、次の日に意見がのった。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]に投書[とうしょ]したら、次[つぎ]の日[ひ]に意見[いけん]がのった。", "sentence_source": "generated"}, {"text": "図書館では、古い新聞を縮刷版で見ることができる。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "図書館[としょかん]では、古[ふる]い新聞[しんぶん]を縮刷版[しゅくさつばん]で見[み]ることができる。", "sentence_source": "generated"}, {"text": "新聞は朝刊と夕刊に分かれて、毎日届けられる。", "target_word": "新聞", "complexity_tier": "T3", "furigana": "新聞[しんぶん]は朝刊[ちょうかん]と夕刊[ゆうかん]に分[わ]かれて、毎日[まいにち]届[とど]けられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "新聞", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "社会の出来事や情報を報道する、定期発行の印刷メディア(報道機関の刊行物)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 縮刷 (Zipf 2.08)']::text[], '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電話", "is_correct": false, "explanation": "「すべての電話が一面で報じた」は意味をなさない。報道の主体ではない。"}, {"text": "運動", "is_correct": false, "explanation": "運動は一面で事故や選挙を報じる主体にならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は報道機関ではないので、「一面で大きく報じた」の主語に合わない。"}, {"text": "新聞", "is_correct": true, "explanation": "報道機関の刊行物として、一面で大きく報じる主語にふさわしい。"}], "explanations": {"電話": "「すべての電話が一面で報じた」は意味をなさない。報道の主体ではない。", "運動": "運動は一面で事故や選挙を報じる主体にならないので合わない。", "天気": "天気は報道機関ではないので、「一面で大きく報じた」の主語に合わない。", "新聞": "報道機関の刊行物として、一面で大きく報じる主語にふさわしい。"}, "sentence_index": 0, "correct_answer": "新聞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新聞は、好きなアイドルの写真を一冊にまとめた本だ。", "explanation": "ここは〈写真集〉の意味。新聞は社会の出来事を報じる紙で、一人の写真を集めた本ではないので合わない。"}, {"text": "この新聞は、町の道順を一本ずつ示した地図だ。", "explanation": "ここは〈地図〉の意味。新聞は出来事を伝える紙で、道順を示す地図ではないので合わない。"}, {"text": "この新聞は、動物の絵がたくさん描かれた絵本だ。", "explanation": "ここは〈絵本〉の意味。新聞は社会の出来事を報じる紙で、絵を中心にした本ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "料理", "is_correct": false, "explanation": "料理は書き方がちがうと比べられるものではないので、各社の比較の文脈に合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽には「書き方」がなく、各社の比較にはならない。"}, {"text": "電池", "is_correct": false, "explanation": "電池には「書き方」がなく、同じ出来事をどう書くかという文脈に合わない。"}, {"text": "新聞", "is_correct": true, "explanation": "各社が発行する新聞を比べると、同じ出来事でも書き方がちがうという文脈に合う。"}], "explanations": {"料理": "料理は書き方がちがうと比べられるものではないので、各社の比較の文脈に合わない。", "音楽": "音楽には「書き方」がなく、各社の比較にはならない。", "電池": "電池には「書き方」がなく、同じ出来事をどう書くかという文脈に合わない。", "新聞": "各社が発行する新聞を比べると、同じ出来事でも書き方がちがうという文脈に合う。"}, "sentence_index": 6, "correct_answer": "新聞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新聞は、家族の写真を並べて思い出を残すアルバムだ。", "explanation": "ここは〈アルバム〉の意味。新聞は出来事を伝える紙で、写真を貼って思い出を残すものではないので合わない。"}, {"text": "この新聞は、一年分の日付を一枚ずつめくる暦だ。", "explanation": "ここは〈暦〉の意味。新聞は出来事を伝える紙で、日付を一枚ずつめくる暦ではないので合わない。"}, {"text": "この新聞は三百ページもあって、読み終わるまで一週間かかった。", "explanation": "ここは〈小説〉の意味。毎日届く新聞は分厚い一冊の作品ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は読者として新聞を投書した。", "corrected_sentence": "私は読者として新聞に投書した。", "error_description": "「投書する」の相手は「に」で示す。「新聞を」は誤りで、正しくは「新聞に」（格助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37017, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は新聞を毎日飲んでいる。", "corrected_sentence": "祖父は新聞を毎日取っている。", "error_description": "「新聞を取る」（購読する）が正しい。「飲む」は新聞と結びつかないので誤り（動詞の選び方の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「割合を変える」の「を」。変える対象（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「割合が変える」では割合が主語になるが、「変える」は対象を必要とするため合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、動詞「変える」の対象は示せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「変える」の対象にはならないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「割合を変える」の「を」。変える対象（目的語）を示す。", "が": "「割合が変える」では割合が主語になるが、「変える」は対象を必要とするため合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、動詞「変える」の対象は示せないので合わない。", "へ": "「へ」は方向を示すが、「変える」の対象にはならないので合わない。"}, "error_tags": {"が": "主格（主語）", "の": "連体（〜の）", "へ": "方向（〜へ）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものを比べたときの、一方の大きさや量の割合のこと。", "primary_collocate": null, "pronunciation": "わりあい", "ipa": "waɾiai", "syllable_count": 4, "sentences": [{"text": "クラスの男子と女子の割合は、ちょうど二対三だ。", "target_word": "割合", "complexity_tier": "T3", "furigana": "クラスの男子[だんし]と女子[じょし]の割合[わりあい]は、ちょうど二対三[にたいさん]だ。", "sentence_source": "generated"}, {"text": "水と砂糖の割合を変えると、味が大きく変わる。", "target_word": "割合", "complexity_tier": "T3", "furigana": "水[みず]と砂糖[さとう]の割合[わりあい]を変[か]えると、味[あじ]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "去年と比べて、雨の日と晴れの日の割合が変わった。", "target_word": "割合", "complexity_tier": "T3", "furigana": "去年[きょねん]と比[くら]べて、雨[あめ]の日[ひ]と晴[は]れの日[ひ]の割合[わりあい]が変[か]わった。", "sentence_source": "generated"}, {"text": "この町では、男の子と女の子の割合がほぼ同じだ。", "target_word": "割合", "complexity_tier": "T3", "furigana": "この町[まち]では、男[おとこ]の子[こ]と女[おんな]の子[こ]の割合[わりあい]がほぼ同[おな]じだ。", "sentence_source": "generated"}, {"text": "小麦粉と牛乳の割合を間違えたので、生地がかたくなった。", "target_word": "割合", "complexity_tier": "T3", "furigana": "小麦粉[こむぎこ]と牛乳[ぎゅうにゅう]の割合[わりあい]を間違[まちが]えたので、生地[きじ]がかたくなった。", "sentence_source": "generated"}, {"text": "塩と水の割合は一対十で、薄めに作る。", "target_word": "割合", "complexity_tier": "T3", "furigana": "塩[しお]と水[みず]の割合[わりあい]は一対十[いちたいじゅう]で、薄[うす]めに作[つく]る。", "sentence_source": "generated"}, {"text": "赤い花と白い花の割合を同じにして、庭に植えた。", "target_word": "割合", "complexity_tier": "T3", "furigana": "赤[あか]い花[はな]と白[しろ]い花[はな]の割合[わりあい]を同[おな]じにして、庭[にわ]に植[う]えた。", "sentence_source": "generated"}, {"text": "好きな色を調べて、赤と青の割合を表にまとめた。", "target_word": "割合", "complexity_tier": "T3", "furigana": "好[す]きな色[いろ]を調[しら]べて、赤[あか]と青[あお]の割合[わりあい]を表[ひょう]にまとめた。", "sentence_source": "generated"}, {"text": "男性と女性の割合が逆になり、女性のほうが多くなった。", "target_word": "割合", "complexity_tier": "T3", "furigana": "男性[だんせい]と女性[じょせい]の割合[わりあい]が逆[ぎゃく]になり、女性[じょせい]のほうが多[おお]くなった。", "sentence_source": "generated"}, {"text": "昼と夜の長さの割合は、季節によって変わる。", "target_word": "割合", "complexity_tier": "T3", "furigana": "昼[ひる]と夜[よる]の長[なが]さの割合[わりあい]は、季節[きせつ]によって変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "割合", "label": "基本形"}, {"form": "割合が", "label": "主格"}, {"form": "割合は", "label": "主題"}], "register": "neutral", "sense_fingerprint": "二つのものを比べたときの量や大きさの比(混ぜ方・男女比・前年との比較など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "料理", "is_correct": false, "explanation": "男子と女子の数の比を表す文脈に、料理は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は男子と女子の数の比を表さないので合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は男子と女子の数の比を表さないので合わない。"}, {"text": "割合", "is_correct": true, "explanation": "男子と女子の数の比を表し、「二対三」という比を示す文脈に合う。"}], "explanations": {"料理": "男子と女子の数の比を表す文脈に、料理は合わない。", "天気": "天気は男子と女子の数の比を表さないので合わない。", "音楽": "音楽は男子と女子の数の比を表さないので合わない。", "割合": "男子と女子の数の比を表し、「二対三」という比を示す文脈に合う。"}, "sentence_index": 0, "correct_answer": "割合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この教室の割合は三十人だ。", "explanation": "ここは〈人数〉の意味。割合は比の大きさで、人の数そのものは表さないので合わない。"}, {"text": "この町では、家賃の割合が一万円と決まっている。", "explanation": "ここは〈料金〉の意味。割合は比の大きさで、金額そのものは表さないので合わない。"}, {"text": "このクラスの割合は七十点だった。", "explanation": "ここは〈平均〉の意味。割合は比の大きさで、点数の平均は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電話", "is_correct": false, "explanation": "赤い花と白い花の「電話」を同じにする、という文脈は成り立たない。"}, {"text": "運動", "is_correct": false, "explanation": "赤い花と白い花の「運動」を同じにする、という文脈は成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "赤い花と白い花の「電池」を同じにする、という文脈は成り立たない。"}, {"text": "割合", "is_correct": true, "explanation": "花の数などの比を同じにして植える、という文脈に合う。"}], "explanations": {"電話": "赤い花と白い花の「電話」を同じにする、という文脈は成り立たない。", "運動": "赤い花と白い花の「運動」を同じにする、という文脈は成り立たない。", "電池": "赤い花と白い花の「電池」を同じにする、という文脈は成り立たない。", "割合": "花の数などの比を同じにして植える、という文脈に合う。"}, "sentence_index": 6, "correct_answer": "割合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今月の苦情の割合は十件だった。", "explanation": "ここは〈件数〉の意味。割合は比の大きさで、件数という数の量は表さないので合わない。"}, {"text": "この庭の割合は三十平方メートルだ。", "explanation": "ここは〈広さ〉の意味。割合は比の大きさで、面積の数値は表さないので合わない。"}, {"text": "私の割合は五十キロだ。", "explanation": "ここは〈体重〉の意味。割合は比の大きさで、重さの数値は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の男女の割合を、三対一だ。", "corrected_sentence": "会社の男女の割合は、三対一だ。", "error_description": "「割合」を主題として示すなら「は」が正しい。「を」は目的語を示すので、ここでは誤り（格助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37018, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域では、若者の割合が強い。", "corrected_sentence": "この地域では、若者の割合が高い。", "error_description": "割合の大小は「高い」「低い」で表す。「強い」は割合と結びつかないので誤り（コロケーションの誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「割合は、三割ほどだ」の「は」。文の主題を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここは主題の位置なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここは主題にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示すが、ここは主題として合わない。"}], "correct_answer": "は", "explanations": {"は": "「割合は、三割ほどだ」の「は」。文の主題を示す正しい助詞。", "を": "「を」は目的語を示すが、ここは主題の位置なので合わない。", "へ": "「へ」は方向を示すが、ここは主題にならないので合わない。", "に": "「に」は場所や対象を示すが、ここは主題として合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "場所・対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「輸入品の割合が高くなり」の「が」。「割合」が主語になる正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果や場所を示すが、ここは主語の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、ここは主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、ここは主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「輸入品の割合が高くなり」の「が」。「割合」が主語になる正しい助詞。", "に": "「に」は結果や場所を示すが、ここは主語の位置には合わない。", "と": "「と」は並列や相手を示すが、ここは主語にならない。", "で": "「で」は手段や場所を示すが、ここは主語の位置には合わない。"}, "error_tags": {"に": "結果・場所", "と": "並列", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体の中である部分が占める大きさや、二つの数量の比。", "primary_collocate": null, "pronunciation": "わりあい", "ipa": "waɾiai", "syllable_count": 4, "sentences": [{"text": "国の人口に占める子どもの割合は、年々減っている。", "target_word": "割合", "complexity_tier": "T3", "furigana": "国[くに]の人口[じんこう]に占[し]める子[こ]どもの割合[わりあい]は、年々[ねんねん]減[へ]っている。", "sentence_source": "generated"}, {"text": "食費が収入に占める割合は、三割ほどだ。", "target_word": "割合", "complexity_tier": "T3", "furigana": "食費[しょくひ]が収入[しゅうにゅう]に占[し]める割合[わりあい]は、三割[さんわり]ほどだ。", "sentence_source": "generated"}, {"text": "この店の売り上げでは、お弁当の割合が最も大きい。", "target_word": "割合", "complexity_tier": "T3", "furigana": "この店[みせ]の売[う]り上[あ]げでは、お弁当[べんとう]の割合[わりあい]が最[もっと]も大[おお]きい。", "sentence_source": "generated"}, {"text": "海の面積が地球全体に占める割合は、約七割である。", "target_word": "割合", "complexity_tier": "T3", "furigana": "海[うみ]の面積[めんせき]が地球[ちきゅう]全体[ぜんたい]に占[し]める割合[わりあい]は、約[やく]七割[ななわり]である。", "sentence_source": "generated"}, {"text": "成績のうち、宿題の割合は二割だ。", "target_word": "割合", "complexity_tier": "T3", "furigana": "成績[せいせき]のうち、宿題[しゅくだい]の割合[わりあい]は二割[にわり]だ。", "sentence_source": "generated"}, {"text": "不合格になった人の割合は、全体の五パーセントだった。", "target_word": "割合", "complexity_tier": "T3", "furigana": "不合格[ふごうかく]になった人[ひと]の割合[わりあい]は、全体[ぜんたい]の五[ご]パーセントだった。", "sentence_source": "generated"}, {"text": "体の中で水分が占める割合は、赤ちゃんのほうが大きい。", "target_word": "割合", "complexity_tier": "T3", "furigana": "体[からだ]の中[なか]で水分[すいぶん]が占[し]める割合[わりあい]は、赤[あか]ちゃんのほうが大[おお]きい。", "sentence_source": "generated"}, {"text": "輸入品の割合が高くなり、国内の商品が売れにくくなった。", "target_word": "割合", "complexity_tier": "T3", "furigana": "輸入品[ゆにゅうひん]の割合[わりあい]が高[たか]くなり、国内[こくない]の商品[しょうひん]が売[う]れにくくなった。", "sentence_source": "generated"}, {"text": "アンケートで「賛成」と答えた人の割合を円グラフで示した。", "target_word": "割合", "complexity_tier": "T3", "furigana": "アンケートで「賛成[さんせい]」と答[こた]えた人[ひと]の割合[わりあい]を円[えん]グラフで示[しめ]した。", "sentence_source": "generated"}, {"text": "森林が国土の中で占める割合は、日本では高いほうだ。", "target_word": "割合", "complexity_tier": "T3", "furigana": "森林[しんりん]が国土[こくど]の中[なか]で占[し]める割合[わりあい]は、日本[にほん]では高[たか]いほうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "割合", "label": "基本形"}, {"form": "割合が", "label": "主格"}, {"form": "割合は", "label": "主題"}], "register": "neutral", "sense_fingerprint": "全体に対して一部分が占める比率(人口・収入・面積などの構成比)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 円グラフ (Zipf 2.27)']::text[], '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "料理", "is_correct": false, "explanation": "人口に占める子どもの比率を「料理」とは言わないので合わない。"}, {"text": "電話", "is_correct": false, "explanation": "人口に占める子どもの比率を「電話」とは言わないので合わない。"}, {"text": "写真", "is_correct": false, "explanation": "人口に占める子どもの比率を「写真」とは言わないので合わない。"}, {"text": "割合", "is_correct": true, "explanation": "全体に占める部分の比率を表し、年々減っているという文脈に合う。"}], "explanations": {"料理": "人口に占める子どもの比率を「料理」とは言わないので合わない。", "電話": "人口に占める子どもの比率を「電話」とは言わないので合わない。", "写真": "人口に占める子どもの比率を「写真」とは言わないので合わない。", "割合": "全体に占める部分の比率を表し、年々減っているという文脈に合う。"}, "sentence_index": 0, "correct_answer": "割合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この公園の割合は、毎朝六時に開く門の時刻だ。", "explanation": "ここは〈開門時刻〉の意味。割合は比率で、門が開く時刻は表さないので合わない。"}, {"text": "この町の割合は、毎年少しずつ減っている。", "explanation": "ここは〈人口〉の意味。割合は比率で、人の数そのものが減ったとは言わないので合わない。"}, {"text": "このりんごの割合は三百グラムだ。", "explanation": "ここは〈重さ〉の意味。割合は比率で、重さの数値は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "体の中で水分が占める比率を「天気」とは言わないので合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "体の中で水分が占める比率を「音楽」とは言わないので合わない。"}, {"text": "電池", "is_correct": false, "explanation": "体の中で水分が占める比率を「電池」とは言わないので合わない。"}, {"text": "割合", "is_correct": true, "explanation": "体の中で水分が占める比率を表し、「大きい」と比べる文脈に合う。"}], "explanations": {"天気": "体の中で水分が占める比率を「天気」とは言わないので合わない。", "音楽": "体の中で水分が占める比率を「音楽」とは言わないので合わない。", "電池": "体の中で水分が占める比率を「電池」とは言わないので合わない。", "割合": "体の中で水分が占める比率を表し、「大きい」と比べる文脈に合う。"}, "sentence_index": 6, "correct_answer": "割合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝の割合は三十六度だった。", "explanation": "ここは〈体温〉の意味。割合は比率で、温度の数値は表さないので合わない。"}, {"text": "駅までの割合は、歩いて十分ほどだ。", "explanation": "ここは〈距離〉の意味。割合は比率で、道のりの長さは表さないので合わない。"}, {"text": "この本の割合は、背表紙に書かれた番号だ。", "explanation": "ここは〈背番号〉の意味。割合は比率で、番号は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この学校では、女子の割合を高い。", "corrected_sentence": "この学校では、女子の割合が高い。", "error_description": "「割合が高い」と主語で示す文なので「が」が正しい。「を」は誤り（格助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37019, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日本では、農業の割合が強くなった。", "corrected_sentence": "日本では、農業の割合が低くなった。", "error_description": "割合の変化は「高くなる」「低くなる」で表す。「強くなる」は割合と結びつかないので誤り（コロケーションの誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
