INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37020, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "うすいものを何枚も重ねたようす。", "primary_collocate": null, "pronunciation": "そうじょう", "ipa": "soːdʑoː", "syllable_count": 4, "sentences": [{"text": "崖の断面には、うすい岩が層状に重なっている。", "target_word": "層状", "complexity_tier": "T3", "furigana": "崖[がけ]の断面[だんめん]には、うすい岩[いわ]が層状[そうじょう]に重[かさ]なっている。", "sentence_source": "generated"}, {"text": "このパイは、生地が層状になっているので、さくさくしている。", "target_word": "層状", "complexity_tier": "T3", "furigana": "このパイは、生地[きじ]が層状[そうじょう]になっているので、さくさくしている。", "sentence_source": "generated"}, {"text": "雲が層状に広がり、空全体がくもってきた。", "target_word": "層状", "complexity_tier": "T3", "furigana": "雲[くも]が層状[そうじょう]に広[ひろ]がり、空[そら]全体[ぜんたい]がくもってきた。", "sentence_source": "generated"}, {"text": "切った玉ねぎは、うすい皮が層状に重なって見える。", "target_word": "層状", "complexity_tier": "T3", "furigana": "切[き]った玉[たま]ねぎは、うすい皮[かわ]が層状[そうじょう]に重[かさ]なって見[み]える。", "sentence_source": "generated"}, {"text": "雲母は、うすくはがれる層状の鉱物だ。", "target_word": "層状", "complexity_tier": "T3", "furigana": "雲母[うんも]は、うすくはがれる層状[そうじょう]の鉱物[こうぶつ]だ。", "sentence_source": "generated"}, {"text": "このケーキは、クリームとスポンジが層状に重ねてある。", "target_word": "層状", "complexity_tier": "T3", "furigana": "このケーキは、クリームとスポンジが層状[そうじょう]に重[かさ]ねてある。", "sentence_source": "generated"}, {"text": "火山灰が層状にたまった地層から、昔の噴火が分かる。", "target_word": "層状", "complexity_tier": "T3", "furigana": "火山灰[かざんばい]が層状[そうじょう]にたまった地層[ちそう]から、昔[むかし]の噴火[ふんか]が分[わ]かる。", "sentence_source": "generated"}, {"text": "古い壁のペンキが層状にはがれ落ちた。", "target_word": "層状", "complexity_tier": "T3", "furigana": "古[ふる]い壁[かべ]のペンキが層状[そうじょう]にはがれ落[お]ちた。", "sentence_source": "generated"}, {"text": "うすい紙を何枚も糊でつけると、層状の板ができる。", "target_word": "層状", "complexity_tier": "T3", "furigana": "うすい紙[かみ]を何枚[なんまい]も糊[のり]でつけると、層状[そうじょう]の板[いた]ができる。", "sentence_source": "generated"}, {"text": "この石は、うすい板が重なった層状の形をしている。", "target_word": "層状", "complexity_tier": "T3", "furigana": "この石[いし]は、うすい板[いた]が重[かさ]なった層状[そうじょう]の形[かたち]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "層状", "label": "基本形"}, {"form": "層状に", "label": "連用形(に)"}, {"form": "層状の", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "うすいものが何枚も重なった状態(パイ・雲・岩・皮などの重なり方)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "層状", "is_correct": true, "explanation": "薄いものが何枚も重なったようすを表す語。「うすい岩が層状に重なっている」に合う。"}, {"text": "球状", "is_correct": false, "explanation": "丸い形を表す語。うすい（平たい）岩が球状に重なるとは言えず、文脈と矛盾する。"}, {"text": "粒状", "is_correct": false, "explanation": "小さな粒の集まりを表す語。岩が粒状に重なるという文にはならず、うすい板状の重なりに合わない。"}, {"text": "放射状", "is_correct": false, "explanation": "中心から四方に広がる形を表す語。層が放射状に重なるとは言えず、断面の層の重なりと矛盾する。"}], "explanations": {"層状": "薄いものが何枚も重なったようすを表す語。「うすい岩が層状に重なっている」に合う。", "球状": "丸い形を表す語。うすい（平たい）岩が球状に重なるとは言えず、文脈と矛盾する。", "粒状": "小さな粒の集まりを表す語。岩が粒状に重なるという文にはならず、うすい板状の重なりに合わない。", "放射状": "中心から四方に広がる形を表す語。層が放射状に重なるとは言えず、断面の層の重なりと矛盾する。"}, "sentence_index": 0, "correct_answer": "層状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の斜面は層状に切り開かれ、棚田が並んでいる。", "explanation": "ここは〈段状〉の意味。棚田のように段になった斜面は段状で表す。層状は薄い層が重なったようすを指すので、斜面を切り開いた段の形には合わない。"}, {"text": "このボールは層状で、よく転がる。", "explanation": "ここは〈球状〉の意味。転がりやすい丸い形は球状で表す。層状は薄い層を重ねた形なので、ボールの形には使わない。"}, {"text": "その事件には、層状の原因が絡み合っている。", "explanation": "ここは〈重層的〉の意味。抽象的な要因が幾重にも重なる複雑さは重層的で表す。層状は薄い板のような物理的な重なりを指すので、原因には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "層状", "is_correct": true, "explanation": "薄い層が重なったようすを表す語。火山灰が層状にたまった地層という文に合う。"}, {"text": "繊維状", "is_correct": false, "explanation": "細い糸のような形を表す語。火山灰が繊維状にたまるとは言えず、地層の文脈に合わない。"}, {"text": "針状", "is_correct": false, "explanation": "細く尖った形を表す語。火山灰が針状にたまるという文にはならない。"}, {"text": "棒状", "is_correct": false, "explanation": "細長い棒の形を表す語。火山灰が棒状にたまるとは言えず、層の重なりと合わない。"}], "explanations": {"層状": "薄い層が重なったようすを表す語。火山灰が層状にたまった地層という文に合う。", "繊維状": "細い糸のような形を表す語。火山灰が繊維状にたまるとは言えず、地層の文脈に合わない。", "針状": "細く尖った形を表す語。火山灰が針状にたまるという文にはならない。", "棒状": "細長い棒の形を表す語。火山灰が棒状にたまるとは言えず、層の重なりと合わない。"}, "sentence_index": 6, "correct_answer": "層状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂糖は層状で、水に溶けやすい。", "explanation": "ここは〈粒状〉の意味。砂糖のように小さな粒の集まりは粒状で表す。層状は薄い層の重なりを指すので、砂糖の形には合わない。"}, {"text": "血管は層状に広がって、体中に血を運ぶ。", "explanation": "ここは〈網状〉の意味。血管のように細い線が網目状に広がる様子は網状で表す。層状は層が重なる形なので、網目の広がりには合わない。"}, {"text": "綿は層状で、糸をつくるのに使われる。", "explanation": "ここは〈繊維状〉の意味。糸の原料になる細い線状の物質は繊維状で表す。層状は薄い層の重なりを指すので、綿の形の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "霧が層状を広がって、谷が白く見えた。", "corrected_sentence": "霧が層状に広がって、谷が白く見えた。", "error_description": "「広がる」に係る様子を表す形は「層状に」。「層状を」の「を」は目的語を示すが、広がるは目的語を取らないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "崖に層状な地層が見えた。", "corrected_sentence": "崖に層状の地層が見えた。", "error_description": "名詞「層状」が後ろの名詞「地層」を修飾するときは「の」を使う。「な」は形容動詞の語尾で、名詞の層状には付かないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「継続が大切だ」と、継続を主語として示す。ここでは「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「継続を大切だ」は成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や目的を示す助詞。「継続に大切だ」は不自然で、主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞。「継続で大切だ」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「継続が大切だ」と、継続を主語として示す。ここでは「が」が正しい。", "を": "目的語を示す助詞。「継続を大切だ」は成り立たないので合わない。", "に": "相手や目的を示す助詞。「継続に大切だ」は不自然で、主語を示せない。", "で": "手段や場所を示す助詞。「継続で大切だ」は意味が通らない。"}, "error_tags": {"を": "目的語（対象）", "に": "相手・目的", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "途中でやめること。「練習をやめずに続ける」の反対になり、継続の対義語として辞書にも挙がる。"}, {"text": "完成", "is_correct": false, "explanation": "完全に仕上がること。続けることの反対の関係にはなく、対義語ではない。"}, {"text": "準備", "is_correct": false, "explanation": "事前に整えること。続けることとは対になる関係ではない。"}, {"text": "記録", "is_correct": false, "explanation": "書き残すこと。続けることの反対の意味にはならない。"}], "correct_answer": "中断", "explanations": {"中断": "途中でやめること。「練習をやめずに続ける」の反対になり、継続の対義語として辞書にも挙がる。", "完成": "完全に仕上がること。続けることの反対の関係にはなく、対義語ではない。", "準備": "事前に整えること。続けることとは対になる関係ではない。", "記録": "書き残すこと。続けることの反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "途中でやめること。やめずに続ける継続の対義語で、ここでは貯金を途中でやめる意味になる。"}, {"text": "開始", "is_correct": false, "explanation": "始めること。続けることの反対ではなく、始まりを表すだけの語。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにして手を加えないこと。続けない状態とは別の概念で、対義語ではない。"}, {"text": "集中", "is_correct": false, "explanation": "ひとつのことに意識を向けること。続けることの反対の意味にはならない。"}], "correct_answer": "中断", "explanations": {"中断": "途中でやめること。やめずに続ける継続の対義語で、ここでは貯金を途中でやめる意味になる。", "開始": "始めること。続けることの反対ではなく、始まりを表すだけの語。", "放置": "そのままにして手を加えないこと。続けない状態とは別の概念で、対義語ではない。", "集中": "ひとつのことに意識を向けること。続けることの反対の意味にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ずっと同じことをやめずに続けること。", "primary_collocate": null, "pronunciation": "けいぞく", "ipa": "keːzokɯ", "syllable_count": 4, "sentences": [{"text": "毎日の練習を継続すれば、必ず上手になる。", "target_word": "継続", "complexity_tier": "T3", "furigana": "毎日[まいにち]の練習[れんしゅう]を継続[けいぞく]すれば、必[かなら]ず上手[じょうず]になる。", "sentence_source": "generated"}, {"text": "勉強は才能より継続が大切だと先生は言った。", "target_word": "継続", "complexity_tier": "T3", "furigana": "勉強[べんきょう]は才能[さいのう]より継続[けいぞく]が大切[たいせつ]だと先生[せんせい]は言[い]った。", "sentence_source": "generated"}, {"text": "彼は十年間、日記を書くことを継続している。", "target_word": "継続", "complexity_tier": "T3", "furigana": "彼[かれ]は十年間[じゅうねんかん]、日記[にっき]を書[か]くことを継続[けいぞく]している。", "sentence_source": "generated"}, {"text": "運動が続かない人は、まず小さな目標で継続を目指すといい。", "target_word": "継続", "complexity_tier": "T3", "furigana": "運動[うんどう]が続[つづ]かない人[ひと]は、まず小[ちい]さな目標[もくひょう]で継続[けいぞく]を目指[めざ]すといい。", "sentence_source": "generated"}, {"text": "ダイエットに失敗したのは、継続する意志が弱かったからだ。", "target_word": "継続", "complexity_tier": "T3", "furigana": "ダイエットに失敗[しっぱい]したのは、継続[けいぞく]する意志[いし]が弱[よわ]かったからだ。", "sentence_source": "generated"}, {"text": "英語の勉強を継続するために、毎朝同じ時間に起きている。", "target_word": "継続", "complexity_tier": "T3", "furigana": "英語[えいご]の勉強[べんきょう]を継続[けいぞく]するために、毎朝[まいあさ]同[おな]じ時間[じかん]に起[お]きている。", "sentence_source": "generated"}, {"text": "三日坊主で終わらず継続できたので、自信がついた。", "target_word": "継続", "complexity_tier": "T3", "furigana": "三日坊主[みっかぼうず]で終[お]わらず継続[けいぞく]できたので、自信[じしん]がついた。", "sentence_source": "generated"}, {"text": "早く結果を出したいが、焦らずに継続することが近道だ。", "target_word": "継続", "complexity_tier": "T3", "furigana": "早[はや]く結果[けっか]を出[だ]したいが、焦[あせ]らずに継続[けいぞく]することが近道[ちかみち]だ。", "sentence_source": "generated"}, {"text": "「継続は力なり」という言葉を信じて、毎朝走っている。", "target_word": "継続", "complexity_tier": "T3", "furigana": "「継続[けいぞく]は力[ちから]なり」という言葉[ことば]を信[しん]じて、毎朝[まいあさ]走[はし]っている。", "sentence_source": "generated"}, {"text": "貯金を継続した結果、旅行に行けるだけのお金がたまった。", "target_word": "継続", "complexity_tier": "T3", "furigana": "貯金[ちょきん]を継続[けいぞく]した結果[けっか]、旅行[りょこう]に行[い]けるだけのお金[かね]がたまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "継続", "label": "名詞形"}, {"form": "継続する", "label": "する動詞 終止形"}, {"form": "継続して", "label": "て形"}, {"form": "継続した", "label": "た形"}, {"form": "継続しない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "習慣や努力を長く途切れさせずに続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "継続", "is_correct": true, "explanation": "やめずに続けること。「練習を続ければ必ず上手になる」という文に合う。"}, {"text": "放棄", "is_correct": false, "explanation": "途中で投げ出すこと。練習を放棄すれば上手になるという文は矛盾する。"}, {"text": "脱線", "is_correct": false, "explanation": "本筋からそれること。練習を脱線すれば上手になるという文は意味が通らない。"}, {"text": "縮小", "is_correct": false, "explanation": "規模を小さくすること。練習を縮小すれば必ず上手になるとは言えず、続けることの意味とは違う。"}], "explanations": {"継続": "やめずに続けること。「練習を続ければ必ず上手になる」という文に合う。", "放棄": "途中で投げ出すこと。練習を放棄すれば上手になるという文は矛盾する。", "脱線": "本筋からそれること。練習を脱線すれば上手になるという文は意味が通らない。", "縮小": "規模を小さくすること。練習を縮小すれば必ず上手になるとは言えず、続けることの意味とは違う。"}, "sentence_index": 0, "correct_answer": "継続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "締め切りを継続するため、社長に頼みに行った。", "explanation": "ここは〈延長〉の意味。締め切りを後ろにずらすことは延長で表す。継続は同じことをやめずに続けることなので、締め切りの変更には合わない。"}, {"text": "雨は三回に分かれて継続した。", "explanation": "ここは〈反復〉の意味。同じことが間をおいて何度も起こることは反復で表す。継続は途切れずに続くことなので、三回に分かれた雨には合わない。"}, {"text": "ロケットは一瞬で継続した。", "explanation": "ここは〈発射〉の意味。打ち上げのように一度に行われる動作は発射で表す。継続は長く続くことなので、一瞬の出来事には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "継続", "is_correct": true, "explanation": "やめずに続けること。「三日坊主で終わらず続けられた」という意味で、自信につながる文に合う。"}, {"text": "中傷", "is_correct": false, "explanation": "根拠のない悪口で人を傷つけること。三日坊主で終わらず中傷できたという文は意味が通らない。"}, {"text": "散財", "is_correct": false, "explanation": "お金を無駄に使うこと。三日坊主を終わらせないことや自信とは結びつかない。"}, {"text": "寄付", "is_correct": false, "explanation": "金品を無償で贈ること。三日坊主で終わらず寄付できたという文は文脈に合わない。"}], "explanations": {"継続": "やめずに続けること。「三日坊主で終わらず続けられた」という意味で、自信につながる文に合う。", "中傷": "根拠のない悪口で人を傷つけること。三日坊主で終わらず中傷できたという文は意味が通らない。", "散財": "お金を無駄に使うこと。三日坊主を終わらせないことや自信とは結びつかない。", "寄付": "金品を無償で贈ること。三日坊主で終わらず寄付できたという文は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "継続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝のコーヒーは、すっかり継続になった。", "explanation": "ここは〈習慣〉の意味。毎日の行いが身につくことは習慣で表す。継続は行為を続けること自体を指すので、「習慣になった」の代わりにはならない。"}, {"text": "賞状は校長から生徒に継続された。", "explanation": "ここは〈授与〉の意味。賞状などを人に渡すことは授与で表す。継続は同じ行為を続けることなので、賞状の受け渡しには合わない。"}, {"text": "祖父の遺産を孫が継続した。", "explanation": "ここは〈継承〉の意味。前の人の財産や地位を受け継ぐことは継承で表す。継続は同じ行為を続けることなので、遺産には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の散歩を継続するば、体が軽くなる。", "corrected_sentence": "毎日の散歩を継続すれば、体が軽くなる。", "error_description": "「～ば」の仮定形は「すれば」。「するば」は「する」の活用の誤りで、継続の後ろの動詞の形が間違っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37022, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝、英語の勉強に継続している。", "corrected_sentence": "毎朝、英語の勉強を継続している。", "error_description": "「継続する」は「～を継続する」の形で、対象に「を」を取る。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「通気を考えて」の「を」は、「考える」の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「通気が考えて」は物である通気が考える主体になり、主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「通気へ考えて」は方向を表すが、「考える」の対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「通気より考えて」は比較の意味になり、家の作り方を表す文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "「通気を考えて」の「を」は、「考える」の対象を示す。", "が": "「通気が考えて」は物である通気が考える主体になり、主語として成り立たない。", "へ": "「通気へ考えて」は方向を表すが、「考える」の対象にはならない。", "より": "「通気より考えて」は比較の意味になり、家の作り方を表す文脈に合わない。"}, "error_tags": {"へ": "方向（〜へ）", "より": "比較（〜より）", "が": "主語（〜が）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空気の通り道を作って、空気を入れかえること。", "primary_collocate": null, "pronunciation": "つうき", "ipa": "tsɯːki", "syllable_count": 3, "sentences": [{"text": "押し入れは通気が悪いので、湿気がたまりやすい。", "target_word": "通気", "complexity_tier": "T3", "furigana": "押[お]し入[い]れは通気[つうき]が悪[わる]いので、湿気[しっけ]がたまりやすい。", "sentence_source": "generated"}, {"text": "靴箱の扉を少し開けて、通気をよくした。", "target_word": "通気", "complexity_tier": "T3", "furigana": "靴箱[くつばこ]の扉[とびら]を少[すこ]し開[あ]けて、通気[つうき]をよくした。", "sentence_source": "generated"}, {"text": "家の床下は通気が大切で、悪いとカビが生える。", "target_word": "通気", "complexity_tier": "T3", "furigana": "家[いえ]の床下[ゆかした]は通気[つうき]が大切[たいせつ]で、悪[わる]いとカビが生[は]える。", "sentence_source": "generated"}, {"text": "夏は通気を考えて、風が通る部屋に住みたい。", "target_word": "通気", "complexity_tier": "T3", "furigana": "夏[なつ]は通気[つうき]を考[かんが]えて、風[かぜ]が通[とお]る部屋[へや]に住[す]みたい。", "sentence_source": "generated"}, {"text": "帽子の横に小さな穴があるのは、通気のためだ。", "target_word": "通気", "complexity_tier": "T3", "furigana": "帽子[ぼうし]の横[よこ]に小[ちい]さな穴[あな]があるのは、通気[つうき]のためだ。", "sentence_source": "generated"}, {"text": "倉庫は通気が足りなくて、中の荷物が湿ってしまった。", "target_word": "通気", "complexity_tier": "T3", "furigana": "倉庫[そうこ]は通気[つうき]が足[た]りなくて、中[なか]の荷物[にもつ]が湿[しめ]ってしまった。", "sentence_source": "generated"}, {"text": "布団を壁から離して置くと、通気がよくなる。", "target_word": "通気", "complexity_tier": "T3", "furigana": "布団[ふとん]を壁[かべ]から離[はな]して置[お]くと、通気[つうき]がよくなる。", "sentence_source": "generated"}, {"text": "新しい家は壁の中まで通気を考えて作られている。", "target_word": "通気", "complexity_tier": "T3", "furigana": "新[あたら]しい家[いえ]は壁[かべ]の中[なか]まで通気[つうき]を考[かんが]えて作[つく]られている。", "sentence_source": "generated"}, {"text": "古い本は通気のよい場所に置いて、カビを防ぐ。", "target_word": "通気", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]は通気[つうき]のよい場所[ばしょ]に置[お]いて、カビを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "犬小屋は暑くならないように、通気を確保してある。", "target_word": "通気", "complexity_tier": "T3", "furigana": "犬小屋[いぬごや]は暑[あつ]くならないように、通気[つうき]を確保[かくほ]してある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通気", "label": "名詞形"}, {"form": "通気する", "label": "する動詞 終止形"}, {"form": "通気して", "label": "て形"}, {"form": "通気した", "label": "た形"}, {"form": "通気しない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "空気の通り道を作って空気を入れかえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通気", "is_correct": true, "explanation": "空気の通り道が悪いことを表し、湿気がたまる理由と合う。"}, {"text": "家賃", "is_correct": false, "explanation": "押し入れの空気の状態を表さず、「悪い」ともつながらないので文が成り立たない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯が悪いという言い方は押し入れの状態を表さず、湿気の理由にならない。"}, {"text": "物価", "is_correct": false, "explanation": "物価は押し入れの状態ではなく、「悪い」と結びつかないので不自然。"}], "explanations": {"通気": "空気の通り道が悪いことを表し、湿気がたまる理由と合う。", "家賃": "押し入れの空気の状態を表さず、「悪い」ともつながらないので文が成り立たない。", "洗濯": "洗濯が悪いという言い方は押し入れの状態を表さず、湿気の理由にならない。", "物価": "物価は押し入れの状態ではなく、「悪い」と結びつかないので不自然。"}, "sentence_index": 0, "correct_answer": "通気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は毎週病院へ通気しているが、体調は安定している。", "explanation": "ここは〈通院〉（病院に通うこと）の意味。通気は空気の通り道を指すので、人が通う意味では使えない。"}, {"text": "あの会社は上司にも気軽に話せて、通気がいい。", "explanation": "ここは〈風通し〉の比喩（人間関係が開放的なこと）の意味。通気は空気の入れ替えを指すので、職場の雰囲気には言わない。"}, {"text": "この国は通気が安定していて、物価も落ち着いている。", "explanation": "ここは〈通貨〉（お金の価値）の意味。通気は空気に関する語なので、お金の安定には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通気", "is_correct": true, "explanation": "布団を離すと空気の通り道がよくなる、という文脈に合う。"}, {"text": "落書き", "is_correct": false, "explanation": "壁の落書きがよくなるとは言わず、布団の置き方とつながらない。"}, {"text": "体重", "is_correct": false, "explanation": "体重がよくなるという言い方は、布団を離す行為の結果にならない。"}, {"text": "小銭", "is_correct": false, "explanation": "小銭がよくなるとは言わず、布団の置き方と関係がない。"}], "explanations": {"通気": "布団を離すと空気の通り道がよくなる、という文脈に合う。", "落書き": "壁の落書きがよくなるとは言わず、布団の置き方とつながらない。", "体重": "体重がよくなるという言い方は、布団を離す行為の結果にならない。", "小銭": "小銭がよくなるとは言わず、布団の置き方と関係がない。"}, "sentence_index": 6, "correct_answer": "通気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎朝電車で会社へ通気している。", "explanation": "ここは〈通勤〉（会社へ通うこと）の意味。通気は空気の通り道の意味なので、人の移動には使わない。"}, {"text": "停電がなおり、電線が通気して、部屋の明かりがついた。", "explanation": "ここは〈通電〉（電気が流れること）の意味。通気は空気の通り道の意味なので、電気が流れる意味には使わない。"}, {"text": "会社から通気が届いて、来月の休みが分かった。", "explanation": "ここは〈通知〉（お知らせ）の意味。通気は空気の通り道の意味で、お知らせには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "倉庫は通気を悪くて、中の荷物が湿ってしまった。", "corrected_sentence": "倉庫は通気が悪くて、中の荷物が湿ってしまった。", "error_description": "「通気が悪い」の主語を示す格助詞は「が」。「を」は目的語を示すため、形容詞「悪い」の主語には使えず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37026, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けておくと、通気がよくした。", "corrected_sentence": "窓を開けておくと、通気がよくなる。", "error_description": "「通気がよくなる」は自動詞。「よくした」は他動詞で、主語「通気」と合わない。自動詞「よくなる」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「小窓から通気して」の「から」は、空気を通す経路を示す。"}, {"text": "を", "is_correct": false, "explanation": "「小窓を通気して」は窓を対象にする言い方になり、経路を示す意味が出ない。"}, {"text": "に", "is_correct": false, "explanation": "「小窓に通気して」は到達点を示すが、空気を通す経路の意味にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「小窓の通気して」は「の」が名詞を修飾するのに動詞が続くため、文として成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「小窓から通気して」の「から」は、空気を通す経路を示す。", "を": "「小窓を通気して」は窓を対象にする言い方になり、経路を示す意味が出ない。", "に": "「小窓に通気して」は到達点を示すが、空気を通す経路の意味にはならない。", "の": "「小窓の通気して」は「の」が名詞を修飾するのに動詞が続くため、文として成り立たない。"}, "error_tags": {"を": "対象（目的語）", "に": "帰着（〜に）", "の": "連体修飾（〜の）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「窓だけで通気している」の「で」は、窓を使う手段を示す。"}, {"text": "と", "is_correct": false, "explanation": "「窓だけと通気している」は並列や相手を表し、手段を示せないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「窓だけへ通気している」は方向を表すが、「通気する」の手段にならない。"}, {"text": "の", "is_correct": false, "explanation": "「窓だけの通気している」は連体修飾になり、動詞の文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「窓だけで通気している」の「で」は、窓を使う手段を示す。", "と": "「窓だけと通気している」は並列や相手を表し、手段を示せないので不自然。", "へ": "「窓だけへ通気している」は方向を表すが、「通気する」の手段にならない。", "の": "「窓だけの通気している」は連体修飾になり、動詞の文として成り立たない。"}, "error_tags": {"と": "並列・相手（〜と）", "へ": "方向（〜へ）", "の": "連体修飾（〜の）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空気を入れ換えるために、窓や換気口などから空気を通すこと。また、その通り道。", "primary_collocate": null, "pronunciation": "つうき", "ipa": "tsɯːki", "syllable_count": 3, "sentences": [{"text": "窓を二か所開けて、通気をはかった。", "target_word": "通気", "complexity_tier": "T3", "furigana": "窓[まど]を二[ふた]か所[しょ]開[あ]けて、通気[つうき]をはかった。", "sentence_source": "generated"}, {"text": "台所の小窓から通気して、においを外に出した。", "target_word": "通気", "complexity_tier": "T3", "furigana": "台所[だいどころ]の小窓[こまど]から通気[つうき]して、においを外[そと]に出[だ]した。", "sentence_source": "generated"}, {"text": "壁の穴は通気のために開けてあるので、ふさがないこと。", "target_word": "通気", "complexity_tier": "T3", "furigana": "壁[かべ]の穴[あな]は通気[つうき]のために開[あ]けてあるので、ふさがないこと。", "sentence_source": "generated"}, {"text": "トンネルの通気が止まり、中の空気が悪くなった。", "target_word": "通気", "complexity_tier": "T3", "furigana": "トンネルの通気[つうき]が止[と]まり、中[なか]の空気[くうき]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "地下室は窓がなく、通気が難しい。", "target_word": "通気", "complexity_tier": "T3", "furigana": "地下室[ちかしつ]は窓[まど]がなく、通気[つうき]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "屋根裏の通気が悪く、夏は熱がこもる。", "target_word": "通気", "complexity_tier": "T3", "furigana": "屋根裏[やねうら]の通気[つうき]が悪[わる]く、夏[なつ]は熱[ねつ]がこもる。", "sentence_source": "generated"}, {"text": "風が弱い日は、ドアも開けて通気する。", "target_word": "通気", "complexity_tier": "T3", "furigana": "風[かぜ]が弱[よわ]い日[ひ]は、ドアも開[あ]けて通気[つうき]する。", "sentence_source": "generated"}, {"text": "換気扇が壊れたので、窓だけで通気している。", "target_word": "通気", "complexity_tier": "T3", "furigana": "換気扇[かんきせん]が壊[こわ]れたので、窓[まど]だけで通気[つうき]している。", "sentence_source": "generated"}, {"text": "通気が不十分な部屋でストーブを使うのは危険だ。", "target_word": "通気", "complexity_tier": "T3", "furigana": "通気[つうき]が不十分[ふじゅうぶん]な部屋[へや]でストーブを使[つか]うのは危険[きけん]だ。", "sentence_source": "generated"}, {"text": "浴室は壁に隙間があって、通気が保たれている。", "target_word": "通気", "complexity_tier": "T3", "furigana": "浴室[よくしつ]は壁[かべ]に隙間[すきま]があって、通気[つうき]が保[たも]たれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通気", "label": "名詞形"}, {"form": "通気する", "label": "する動詞 終止形"}, {"form": "通気して", "label": "て形"}, {"form": "通気した", "label": "た形"}, {"form": "通気しない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "窓や換気口などから空気を通すこと、またその通り道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通気", "is_correct": true, "explanation": "窓から空気を通すことを企てる意味の「通気をはかる」に合う。"}, {"text": "注文", "is_correct": false, "explanation": "注文をはかるとは言わず、窓を開ける行為と結びつかない。"}, {"text": "献立", "is_correct": false, "explanation": "献立をはかるとは言わず、窓を開けた文脈では意味をなさない。"}, {"text": "報告", "is_correct": false, "explanation": "報告をはかるとは言わず、窓を開ける動作とつながらない。"}], "explanations": {"通気": "窓から空気を通すことを企てる意味の「通気をはかる」に合う。", "注文": "注文をはかるとは言わず、窓を開ける行為と結びつかない。", "献立": "献立をはかるとは言わず、窓を開けた文脈では意味をなさない。", "報告": "報告をはかるとは言わず、窓を開ける動作とつながらない。"}, "sentence_index": 0, "correct_answer": "通気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨で道路の通気が止まり、バスが動けなくなった。", "explanation": "ここは〈通行〉（車や人が道を通ること）の意味。通気は空気を通すことなので、道路の通行には使わない。"}, {"text": "狭い会場の通気が人で混み合い、受付が進まなかった。", "explanation": "ここは〈通路〉（人が通る道）の意味。通気は空気の通り道を指すので、人の通路には言わない。"}, {"text": "英語の会議で通気を務めて、皆の意見を伝えた。", "explanation": "ここは〈通訳〉（言葉を訳すこと）の意味。通気は空気に関する語なので、言葉を訳す仕事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通気", "is_correct": true, "explanation": "風が弱い日はドアを開けて空気を通す行為と合う。"}, {"text": "施錠", "is_correct": false, "explanation": "ドアを開けている日に施錠するのは矛盾し、文脈に合わない。"}, {"text": "計測", "is_correct": false, "explanation": "ドアを開けて計測するのは文脈に合わず、意味をなさない。"}, {"text": "採寸", "is_correct": false, "explanation": "ドアを開けて採寸するのは不自然で、風の話とつながらない。"}], "explanations": {"通気": "風が弱い日はドアを開けて空気を通す行為と合う。", "施錠": "ドアを開けている日に施錠するのは矛盾し、文脈に合わない。", "計測": "ドアを開けて計測するのは文脈に合わず、意味をなさない。", "採寸": "ドアを開けて採寸するのは不自然で、風の話とつながらない。"}, "sentence_index": 6, "correct_answer": "通気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの職場は上下関係が厳しくなく、通気がよい。", "explanation": "ここは〈風通し〉（雰囲気が開放的なこと）の比喩の意味。通気は空気の通り道の意味なので、職場の雰囲気には使わない。"}, {"text": "遠くの家族と毎晩通気をして、近況を話し合う。", "explanation": "ここは〈通信〉（連絡をやり取りすること）の意味。通気は空気の通り道なので、連絡のやり取りには使わない。"}, {"text": "子どもは毎朝、自転車で学校へ通気している。", "explanation": "ここは〈通学〉（学校へ通うこと）の意味。通気は空気の通り道なので、学校へ通う意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を二か所開けると、通気が増やした。", "corrected_sentence": "窓を二か所開けると、通気が増えた。", "error_description": "「通気が増える」は自動詞。「増やした」は他動詞で、主語「通気」と合わない。自動詞「増えた」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37027, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根裏は隙間があって、通気を保たれている。", "corrected_sentence": "屋根裏は隙間があって、通気が保たれている。", "error_description": "「保たれる」の主語は「通気」なので「が」を使う。「を」は目的語を示すため、受け身の主語には使えず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "状態や品質が良いことで、不良の反対語になる。"}, {"text": "健康", "is_correct": false, "explanation": "健康は人や体の健やかさを指し、状態の良し悪しの反対語にはならない。"}, {"text": "清潔", "is_correct": false, "explanation": "清潔は汚れがないことで、不良の反対語としては対応しない。"}, {"text": "安全", "is_correct": false, "explanation": "安全は危険の反対で、不良の反対語ではない。"}], "correct_answer": "良好", "explanations": {"良好": "状態や品質が良いことで、不良の反対語になる。", "健康": "健康は人や体の健やかさを指し、状態の良し悪しの反対語にはならない。", "清潔": "清潔は汚れがないことで、不良の反対語としては対応しない。", "安全": "安全は危険の反対で、不良の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "状態や品質が良いことで、不良の反対語になる。"}, {"text": "順調", "is_correct": false, "explanation": "順調は物事が思い通りに進むことで、不良の反対語としては対応しない。"}, {"text": "安定", "is_correct": false, "explanation": "安定は揺れがないことで、不良の反対語とは言えない。"}, {"text": "堅実", "is_correct": false, "explanation": "堅実は着実で確かなことで、不良の反対語ではない。"}], "correct_answer": "良好", "explanations": {"良好": "状態や品質が良いことで、不良の反対語になる。", "順調": "順調は物事が思い通りに進むことで、不良の反対語としては対応しない。", "安定": "安定は揺れがないことで、不良の反対語とは言えない。", "堅実": "堅実は着実で確かなことで、不良の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "調子や状況がよくなく、うまくいかないこと。", "primary_collocate": null, "pronunciation": "ふりょう", "ipa": "ɸɯɾʲoː", "syllable_count": 3, "sentences": [{"text": "昨日は通信の状態が不良で、動画が止まった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "昨日[きのう]は通信[つうしん]の状態[じょうたい]が不良[ふりょう]で、動画[どうが]が止[と]まった。", "sentence_source": "generated"}, {"text": "天候が不良のため、船は出なかった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "天候[てんこう]が不良[ふりょう]のため、船[ふね]は出[で]なかった。", "sentence_source": "generated"}, {"text": "機械の動きが不良になり、作業が止まった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "機械[きかい]の動[うご]きが不良[ふりょう]になり、作業[さぎょう]が止[と]まった。", "sentence_source": "generated"}, {"text": "会場の状況が不良で、試合は延期になった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "会場[かいじょう]の状況[じょうきょう]が不良[ふりょう]で、試合[しあい]は延期[えんき]になった。", "sentence_source": "generated"}, {"text": "道の状況が不良で、バスは遅れた。", "target_word": "不良", "complexity_tier": "T3", "furigana": "道[みち]の状況[じょうきょう]が不良[ふりょう]で、バスは遅[おく]れた。", "sentence_source": "generated"}, {"text": "電波が不良で、電話の声が聞こえにくい。", "target_word": "不良", "complexity_tier": "T3", "furigana": "電波[でんぱ]が不良[ふりょう]で、電話[でんわ]の声[こえ]が聞[き]こえにくい。", "sentence_source": "generated"}, {"text": "照明の状態が不良だと、細かい字が読みにくい。", "target_word": "不良", "complexity_tier": "T3", "furigana": "照明[しょうめい]の状態[じょうたい]が不良[ふりょう]だと、細[こま]かい字[じ]が読[よ]みにくい。", "sentence_source": "generated"}, {"text": "出来が不良だったので、絵をもう一度かき直した。", "target_word": "不良", "complexity_tier": "T3", "furigana": "出来[でき]が不良[ふりょう]だったので、絵[え]をもう一度[いちど]かき直[なお]した。", "sentence_source": "generated"}, {"text": "運転中に視界が不良になったら、速度を落とす。", "target_word": "不良", "complexity_tier": "T3", "furigana": "運転中[うんてんちゅう]に視界[しかい]が不良[ふりょう]になったら、速度[そくど]を落[お]とす。", "sentence_source": "generated"}, {"text": "パソコンの動作が不良で、仕事が進まなかった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "パソコンの動作[どうさ]が不良[ふりょう]で、仕事[しごと]が進[すす]まなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不良", "label": "名詞形"}, {"form": "不良だ", "label": "断定形"}, {"form": "不良な", "label": "連体形"}, {"form": "不良で", "label": "連用形（で）"}, {"form": "不良に", "label": "連用形（に）"}], "register": "中立（普通体）", "sense_fingerprint": "調子や状況がよくなく、うまくいかないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "通信の状態が悪く、動画が止まった理由と合う。"}, {"text": "体調", "is_correct": false, "explanation": "体調は人の健康状態を指し、通信の状態には使わないので文が成り立たない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は通信の状態を表す語ではなく、「状態が」に続けると不自然。"}, {"text": "通話", "is_correct": false, "explanation": "通話は状態を表す語ではないので、「通信の状態が通話で」は意味をなさない。"}], "explanations": {"不良": "通信の状態が悪く、動画が止まった理由と合う。", "体調": "体調は人の健康状態を指し、通信の状態には使わないので文が成り立たない。", "停電": "停電は通信の状態を表す語ではなく、「状態が」に続けると不自然。", "通話": "通話は状態を表す語ではないので、「通信の状態が通話で」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犯人の行方が不良のまま、捜査は進まない。", "explanation": "ここは〈不明〉（はっきりしないこと、行方が分からないこと）の意味。不良は品質や状態の悪さを表すので、行方が分からない意味には使わない。"}, {"text": "申込書に不良があったので、受付できなかった。", "explanation": "ここは〈不備〉（書類の欠けや誤り）の意味。不良は状態や品質の悪さを表すので、書類の欠けには使わない。"}, {"text": "うっかり不良で財布を落としてしまった。", "explanation": "ここは〈不注意〉（気をつけないこと）の意味。不良は状態の悪さを表すので、うっかりした原因には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "照明の状態が悪いと字が読みにくい、という理由と合う。"}, {"text": "混線", "is_correct": false, "explanation": "混線は通信に使う語で、照明の状態に続けると意味をなさない。"}, {"text": "反響", "is_correct": false, "explanation": "反響は音の響きを表し、照明の状態とは結びつかない。"}, {"text": "雑音", "is_correct": false, "explanation": "雑音は音の話で、照明の状態には当てはまらない。"}], "explanations": {"不良": "照明の状態が悪いと字が読みにくい、という理由と合う。", "混線": "混線は通信に使う語で、照明の状態に続けると意味をなさない。", "反響": "反響は音の響きを表し、照明の状態とは結びつかない。", "雑音": "雑音は音の話で、照明の状態には当てはまらない。"}, "sentence_index": 6, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "将来が不良で、夜もよく眠れない。", "explanation": "ここは〈不安〉（心配な気持ち）の意味。不良は状態の悪さを表し、将来への気持ちには使わない。"}, {"text": "彼の言い方に不良を感じて、話す気になれなかった。", "explanation": "ここは〈不快〉（いやな感じ）の意味。不良は状態を表すので、人の感じ方には使わない。"}, {"text": "取引先の帳簿に不良があったため、契約を取り消した。", "explanation": "ここは〈不正〉（ごまかしや法に反すること）の意味。不良は品質や状態の悪さで、ごまかしの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天候が不良を、船は出なかった。", "corrected_sentence": "天候が不良で、船は出なかった。", "error_description": "状態を表す「不良」の後には「で」を使う。「を」は動作の目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37028, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照明の状態が不良くなると、細かい字が読みにくい。", "corrected_sentence": "照明の状態が不良になると、細かい字が読みにくい。", "error_description": "「不良」は名詞なので、状態の変化は「になる」で表す。「くなる」は形容詞の活用で、名詞の不良には続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "品質や状態が良いことで、品質が悪い不良の反対語になる。"}, {"text": "順調", "is_correct": false, "explanation": "順調は物事がうまく進むことで、品質の反対語にはならない。"}, {"text": "健康", "is_correct": false, "explanation": "健康は人や体の状態を指し、品質の反対語にはならない。"}, {"text": "清潔", "is_correct": false, "explanation": "清潔は汚れがないことで、品質の良し悪しの反対語ではない。"}], "correct_answer": "良好", "explanations": {"良好": "品質や状態が良いことで、品質が悪い不良の反対語になる。", "順調": "順調は物事がうまく進むことで、品質の反対語にはならない。", "健康": "健康は人や体の状態を指し、品質の反対語にはならない。", "清潔": "清潔は汚れがないことで、品質の良し悪しの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "良好", "is_correct": true, "explanation": "品質や状態が良いことで、品質が悪い不良の反対語になる。"}, {"text": "安定", "is_correct": false, "explanation": "安定は揺れがないことで、不良の反対語とは言えない。"}, {"text": "堅実", "is_correct": false, "explanation": "堅実は着実で確かなことで、不良の反対語ではない。"}, {"text": "丈夫", "is_correct": false, "explanation": "丈夫は壊れにくいことで、不良の反対語とはされない。"}], "correct_answer": "良好", "explanations": {"良好": "品質や状態が良いことで、品質が悪い不良の反対語になる。", "安定": "安定は揺れがないことで、不良の反対語とは言えない。", "堅実": "堅実は着実で確かなことで、不良の反対語ではない。", "丈夫": "丈夫は壊れにくいことで、不良の反対語とはされない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "品質や状態が悪いこと。また、悪い状態であること。", "primary_collocate": null, "pronunciation": "ふりょう", "ipa": "ɸɯɾʲoː", "syllable_count": 3, "sentences": [{"text": "この店の野菜は品質が不良で、すぐ腐った。", "target_word": "不良", "complexity_tier": "T3", "furigana": "この店[みせ]の野菜[やさい]は品質[ひんしつ]が不良[ふりょう]で、すぐ腐[くさ]った。", "sentence_source": "generated"}, {"text": "電池の端子の状態が不良で、ライトがつかない。", "target_word": "不良", "complexity_tier": "T3", "furigana": "電池[でんち]の端子[たんし]の状態[じょうたい]が不良[ふりょう]で、ライトがつかない。", "sentence_source": "generated"}, {"text": "部品の状態が不良だと、機械はすぐ壊れる。", "target_word": "不良", "complexity_tier": "T3", "furigana": "部品[ぶひん]の状態[じょうたい]が不良[ふりょう]だと、機械[きかい]はすぐ壊[こわ]れる。", "sentence_source": "generated"}, {"text": "配線が不良だったため、火事になりかけた。", "target_word": "不良", "complexity_tier": "T3", "furigana": "配線[はいせん]が不良[ふりょう]だったため、火事[かじ]になりかけた。", "sentence_source": "generated"}, {"text": "工場は不良の原因を調べて、作り方を改めた。", "target_word": "不良", "complexity_tier": "T3", "furigana": "工場[こうじょう]は不良[ふりょう]の原因[げんいん]を調[しら]べて、作[つく]り方[かた]を改[あらた]めた。", "sentence_source": "generated"}, {"text": "栄養状態が不良で、食事が足りない子どもに、弁当を配った。", "target_word": "不良", "complexity_tier": "T3", "furigana": "栄養[えいよう]状態[じょうたい]が不良[ふりょう]で、食事[しょくじ]が足[た]りない子[こ]どもに、弁当[べんとう]を配[くば]った。", "sentence_source": "generated"}, {"text": "水質が不良な川では、魚が育たない。", "target_word": "不良", "complexity_tier": "T3", "furigana": "水質[すいしつ]が不良[ふりょう]な川[かわ]では、魚[さかな]が育[そだ]たない。", "sentence_source": "generated"}, {"text": "土の状態が不良で、花が咲かなかった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "土[つち]の状態[じょうたい]が不良[ふりょう]で、花[はな]が咲[さ]かなかった。", "sentence_source": "generated"}, {"text": "検査で、ねじの精度が不良と分かった。", "target_word": "不良", "complexity_tier": "T3", "furigana": "検査[けんさ]で、ねじの精度[せいど]が不良[ふりょう]と分[わ]かった。", "sentence_source": "generated"}, {"text": "道路の状態が不良なので、車はゆっくり走った。", "target_word": "不良", "complexity_tier": "T3", "furigana": "道路[どうろ]の状態[じょうたい]が不良[ふりょう]なので、車[くるま]はゆっくり走[はし]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不良", "label": "名詞形"}, {"form": "不良だ", "label": "断定形"}, {"form": "不良な", "label": "連体形"}, {"form": "不良で", "label": "連用形（で）"}, {"form": "不良に", "label": "連用形（に）"}], "register": "中立（普通体）", "sense_fingerprint": "品質や状態が基準に達せず悪いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f6bbceb-b948-4a51-8f22-b4d717eb39f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "品質が悪く、野菜がすぐ腐った理由と合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は道路の状態を表し、野菜の品質には使わない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は音の大きさを表し、品質の状態とは結びつかない。"}, {"text": "乱気流", "is_correct": false, "explanation": "乱気流は空の気流を表し、野菜の品質とは関係がない。"}], "explanations": {"不良": "品質が悪く、野菜がすぐ腐った理由と合う。", "渋滞": "渋滞は道路の状態を表し、野菜の品質には使わない。", "騒音": "騒音は音の大きさを表し、品質の状態とは結びつかない。", "乱気流": "乱気流は空の気流を表し、野菜の品質とは関係がない。"}, "sentence_index": 0, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の外でカラスが鳴き、不良な予感がした。", "explanation": "ここは〈不吉〉（縁起が悪いこと）の意味。不良は品質や状態の悪さを表し、予感には使わない。"}, {"text": "子どもの行方が不良のまま、警察は捜索を続けている。", "explanation": "ここは〈不明〉（行方が分からないこと）の意味。不良は品質や状態の悪さを表すので、行方が分からない意味には使わない。"}, {"text": "今朝は機嫌が不良で、家族とあまり話さなかった。", "explanation": "ここは〈不機嫌〉（機嫌が悪いこと）の意味。不良は品質や状態の悪さで、人の気分には言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不良", "is_correct": true, "explanation": "水質が悪いと魚が育たない、という文脈に合う。"}, {"text": "混雑", "is_correct": false, "explanation": "混雑は人や車の多さを表し、水質には使わない。"}, {"text": "電波", "is_correct": false, "explanation": "電波は通信に使う語で、水質の状態とは結びつかない。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は体の休息を指し、川の水質には当てはまらない。"}], "explanations": {"不良": "水質が悪いと魚が育たない、という文脈に合う。", "混雑": "混雑は人や車の多さを表し、水質には使わない。", "電波": "電波は通信に使う語で、水質の状態とは結びつかない。", "睡眠": "睡眠は体の休息を指し、川の水質には当てはまらない。"}, "sentence_index": 6, "correct_answer": "不良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの日の出来事は不良で、つい笑ってしまった。", "explanation": "ここは〈不運〉（運が悪いこと）の意味。不良は品質や状態の悪さで、出来事の運には使わない。"}, {"text": "薬を飲んでも不良が続き、朝まで一睡もできなかった。", "explanation": "ここは〈不眠〉（眠れないこと）の意味。不良は品質や状態の悪さを表すので、眠れないことには使わない。"}, {"text": "昼過ぎに不良の来客があり、驚いて玄関へ出た。", "explanation": "ここは〈不意〉（思いがけないこと）の意味。不良は品質や状態の悪さを表すので、突然の出来事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "配線が不良を、火事になりかけた。", "corrected_sentence": "配線が不良で、火事になりかけた。", "error_description": "状態を表す「不良」の後には「で」を使う。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37029, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "道路の状態が不良くなったので、車はゆっくり走った。", "corrected_sentence": "道路の状態が不良になったので、車はゆっくり走った。", "error_description": "「不良」は名詞なので、状態の変化は「になった」で表す。「くなった」は形容詞の活用で、名詞の不良には続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae3465e-e247-4b7f-b386-1cac5004000e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「招く」の目的語になる失敗を示す。"}, {"text": "に", "is_correct": false, "explanation": "「招く」は「に」を相手として取らないので、「失敗に招く」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」が重なり、「準備不足が、失敗が招く」は主語が二つになり成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」にすると「失敗と招く」となり、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「招く」の目的語になる失敗を示す。", "に": "「招く」は「に」を相手として取らないので、「失敗に招く」は合わない。", "が": "「が」が重なり、「準備不足が、失敗が招く」は主語が二つになり成り立たない。", "と": "並列の「と」にすると「失敗と招く」となり、文として成り立たない。"}, "error_tags": {"に": "相手", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「招いた」の目的語になる反発を示す。"}, {"text": "が", "is_correct": false, "explanation": "「招いた」の目的語は「を」で示すので、「反発が招いた」は主語が重なり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「反発から招いた」は目的語にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「反発より招いた」は比べる意味にならず、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「招いた」の目的語になる反発を示す。", "が": "「招いた」の目的語は「を」で示すので、「反発が招いた」は主語が重なり、文が成り立たない。", "から": "「から」は起点を示すので、「反発から招いた」は目的語にならず、文が成り立たない。", "より": "「より」は比較を示すので、「反発より招いた」は比べる意味にならず、文が通らない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「招く」は、ある悪いことや問題が起こる原因になるという意味です。", "primary_collocate": null, "pronunciation": "まねく", "ipa": "maneku", "syllable_count": 3, "sentences": [{"text": "小さな嘘が、大きな誤解を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "小[ちい]さな嘘[うそ]が、大[おお]きな誤解[ごかい]を招[まね]いた。", "sentence_source": "generated"}, {"text": "準備不足が、失敗を招くことは多い。", "target_word": "招く", "complexity_tier": "T3", "furigana": "準備不足[じゅんびぶそく]が、失敗[しっぱい]を招[まね]くことは多[おお]い。", "sentence_source": "generated"}, {"text": "彼の不用意な発言は、混乱を招いてしまった。", "target_word": "招いて", "complexity_tier": "T3", "furigana": "彼[かれ]の不用意[ふようい]な発言[はつげん]は、混乱[こんらん]を招[まね]いてしまった。", "sentence_source": "generated"}, {"text": "油断は事故を招く原因になる。", "target_word": "招く", "complexity_tier": "T3", "furigana": "油断[ゆだん]は事故[じこ]を招[まね]く原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "運動不足が、病気を招くこともある。", "target_word": "招く", "complexity_tier": "T3", "furigana": "運動不足[うんどうぶそく]が、病気[びょうき]を招[まね]くこともある。", "sentence_source": "generated"}, {"text": "説明が足りなかったため、客の不満を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "説明[せつめい]が足[た]りなかったため、客[きゃく]の不満[ふまん]を招[まね]いた。", "sentence_source": "generated"}, {"text": "無理な計画は、かえって遅れを招く。", "target_word": "招く", "complexity_tier": "T3", "furigana": "無理[むり]な計画[けいかく]は、かえって遅[おく]れを招[まね]く。", "sentence_source": "generated"}, {"text": "部下への厳しすぎる態度が、反発を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "部下[ぶか]への厳[きび]しすぎる態度[たいど]が、反発[はんぱつ]を招[まね]いた。", "sentence_source": "generated"}, {"text": "一つの判断ミスが、会社に大きな損害を招いた。", "target_word": "招いた", "complexity_tier": "T3", "furigana": "一[ひと]つの判断[はんだん]ミスが、会社[かいしゃ]に大[おお]きな損害[そんがい]を招[まね]いた。", "sentence_source": "generated"}, {"text": "手入れを怠ると、故障を招く恐れがある。", "target_word": "招く", "complexity_tier": "T3", "furigana": "手入[ていれ]れを怠[おこた]ると、故障[こしょう]を招[まね]く恐[おそ]れがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "招く", "label": "終止形"}, {"form": "招いた", "label": "過去形"}, {"form": "招いて", "label": "て形"}, {"form": "招かない", "label": "否定形"}, {"form": "招き", "label": "連用形"}], "register": "中立", "sense_fingerprint": "悪い結果や問題の原因となる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ccf0ee-587d-4100-bacc-1b9c2c21e01c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招いた", "is_correct": true, "explanation": "「大きな誤解を〜」に続き、原因が結果を生んだ意味で文に合う過去形。"}, {"text": "食べた", "is_correct": false, "explanation": "誤解は食べられないので、「誤解を食べた」は文として成り立たない。"}, {"text": "眠った", "is_correct": false, "explanation": "誤解が眠るという意味にはならず、文脈に合わない。"}, {"text": "泳いだ", "is_correct": false, "explanation": "誤解は泳がないので、「誤解を泳いだ」は意味が通らない。"}], "explanations": {"招いた": "「大きな誤解を〜」に続き、原因が結果を生んだ意味で文に合う過去形。", "食べた": "誤解は食べられないので、「誤解を食べた」は文として成り立たない。", "眠った": "誤解が眠るという意味にはならず、文脈に合わない。", "泳いだ": "誤解は泳がないので、「誤解を泳いだ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "招いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を招いて、家まで運んだ。", "explanation": "ここは〈運ぶ〉の意味。物を移動させる場合は運ぶを使い、招くは人を迎える意味で使うので、荷物には合わない。"}, {"text": "先生は議論を、正しい結論へ招いた。", "explanation": "ここは〈導く〉の意味。良い方向へ話を進める場合は導くを使い、招くは悪い結果を生む意味になる。"}, {"text": "床に落ちた鉛筆を、招いて拾った。", "explanation": "ここは〈拾う〉の意味。落ちた物を手に取る動作は拾うを使い、招くは人や動物を呼び寄せる場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招く", "is_correct": true, "explanation": "「遅れを〜」に続き、原因が悪い結果を生む意味で文に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "遅れは食べられないので、「遅れを食べる」は文として成り立たない。"}, {"text": "眠る", "is_correct": false, "explanation": "遅れが眠るという意味にはならず、文脈に合わない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "遅れは泳がないので、「遅れを泳ぐ」は意味が通らない。"}], "explanations": {"招く": "「遅れを〜」に続き、原因が悪い結果を生む意味で文に合う。", "食べる": "遅れは食べられないので、「遅れを食べる」は文として成り立たない。", "眠る": "遅れが眠るという意味にはならず、文脈に合わない。", "泳ぐ": "遅れは泳がないので、「遅れを泳ぐ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "招く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は、寄付を広く招くことにした。", "explanation": "ここは〈集める〉の意味。寄付のように物や金を集める場合、招くは使わない。"}, {"text": "店は、週末だけアルバイトを招くことにした。", "explanation": "ここは〈雇う〉の意味。人を仕事として採用する場合、招くは使わない。"}, {"text": "倒れた人を見て、救急車を招いた。", "explanation": "ここは〈呼ぶ〉の意味。救急車を来させる場合は呼ぶを使い、招くは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ささいな嘘が、大きな誤解に招いた。", "corrected_sentence": "ささいな嘘が、大きな誤解を招いた。", "error_description": "「招く」は目的語に「を」を取る。「に」は誤りで、正しくは「誤解を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "招く", "is_correct": true, "explanation": "終止形で、「〜ことは多い」の前に置いて一般論を述べる形。"}, {"text": "招けば", "is_correct": false, "explanation": "仮定形なので「ことは多い」に続かず、文が成り立たない。"}, {"text": "招いて", "is_correct": false, "explanation": "て形なので文を言い切れず、「〜ことは多い」に続かない。"}, {"text": "招こう", "is_correct": false, "explanation": "意志形なので「ことは多い」に続かず、文が成り立たない。"}], "correct_form": "招く", "base_form": "招く", "form_label": "終止形", "sentence_index": 1, "explanations": {"招く": "終止形で、「〜ことは多い」の前に置いて一般論を述べる形。", "招けば": "仮定形なので「ことは多い」に続かず、文が成り立たない。", "招いて": "て形なので文を言い切れず、「〜ことは多い」に続かない。", "招こう": "意志形なので「ことは多い」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37030, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "無理に進めた計画が、かえって遅れを招きない。", "corrected_sentence": "無理に進めた計画が、かえって遅れを招く。", "error_description": "終止形は「招く」。「招きない」という活用は存在せず、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "招いた", "is_correct": true, "explanation": "過去形で、すでに起きた出来事として「反発を招いた」と述べる形。"}, {"text": "招き", "is_correct": false, "explanation": "連用形なので文を言い切れず、「反発を招き」で文が終わらない。"}, {"text": "招かれた", "is_correct": false, "explanation": "受け身にすると「反発が招かれた」は主語と述語が噛み合わず、文の意味が通らない。"}, {"text": "招こう", "is_correct": false, "explanation": "意志形なので、意図して反発を起こす意味になり、すでに起きた出来事の文には合わない。"}], "correct_form": "招いた", "base_form": "招く", "form_label": "過去形", "sentence_index": 7, "explanations": {"招いた": "過去形で、すでに起きた出来事として「反発を招いた」と述べる形。", "招き": "連用形なので文を言い切れず、「反発を招き」で文が終わらない。", "招かれた": "受け身にすると「反発が招かれた」は主語と述語が噛み合わず、文の意味が通らない。", "招こう": "意志形なので、意図して反発を起こす意味になり、すでに起きた出来事の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f17068e-d853-40f2-aec6-e53423175973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
